def impute_missing_values(ts, method):
    def fill_na(x, method):
        x_values = x.toArray()
        if method == "nearest":
            filled_values = []
            for i in range(len(x_values)):
                if i == 0 or not np.isnan(x_values[i]):
                    filled_values.append(x_values[i])
                else:
                    j = i-1
                    while(j>=0 and np.isnan(x_values[j])):
                        j -= 1
                    filled_values.append(x_values[j])
            filled_values = np.array(filled_values)
        elif method == "linear":
            filled_values = []
            for i in range(len(x_values)):
                if not np.isnan(x_values[i]):
                    filled_values.append(x_values[i])
                else:
                    j = i-1
                    while(j>=0 and np.isnan(x_values[j])):
                        j -= 1
                    if j<0:
                        j = i+1
                        while(j<len(x_values) and np.isnan(x_values[j])):
                            j += 1
                        if j == len(x_values):
                            return None
                        filled_values.append(x_values[j])
                    else:
                        m = (x_values[i] - x_values[j]) / (i-j)
                        filled_values.append(x_values[j] + m*(i-j))
            filled_values = np.array(filled_values)
        elif method == "next":
            filled_values = []
            for i in range(len(x_values)):
                if not np.isnan(x_values[i]):
                    filled_values.append(x_values[i])
                else:
                    j = i+1
                    while(j<len(x_values) and np.isnan(x_values[j])):
                        j += 1
                    if j == len(x_values):
                        return None
                    filled_values.append(x_values[j])
            filled_values = np.array(filled_values)
        elif method == "previous":
            filled_values = []
            for i in range(len(x_values)):
                if not np.isnan(x_values[i]):
                    filled_values.append(x_values[i])
                else:
                    j = i-1
                    while(j>=0 and np.isnan(x_values[j])):
                        j -= 1
                    if j<0:
                        return None
                    filled_values.append(x_values[j])
            filled_values = np.array(filled_values)
        elif method == "spline":
            filled_values = []
            filled_mask = []
            for i in range(len(x_values)):
                if not np.isnan(x_values[i]):
                    filled_values.append(x_values[i])
                    filled_mask.append(1)
                else:
                    filled_mask.append(0)
            filled_values = np.array(filled_values)
            filled_mask = np.array(filled_mask)
            if len(filled_values)==0:
                return None
            else:
                f = interpolate.interp1d(np.where(filled_mask)[0], filled_values, kind='cubic', bounds_error=False)
                filled_values = f(np.where(np.logical_not(filled_mask))[0])
            filled_values = np.array(filled_values)
        else:
            raise ValueError("Invalid imputation strategy %s specified. Must be 'nearest', 'linear', 'next', 'previous', or 'spline'." % (method))
        return DenseVector(filled_values)

    filled_ts = ts.toInferredRDD().mapValues(lambda x: fill_na(x, method))
    return TimeSeriesRDD.fromInferredRDD(filled_ts)

