    return menubar

def ensure_provisioning_correct(table_name: str, key_name: str, num_consec_read_checks: int) -> Tuple[bool, int, int]:
    try:
        dynamodb_client = boto3.client('dynamodb')
        response = dynamodb_client.describe_table(TableName=table_name)
        current_read_units = response['Table']['ProvisionedThroughput']['ReadCapacityUnits']
        expected_read_units = config.getint('dynamodb', key_name)
        if expected_read_units != current_read_units:
            dynamodb_client.update_table(TableName=table_name, ProvisionedThroughput={'ReadCapacityUnits': expected_read_units})
            return True, expected_read_units, 0
        return False, 0, num_consec_read_checks + 1
    except Exception as e:
        print(f"Failed to ensure correct read provisioning with error {e}")
        return False, 0, num_consec_read_checks + 1

