    """dm(string) -> (string, string or None)
    returns the double metaphone codes for given string - always a tuple
    there are no checks done on the input string, but it should be a single
    word or name.
    """
    st = st.lower()
    codes = ['', '']

    if st[0] in 'aeiou':
