                            t_collar=self.t_collar,
                            percentage_of_length=self.percentage_of_length
                        )
                hit_matrix *= offset_hit_matrix
            hits = numpy.where(hit_matrix)
            G = {}
            for ref_i, est_i in zip(*hits):
                if est_i not in G:
                    G[est_i] = []
                G[est_i].append(ref_i)
