                            )
                        else:
                            offset_condition = True
                        if onset_condition and offset_condition:
                            sys_counted[i] = True
                            Nsubs += 1
                            break
        Nfp = Nsys - Ntp - Nsubs
        Nfn = Nref - Ntp - Nsubs
        self.overall['Nref'] += Nref
        self.overall['Nsys'] += Nsys
        self.overall['Ntp'] += Ntp
        self.overall['Nsubs'] += Nsubs
        self.overall['Nfp'] += Nfp
