def remove_overlapping_blocks(blocks):
    new_blocks = []
    for i in range(len(blocks)):
        block = blocks[i]
        if i < len(blocks) - 1:
            next_block = blocks[i+1]
            if block.end == next_block.start and block.end % 16 == 0 and (next_block.end - next_block.start) % 16 == 0 and all(byte == 0x90 for byte in next_block.bytes):
