def ensure_port_exists(name: str, bridge: str, tunnel_type: str = None, id: str = None, remote: str = None, dst_port: str = None, internal: bool = False) -> None:
    command = ["ovs-vsctl", "--", " --may-exist", "add-port", bridge, name]
    if tunnel_type:
        command.extend(["--", "set", "interface", name, f"type={tunnel_type}"])
    if id:
        command.extend(["--", "set", "interface", name, f"{tunnel_type}-id={id}"])
    if remote:
        command.extend(["--", "set", "interface", name, f"options:remote_ip={remote}"])
    if dst_port:
        command.extend(["--", "set", "interface", name, f"options:dst_port={dst_port}"])
    if internal:
        command.extend(["--", "set", "interface", name, "type=internal"])
    subprocess.check_call(command)

