def evaluate(expression):
    """
    Evaluates an expression of the form 'conditional : conditional AND condition
                    | conditional OR condition
        condition   : condition LTE expression
                    | condition GTE expression
                    | condition LT expression
                    | condition GT expression
                    | condition EQ expression
        expression  : expression ADD term
                    | expression SUB term
        term        : term MUL factor
                    | term DIV factor
                    | term POW factor
                    | term MOD factor'
    """
    conditional = evaluate_conditional(expression)
    if conditional:
        return True
    else:
        return False

def evaluate_conditional(expression):
    if ' AND ' in expression:
        left, right = expression.split(' AND ')
        return evaluate_conditional(left) and evaluate_condition(right)
    elif ' OR ' in expression:
        left, right = expression.split(' OR ')
        return evaluate_conditional(left) or evaluate_condition(right)
    else:
        return evaluate_condition(expression)

def evaluate_condition(expression):
    if ' LTE ' in expression:
        left, right = expression.split(' LTE ')
        return evaluate_expression(left) <= evaluate_expression(right)
    elif ' GTE ' in expression:
        left, right = expression.split(' GTE ')
        return evaluate_expression(left) >= evaluate_expression(right)
    elif ' LT ' in expression:
        left, right = expression.split(' LT ')
        return evaluate_expression(left) < evaluate_expression(right)
    elif ' GT ' in expression:
        left, right = expression.split(' GT ')
        return evaluate_expression(left) > evaluate_expression(right)
    elif ' EQ ' in expression:
        left, right = expression.split(' EQ ')
        return evaluate_expression(left) == evaluate_expression(right)
    else:
        return evaluate_expression(expression)

def evaluate_expression(expression):
    if ' ADD ' in expression:
        left, right = expression.split(' ADD ')
        return evaluate_expression(left) + evaluate_term(right)
    elif ' SUB ' in expression:
        left, right = expression.split(' SUB ')
        return evaluate_expression(left) - evaluate_term(right)
    else:
        return evaluate_term(expression)

def evaluate_term(expression):
    if ' MUL ' in expression:
        left, right = expression.split(' MUL ')
        return evaluate_term(left) * evaluate_factor(right)
    elif ' DIV ' in expression:
        left, right = expression.split(' DIV ')
        return evaluate_term(left) / evaluate_factor(right)
    elif ' POW ' in expression:
        left, right = expression.split(' POW ')
        return evaluate_term(left) ** evaluate_factor(right)
    elif ' MOD ' in expression:
        left, right = expression.split(' MOD ')
        return evaluate_term(left) % evaluate_factor(right)
    else:
        return evaluate_factor(expression)

def evaluate_factor(expression):
    return int(expression)

