def find_intersections(self, other_seg):
    t1, t2 = symbols('t1 t2')
    eq1 = Eq(self.x1*(1-t1) + self.x2*t1, other_seg.x1*(1-t2) + other_seg.x2*t2)
    eq2 = Eq(self.y1*(1-t1) + self.y2*t1, other_seg.y1*(1-t2) + other_seg.y2*t2)
    sol = solve((eq1, eq2), (t1, t2))

    intersections = []
    for s in sol:
        if 0 <= s[0] <= 1 and 0 <= s[1] <= 1:
            intersections.append(s)
    return intersections

