                    with salt.utils.files.fopen(pubfn_denied, 'w+') as fp_:
                        fp_.write(load['pub'])
                    eload = {'result': False,
                             'id': load['id'],
                             'act': 'denied',
                             'pub': load['pub']}
                    if self.opts.get('auth_events') is True:
                        self.event.fire_event(eload, salt.utils.event.tagify(prefix='auth'))
