def hfoslog(*what, **kwargs):
    # Count all messages (missing numbers give a hint at too high log level)
    global count
    global verbosity
    count += 1
    lvl = kwargs.get('lvl', info)
    if lvl < verbosity['global']:
        return
    emitter = kwargs.get('emitter', 'UNKNOWN')
    traceback = kwargs.get('tb', False)
    frame_ref = kwargs.get('frame_ref', 0)
    output = None
    timestamp = time.time()
    runtime = timestamp - start
    callee = None
    exception = kwargs.get('exc', False)
    if exception:
        exc_type, exc_obj, exc_tb = sys.exc_info()  # NOQA
    if verbosity['global'] <= debug or traceback:
        # Automatically log the current function details.
        if 'sourceloc' not in kwargs:
            frame = kwargs.get('frame', frame_ref)
            # Get the previous frame in the stack, otherwise it would
            # be this function
            current_frame = inspect.currentframe()
            while frame > 0:
                frame -= 1
                current_frame = current_frame.f_back
            func = current_frame.f_code
            # Dump the message + the name of this function to the log.
            if exception:
                line_no = exc_tb.tb_lineno
                if lvl <= error:
                    lvl = error
            else:
                line_no = func.co_firstlineno
            callee = "[%.10s@%s:%i]" % (
                func.co_name,
                func.co_filename,
                line_no
            )
        else:
            callee = kwargs['sourceloc']
    now = time.asctime()
    msg = "[%s] : %5s : %.5f : %3i : [%5s]" % (now,
                                               lvldata[lvl][0],
                                               runtime,
                                               count,
                                               emitter)
    content = ""
    if callee:
        if not uncut and lvl > 10:
            msg += "%-60s" % callee
        else:
            msg += "%s" % callee
    for thing in what:
        content += " "
        if kwargs.get('pretty', False):
            content += pprint.pformat(thing)
        else:
            content += str(thing)
    msg += content
    if exception:
        msg += "\n" + "".join(format_exception(exc_type, exc_obj, exc_tb))
    if is_muted(msg):
        return
    if not uncut and lvl > 10 and len(msg) > 1000:
        msg = msg[:1000]
    if lvl >= verbosity['file']:
        try:
            f = open(logfile, "a")
            f.write(msg + '\n')
            f.flush()
            f.close()
        except IOError:
            print("Can't open logfile %s for writing!" % logfile)
            # sys.exit(23)
    if is_marked(msg):
        lvl = hilight
    if lvl >= verbosity['console']:
        output = str(msg)
        if six.PY3 and color:
            output = lvldata[lvl][1] + output + terminator
        try:
            print(output)
        except UnicodeEncodeError as e:
            print(output.encode("utf-8"))
            hfoslog("Bad encoding encountered on previous message:", e,
                    lvl=error)
        except BlockingIOError:
            hfoslog("Too long log line encountered:", output[:20], lvl=warn)
    if live:
        item = [now, lvl, runtime, count, emitter, str(content)]
        LiveLog.append(item)

def tbw(self, delegate_address, blacklist=None, share_fees=False, compound_interest=False):
        if not blacklist:
            blacklist = []
        delegate_public_key = self.account_details(address=delegate_address)['public_key']
        height_at_calculation = self.node_height_details()['height']
        # string format of the rawasset
        minvote = '{{"votes":["-{0}"]}}'.format(delegate_public_key)
        plusvote = '{{"votes":["+{0}"]}}'.format(delegate_public_key)
        events = self.get_events_vote_cluster(delegate_address)
        votes = self.get_historic_voters(delegate_address)
        blocks = self.get_blocks(delegate_address)

        # create a map of voters
        voter_dict = {}
        for voter in votes:
            voter_dict.update({voter: {
                'balance': 0.0,
                'status': False,
                'last_payout': votes[voter]['height'],
                'share': 0.0,
                'vote_height': votes[voter]['height'],
                'blocks_forged': []}
            })
        for blacklisted_address in blacklist:
            voter_dict.pop(blacklisted_address, None)
        last_payout = self.get_last_out_transactions(delegate_address)
        # not all voters have had a payout, thus a KeyError is thrown
        for payout in last_payout:
            try:
                voter_dict[payout]['last_payout'] = last_payout[payout]['height']
            except KeyError:
                pass
        # the change in the previous state of the voter_dict. This is added to the voterdict if
        # no state change occurs in the blockchain.
        delta_state = {}
        no_state_change = False
        block_keys = sorted(list(blocks.keys()))
        block_nr = 0
        try:
            for id in events:
                # calculating poolbalances and updating shares
                if events[id]['height'] > blocks[block_keys[block_nr]]['height']:
                    # if the state is the same for the votepool, the previous calculation can be reused.
                    block_nr += 1
                    if no_state_change:
                        for x in delta_state:
                            voter_dict[x]['share'] += delta_state[x]
                        continue
                    # update pool balances
                    poolbalance = 0
                    delta_state = {}
                    for i in voter_dict:
                        # here we update the poolbalance
                        if compound_interest:
                            balance = voter_dict[i]['balance'] + voter_dict[i]['share']
                        else:
                            balance = voter_dict[i]['balance']
                        if voter_dict[i]['status']:
                            # if not voter_dict[i]['balance'] < 0:
                            poolbalance += balance
                            # else:
                            #     raise exceptions.NegativeBalanceError('balance lower than zero for: {0}. balance: {1}'.format(i, voter_dict[i]['balance']))
                    # here we calculate the share per voter
                    for i in voter_dict:
                        if compound_interest:
                            balance = voter_dict[i]['balance'] + voter_dict[i]['share']
                        else:
                            balance = voter_dict[i]['balance']
                        if voter_dict[i]['status'] and voter_dict[i]['last_payout'] < blocks[block_keys[block_nr]]['height']:
                            if share_fees:
                                share = (balance / poolbalance) * (blocks[block_keys[block_nr]]['reward'] +
                                                                   blocks[block_keys[block_nr]]['totalFee'])
                            else:
                                share = (balance / poolbalance) * blocks[block_keys[block_nr]]['reward']
                            voter_dict[i]['share'] += share
                            delta_state.update({i: share})
                    no_state_change = True
                    continue
                # parsing an event
                no_state_change = False
                if events[id]['event_type'] == 'transaction':
                    if events[id]['recipient_id'] == 'Acw2vAVA48TcV8EnoBmZKJdV8bxnW6Y4E9':
                        print(events[id]['amount'])
                # parsing a transaction
                if events[id]['event_type'] == 'transaction':
                    if events[id]['recipient_id'] in voter_dict:
                        voter_dict[events[id]['recipient_id']]['balance'] += events[id]['amount']
                    if events[id]['sender_id'] in voter_dict:
                        voter_dict[events[id]['sender_id']]['balance'] -= (events[id]['amount'] + events[id]['fee'])
                    if events[id]['sender_id'] in voter_dict and events[id]['type'] == 3 and plusvote in events[id]['rawasset']:
                        voter_dict[events[id]['sender_id']]['status'] = True
                    if events[id]['sender_id'] in voter_dict and events[id]['type'] == 3 and minvote in events[id]['rawasset']:
                        voter_dict[events[id]['sender_id']]['status'] = False
                # parsing a forged block (if forged by a voter)
                if events[id]['event_type'] == 'block':
                    voter_dict[events[id]['address']]['balance'] += (events[id]['reward'] + events[id]['total_fee'])
            # the transaction for loop ends with the final transaction. However more blocks may be forged. This copies
            # the final delta share and adds it to the share x the amount of blocks left.
            remaining_blocks = len(block_keys) - block_nr - 1
            for i in range(remaining_blocks):
                for x in delta_state:
                    voter_dict[x]['share'] += delta_state[x]
            # and indexerror indicates that we have ran out of forged blocks, thus the calculation is done (blocks[block_nr]
            # throw the error)
        except IndexError:
            raise
        return voter_dict, height_at_calculation

def _present(name,
            block_icmp=None,
            prune_block_icmp=False,
            default=None,
            masquerade=False,
            ports=None,
            prune_ports=False,
            port_fwd=None,
            prune_port_fwd=False,
            services=None,
            # TODO: prune_services=False in future release
            # prune_services=False,
            prune_services=None,
            interfaces=None,
            prune_interfaces=False,
            sources=None,
            prune_sources=False,
            rich_rules=None,
            prune_rich_rules=False):
    ret = {'name': name,
           'result': False,
           'changes': {},
           'comment': ''}
    try:
        zones = __salt__['firewalld.get_zones'](permanent=True)
    except CommandExecutionError as err:
        ret['comment'] = 'Error: {0}'.format(err)
        return ret
    if name not in zones:
        if not __opts__['test']:
            try:
                __salt__['firewalld.new_zone'](name)
            except CommandExecutionError as err:
                ret['comment'] = 'Error: {0}'.format(err)
                return ret
        ret['changes'].update({name:
                                {'old': zones,
                                'new': name}})
    if block_icmp or prune_block_icmp:
        block_icmp = block_icmp or []
        new_icmp_types = []
        old_icmp_types = []
        try:
            _current_icmp_blocks = __salt__['firewalld.list_icmp_block'](name,
                permanent=True)
        except CommandExecutionError as err:
            ret['comment'] = 'Error: {0}'.format(err)
            return ret
        if block_icmp:
            try:
                _valid_icmp_types = __salt__['firewalld.get_icmp_types'](
                    permanent=True)
            except CommandExecutionError as err:
                ret['comment'] = 'Error: {0}'.format(err)
                return ret
            # log errors for invalid ICMP types in block_icmp input
            for icmp_type in set(block_icmp) - set(_valid_icmp_types):
                log.error('%s is an invalid ICMP type', icmp_type)
                block_icmp.remove(icmp_type)
            new_icmp_types = set(block_icmp) - set(_current_icmp_blocks)
            for icmp_type in new_icmp_types:
                if not __opts__['test']:
                    try:
                        __salt__['firewalld.block_icmp'](name, icmp_type,
                                                         permanent=True)
                    except CommandExecutionError as err:
                        ret['comment'] = 'Error: {0}'.format(err)
                        return ret
        if prune_block_icmp:
            old_icmp_types = set(_current_icmp_blocks) - set(block_icmp)
            for icmp_type in old_icmp_types:
                # no need to check against _valid_icmp_types here, because all
                # elements in old_icmp_types are guaranteed to be in
                # _current_icmp_blocks, whose elements are inherently valid
                if not __opts__['test']:
                    try:
                        __salt__['firewalld.allow_icmp'](name, icmp_type,
                                                         permanent=True)
                    except CommandExecutionError as err:
                        ret['comment'] = 'Error: {0}'.format(err)
                        return ret
        if new_icmp_types or old_icmp_types:
            # If we're not pruning, include current items in new output so it's clear
            # that they're still present
            if not prune_block_icmp:
                block_icmp = list(new_icmp_types | set(_current_icmp_blocks))
            ret['changes'].update({'icmp_types':
                                    {'old': _current_icmp_blocks,
                                    'new': block_icmp}})
    # that's the only parameter that can't be permanent or runtime, it's
    # directly both
    if default:
        try:
            default_zone = __salt__['firewalld.default_zone']()
        except CommandExecutionError as err:
            ret['comment'] = 'Error: {0}'.format(err)
            return ret
        if name != default_zone:
            if not __opts__['test']:
                try:
                    __salt__['firewalld.set_default_zone'](name)
                except CommandExecutionError as err:
                    ret['comment'] = 'Error: {0}'.format(err)
                    return ret
            ret['changes'].update({'default':
                                  {'old': default_zone,
                                   'new': name}})
    try:
        masquerade_ret = __salt__['firewalld.get_masquerade'](name,
            permanent=True)
    except CommandExecutionError as err:
        ret['comment'] = 'Error: {0}'.format(err)
        return ret
    if masquerade and not masquerade_ret:
        if not __opts__['test']:
            try:
                __salt__['firewalld.add_masquerade'](name, permanent=True)
            except CommandExecutionError as err:
                ret['comment'] = 'Error: {0}'.format(err)
                return ret
        ret['changes'].update({'masquerade':
                              {'old': '',
                               'new': 'Masquerading successfully set.'}})
    elif not masquerade and masquerade_ret:
        if not __opts__['test']:
            try:
                __salt__['firewalld.remove_masquerade'](name,
                                                        permanent=True)
            except CommandExecutionError as err:
                ret['comment'] = 'Error: {0}'.format(err)
                return ret
        ret['changes'].update({'masquerade':
                              {'old': '',
                               'new': 'Masquerading successfully '
                               'disabled.'}})
    if ports or prune_ports:
        ports = ports or []
        try:
            _current_ports = __salt__['firewalld.list_ports'](name, permanent=True)
        except CommandExecutionError as err:
            ret['comment'] = 'Error: {0}'.format(err)
            return ret
        new_ports = set(ports) - set(_current_ports)
        old_ports = []
        for port in new_ports:
            if not __opts__['test']:
                try:
                    # TODO: force_masquerade to be removed in future release
                    __salt__['firewalld.add_port'](name, port, permanent=True, force_masquerade=False)
                except CommandExecutionError as err:
                    ret['comment'] = 'Error: {0}'.format(err)
                    return ret
        if prune_ports:
            old_ports = set(_current_ports) - set(ports)
            for port in old_ports:
                if not __opts__['test']:
                    try:
                        __salt__['firewalld.remove_port'](name, port, permanent=True)
                    except CommandExecutionError as err:
                        ret['comment'] = 'Error: {0}'.format(err)
                        return ret
        if new_ports or old_ports:
            # If we're not pruning, include current items in new output so it's clear
            # that they're still present
            if not prune_ports:
                ports = list(new_ports | set(_current_ports))
            ret['changes'].update({'ports':
                                    {'old': _current_ports,
                                    'new': ports}})
    if port_fwd or prune_port_fwd:
        port_fwd = port_fwd or []
        try:
            _current_port_fwd = __salt__['firewalld.list_port_fwd'](name,
                                                                    permanent=True)
        except CommandExecutionError as err:
            ret['comment'] = 'Error: {0}'.format(err)
            return ret
        port_fwd = [_parse_forward(fwd) for fwd in port_fwd]
        _current_port_fwd = [
            ForwardingMapping(
                srcport=fwd['Source port'],
                destport=fwd['Destination port'],
                protocol=fwd['Protocol'],
                destaddr=fwd['Destination address']
            ) for fwd in _current_port_fwd]
        new_port_fwd = set(port_fwd) - set(_current_port_fwd)
        old_port_fwd = []
        for fwd in new_port_fwd:
            if not __opts__['test']:
                try:
                    # TODO: force_masquerade to be removed in future release
                    __salt__['firewalld.add_port_fwd'](name, fwd.srcport,
                        fwd.destport, fwd.protocol, fwd.destaddr, permanent=True,
                        force_masquerade=False)
                except CommandExecutionError as err:
                    ret['comment'] = 'Error: {0}'.format(err)
                    return ret
        if prune_port_fwd:
            old_port_fwd = set(_current_port_fwd) - set(port_fwd)
            for fwd in old_port_fwd:
                if not __opts__['test']:
