import pyproj

def from_proj4(proj4, strict=False):
    if isinstance(proj4, str):
        proj4 = dict(item.split('=') for item in proj4.split(' +'))

    if strict:
        # If strict, check that all keys and values match exactly
        crs = pyproj.CRS.from_string(str(proj4))
    else:
        # If not strict, convert keys and values to lowercase
        proj4 = {k.lower(): v.lower() for k, v in proj4.items()}
        crs = pyproj.CRS.from_string(str(proj4))

    return crs

