def dpll_satisfiable(sentence):
    symbols = list(prop_symbols(sentence))
    return dpll(sentence, symbols, {}) if isinstance(sentence, Expr) else dpll_cnf(cnf(sentence), symbols, {})


def dpll_cnf(clauses, symbols, model):
    unknown_clauses = [c for c in clauses if c not in model.keys()]
    # checks if there are empty clauses and returns False
    if set() in unknown_clauses:
        return False
    # if all clauses are true in the current model, return model
    if not unknown_clauses:
        return model
    # check if any pure symbols exist in unknown_clauses
    pure_symbol, value = find_pure_symbol(unknown_clauses, symbols, model)
    if pure_symbol:
        model[pure_symbol] = value
        return dpll_cnf(clauses, remove_all(pure_symbol, symbols), model)
    # check if any unit clauses exist in unknown_clauses
    unit_clause, value = find_unit_clause(unknown_clauses, model)
    if unit_clause:
        model[unit_clause] = value
        return dpll_cnf(clauses, remove_all(unit_clause, symbols), model)
    # if we reach this point, we need to guess a symbol and try both possible values recursively
    P, value = symbols[0], True
    return (dpll_cnf(clauses, symbols[1:], extend(model, P, value)) or
            dpll_cnf(clauses, symbols[1:], extend(model, P, not value)))


def find_pure_symbol(clauses, symbols, model):
    for s in symbols:
        found_pos, found_neg = False, False
        for c in clauses:
            if model.get(s) == True or s in c.args:
                found_pos = True
            if model.get(s) == False or ~s in c.args:
                found_neg = True
            if found_pos and found_neg:
                break
        if found_pos != found_neg:
            return s, found_pos
    return None, None


def find_unit_clause(clauses, model):
    for c in clauses:
        if len(c.args) == 1:
            P = c.args[0]
            value = (not c.op) if P in prop_symbols(c) else c.op
            if P not in model:
                return P, value
    return None, None


def extend(s, var, val):
    out = s.copy()
    out[var] = val
    return out


def remove_all(items, seq):
    return [x for x in seq if x != items]

