from typing import List, Optional

class zdir_patch_t:
    def __init__(self, patch: List[str], alias: Optional[str]=None):
        self.patch = patch
        self.alias = alias

def calculate_directory_diff(older: Optional[List[str]], newer: Optional[List[str]], alias: Optional[str]=None) -> List[zdir_patch_t]:
    if older is None and newer is None:
        # Directory is absent
        return []

    patches = []
    if older is None:
        # Newly added directory
        patches.append(zdir_patch_t(newer, alias))
    elif newer is None:
        # Deleted directory
        patches.append(zdir_patch_t(['-' + f for f in older], alias))
    else:
        # Calculate differences
        old_set = set(older)
        new_set = set(newer)
        added = new_set - old_set
        removed = old_set - new_set
        modified = set()
        for file in old_set.intersection(new_set):
            if file in added or file in removed:
                continue
            with open(file) as old_file, open(file) as new_file:
                if old_file.read() != new_file.read():
                    modified.add(file)

        # Generate patches
        if added:
            patches.append(zdir_patch_t(['+' + f for f in added], alias))
        if removed:
            patches.append(zdir_patch_t(['-' + f for f in removed], alias))
        if modified:
            patches.append(zdir_patch_t(['*' + f for f in modified], alias))

    return patches

