def deriv(f, c, dx=0.0001):
    return (f(c + dx) - f(c - dx)) / (2 * dx)

    def deriv2(f, c, dx=0.0001):
        """deriv2(f,c,dx)  --> float

        Returns f''(x), computed as a symmetric difference quotient."""
        return (deriv(f, c + dx, dx) - deriv(f, c - dx, dx)) / (2 * dx)

    def deriv3(f, c, dx=0.0001):
        """deriv3(f,c,dx)  --> float

        Returns f'''(x), computed as a symmetric difference quotient."""
        return (deriv2(f, c + dx, dx) - deriv2(f, c - dx, dx)) / (2 * dx)

    def deriv4(f, c, dx=0.0001):
        """deriv4(f,c,dx)  --> float

        Returns f''''(x), computed as a symmetric difference quotient."""
        return (deriv3(f, c + dx, dx) - deriv3(f, c - dx, dx)) / (2 * dx)

    def deriv5(f, c, dx=0.0001):
        """deriv5(f,c,dx)  --> float

        Returns f'''''(x), computed as a symmetric difference quotient."""
        return (deriv4(f, c + dx, dx) - deriv4(f, c - dx, dx)) / (2 * dx)

    def deriv6(f, c, dx=0.0001):
        """deriv6(f,c,dx)  --> float

        Returns f''''''(x), computed as a symmetric difference quotient."""
        return (deriv5(f, c + dx, dx) - deriv5(f, c - dx, dx)) / (2 * dx)

    def deriv7(f, c, dx=0.0001):
        """deriv7(f,c,dx)  --> float

        Returns f'''''''(x), computed as a symmetric difference quotient."""
        return (deriv6(f, c + dx, dx) - deriv6(f, c - dx, dx)) / (2 * dx)

