def format_gff(gff_file):
    with open(gff_file, 'r') as file:
        lines = file.readlines()

    formatted_lines = []
    for line in lines:
        if line.startswith('#'):
            continue
        fields = line.strip().split('\t')
        fields[0] = 'new_seqid'  # Change seqid
        formatted_lines.append('\t'.join(fields))

    return '\n'.join(formatted_lines)


