def rewrite_elife_datasets_json(json_content, doi):
    import json
    import re
    data = json.loads(json_content)

    def update_doi_in_json(obj, doi):
        if isinstance(obj, dict):
            for (key, value) in obj.items():
                if key == 'doi':
                    obj[key] = doi
                else:
                    update_doi_in_json(value, doi)
        elif isinstance(obj, list):
            for item in obj:
                update_doi_in_json(item, doi)
    update_doi_in_json(data, doi)

    def clean_json(obj):
        if isinstance(obj, dict):
            return {k: clean_json(v) for (k, v) in obj.items() if v is not None and v != ''}
        elif isinstance(obj, list):
            return [clean_json(item) for item in obj if item is not None and item != '']
        else:
            return obj
    cleaned_data = clean_json(data)
    cleaned_json_content = json.dumps(cleaned_data, indent=4)
    return cleaned_json_content
