def Match_Adsorbate_structures_with_reaction_entries(adsorbate_structure, reaction_entries):
    """
    Match adsorbate structures with reaction entries
    :param adsorbate_structure: A dictionary of adsorbate structures
    :param reaction_entries: A list of reaction entries
    :return: A list of matched reaction entries
    """
    matched_entries = []
    for entry in reaction_entries:
        for reactant in entry.reactants:
            for species in reactant.species:
                if species.to_dict() == adsorbate_structure:
                    matched_entries.append(entry)
                    break
    return matched_entries

