def generate_script(attrs: list, frozen: bool) -> tuple:
    if frozen:
        setter = 'object.__setattr__(self, "{attr}", value)\n'
    else:
        setter = 'self.{attr} = value\n'

    script_lines = ['class __Initializer:\n']
    globals_dict = {}
    for attr in attrs:
        script_lines.append(f'    def set_{attr}(self, value):\n        {setter.format(attr=attr)}')
        globals_dict[f'set_{attr}'] = getattr(__Initializer, f'set_{attr}')

    script_lines.append(f'\nattrs = {attrs}')
    script_lines.append(f'globals().update({globals_dict})')
    return ''.join(script_lines), globals_dict

