import numpy as np
from scipy.optimize import curve_fit

def fit_fid(fid, model, baseline_points):
    x = np.arange(len(fid))
    x = x[baseline_points:]
    y = fid[baseline_points:]
    def func(x, *params):
        return model["func"](x, *params)
    popt, pcov = curve_fit(func, x, y, **model["fit_args"])
    model["params"] = popt
    y_fit = func(x, *popt)
    residuals = y - y_fit
    s_sq = (residuals**2).sum()/(len(y)-len(popt))
    try:
        pcov = np.abs(np.diag(pcov))
    except TypeError as e:
        pcov = np.abs(np.diag(np.zeros(len(model["params"]))))
    pcov = pcov*s_sq
    model["se"] = np.sqrt(pcov)
    return {"model": model, "fit": {"x": x, "y": y_fit}, "err": {"residuals": residuals, "s_sq": s_sq}}

