def cast_new_model(prev_model, wavelength_range=None, channels=None, sampling=None, resolution=None):
    new_model = prev_model.copy()

    if wavelength_range is not None:
        new_model = new_model.slice_by_wave_range(wavelength_range)

    if channels is not None:
        new_model = new_model.change_channels(channels)

    if sampling is not None:
        new_model = new_model.rebin(sampling)

    if resolution is not None:
        new_model = new_model.convolve(resolution)

