def get_latex(circuit, aliases=None):
    if aliases is None:
        latex_array = circuit.draw(output='text').strip().split('\n')
    else:
        new_qubits = []
        for qubit in circuit.qubits:
            if qubit.name not in aliases:
                new_qubits.append(qubit)
        for qubit_alias in aliases.values():
            new_qubits.append(circuit.qubits[aliases.index(qubit_alias)])
        new_qubits.sort(key=lambda x: int(x.name[1:]))
        circuit_renamed = QuantumCircuit(*[qb.register for qb in new_qubits])
        qubit_mapping = {qubit.name: circuit_renamed.qubits[i] for i, qubit in enumerate(new_qubits)}
        for gate in circuit.data:
            new_qargs = [qubit_mapping[qubit.name] for qubit in gate.qargs]
            new_cargs = gate.cargs
            new_op = gate.op.copy()
            circuit_renamed.append(new_op, new_qargs, new_cargs)
        latex_array = circuit_renamed.draw(output='text').strip().split('\n')
    latex_array = [line.replace('→', '\\rightarrow') for line in latex_array]
    latex_array = [line.replace('⇒', '\\Rightarrow') for line in latex_array]
    latex_array = [line.replace('⦿', '\\odot') for line in latex_array]
    return latex_array

