def min_assignment_cost(cost_matrix):
    import sys
    n = len(cost_matrix)
    m = len(cost_matrix[0])
    if n != m:
        raise ValueError("Cost matrix should be square")
    # col j of row_assignment records the assignment for row j
    # (if row j is unassigned, row_assignment[j] = None)
    # the format of this list will do for our purposes, but we
    # will convert it to a dictionary later for faster look-ups
    row_assignment = [None] * n

    # col j of col_covered is a boolean indicating whether column j is covered
    col_covered = [False] * m

    # row i of row_covered is a boolean indicating whether row i is covered
    row_covered = [False] * n

    # find minimum cost of each row
    row_mins = [min(row) for row in cost_matrix]

    # subtract row minimum from each element in row i
    for i in range(n):
        cost_matrix[i] = [cost - row_mins[i] for cost in cost_matrix[i]]

    # find minimum cost of each column
    col_mins = []
    for j in range(m):
        col_vals = [cost_matrix[i][j] for i in range(n)]
        col_mins.append(min(col_vals))

    # subtract column minimum from each element in column j
    for j in range(m):
        for i in range(n):
            cost_matrix[i][j] -= col_mins[j]

    # main loop
    while True:
        # convert row assignment list to a dictionary for faster look-ups
        row_assignment_dict = {}
        for row, col in enumerate(row_assignment):
            if col is not None:
                row_assignment_dict[row] = col

        # find an uncovered row index
        uncovered_i = None
        for i, covered in enumerate(row_covered):
            if not covered:
                uncovered_i = i
                break

        if uncovered_i is None:
            # all rows are covered; we're done
            break

        # initialize alternate path list with just the uncovered row index
        path = [(uncovered_i, None)]

        # initialize a set of visited nodes
        visited = set()

        while True:
            # find an unchecked column index in the current row
            i, j_prev = path[-1]
            j = None
            for col in range(m):
                if col_covered[col]:
                    continue
                if cost_matrix[i][col] == 0:
                    j = col
                    break
            if j is not None:
                # found unchecked column; add to augmenting path
                path.append((i, j))
                col_covered[j] = True
                row = row_assignment_dict.get(i)
                if row is None:
                    # found unassigned row; alternate path has been found
                    break
                path.append((row, j))
                row_covered[row] = True
            else:
                if len(path) == 1:
                    # couldn't find unchecked column; no alternating path exists
                    break
                # remove the last node from the alternating path
                path.pop()
                # remove the last node's column from col_covered
                col_covered[path[-1][1]] = False
                # mark the last node's row as covered (since we removed the node from an
                # augmenting path, which means its row now has one fewer assigned column)
                row_covered[path[-1][0]] = True
                # continue augmenting path from the new last node's row
                visited.add(path[-1][0])

        if len(path) == 1:
            # couldn't find alternating path; set up for another iteration
            min_val = sys.maxsize
            for i in range(n):
                if i in visited:
                    for j in range(m):
                        if not col_covered[j]:
                            val = cost_matrix[i][j]
                            if val < min_val:
                                min_val = val
            for i in range(n):
                if row_covered[i]:
                    row_mins[i] += min_val
                for j in range(m):
                    if col_covered[j]:
                        col_mins[j] -= min_val
                    else:
                        cost_matrix[i][j] -= min_val
        else:
            # found alternating path; augment along path
            for i, j in path:
                row_assignment[i] = j
                col_covered[j] = True
                row_covered[i] = False

    # calculate optimal assignment cost
    cost = 0
    for i, j in enumerate(row_assignment):
        if j is not None:
            cost += cost_matrix[i][j]
    return cost

