def pformat(self, indent=4):
    lines = self.string.split('\n')
    formatted_lines = []
    for line in lines:
        if '=' in line:
            parts = line.split('=')
            formatted_line = '{}{}{}{}'.format(
                ' ' * indent,
                parts[0].strip(),
                ' ' * (indent - len(parts[0].strip())),
                '={}'.format(parts[1].strip())
            )
            formatted_lines.append(formatted_line)
        else:
            formatted_lines.append(line)
    return '\n'.join(formatted_lines)

