def decode(self, msgbuf):
    if not msgbuf:
        return None
    msgid = struct.unpack('<H', msgbuf[0:2])[0]
    msg = self.mavlink_map[msgid]
    if not msg:
        return None
    msg.unpack(msgbuf)
    return msg

