from asciitree.drawing import ASCENT, DESCENT, HEIGHT, LEFT_LABEL_OFFSET

def draw_tree(tree, childattr='children', nameattr='name', formatter=str,
              nodestyle=None, horizontal=False, indent=4, draw=print):
    if nodestyle is None:
        nodestyle = BOX_LIGHT

    if horizontal:
        lines = _draw_horizontal_tree_(tree, childattr, nameattr, formatter,
                                        nodestyle, indent)
    else:
        lines = _draw_vertical_tree_(tree, childattr, nameattr, formatter,
                                        nodestyle, indent)

    for line in lines:
        draw(line)


def _draw_vertical_tree_(tree, childattr, nameattr, formatter, nodestyle, indent):
    box = BoxStyle(gfx=BOX_LIGHT, horiz_len=1)

    def _height(node):
        h = 1
        for child in getattr(node, childattr):
            h = max(h, _height(child) + 1)
        return h

    def _traverse(node, depth):
        children = list(getattr(node, childattr))
        name = getattr(node, nameattr)
        if formatter:
            name = formatter(name)
        appended = False
        if children:
            first_child = children.pop(0)
            appended = True
            _traverse(first_child, depth + 1)
            for child in children:
                _traverse(child, depth + 1)
        stem = ''
        if depth > 0:
            stem += ' ' * ((depth - 1) * indent)
            if appended:
                stem += '+'
            else:
                stem += '\\'
            stem += '-' * indent
        height = _height(node)
        line = stem + box.horiz[0] * (indent - 1 + NODE_WIDTH)
        label = LINE_VERT + ' ' * (NODE_WIDTH - 2) + LINE_VERT
        lines = ['', nodestyle.draw(label, name)]
        for i in range(2, height + 1):
            lines.append(stem + '|' + ' ' * (indent - 1) + LINE_VERT)
        return lines

    if len(tree) == 1:
        if childattr:
            root = list(tree)[0]
            children = list(getattr(root, childattr))
            name = getattr(root, nameattr)
            if formatter:
                name = formatter(name)
            height = _height(root)
            lines = [nodestyle.draw(' ' * indent + BOX_LIGHT.hori_single * NODE_WIDTH,
                                    name)]
            for i in range(1, height):
                lines.append(' ' * indent + '|')
            for child in children:
                for line in _traverse(child, 2):
                    lines.append(line)
            return lines
        else:
            return []

    else:
        lines = []
        first = next(iter(tree))
        for child in getattr(first, childattr):
            for line in _traverse(child, 1):
                lines.append(line)
        for node in sorted(tree, key=lambda n: getattr(n, nameattr)):
            lines.append('')
            for line in _traverse(node, 1):
                lines.append(line)
        return lines


def _draw_horizontal_tree_(tree, childattr, nameattr, formatter, nodestyle, indent):
    box = BoxStyle(gfx=BOX_LIGHT, horiz_len=1)

    def _max_depth(node, depth=0):
        if not getattr(node, childattr):
            return depth
        else:
            return max(_max_depth(child, depth + 1) for child in getattr(node, childattr))

    def _traverse(node, lefts, rights, depth):
        """
        This function returns a list of strings, representing lines to be displayed.
        `lefts` and `rights` are the positions of the left and rightmost nodes
        for each depth, these are used to position parent nodes.
        """
        children = list(getattr(node, childattr))
        name = getattr(node, nameattr)
        if formatter:
            name = formatter(name)

        # Draw the node
        position = lefts[depth] + len(rights[depth]) + 1
        lines = [nodestyle.draw(' ' * position + BOX_LIGHT.up +
                                BOX_LIGHT.horiz_single * (NODE_WIDTH - 1),
                                name)]

        # If Heirarchy has been exhausted
        if not children:
            return lines

        # Calculate next gen left and right
        next_depth = depth + 1
        nextlefts = lefts[:]
        nextlefts.append(position + 1)
        nextrights = []
        for child in children[:-1]:
            right = nextlefts[-1] + len(rights[next_depth]) + NODE_WIDTH - 1
            nextrights.append(' ' * (right - position) + BOX_LIGHT.vertical)
            for line in _traverse(child, nextlefts, nextrights, next_depth):
                lines.append(line)
            nextlefts[-1] = right - NODE_WIDTH + 1
            nextright = right + (indent * NODE_WIDTH) - NODE_WIDTH
            nextrights.append(' ' * (nextright - right + 1) + BOX_LIGHT.junction)

        #The last child closes the last ancestor's sub hierarchy,
        #so both right and left need to be adjusted
        right = nextlefts[-1] + len(rights[next_depth]) + NODE_WIDTH - 1
        nextrights.append(' ' * (right - position) + BOX_LIGHT.vertical)

        for line in _traverse(children[-1], nextlefts, nextrights, next_depth):
            lines.append(line)

        i = next_depth + 1
        while i < len(lefts) and not rights[i]:
            rights[i] = ' ' * (nextlefts[i] - len(rights[i - 1])) + BOX_LIGHT.vertical
            i += 1

        return lines

    lefts = ['']
    rights = ['']

    maxdepth = _max_depth(next(iter(tree)))
    for i in range(maxdepth):
        lefts.append('')
        rights.append('')

    for node in sorted(tree, key=lambda n: getattr(n, nameattr)):
        for line in _traverse(node, lefts, rights, 0):
            yield line
        for i in range(maxdepth + 1):
            lefts[i] = lefts[i] + ' ' * indent + BOX_LIGHT.vertical
            rights[i] = rights[i] + ' ' * indent + ' '

    return lines

