def unicode_parser(input_unicode):
    # Convert unicode into standard form
    standard_unicode = input_unicode.encode('raw_unicode_escape').decode('utf-8')
    # Convert each character of the unicode symbol to its numerical equivalent
    char_codes = [str(ord(char)) for char in standard_unicode]
    # Join all char codes to form a single string
    numerical_unicode = ''.join(char_codes)
    # Initialize the dictionaries
    pattern_dict = {'some_key': 'some_value'}
    emoticon_dict = {'some_key': 'some_value'}
    direct_dict = {'some_key': 'some_value'}
    # Check in pattern dictionary to map suffix/prefix
    if numerical_unicode in pattern_dict:
        mapped_value = pattern_dict[numerical_unicode]
    # Check Emoticon Dictionary 
    elif numerical_unicode in emoticon_dict:
        mapped_value = emoticon_dict[numerical_unicode]
    else:
        # Replace value pair with Key whenever found
        for key, value in direct_dict.items():
            if value == numerical_unicode:
                mapped_value = key
                break
        else:
            # Append to .txt file if unicode not found in any dictionary
            with open('unicode_not_found.txt', 'a') as f:
                f.write(numerical_unicode + '\n')
            mapped_value = None
    return mapped_value

