def decode_unicode(data, replace_boo=True):
    pattern_dict = {'\\u': 'U+', 'U+': 'U+'}
    emoticon_dict = {'U+1F600': '😀', 'U+1F601': '😁'}
    direct_dict = {'U+0041': 'A', 'U+0042': 'B'}
    if replace_boo:
        for (key, value) in pattern_dict.items():
            data = data.replace(key, value)
    unicode_list = data.split()
    mapped_list = []
    for unicode_symbol in unicode_list:
        if unicode_symbol in pattern_dict.values():
            mapped_list.append(unicode_symbol)
            continue
        if unicode_symbol in emoticon_dict:
            mapped_list.append(emoticon_dict[unicode_symbol])
            continue
        if unicode_symbol in direct_dict:
            mapped_list.append(direct_dict[unicode_symbol])
            continue
        with open('unicode_not_found.txt', 'a') as file:
            file.write(unicode_symbol + '\n')
        mapped_list.append(unicode_symbol)
    return ' '.join(mapped_list)

