from pyarrow import schema as pa_schema
from pyspark.sql.types import StructType, StructField, StringType, IntegerType, DoubleType, FloatType, BooleanType, TimestampType, LongType, ShortType, ByteType, BinaryType, DateType, DecimalType, ArrayType, MapType

def spark_schema_to_arrow_schema(spark_schema: StructType) -> pa_schema:
    arrow_fields = []

    for field in spark_schema.fields:
        if isinstance(field.dataType, StringType):
            arrow_fields.append(pa_schema.field(field.name, pa.string()))
        elif isinstance(field.dataType, IntegerType):
            arrow_fields.append(pa_schema.field(field.name, pa.int32()))
        elif isinstance(field.dataType, DoubleType):
            arrow_fields.append(pa_schema.field(field.name, pa.float64()))
        elif isinstance(field.dataType, FloatType):
            arrow_fields.append(pa_schema.field(field.name, pa.float32()))
        elif isinstance(field.dataType, BooleanType):
            arrow_fields.append(pa_schema.field(field.name, pa.bool_()))
        elif isinstance(field.dataType, TimestampType):
            arrow_fields.append(pa_schema.field(field.name, pa.timestamp('s')))
        elif isinstance(field.dataType, LongType):
            arrow_fields.append(pa_schema.field(field.name, pa.int64()))
        elif isinstance(field.dataType, ShortType):
            arrow_fields.append(pa_schema.field(field.name, pa.int16()))
        elif isinstance(field.dataType, ByteType):
            arrow_fields.append(pa_schema.field(field.name, pa.int8()))
        elif isinstance(field.dataType, BinaryType):
            arrow_fields.append(pa_schema.field(field.name, pa.binary()))
        elif isinstance(field.dataType, DateType):
            arrow_fields.append(pa_schema.field(field.name, pa.date32()))
        elif isinstance(field.dataType, DecimalType):
            arrow_fields.append(pa_schema.field(field.name, pa.decimal128(field.dataType.precision, field.dataType.scale)))
        elif isinstance(field.dataType, ArrayType):
            element_type = spark_sql_type_to_arrow(field.dataType.elementType)
            arrow_fields.append(pa_schema.field(field.name, pa.list_(element_type)))
        elif isinstance(field.dataType, MapType):
            key_type = spark_sql_type_to_arrow(field.dataType.keyType)
            value_type = spark_sql_type_to_arrow(field.dataType.valueType)
            arrow_fields.append(pa_schema.field(field.name, pa.map_(key_type, value_type)))

    return pa_schema(arrow_fields)

