def is_integer(value):
    return isinstance(value, int)

    def is_float(value):
        """Return true if a value is a float number."""
        return isinstance(value, float)

    def is_number(value):
        """Return true if a value is a number (either integer or float)."""
        return isinstance(value, (int, float))

    def is_string(value):
        """Return true if a value is a string."""
        return isinstance(value, str)

    def is_list(value):
        """Return true if a value is a list."""
        return isinstance(value, list)

    def is_dict(value):
        """Return true if a value is a dictionary."""
        return isinstance(value, dict)

    def is_tuple(value):
        """Return true if a value is a tuple."""
        return isinstance(value, tuple)

    def is_set(value):
        """Return true if a value is a set."""
        return isinstance(value, set)

    def is_frozenset(value):
        """Return true if a value is a frozenset."""
        return isinstance(value, frozenset)

    def is_bool(value):
        """Return true if a value is a boolean."""
        return isinstance(value, bool)

    def is_none(value):
        """Return true if a value is None."""
        return value is None

    def is_callable(value):
        """Return true if a value is callable."""
        return callable(value)

    def is_iterable(value):
        """Return true if a value is iterable."""
        try:
