def _get_value_(cls, value):
    """Retrieve the value from the class if it exists."""
    if value in cls.__dict__:
        return cls.__dict__[value]
    else:
        return _missing_(cls, value)

def _set_value_(cls, key, value):
    """Set the value in the class."""
    cls.__dict__[key] = value

class Meta(type):

