def dump_dict(self, dump=None):
    if dump is None:
        dump = {}
    for (key, value) in self.__dict__.items():
        if isinstance(value, dict):
            dump[key] = {}
            self.dump_dict(dump[key], value)
        elif isinstance(value, list):
            dump[key] = []
            for item in value:
                if isinstance(item, dict):
                    new_dict = {}
                    self.dump_dict(new_dict, item)
                    dump[key].append(new_dict)
                else:
                    dump[key].append(item)
        else:
            dump[key] = value
    return dump

