def request_instance(vm_=None, call=None):
    if vm_ is None:
        vm_ = {}
    if call is None:
        call = 'function'
    if call == 'function':
        if 'aws_access_key_id' not in vm_ or 'aws_secret_access_key' not in vm_:
            raise ValueError('AWS credentials are required')
        if 'instance_type' not in vm_ or 'image_id' not in vm_:
            raise ValueError('Instance type and image ID are required')
        session = boto3.Session(aws_access_key_id=vm_['aws_access_key_id'], aws_secret_access_key=vm_['aws_secret_access_key'])
        ec2 = session.resource('ec2')
        instance = ec2.create_instances(ImageId=vm_['image_id'], InstanceType=vm_['instance_type'], MinCount=1, MaxCount=1)[0]
        instance.wait_until_running()
        instance.reload()
        return {'instance_id': instance.id, 'public_ip': instance.public_ip_address, 'private_ip': instance.private_ip_address, 'state': instance.state['Name']}
    else:
        raise ValueError('Unsupported call type')

