def get_weather_power_tstat(self, site, start, end, data_type=['weather', 'power']):
        m = dataclient.MDALClient("corbusier.cs.berkeley.edu:8088")
        request = {
            "Variables": {
                "greenbutton": {
                    "Definition": """SELECT ?meter ?meter_uuid FROM %s WHERE {
