                get_code=True):
    if code_objects is None:
        code_objects = {}
    timestamp = 0
    try:
        magic = fp.read(4)
        magic_int = magics.magic2int(magic)
        # For reasons I don't understand, PyPy 3.2 stores a magic
        # of '0'...  The two values below are for Python 2.x and 3.x respectively
        if magic[0:1] in ['0', b'0']:
