from django import template
register = template.Library()

operators = {
    '=': lambda a, b: a == b,
    '==': lambda a, b: a == b,
    '!=': lambda a, b: a != b,
    '<=': lambda a, b: a <= b,
    '>=': lambda a, b: a >= b,
    '>': lambda a, b: a > b,
    '<': lambda a, b: a < b,
    'in': lambda a, b: a in b,
    'or': lambda a, b: a or b,
    'and': lambda a, b: a and b,
}

@register.tag(name="smart_if")
def smart_if(parser, token):
    """
    A smarter {% if %} tag for django templates.
    While retaining current Django functionality, it also handles equality, greater
    than and less than operators. Some common case examples:

    {% if articles|length >= 5 %}...{% endif %}
    {% if "ifnotequal tag" != "beautiful" %}...{% endif %}

    Arguments and operators _must_ have a space between them, so
    {% if 1>2 %} is not a valid smart if tag

    All supported operators are: or, and, in, = (or ==), !=, >, >=, < and <=.
    """
    bits = token.split_contents()[1:]

    comparisons = []
    logical_operators = []

    for bit in bits:
        if bit.lower() in operators:
            logical_operators.append(bit.lower())
        else:
            comparisons.append(bit)

    if comparisons and logical_operators:
        return SmartIfComparison(comparisons, logical_operators)
    else:
        return template.TemplateSyntaxError("Invalid smart if syntax.")


class SmartIfComparison(template.Node):
    def __init__(self, comparisons, logical_operators):
        self.comparisons = comparisons
        self.logical_operators = logical_operators

    def __repr__(self):
        return "<SmartIfComparison node>"

    def _evaluate(self, comparison):
        try:
            return int(comparison)
        except ValueError:
            try:
                return float(comparison)
            except ValueError:
                return comparison

    def _resolve(self, variable, context):
        """
        Resolve a variable out of the context
        """
        try:
            return template.Variable(variable).resolve(context)
        except template.VariableDoesNotExist:
            return variable

    def _evaluate_as_var(self, val, context):
        if val.isdigit():
            return self._evaluate(val)
        return self._resolve(val, context)

    def _evaluate_as_bool(self, val, context):
        return val.lower() == 'true'

    def _operate(self, op, val1, val2):
        op_func = operators.get(op.lower())
        if op_func:
            return op_func(val1, val2)
        else:
            raise ValueError("Invalid operator %s" % op)

    def render(self, context):
        try:
            var1 = self._evaluate_as_var(self.comparisons[0], context)
        except ValueError:
            raise template.TemplateSyntaxError("The left part of your smart if statement is not a valid variable.")
        except IndexError:
            raise template.TemplateSyntaxError("Your smart if statement is not valid: missing argument(s).")

        buff = str(var1)

        comp_len = len(self.comparisons)

        for i in range(1, comp_len):
            # Add in the middle variable + operator
            try:
                var2, op = self.comparisons[i], self.logical_operators[i-1]
                should_quote = (op not in ('or', 'and') and (
                    not var2.isdigit() and
                    var2 not in ('true', 'false') and
                    not var2.startswith('"') and
                    not var2.startswith("'")
                ))
                if should_quote:
                    var2 = "'%s'" % var2.replace("'", "\'")
                if op not in ('or', 'and'):
                    var2 = self._evaluate_as_var(var2, context)
                buff = "%s %s %s" % (buff, op, var2)
            except ValueError:
                raise template.TemplateSyntaxError("Your smart if statement contains a non-valid variable.")
            except IndexError:
                raise template.TemplateSyntaxError("Your smart if statement is not valid: missing argument(s).")

        try:
            return str(self._operate(self.logical_operators[0], eval(buff), True))
        except:
            return ''

