    url = f"http://your-api-url/{resource_name}/"
    data = {"name": name}

    if update:
        response = requests.put(url, json=data)
    else:
        response = requests.post(url, json=data)

    if response.status_code == 200:
        print("Resource created/updated successfully")
    else:
        print("Failed to create/update resource")

