def node_sub(node_self, node_other):
    # Check if both nodes have the same tag
    if node_self.tag != node_other.tag:
        raise ValueError("Nodes have different tags")

    # Check if both nodes have the same number of children
    if len(node_self) != len(node_other):
        raise ValueError("Nodes have different number of children")

    # Check if both nodes have the same attributes
    if node_self.attrib != node_other.attrib:
        raise ValueError("Nodes have different attributes")

    # Traverse the child nodes recursively
    for child_self, child_other in zip(node_self, node_other):
        node_sub(child_self, child_other)

