def parse_hocon(content, resolve=True, unresolved_value=None):
    if unresolved_value is not None:
        if unresolved_value == 'STR_SUBSTITUTION':
            unresolved_value = ConfigFactory.parse_string('"\${}"'.format(ConfigFactory.UNRESOLVED_SUBSTITUTION))
        else:
            unresolved_value = ConfigFactory.parse_string('"{0}"'.format(unresolved_value))

    config_tree = ConfigFactory.parse_string(content, resolve=resolve, unresolved_substitution_value=unresolved_value)
    if config_tree.get_config("pyhocon.is_list"):
        return config_tree.as_plain_ordered_dict().values()
    else:
        return config_tree.as_plain_ordered_dict()

