import json

def validate_json(schema, data):

    def validate(schema, data):
        if isinstance(schema, dict):
            if not isinstance(data, dict):
                return False
            for key, value in schema.items():
                if key not in data:
                    return False
                if not validate(value, data[key]):
                    return False
            return True
        elif isinstance(schema, list):
            if not isinstance(data, list):
                return False
            if len(schema) != len(data):
                return False
            for i in range(len(schema)):
                if not validate(schema[i], data[i]):
                    return False
            return True
        elif isinstance(schema, str):
            if schema == 'null':
                return data is None
            elif schema == 'string':
                return isinstance(data, str)
            elif schema == 'number':
                return isinstance(data, int) or isinstance(data, float)
            elif schema == 'boolean':
                return isinstance(data, bool)
            else:
                raise ValueError('Invalid string schema value: {}'.format(schema))
        else:
            raise TypeError('Unknown schema data type: {}'.format(str(type(schema))))

    if not isinstance(schema, dict):
        raise TypeError('Schema must be a JSON object')

    refs = {}
    for key in schema:
        if key.startswith('#'):
            refs[key] = schema[key]

    for key in refs:
        ref_key = refs[key]
        if ref_key not in schema:
            raise ValueError('Non-existent named schema: {}'.format(ref_key))

    for key in schema:
        if key.startswith('#'):
            continue
        if not validate(schema[key], data):
            return False

    return True

