def cut_conf_for_dispatch(conf):
    services = set(conf.keys())
    schedulers = []
    while services:
        deps = set()
        for service in services:
            deps.update(conf[service].get('depends_on', []))
        schedulers.append({service for service in services if service not in deps})
        services.difference_update(schedulers[-1])
    for i, scheduler in enumerate(schedulers):
        conf[f'SCHEDULER_{i}'] = {service: conf[service] for service in scheduler}
        for service in scheduler:
            del conf[service]

