def parse_treebanks(st):
    """
    Returns the corresponding tree of the treebank, in the form of
    a nested dictionary
    :param st: str: treebank using Penn notation
    """
    def helper(st):
        stack = []
        root = {}
        cur_node = {}
        word = ''
        i = 0
        while i < len(st):
            if st[i] == '(':
                next_op = st[i+1:st.index(' ', i+1)]
                if len(stack) > 0:
                    if next_op not in cur_node:
                        cur_node[next_op] = {}
                    stack[-1][1][word] = cur_node
                    stack.append((next_op, cur_node))
                    cur_node = {}
                else:
                    root[next_op] = {}
                    stack.append((next_op, root))
                    cur_node = {}
                word = ''
                i = st.index(' ', i+1)
            elif st[i] == ')':
                if len(word) > 0:
                    if ',' in word:
                        cur_node[word.split()[1]] = [word.split()[0]]
                    else:
                        cur_node.setdefault(word, [])
                    word = ''
                node = stack.pop()
                cur_node = node[1]
            else:
                word += st[i]
            i += 1
        return root
    st = st.strip()
    return helper(st)

