def recursively_subdivide_spans(spans, rules):
    # base case
    if not spans:
        return []

    # apply rules to first span
    new_spans = []
    for r in rules:
        if r(spans[0]):
            new_spans.extend(r(sub_span) for sub_span in recursively_subdivide_spans(spans[1:], rules))
            break

    # if no rules apply, keep first span as is
    if not new_spans:
        new_spans.append(spans[0])
        new_spans.extend(recursively_subdivide_spans(spans[1:], rules))

    return new_spans

