def fetch_custom_layout(logdir:str, config_file:str)->dict:
    """
    Fetches the custom layout specified by the config file in the logdir.
    If more than 1 run contains a layout, this method merges the layouts by merging charts within individual categories. If 2 categories with the same name are found, the charts within are merged. The merging is based on the order of the runs to which the layouts are written.
    The response is a JSON object mirroring properties of the Layout proto if a layout for any run is found.
    The response is an empty object if no layout could be found.
    """

    from tensorboard.backend.event_processing import directory_loader
    from tensorboard.plugins.projector import ProjectorConfig

    try:
        dirs = directory_loader.load(logdir)

        event_file_paths = {}
        for dir_path in dirs:
            event_file_paths[dir_path.run_name] = dir_path.path

        runs_with_projector = []
        for run_name, event_file_path in event_file_paths.items():
            config = ProjectorConfig(config_file)
            if config.ExistsInEventFile(event_file_path):
                runs_with_projector.append((run_name, event_file_path, config))

        n_runs = len(runs_with_projector)
        if n_runs == 0:
            return {}

        category_names = set()
        for _, _, config in runs_with_projector:
            for category in config.embeddings:
                category_names.add(category.tensor_name)

        chart_name_to_index = {}
        layouts = []

        for run_index, (run_name, event_file_path, config) in enumerate(runs_with_projector):
            layout = {"run":run_name, "categories":[]}

            for category_index, category in enumerate(config.embeddings):
                if category.tensor_name not in chart_name_to_index:
                    chart_name_to_index[category.tensor_name] = len(chart_name_to_index)
                    layout["categories"].append({"name": category.tensor_name, "charts": []})
                chart_index = chart_name_to_index[category.tensor_name]

                chart_data = {
                    "embeddingData": {
                        "tensorName": category.tensor_name,
                        "metadataPath": category.metadata_path or "",
                        "sprite": {
                            "imagePath": category.sprite.image_path or "",
                            "singleImageDim": {
                                "width": category.sprite.single_image_dim.width,
                                "height": category.sprite.single_image_dim.height,
