                            "minDist": category.umap_options.min_dist,
                            "spread": category.umap_options.spread,
                            "setOpMixRatio": category.umap_options.set_op_mix_ratio,
                            "localConnectivity": category.umap_options.local_connectivity,
                            "repulsionStrength": category.umap_options.repulsion_strength,
                            "negativeSampleRate": category.umap_options.negative_sample_rate,
                            "transformQueueSize": category.umap_options.transform_queue_size,
                            "a": category.umap_options.a,
                            "b": category.umap_options.b,
                            "initialAlpha": category.umap_options.initial_alpha,
                            "randomState": category.umap_options.random_state,
                            "metric": category.umap_options.metric,
                        },
                        "modelCheckpointPath":category.tensor_name,
                    },
                    "name": category.tensor_name,
                }

                layout["categories"][chart_index]["charts"].append(chart_data)

            layouts.append((run_index, layout))

        merged_categories = []

        for category_index, category_name in enumerate(chart_name_to_index.keys()):
            current_charts = []
            num_charts = 0

            for run_index, layout in layouts:
                charts = [
                    chart for chart in layout["categories"]
                    if chart["name"] == category_name
