                if len(charts) == 0:
                    continue
                assert len(charts) == 1, f"Only 1 chart allowed per category. category={category_name}, run={run_index}"
                current_charts += charts[0]["charts"]
                num_charts += len(charts[0]["charts"])

            if num_charts == 0:
                continue

            merged_categories.append({
                "name": category_name,
                "charts": current_charts,
            })

        layout = {
            "categories": merged_categories,
        }

        return layout

