def ensure_linux_acl(path, acl_type, acl_name, perms, recurse=False, force=False):
    acl_option = ''
    if acl_type.lower() == 'user':
        acl_option = 'u:'+acl_name
    elif acl_type.lower() == 'group':
        acl_option = 'g:'+acl_name
    else:
        raise ValueError("Valid acl types are 'user' or 'group' only")

    if recurse:
        acl_option += 'R'

    if force:
        subprocess.call(['setfacl', '-R', '-b', path])

    subprocess.call(['setfacl', '-m', acl_option+':'+perms, path])

