def toNepali(date):
    # Gregorian to Julian
    year = date.year
    month = date.month
    day = date.day
    totalDays = 0
    for i in range(1943, year):
        totalDays += 365
        if isLeapYear(i):
            totalDays += 1
    for i in range(1, month):
