def All(sequence):
    return all(sequence)

def Any(sequence):
    """:param sequence: Any sequence whose elements can be evaluated as booleans.
  :returns: true if any element of the sequence satisfies True and x."""
    return any(sequence)

def Count(sequence, value):
    """:param sequence: Any sequence.
  :param value: The value to count in the sequence.
  :returns: The number of times value appears in the sequence."""
    return sequence.count(value)

def Index(sequence, value):
    """:param sequence: Any sequence.
  :param value: The value to find in the sequence.
  :returns: The index of the first occurrence of value in the sequence.
  :raises ValueError: If value is not found in the sequence."""
    return sequence.index(value)

def Reverse(sequence):
    """:param sequence: Any sequence.
  :returns: A new sequence with the elements in reverse order."""
    return sequence[::-1]

def Sort(sequence):
    """:param sequence: Any sequence.
  :returns: A new sequence with the elements sorted in ascending order."""
    return sorted(sequence)

def Sum(sequence):
    """:param sequence: Any sequence of numbers.
  :returns: The sum of all elements in the sequence."""
    return sum(sequence)

def Average(sequence):
    """:param sequence: Any sequence of numbers.
  :returns: The average of all elements in the sequence.
  :raises ZeroDivisionError: If the sequence is empty."""
    if not sequence:
        raise ZeroDivisionError('Cannot compute the average of an empty sequence.')
    return sum(sequence) / len(sequence)

def Max(sequence):
    """:param sequence: Any sequence of numbers.
  :returns: The maximum value in the sequence.
  :raises ValueError: If the sequence is empty."""
    if not sequence:
        raise ValueError('Cannot find the maximum of an empty sequence.')
    return max(sequence)

def Min(sequence):
    """:param sequence: Any sequence of numbers.
  :returns: The minimum value in the sequence.
  :raises ValueError: If the sequence is empty."""
    if not sequence:
        raise ValueError('Cannot find the minimum of an empty sequence.')
    return min(sequence)

