import inspect

def apply_pointcut(pointcut, target):
    target_signature = inspect.signature(target)
    meta = {
        'module_path': inspect.getmodule(target).__file__,
        'file_path': inspect.getsourcefile(target),
        'func_dict': target.__dict__,
        'signature': str(target_signature)
    }

    def intercepted_target(*args, **kwargs):
        if pointcut(*args, **kwargs):
            return target(*args, **kwargs)
        else:
            return None

    intercepted_target.meta = meta

    return intercepted_target

