def constant_fold(code, silent=False, ignore_errors=True):
    try:
        code = code.split()
        stack = []
        for token in code:
            if token.isnumeric():
                stack.append(token)
            elif token in ["+", "-", "*", "/"]:
                op2 = int(stack.pop())
                op1 = int(stack.pop())
                if token == "+":
                    result = op1 + op2
                elif token == "-":
                    result = op1 - op2
                elif token == "*":
                    result = op1 * op2
                elif token == "/":
                    result = op1 / op2
                stack.append(str(result))
            else:
                stack.append(token)
        return " ".join(stack)
    except Exception as e:
        if not ignore_errors:
            raise e
        return code

