def load_netcdf4(fnames=None, strict_meta=False, file_format=None, epoch_name='Epoch'):
    import pandas as pd
    import netCDF4 as nc
    from pysat._meta import Meta
    out = pd.DataFrame()
    mdata = Meta()
    if isinstance(fnames, str):
        fnames = [fnames]
    for fname in fnames:
        with nc.Dataset(fname, mode='r', format=file_format) as dataset:
            data_vars = dataset.variables.keys()
            for var in data_vars:
                if var != epoch_name:
                    out[var] = dataset.variables[var][:]
            out[epoch_name] = pd.to_datetime(dataset.variables[epoch_name][:], unit='s', origin='unix')
            for attr in dataset.ncattrs():
                mdata[attr] = dataset.getncattr(attr)
            if strict_meta:
                if not mdata.is_equal(mdata):
                    raise ValueError('Metadata is not consistent across files')
    return (out, mdata)

