        return abs(x)

    def distance(self, x1, x2):
        """Compute the distance between two elements."""
        if not isinstance(x1, (int, float)) or not isinstance(x2, (int, float)):
            raise ValueError('Both elements must be integers or floats.')
        return self.norm(x1 - x2)

    def angle(self, x1, x2):
        """Compute the angle between two elements."""
        if not isinstance(x1, (int, float)) or not isinstance(x2, (int, float)):
            raise ValueError('Both elements must be integers or floats.')
        if x1 == 0 or x2 == 0:
            raise ValueError('Cannot compute angle with zero.')
        return math.acos(self.inner_product(x1, x2) / (self.norm(x1) * self.norm(x2)))

