    if region_calling_from == "US":
        if len(numobj) == 10:
            formatted = "({}{}{}) {}{}{}-{}{}{}{}".format(*numobj)
    elif region_calling_from == "UK":
        if len(numobj) == 11 and numobj[0] == "0":
            formatted = "+44 {} {}{}{} {}".format(numobj[1], *numobj[2:6], *numobj[6:10])
