from PIL import Image

def read_image(filename, squeeze=True, colormapped=False, rgbonly=False):
    try:
        img = Image.open(filename)
    except IOError as e:
        raise ValueError(f"{filename} cannot be opened: {e}")

    # Perform color mapping for palette-indexed images
    if colormapped and 'P' == img.mode:
        img = img.convert('RGBA', colors=256)
    else:
        img.load()

    # Extract RGB(A) if required
    if rgbonly and "A" in img.mode:
        img_im = img.split()[:3][::-1]
        img = Image.merge(img.mode, img_im)

    # Convert to numpy array
    data = np.asarray(img)
    if data.ndim == 3 and squeeze:
        data = np.squeeze(data)

    return data

