def random_distribution(loc, scale, shape, skewness, nsims):
    """
    This function draws random variables from a distribution.

    :param loc: float, location parameter for the distribution
    :param scale: float, scale parameter for the distribution
    :param shape: float, tail thickness parameter for the distribution
    :param skewness: float, skewness parameter for the distribution
    :param nsims: int or list, number of draws to take from the distribution
    :return: list, random draws from the distribution
    """
    import numpy as np

    def pearson_type(x, shape, skewness):
        # Function to calculate pearson type VI distribution
        return shape * (x - skewness) ** 2

    # Define the inverse transformation function
    def inv_transform(u):
        return loc + scale * (1 / shape * np.sinh(u)) * ((np.cosh(u)) ** -(1 / shape - 1))

    # Draw random variables from a uniform distribution
    if isinstance(nsims, int):
        uniform_draws = np.random.rand(nsims)
    elif isinstance(nsims, list):
        uniform_draws = np.random.rand(*nsims)
    else:
        raise TypeError('nsims must be an integer or a list')

    # Apply inverse transformation
    return inv_transform(pearson_type(np.log(uniform_draws), shape, skewness))

