def fix_phrases(text, problematic_words, cutPhrases=False, cutMaxThreshold=None):
    # remove text decorations
    text = remove_text_decorations(text)

    # remove problematic words from the beginning of phrases
    word_list = text.split()
    for i, word in enumerate(word_list):
        if word in problematic_words:
            word_list = word_list[i+1:]
        else:
            break
    text = ' '.join(word_list)

    # remove phrases consisting only of numbers
    word_list = text.split()
    for word in word_list:
        if not word.isnumeric():
            break
    else:
        return ''

    # fix B/I characters
    text = text.replace('B', '8').replace('I', '1')

    # cut phrases to appropriate length
    if cutPhrases:
        phrases = text.split('.')
        text = ''
        for phrase in phrases:
            if len(phrase.split()) <= cutMaxThreshold:
                text += phrase + '.'

    return text

