    def set_cursor(self, position):
        """Set the position of the cursor in the text."""
        if position < 0 or position > len(self._text):
            raise ValueError('Cursor position out of bounds')
        self._cursor = position

    def insert_text(self, text):
        """Insert text at the current cursor position."""
        if not isinstance(text, str):
            raise TypeError('Text must be a string')
        self._text = self._text[:self._cursor] + text + self._text[self._cursor:]
        self._cursor += len(text)

    def delete_text(self, length):
        """Delete text starting from the current cursor position."""
        if length < 0:
            raise ValueError('Length must be non-negative')
        if self._cursor + length > len(self._text):
            raise ValueError('Deletion length out of bounds')
        self._text = self._text[:self._cursor] + self._text[self._cursor + length:]

    def move_cursor(self, offset):
        """Move the cursor by a given offset."""
        new_position = self._cursor + offset
        if new_position < 0 or new_position > len(self._text):
