def transform_grammar(grammar, inplace=False):
    if not inplace:
        grammar = grammar.copy()

    start = grammar.start()
    #Step-1 :Removing Useless Symbols
    grammar = CFG(grammar.start(), grammar.productions())
    non_terminals = set(grammar.nonterminals())
    reachable = set()
    productions = []
    for production in grammar.productions():
        if non_terminals == reachable:
            productions.append(production)
            continue

        if production.lhs() == start or len(production.rhs()) == 0:
            reachable.add(production.lhs())

        for symbol in production.rhs():
            if symbol in reachable:
                reachable.add(production.lhs())
                productions.append(production)
                break
    #  Step-2 : Removing rules with empty symbols
    epsilons = set()
    for production in productions:
        if production.rhs() == ():
            epsilons.add(production.lhs())
    productions = [
        production
        for production in productions
        if not production.rhs() == ()
    ]
    # Step-3 : Removing unit productions
    unit_productions = defaultdict(set)
    new_productions = []
    for production in productions:
        if len(production.rhs()) == 1 and production.rhs()[0] in non_terminals:
            unit_productions[production.lhs()].add(production.rhs()[0])
        else:
            new_productions.append(production)

    finished = False
    while not finished:
        finished = True
        remove_keys = set()
        for key, value in unit_productions.items():
            remove = set()
            for val in value:
                if val in unit_productions:
                    remove.add(val)
                    finished = False
                    value |= unit_productions[val]
            value -= remove
            if not value:
                remove_keys.add(key)
        for key in remove_keys:
            del unit_productions[key]

    #  Step-4: Removing useless symbols again
    used = set([start])
    finished = False
    while not finished:
        finished = True
        for production in new_productions:
            if all(s in used for s in production.rhs()):
                if production.lhs() not in used:
                    used.add(production.lhs())
                    finished = False

    removed_non_terminals = non_terminals - used
    removed = []
    for production in new_productions:
        if not any(symbol in removed_non_terminals
                   for symbol in production.rhs()):
            removed.append(production)
    productions = removed

    # Step-5: Converting to Chomsky Normal Form

    new_productions = []
    for production in productions:
        lhs = production.lhs()
        rhs = production.rhs()
        if len(rhs) == 1:
            new_productions.append(production)
            continue

        for i, symbol in enumerate(rhs):
            if symbol not in non_terminals:
                continue
            new = f'({symbol})'
            new_productions.append(
                CFG.NEW_NONTERMINAL if i == 0 else new,
                (rhs[i], new))
            rhs = rhs[:i] + (new,) + rhs[i + 1:]

        if len(rhs) == 2:
            new_productions.append(CFG.NEW_NONTERMINAL, rhs)
        else:
            for i in range(len(rhs) - 2):
                new = CFG.NEW_NONTERMINAL
                new_productions.append(
                    new, (rhs[i], new + str(i)))
                rhs = rhs[:i + 1] + (new + str(i),) + rhs[i + 2:]
            new_productions.append(CFG.NEW_NONTERMINAL, rhs)

    return CFG(start, new_productions)

