import scipy.sparse as sp

def encode_tweet_info(tweet_generator: Generator[Dict], 
                       ) -> Tuple[sp.spmatrix, Set[int], Dict[str, int]]:
    user_id_set = set()
    node_id = 0
    edges = []
    node_to_id = {}

    for tweet in tweet_generator:
        user_id = tweet['user_id']
        user_id_set.add(user_id)
        if user_id not in node_to_id:
            node_to_id[user_id] = node_id
            node_id += 1

        if 'mentions' in tweet:
            for mention in tweet['mentions']:
                mention_id = mention['id']
                user_id_set.add(mention_id)
                if mention_id not in node_to_id:
                    node_to_id[mention_id] = node_id
                    node_id += 1
                edges.append((node_to_id[user_id], node_to_id[mention_id]))

        if 'retweeted_user' in tweet:
            retweet_id = tweet['retweeted_user']
            user_id_set.add(retweet_id)
            if retweet_id not in node_to_id:
                node_to_id[retweet_id] = node_id
                node_id += 1
            edges.append((node_to_id[user_id], node_to_id[retweet_id]))

    users_sorted = list(user_id_set)
    users_node_id = [node_to_id[i] for i in users_sorted]
    mention_graph = sp.dok_matrix((node_id, node_id), dtype=np.float32)
    for edge in edges:
        mention_graph[edge[0], edge[1]] = 1

    return mention_graph.tocsr(), user_id_set, node_to_id

