def get_bgp_config(self, group="", neighbor=""):
    """Parse BGP config params into a dict
    :param group='':
    :param neighbor='':
    """
    bgp_config = {}

    with open("bgp_config.txt", "r") as file:
        for line in file:
            if line.startswith("group"):
                group = line.split(" ")[1].strip()
                bgp_config[group] = {}
            elif line.startswith("neighbor"):
                neighbor = line.split(" ")[1].strip()
                bgp_config[group][neighbor] = {}
            elif line.startswith("remote-as"):
                bgp_config[group][neighbor]["remote-as"] = line.split(" ")[1].strip()
            elif line.startswith("update-source"):
                bgp_config[group][neighbor]["update-source"] = line.split(" ")[1].strip()
            elif line.startswith("address-family"):
                bgp_config[group][neighbor]["address-family"] = line.split(" ")[1].strip()

    return bgp_config

