def find_unused_definitions(node):
    # Implementing the function according to the requirements
    definitions = set()
    used_definitions = set()
    unused_definitions = set()

    def visit_fn(node):
        for idx, child_node in enumerate(node):
            if isinstance(child_node, ast.Assign):
                for target in child_node.targets:
                    if isinstance(target, ast.Name):
                        definitions.add((target.id, child_node))
            visit_fn(child_node)

    visit_fn(node)

    def visit_fn2(node):
        for idx, child_node in enumerate(node):
            if isinstance(child_node, ast.Name):
                used_definitions.add(child_node.id)
            if isinstance(child_node, ast.FunctionDef):
                for arg in child_node.args.args:
                    used_definitions.add(arg.arg)
                for decorator in child_node.decorator_list:
                    used_definitions.add(decorator.id)
            visit_fn2(child_node)

    visit_fn2(node)

    for item in definitions:
        if item[0] not in used_definitions:
            unused_definitions.add(item)

    return unused_definitions

