import json

def get_bgp_config(self, group="", neighbor=""):
    """Implementation of NAPALM method get_bgp_config."""
    # Assuming you have a connection to a device
    if self.device:
        # Get BGP configuration
        bgp_config = self.device.get_bgp_config()

        # If group or neighbor is specified, filter the configuration
        if group:
            bgp_config = {k: v for k, v in bgp_config.items() if k == group}
        if neighbor:
            bgp_config = {k: {n: v for n, v in neighbors.items() if n == neighbor} for k, neighbors in bgp_config.items()}

        return json.dumps(bgp_config, indent=4)
    else:
        return "No device connected"

