def magnitude(self):
    return math.sqrt(self.x ** 2 + self.y ** 2)

def normalize(self):
    """Normalize the vector represented by the point."""
    mag = self.magnitude()
    if mag == 0:
        raise ValueError('Cannot normalize a zero vector')
    self.x /= mag
    self.y /= mag

def dot(self, other):
    """Compute the dot product of two vectors."""
    return self.x * other.x + self.y * other.y

def cross(self, other):
    """Compute the cross product of two vectors in 2D."""
    return self.x * other.y - self.y * other.x

def angle_between(self, other):
    """Compute the angle between two vectors."""
    dot_product = self.dot(other)
    mag_self = self.magnitude()
    mag_other = other.magnitude()
    cos_theta = dot_product / (mag_self * mag_other)
    return math.acos(cos_theta)

def project(self, other):
    """Project one vector onto another."""
    dot_product = self.dot(other)
    mag_other_squared = other.magnitude() ** 2
    scalar_projection = dot_product / mag_other_squared
    return Point(scalar_projection * other.x, scalar_projection * other.y)

def reflect(self, normal):
    """Reflect a vector over a normal vector."""
    dot_product = self.dot(normal)
    return Point(self.x - 2 * dot_product * normal.x, self.y - 2 * dot_product * normal.y)

def rotate(self, angle):
    """Rotate the vector by a given angle in radians."""
    cos_angle = math.cos(angle)
    sin_angle = math.sin(angle)
    new_x = self.x * cos_angle - self.y * sin_angle
    new_y = self.x * sin_angle + self.y * cos_angle
    return Point(new_x, new_y)

def scale(self, factor):
    """Scale the vector by a given factor."""
    return Point(self.x * factor, self.y * factor)

def translate(self, dx, dy):
    """Translate the point by given deltas."""
    return Point(self.x + dx, self.y + dy)

def distance_to(self, other):
    """Compute the Euclidean distance between two points."""
    return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2)

