def grep_iter(target, pattern, **kwargs):
    import re
    if isinstance(target, str):
        target = [target]
    if isinstance(target, (list, tuple)):
        for i in target:
            if not isinstance(i, str):
                raise TypeError('Target item is not a string')
            for match in re.finditer(pattern, i, **kwargs):
                yield match.group()
    elif callable(target):
        for match in re.finditer(pattern, target(**kwargs), **kwargs):
            yield match.group()
    elif hasattr(target, 'read'):
        for match in re.finditer(pattern, target.read(), **kwargs):
            yield match.group()
    else:
        raise TypeError('Target is not iterable, a callable, or a file handler')

