def create_subgraph_with_custom_gradient(fn, inputs, grad_fn, use_global_vars):
    @tf.custom_gradient
    def subgraph(*inputs):
        outputs = fn(*inputs)
        def grad(output_grads):
            grad_inputs, grad_vars = grad_fn(inputs, tf.global_variables() if use_global_vars else tf.trainable_variables(), outputs, output_grads)
            return grad_inputs, grad_vars
        return outputs, grad
    return subgraph(*inputs)

