    for part in parts:
        if contains(ctx, full, part):
            return True
    return False

def contains_all(ctx, full, parts):
    """Yields one boolean, whether the first string contains all of the second list of strings"""
    for part in parts:
        if not contains(ctx, full, part):
            return False
    return True

def contains_none(ctx, full, parts):
    """Yields one boolean, whether the first string contains none of the second list of strings"""
    for part in parts:
        if contains(ctx, full, part):
            return False
    return True

def contains_only(ctx, full, parts):
    """Yields one boolean, whether the first string contains only the second list of strings"""
    for char in full:
        if char not in parts:
            return False
    return True

def contains_exactly(ctx, full, parts):
    """Yields one boolean, whether the first string contains exactly the second list of strings"""
