from datetime import datetime

def days(start, stop):
    """Return days between start & stop (inclusive)

    Note that start must be less than stop or else 0 is returned.

    @param start: Start date in the format 'YYYY-MM-DD'
    @param stop: Stop date in the format 'YYYY-MM-DD'
    @return int"""

    format_str = '%Y-%m-%d' # The format
    start_dt = datetime.strptime(start, format_str)
    stop_dt = datetime.strptime(stop, format_str)

    if start_dt > stop_dt:
        return 0
    else:
        return (stop_dt - start_dt).days

