def create_flag_class(cls, member_definitions):
    """Creates a flag class with the given member definitions.
    :param cls: The class to be created.
    :param member_definitions: The member definitions to be used for the flag class.
    :return: The created flag class."""

    class FlagClass(cls):

        def __init__(self, value=0):
            self.value = value

        def __or__(self, other):
            return FlagClass(self.value | other.value)

        def __and__(self, other):
            return FlagClass(self.value & other.value)

        def __xor__(self, other):
            return FlagClass(self.value ^ other.value)

        def __invert__(self):
            return FlagClass(~self.value)

        def __int__(self):
            return self.value

        def __repr__(self):
            return f'{cls.__name__}({self.value})'

        def __contains__(self, item):
            return bool(self.value & item.value)

        def __iter__(self):
            for (name, bits, data) in member_definitions:
                if self.value & bits:
                    yield (name, bits, data)
    for (name, bits, data) in process_member_definitions(cls, member_definitions):
        setattr(FlagClass, name, FlagClass(bits))
    return FlagClass

