import json

def _samplejson_to_inputs(svals):
    """Convert sample output into inputs for CWL configuration files, with types."""
    # Load the sample output
    sample_output = json.loads(svals)

    # Initialize an empty dictionary to store the inputs
    inputs = {}

    # Iterate over the sample output
    for key, value in sample_output.items():
        # Determine the type of the value
        if isinstance(value, int):
            value_type = 'int'
        elif isinstance(value, float):
            value_type = 'float'
        elif isinstance(value, str):
            value_type = 'string'
        elif isinstance(value, list):
            value_type = 'array'
        elif isinstance(value, dict):
            value_type = 'object'
        else:
            value_type = 'unknown'

        # Add the input to the dictionary
        inputs[key] = {
            'type': value_type,
            'value': value
        }

    # Return the inputs
    return inputs

