def detect_builtin_shadowing(contract):
    """
    Given a Solidity contract, this function recursively visits its functions and detects shadowing of built-in symbols.
    It returns a list of dictionaries with the following keys: 'vuln', 'filename,'contract','func', 'shadow'. 
    If a built-in symbol is shadowed in a function, the corresponding dictionary has the value True for 'vuln' and the name of 
    the contract, function and symbol in 'filename', 'contract' and 'func' respectively. Otherwise, its value for 'vuln' is False.
    """
    symbols = ["assert", "require", "revert", "transfer", "send", "suicide"] # Built-in symbols to look for
    vulns = []
    def visit(node, contract):
        if isinstance(node, ast.FunctionDef):
            locals_ = [arg.arg for arg in node.args.args] # List of local symbols in the function
            for s in symbols:
                if s in locals_:
                    vulns.append({
                        'vuln': True,
                        'filename': contract.source,
                        'contract': contract.name,
                        'func': node.name,
                        'shadow': s
                    })
            for child in node.body:
                visit(child, contract) # Visit recursively
        elif hasattr(node, "body"):
            for child in node.body:
                visit(child, contract)
    visit(ast.parse(contract.code), contract)
    return vulns

