def delete_field_from_vcf(vcf_path, field_name):
    """
    This function takes a VCF file path and a field name to delete from all variants in the VCF file. The function
    returns a new VCF file with the specified field removed from all variants.

    :param vcf_path: str, a path to the VCF file
    :param field_name: str, the name of the field to delete from all variants
    :return: str, a path to the new VCF file without the specified field
    """
    new_vcf_path = f"{vcf_path}_without_{field_name}.vcf"
    with open(vcf_path, 'r') as vcf_file, open(new_vcf_path, 'w') as new_vcf_file:
        for line in vcf_file:
            if line.startswith('#'):
                new_vcf_file.write(line)
            else:
                fields = line.split('\t')
                info_str = fields[7]
                info_fields = info_str.split(';')
                info_dict = {}
                for field in info_fields:
                    if '=' in field:
                        key, value = field.split('=')
                        if key != field_name:
                            info_dict[key] = value
                fields[7] = ';'.join([f"{key}={value}" for key, value in info_dict.items()])
                new_vcf_file.write('\t'.join(fields))
    return new_vcf_path

