import pysam

def delete_info(vcf_file, info_to_delete):
    vcf_in = pysam.VariantFile(vcf_file)  # open VCF file
    vcf_out = pysam.VariantFile('out.vcf', 'w', header=vcf_in.header)  # create output VCF file

    for record in vcf_in.fetch():
        if info_to_delete in record.info:
            del record.info[info_to_delete]
        vcf_out.write(record)

    vcf_in.close()
    vcf_out.close()

