class DatetimeWithNanoseconds(datetime):
    __slots__ = ('_nanosecond',)
    _nanosecond = 0

    @property
    def nanosecond(self):
        return self._nanosecond

    def __repr__(self):
        return '%s.%09d' % (datetime.__repr__(self).rstrip(')'), self.nanosecond)

    def replace(self, **kw):
        if 'microsecond' in kw:
            kw['nanosecond'] = kw.pop('microsecond') * 1000
        d = datetime.replace(self, **kw)
        return type(self)(d.year, d.month, d.day, d.hour, d.minute, d.second, d.microsecond, self.nanosecond, tzinfo=d.tzinfo)

    def __add__(self, other):
        result = datetime.__add__(self, other)

        ns = self._nanosecond + getattr(other, '_nanosecond', 0)
        s, ns = divmod(ns, 1000000000)
        return type(self)(result.year, result.month, result.day, result.hour, result.minute, result.second + s, result.microsecond + ns // 1000, ns % 1000, tzinfo=result.tzinfo)

    @classmethod
    def from_rfc3339(cls, string):
        if string[-1] == 'Z':
            tz = None
        else:
            tz = datetime.strptime(string[-6:], '%z').tzinfo
            string = string[:-6]
        if '.' in string:
            date_string, ns_string = string.split('.')
            ns = int(ns_string[:9].ljust(9, '0'))
            string = date_string[:19] + date_string[26:]
        else:
            ns = 0
        dt = datetime.strptime(string, '%Y-%m-%dT%H:%M:%S')
        return cls(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, ns, tz)


