def calculate_triples(nodes, adjacency_matrix, corr_matrix):
    import numpy as np
    import scipy.linalg as la

    d = np.sum(adjacency_matrix, axis=0)
    D = np.diag(d)
    L = D - adjacency_matrix
    E = np.column_stack((np.ones(len(d)), d))
    v = la.solve(E.T @ E, E.T @ np.ones(len(d)))
    q = 1 + L @ v
    Q = np.diag(q)
    Ji = np.eye(len(nodes)) - la.inv(Q) @ L
    J = Ji @ corr_matrix @ Ji
    trips = []
    for i in range(len(nodes)):
        for j in range(len(nodes)):
            if adjacency_matrix[i,j] == 1 and corr_matrix[j,i] > 0:
                for k in range(len(nodes)):
                    if adjacency_matrix[i,k] == 0 and adjacency_matrix[j,k] == 1 and corr_matrix[k,i] > 0:
                        trips.append((nodes[i], nodes[j], nodes[k]))
    return trips

