from scipy.integrate import quad


def evaluate_igci(a, b, **kwargs):
    ref_measure = kwargs.get('ref_measure', None)
    estimator = kwargs.get('estimator', 'entropy')

    def p(x):
        if ref_measure == 'gaussian':
            return np.exp(-x ** 2 / 2) / np.sqrt(2 * np.pi)
        elif ref_measure == 'integral':
            return quad(lambda t: 1 / (np.abs(x - t) + 1e-5), -np.inf, np.inf)[0]
        else:
            return 1

    def H(x, y):
        z = np.column_stack([x, y])
        xy_min = np.min(z, axis=0)
        xy_max = np.max(z, axis=0)
        Hxy = np.log2(len(z)) + np.log2((xy_max - xy_min)).sum()
        return Hxy

    na = len(a)
    nb = len(b)

    if estimator == 'integral':
        # computes ∑ p(a[i]-a[j]) p(b[j]-b[i])
        res = 0
        for i in range(na):
            for j in range(i):
                res += p(a[i] - a[j]) * p(b[j] - b[i])
        res /= (na * (na - 1) / 2)
        res /= (nb * (nb - 1) / 2)
        return res

    elif estimator == 'entropy':
        # computes ∑ H(a[i],b[j]) - H(a[i],a[j]) - H(b[i],b[j])
        res = 0
        for i in range(na):
            for j in range(nb):
                res += H(a[i], b[j]) - H(a[i], a[j]) - H(b[i], b[j])
        res /= (na * nb)
        return res

