import sqlite3

def execute_in_transaction(func):
    """Execute a function within the context of a transaction."""
    @contextmanager
    def transaction():
        conn = sqlite3.connect('mydb.sqlite')
        try:
            yield conn
            conn.commit()
        except:
            conn.rollback()
            raise
        finally:
            conn.close()

    with transaction() as conn:
        cursor = conn.cursor()
        cursor.execute("BEGIN")
        try:
            result = func(cursor)
        except:
            cursor.execute("ROLLBACK")
            raise
        else:
            cursor.execute("COMMIT")
        return result

