def get_ip_address(interface_name):
    """Retrieve the IP address of a network interface."""
    import socket
    import fcntl
    import struct
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        ip = socket.inet_ntoa(fcntl.ioctl(s.fileno(), 35093, struct.pack('256s', bytes(interface_name[:15], 'utf-8')))[20:24])
    except IOError:
        return None
    finally:
        s.close()
    return ip

def get_connectable_ip(interface_name, location=None):
    """Get a connectable IP address for a given network interface."""
    ip = get_ip_address(interface_name)
    if ip is None:
        return disambiguate_ip_address('0.0.0.0', location)
    return disambiguate_ip_address(ip, location)

