def iat(x, maxlag=None):
    if maxlag is None:
        maxlag = int(len(x) / 5)
    if maxlag > len(x) - 1:
        maxlag = len(x) - 1
    gamma = [np.correlate(x, np.roll(x, i))[0] / len(x) for i in range(maxlag + 1)]
    gamma0 = gamma[0]
    iat = 1 + 2 * sum((gamma[i] / gamma0 for i in range(1, maxlag + 1)))
    return iat

