from cryptography.hazmat.primitives import serialization

def parse_ssh_public_key(blob):
    parts = blob.strip().split()
    key_type = parts[0]
    key_blob = base64.b64decode(parts[1])
    if key_type == "ssh-ed25519":
        return key_blob
    elif key_type.startswith("ecdsa-sha2-"):
        curve_name = key_type[11:]
        if curve_name == "nistp256":
            curve = ec.SECP256R1()
        else:
            return None
        point_size = (curve.key_size + 7) // 8
        if len(key_blob) != 2 + point_size:
            return None
        if key_blob[0] != 4:
            return None
        x = int.from_bytes(key_blob[1:1+point_size], byteorder="big")
        y = int.from_bytes(key_blob[1+point_size:], byteorder="big")
        public_numbers = ec.EllipticCurvePublicNumbers(x, y, curve())
        public_key = public_numbers.public_key()
        return public_key.public_bytes(
            encoding=serialization.Encoding.DER,
            format=serialization.PublicFormat.SubjectPublicKeyInfo,
        )
    else:
        return None

def construct_verifier(ecdsa_key):
    if isinstance(ecdsa_key.curve, ec.SECP256R1):
        curve_name = "nistp256"
    else:
        return None
    tlv = f"ecdsa-sha2-{curve_name}\0".encode("ascii")
    der = ecdsa_key.public_bytes(
        encoding=serialization.Encoding.DER,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    )[1:]
    return tlv + der

