def get_content_hashes(root_dir: str, file_extensions: list, include_sizes: bool) -> dict:
    """
    Returns a dictionary of file names and their respective hashes.

    Args:
        root_dir (str): the root directory to start the search for files.
        file_extensions (list): a list of file extensions to include in the search.
        include_sizes (bool): if True, includes a second data structure with sizes.

    Returns:
        A dictionary of file names and their respective hashes.
    """
    import hashlib
    import os

    content_hashes = {}
    if include_sizes:
        sizes = {}

    for subdir, _, files in os.walk(root_dir):
        for file in files:
            _, file_extension = os.path.splitext(file)
            if file_extension.lower() in file_extensions:
                file_path = os.path.join(subdir, file)
                try:
                    with open(file_path, 'rb') as f:
                        content = f.read()
                        file_hash = hashlib.md5(content).hexdigest()
                        content_hashes[file_path] = file_hash
                        if include_sizes:
                            sizes[file_path] = os.path.getsize(file_path)
                except Exception as e:
                    print(f"Error reading {file_path}: {e}")
    if include_sizes:
        result = {'content_hashes': content_hashes, 'sizes': sizes}
    else:
        result = content_hashes
    return result

