def lookup_attribute_in_path_to_root(obj, attribute_name):
    """
    Look up an attribute in the path to the root.
    """
    current_obj = obj
    while current_obj is not None:
        if hasattr(current_obj, attribute_name):
            return getattr(current_obj, attribute_name)
        else:
            current_obj = getattr(current_obj, '__dict__', None)
    return None

