public class DocumentationFormatter {
    private String prefix;

    public DocumentationFormatter(String prefix) {
        this.prefix = prefix;
    }

    public String format(String doc) {
        String[] lines = doc.split("\n");
        StringBuilder formattedDoc = new StringBuilder();

        for (String line : lines) {
            formattedDoc.append(prefix).append(line).append("\n");
        }

        return formattedDoc.toString();
    }
}

