import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class CronParser {

    public CronFieldParseResult parseCronExpression(String expression) {
        CronFieldParseResult result = new CronFieldParseResult();
        String[] fields = expression.split("\\s+");

        if (fields.length < 6) {
            throw new RuntimeException("Invalid CRON expression - not enough fields");
        }

        try {
            for (int i = 0; i < fields.length; i++) {
                CronFieldType fieldType = CronFieldType.values()[i];
                String field = fields[i];

                if (fieldType == CronFieldType.DAY_OF_MONTH && field.equals("?")) {
                    fieldType = CronFieldType.DAY_OF_WEEK;
                    field = "*";
                }

                CronFieldParser fieldParser = fieldType.getFieldParser();
                CronFieldValues fieldValues = fieldParser.parse(field, fieldType);

                result.setFieldValues(fieldType, fieldValues);
            }
        }
        catch (IllegalFieldValueException e) {
            throw new RuntimeException("Invalid CRON expression - " + e.getMessage());
        }

        return result;
    }
}

enum CronFieldType {
    SECOND(new SimpleCronFieldParser(0, 59)),
    MINUTE(new SimpleCronFieldParser(0, 59)),
    HOUR(new SimpleCronFieldParser(0, 23)),
    DAY_OF_MONTH(new SimpleCronFieldParser(1, 31)),
    MONTH(new SimpleCronFieldParser(1, 12)),
    DAY_OF_WEEK(new DayOfWeekCronFieldParser());

    private CronFieldParser fieldParser;

    CronFieldType(CronFieldParser fieldParser) {
        this.fieldParser = fieldParser;
    }

    public CronFieldParser getFieldParser() {
        return fieldParser;
    }
}

class CronFieldValues {
    private boolean allSpecified;
    private boolean hasIncrement;
    private boolean hasRange;
    private boolean hasComma;
    private int[] values;

    public CronFieldValues() {
        this.allSpecified = false;
        this.hasIncrement = false;
        this.hasRange = false;
        this.hasComma = false;
        this.values = new int[0];
    }

    public boolean isAllSpecified() {
        return allSpecified;
    }

    public void setAllSpecified() {
        this.allSpecified = true;
        this.values = new int[0];
    }

    public boolean hasIncrement() {
        return hasIncrement;
    }

    public void setIncrement(int start, int increment, int max) {
        this.values = new int[(max - start) / increment + 1];
        for (int i = start, j = 0; i <= max; i += increment, j++) {
            this.values[j] = i;
        }
        this.hasIncrement = true;
    }

    public boolean hasRange() {
        return hasRange;
    }

    public void setRange(int start, int end) {
        this.values = new int[end - start + 1];
        for (int i = start, j = 0; i <= end; i++, j++) {
            this.values[j] = i;
        }
        this.hasRange = true;
    }

    public boolean hasComma() {
        return hasComma;
    }

    public void setCommaValues(int[] values) {
        this.values = values;
        this.hasComma = true;
    }

    public int[] getValues() {
        return values;
    }
}

interface CronFieldParser {
    CronFieldValues parse(String field, CronFieldType fieldType) throws IllegalFieldValueException;
}

class SimpleCronFieldParser implements CronFieldParser {
    private int min;
    private int max;

    public SimpleCronFieldParser(int min, int max) {
        this.min = min;
        this.max = max;
    }

    public CronFieldValues parse(String field, CronFieldType fieldType) throws IllegalFieldValueException {
        CronFieldValues result = new CronFieldValues();

        if (field.equals("*")) {
            result.setAllSpecified();
        }
        else if (field.contains("/")) {
            String[] parts = field.split("/");
            if (parts.length != 2) {
                throw new IllegalFieldValueException("field contains invalid increment specification");
            }
            int start = 0;
            int increment = Integer.parseInt(parts[1]);
            if (!parts[0].equals("*")) {
                start = Integer.parseInt(parts[0]);
            }
            result.setIncrement(start, increment, max);
        }
        else if (field.contains("-")) {
            String[] parts = field.split("-");
            if (parts.length != 2) {
                throw new IllegalFieldValueException("field contains invalid range specification");
            }
            int start = Integer.parseInt(parts[0]);
            int end = Integer.parseInt(parts[1]);
            if (start < min || start > max || end < min || end > max || start > end) {
                throw new IllegalFieldValueException("invalid range specification");
            }
            result.setRange(start, end);
        }
        else if (field.contains(",")) {
            String[] parts = field.split(",");
            int[] values = new int[parts.length];
            for (int i = 0; i < parts.length; i++) {
                int value = Integer.parseInt(parts[i]);
                if (value < min || value > max) {
                    throw new IllegalFieldValueException("field contains out-of-range value");
                }
                values[i] = value;
            }
            result.setCommaValues(values);
        }
        else {
            int value = Integer.parseInt(field);
            if (value < min || value > max) {
                throw new IllegalFieldValueException("field contains out-of-range value");
            }
            result.setRange(value, value);
        }

        return result;
    }
}

class DayOfWeekCronFieldParser implements CronFieldParser {
    private static final Pattern pattern = Pattern.compile("(\\d+)?[WL#]?([1-7lL])");

    public CronFieldValues parse(String field, CronFieldType fieldType) throws IllegalFieldValueException {
        CronFieldValues result = new CronFieldValues();

        if (field.equals("*")) {
            result.setAllSpecified();
        }
        else {
            Matcher matcher = pattern.matcher(field);
            if (!matcher.matches()) {
                throw new IllegalFieldValueException("field contains invalid value");
            }

            int dow = getField(matcher.group(2));
            int nth = getField(matcher.group(1));

            if (field.contains("#")) {
                if (nth == 0) {
                    throw new IllegalFieldValueException("field contains invalid value");
                }
                result.setCommaValues(new int[] {nth * 7 + dow});
            }
            else if (field.contains("L")) {
                if (nth != 0) {
                    throw new IllegalFieldValueException("field contains invalid value");
                }
                if (field.endsWith("L")) {
                    result.setCommaValues(new int[] {99});
                }
                else {
                    int daysBack = Integer.parseInt(field.substring(0, field.length() - 1));
                    if (daysBack > 6) {
                        throw new IllegalFieldValueException("field contains invalid value");
                    }
                    result.setCommaValues(new int[] {getLastDowOfMonth(daysBack)});
                }
            }
            else if (nth != 0) {
                int maxDays = getMaxDaysForMonth("*");
                int resultDow = -1;
                int resultNth = nth > 0 ? nth : maxDays / 7 + 1 + nth;
                int offset = (resultNth - 1) * 7;
                for (int i = 1; i <= 7; i++) {
                    int testDow = (dow + i) % 7;
                    if (testDow == getField("*")) {
                        if (i + offset <= maxDays) {
                            resultDow = i;
                        }
                        else {
                            break;
                        }
                    }
                }
                if (resultDow == -1) {
                    throw new IllegalFieldValueException("no such day of week in this month for specified nth occurrence");
                }
                result.setCommaValues(new int[] {resultDow + offset});
            }
            else {
                result.setCommaValues(new int[] {dow});
            }
        }

        return result;
    }

    private int getLastDowOfMonth(int dow) {
        int maxDays = getMaxDaysForMonth("*");
        int lastDow = -1;
        for (int i = maxDays; i >= 1; i--) {
            int testDow = getDayOfWeek(i, "*");
            if (testDow == dow) {
                lastDow = i;
                break;
            }
        }
        return lastDow;
    }

    private int getField(String fieldName) {
        switch (fieldName) {
            case "1":
                return CronConstants.SUNDAY;
            case "2":
                return CronConstants.MONDAY;
            case "3":
                return CronConstants.TUESDAY;
            case "4":
                return CronConstants.WEDNESDAY;
            case "5":
                return CronConstants.THURSDAY;
            case "6":
                return CronConstants.FRIDAY;
            case "7":
                return CronConstants.SATURDAY;
            case "l":
                return CronConstants.SATURDAY;
            case "L":
                return CronConstants.SUNDAY;
            default:
                throw new IllegalArgumentException("invalid field value");
        }
    }

    private int getMaxDaysForMonth(String month) {
        switch (month) {
            case "1":
            case "01":
            case "3":
            case "03":
            case "5":
            case "05":
            case "7":
            case "07":
            case "8":
            case "08":
            case "10":
            case "12":
                return 31;
            case "4":
            case "04":
            case "6":
            case "06":
            case "9":
            case "09":
            case "11":
                return 30;
            default:
                if (!month.equals("*") && !month.equals("?")) {
                    throw new IllegalArgumentException("invalid field value");
                }
                return 31;
        }
    }

    private int getDayOfWeek(int dayOfMonth, String month) {
        int monthNum = Integer.parseInt(month.equals("*") ? "1" : month); // default to January
        int year = 2000; // arbitrary leap year
        int[] daysInMonth = {31, year % 4 == 0 && year % 100 != 0 || year % 400 == 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        int doy = 0;
        for (int i = 1; i <= monthNum; i++) {
            if (i == monthNum) {
                doy += dayOfMonth;
            }
            else {
                doy += daysInMonth[i - 1];
            }
        }
        int dow = (doy + CronConstants.THURSDAY) % 7; // Jan 1, 1970 was a Thursday
        return dow;
    }
}

