/**
 * Implementation of {@link TcpServer} using netty.
 */
public final class NettyTcpServer extends TcpServer {

    private static final AttributeKey<InetSocketAddress> BOUND_ADDRESS_KEY =
            AttributeKey.valueOf("boundAddress");

    private static final AttributeKey<Consumer<ServerBootstrap>> CONFIGURE_BOOTSTRAP_KEY =
            AttributeKey.valueOf("configureBootstrap");

    private final EventLoopGroup parentGroup;
    private final Class<? extends ServerChannel> channelClass;

    private final Consumer<? super ServerBootstrap> serverConfiguration;

    private final InetSocketAddress listenHost;
    private final Map<ChannelOption<?>, Object> options;
    private final Map<ChannelOption<?>, Object> childOptions;
    private final List<ChannelHandler> channelHandlers;
    private final List<ChannelHandler> childHandlers;

    NettyTcpServer(
            final EventLoopGroup parentGroup,
            final Class<? extends ServerChannel> channelClass,
            final Consumer<? super ServerBootstrap> serverConfiguration,
            final InetSocketAddress listenHost,
            final Map<ChannelOption<?>, Object> options,
            final Map<ChannelOption<?>, Object> childOptions,
            final List<ChannelHandler> channelHandlers,
            final List<ChannelHandler> childHandlers) {
        this.parentGroup = checkNotNull(parentGroup, "parentGroup");
        this.channelClass = checkNotNull(channelClass, "channelClass");
        this.serverConfiguration =
                checkNotNull(serverConfiguration, "serverConfiguration");
        this.listenHost = checkNotNull(listenHost, "listenHost");
        this.options = ImmutableMap.copyOf(checkNotNull(options, "options"));
        this.childOptions = ImmutableMap.copyOf(checkNotNull(childOptions, "childOptions"));
        this.channelHandlers = ImmutableList.copyOf(checkNotNull(channelHandlers, "channelHandlers"));
        this.childHandlers = ImmutableList.copyOf(checkNotNull(childHandlers, "childHandlers"));
    }

    static NettyTcpServer forAddress(final InetSocketAddress listenAddress) {
        return new Builder().bindAddress(checkNotNull(listenAddress, "listenAddress")).build();
    }

    @Override
    TcpServer duplicate() {
        return new NettyTcpServer(
                parentGroup,
                channelClass,
                configureBootstrap(serverBootstrap().duplicate()),
                listenHost,
                options,
                childOptions,
                channelHandlers,
                childHandlers);
    }

    @Override
    public InetSocketAddress getListenAddress() {
        final Channel serverChannel = serverChannelRef.get();
        if (serverChannel == null) {
            return null;
        }

        final Attribute<InetSocketAddress> addressAttr = serverChannel.attr(BOUND_ADDRESS_KEY);
        return addressAttr.get();
    }

    @Override
    public ListenableFuture<Void> start(final TcpServerListener listener) {
        final ServerBootstrap serverBootstrap = serverBootstrap();
        serverBootstrap.handler(new LoggingHandler(getLoggingHandlerLogLevel()));
        serverConfiguration.accept(serverBootstrap);

        if (getSslContext() != null) {
            final SslHandler sslHandler;
            try {
                final SSLEngine sslEngine = getSslContext().newEngine(parentGroup.next());
                sslHandler = new SslHandler(sslEngine, getSslRequireMutualAuthentication());
            } catch (final SSLException e) {
                return FutureUtils.failedFuture(e);
            }

            if (getSslParameters() != null) {
                sslHandler.setSSLParameters(getSslParameters());
            }

            // Insert the SslHandler into the channel pipeline as the first user handler after
            // the channel is finally registered. This will ensure that the SslHandler is added
            // first in the user provided handler list.
            serverBootstrap.childHandler(
                    new ChannelInitializer<SocketChannel>() {
                        @Override
                        protected void initChannel(final SocketChannel ch) throws Exception {
                            ch.attr(BOUND_ADDRESS_KEY).set(listenHost);
                            ch.pipeline().addLast(sslHandler);
                            afterSslHandler(ch);
                        }
                    });
        } else {
            serverBootstrap.childHandler(
                    new ChannelInitializer<SocketChannel>() {
                        @Override
                        protected void initChannel(final SocketChannel ch) throws Exception {
                            ch.attr(BOUND_ADDRESS_KEY).set(listenHost);
                            afterChannelConnected(ch);
                        }
                    });
        }

        for (final Map.Entry<ChannelOption<?>, Object> entry : options.entrySet()) {
            serverBootstrap.option((ChannelOption<Object>) entry.getKey(), entry.getValue());
        }

        for (final Map.Entry<ChannelOption<?>, Object> entry : childOptions.entrySet()) {
            serverBootstrap.childOption((ChannelOption<Object>) entry.getKey(), entry.getValue());
        }

        for (final ChannelHandler handler : channelHandlers) {
            serverBootstrap.handler(handler);
        }

        for (final ChannelHandler handler : childHandlers) {
            serverBootstrap.childHandler(handler);
        }

        final SettableFuture<Void> startupFuture = SettableFuture.create();
        final ChannelFutureListener startupListener =
                new ChannelFutureListener() {
                    @Override
                    public void operationComplete(final ChannelFuture future) throws Exception {
                        if (future.cause() != null) {
                            startupFuture.setException(future.cause());
                        } else {
                            startupFuture.set(null);
                        }
                    }
                };

        serverBootstrap.bind(listenHost)
                .addListener(
                        new GenericFutureListener<Future<? super Void>>() {
                            @Override
                            public void operationComplete(
                                    final Future<? super Void> bindCompletion) throws Exception {
                                if (bindCompletion.isSuccess()) {
                                    final Channel serverChannel = ((ChannelFuture) bindCompletion).channel();
                                    serverChannelRef.compareAndSet(null, serverChannel);
                                    final Map<String, String> properties =
                                            getChannelProperties(serverChannel);

                                    afterChannelInitialized(serverChannel, properties);

                                    startupFuture.addListener(
                                            new Runnable() {
                                                @Override
                                                public void run() {
                                                    listener.serverStarted(
                                                            DefaultTcpServer.this,
                                                            properties);
                                                }
                                            },
                                            directExecutor());
                                } else {
                                    startupFuture.setException(bindCompletion.cause());
                                }
                            }
                        })
                .addListener(startupListener);

        return startupFuture;
    }

    /**
     * Configures the given {@link ServerBootstrap} based on the builder-provided settings.
     */
    private ServerBootstrap configureBootstrap(final ServerBootstrap bootstrap) {
        bootstrap.group(parentGroup).channel(channelClass);
        if (isReuseAddr()) {
            bootstrap.option(ChannelOption.SO_REUSEADDR, true);
        }
        bootstrap.attr(CONFIGURE_BOOTSTRAP_KEY, serverConfiguration);
        return bootstrap;
    }

    /**
     * Returns the {@link ServerBootstrap} instance used by {@link #start(TcpServerListener)}.
     */
    private ServerBootstrap serverBootstrap() {
        return serverBootstrapRef.get();
    }

    /**
     * Returns all channel properties for the given {@link Channel}.
     */
    private static Map<String, String> getChannelProperties(final Channel serverChannel) {
        final LinkedHashMap<String, String> properties = new LinkedHashMap<>();
        final SocketAddress localAddr = serverChannel.localAddress();

        properties.put("localAddress", localAddr.toString());
        if (localAddr instanceof InetSocketAddress) {
            final InetAddress addr = ((InetSocketAddress) localAddr).getAddress();
            if (addr != null) {
                properties.put(
                        "localIp",
                        addr.getHostAddress() + ":" + ((InetSocketAddress) localAddr).getPort());
            }
        }
        properties.put("channelProtocol", serverChannel.getClass().getSimpleName());

        for (final Map.Entry<ChannelOption<?>, Object> entry : ((ConcurrentMap<ChannelOption<?>, Object>) serverChannel
                .config()
                .getOptions())
                .entrySet()) {
            properties.put(entry.getKey().toString(), entry.getValue().toString());
        }

        for (final Map.Entry<AttributeKey<?>, Object> entry : ((ConcurrentMap<AttributeKey<?>, Object>) serverChannel
                .attrs())
                .entrySet()) {
            properties.put(entry.getKey().toString(), entry.getValue().toString());
        }

        return properties;
    }

    /**
     * Bootstrap builder for {@link NettyTcpServer}.
     */
    static final class Builder extends TcpServer.Builder<Builder, NettyTcpServer> {

        private static final AtomicInteger CHANNEL_ID = new AtomicInteger();

        private final Map<ChannelOption<?>, Object> options = new LinkedHashMap<>();
        private final Map<ChannelOption<?>, Object> childOptions = new LinkedHashMap<>();
        private final List<ChannelHandler> channelHandlers = new ArrayList<>();
        private final List<ChannelHandler> childHandlers = new ArrayList<>();

        private EventLoopGroup parentGroup;
        private Class<? extends ServerChannel> channelClass;

        Builder() {}

        @Override
        NettyTcpServer doBuild(final InetSocketAddress listenHost) {
            if (channelClass == null) {
                channelClass = NioServerSocketChannel.class;
            }
            if (parentGroup == null) {
                parentGroup = new NioEventLoopGroup(0, new DefaultThreadFactory("netty-tcp-parent"));
            }

            final NettyTcpServer tcpServer =
                    new NettyTcpServer(
                            parentGroup,
                            channelClass,
                            serverBootstrap -> configureBootstrap(serverBootstrap, options),
                            listenHost,
                            options,
                            childOptions,
                            channelHandlers,
                            childHandlers);
            tcpServer.setConnectionFilter(getConnectionFilter());
            tcpServer.setChannelId(CHANNEL_ID.incrementAndGet());
            return tcpServer;
        }

        @Override
        Builder getThis() {
            return this;
        }

        /**
         * Sets the parent {@link EventLoopGroup} to be used by the server. By default, a new
         * {@link NioEventLoopGroup} is used.
         */
        Builder parentEventLoopGroup(final EventLoopGroup eventLoopGroup) {
            parentGroup = checkNotNull(eventLoopGroup, "eventLoopGroup");
            return this;
        }

        /**
         * Sets the server socket channel class to use. By default, {@link NioServerSocketChannel}
         * is used.
         *
         * @see #parentEventLoopGroup(EventLoopGroup)
         */
        Builder channelClass(final Class<? extends ServerChannel> channelClass) {
            this.channelClass = checkNotNull(channelClass, "channelClass");
            return this;
        }

        /**
         * Adds the {@link ChannelOption} with the given value to the server's options. These are
         * used as-is when binding the server channel. This method may be called multiple times
         * and the pairs will be applied in the order they were added.
         *
         * <p>For example:
         *
         * <pre>{@code
         *   NettyTcpServer.builder()
         *       .withOption(ChannelOption.SO_BACKLOG, 128)
         *       .withChildOption(ChannelOption.AUTO_READ, false)
         *       ...
         * }</pre>
         */
        <T> Builder withOption(final ChannelOption<T> option, final T value) {
            options.put(checkNotNull(option, "option"), checkNotNull(value, "value"));
            return this;
        }

        /**
         * Adds the {@link ChannelOption} with the given value to the server's child options. These
         * are applied to each incoming connection. This method may be called multiple times and
         * the pairs will be applied in the order they were added.
         *
         * @see #withOption(ChannelOption, Object)
         */
        <T> Builder withChildOption(final ChannelOption<T> option, final T value) {
            childOptions.put(checkNotNull(option, "option"), checkNotNull(value, "value"));
            return this;
        }

        /**
         * Adds a {@link ChannelHandler} to be applied to the server's {@link ChannelPipeline}. This
         * method may be called multiple times and the handlers will be applied in the order they
         * were added.
         *
         * <p>To add a handler to be applied to each incoming connection, use
         * {@link #withChildHandler(ChannelHandler)} instead.
         *
         * <p>Note that some pipelines are long-lived and may exist beyond the lifetime of the
         * {@link NettyTcpServer}, especially in long-lived tests. Be sure to not store memory-hogging
         * objects in your handlers. Static objects should be particularly avoided.
         *
         * @see #withInitializer(ChannelInitializer)
         * @see #withChildHandler(ChannelHandler)
         */
        Builder withHandler(final ChannelHandler channelHandler) {
            channelHandlers.add(checkNotNull(channelHandler, "channelHandler"));
            return this;
        }

        /**
         * Adds a {@link ChannelHandler} to be applied to each incoming connection. This method may
         * be called multiple times and the handlers will be applied in the order they were added.
         *
         * <p>To add a handler to be applied to the server's {@link ChannelPipeline}, use
         * {@link #withHandler(ChannelHandler)} instead.
         *
         * <p>Note that some pipelines are long-lived and may exist beyond the lifetime of the
         * {@link NettyTcpServer}.
         */
        Builder withChildHandler(final ChannelHandler channelHandler) {
            childHandlers.add(checkNotNull(channelHandler, "channelHandler"));
            return this;
        }

        /**
         * Adds an initializer to modify new child pipeline created for each incoming connection.
         *
         * <p>Your initializer should generally add some application-level handlers to the pipeline.
         *
         * <p>n.b. this is equivalent to calling {@link
         * #withChildHandler(io.netty.channel.ChannelHandler)}
         */
        Builder withInitializer(final ChannelInitializer<SocketChannel> channelInitializer) {
            return withChildHandler(channelInitializer);
        }

        private static void configureBootstrap(final ServerBootstrap serverBootstrap,
                                                final Map<ChannelOption<?>, Object> options) {
            for (final Map.Entry<ChannelOption<?>, Object> entry : options.entrySet()) {
                serverBootstrap.option((ChannelOption<Object>) entry.getKey(), entry.getValue());
            }
        }
    }
}

