protected BufferedImage createPostsImage(final int WIDTH, BufferedImage image, final PostPosition... POSITIONS) {
	// Create a new BufferedImage to hold the posts
    BufferedImage postsImage = new BufferedImage(WIDTH, image.getHeight(), BufferedImage.TYPE_INT_ARGB);
    Graphics2D g2d = postsImage.createGraphics();
    g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

    // Draw the background image onto the postsImage
    g2d.drawImage(image, 0, 0, null);

    // Draw the posts at the specified positions
    for (PostPosition position : POSITIONS) {
        g2d.setColor(position.getColor());
        g2d.fillRect(position.getX(), position.getY(), position.getWidth(), position.getHeight());
    }

    // Dispose the Graphics2D object
    g2d.dispose();

    // Return the created posts image
    return postsImage;
}

