public String alignCodeToLeftMargin(String code) {
    String[] lines = code.split("\n");
    StringBuilder result = new StringBuilder();
    int minIndentation = Integer.MAX_VALUE;

    // Determine the minimum indentation
    for (String line : lines) {
        int whiteSpaceCount = 0;
        for (char c : line.toCharArray()) {
            if (Character.isWhitespace(c)) {
                whiteSpaceCount++;
            } else {
                break;
            }
        }
        minIndentation = Math.min(minIndentation, whiteSpaceCount);
    }

    // Remove the minimum indentation from all the lines
    for (String line : lines) {
        result.append(line.substring(minIndentation)).append("\n");
    }
    return result.toString().trim();
}

