public void disassembleMethodInfo(MethodInfo mi, CodeAssembler asm, Object[] params, CodeLocation returnLocation) {
    if (mi == null || asm == null) {
        return;
    }
    CodeAttribute ca = mi.getCodeAttribute();
    if (ca == null) {
        return;
    }
    CodeIterator ci = ca.iterator();
    int[] originalPositions = new int[ca.getMaxPC()];
    int position = 0;
    while (ci.hasNext()) {
        int originalIndex = ci.next();
        originalPositions[position++] = originalIndex;
        OpHandler opHandler = OpHandlers.getHandler(ci.byteAt(originalIndex));
        if (opHandler == null) {
            throw new IllegalStateException("Unrecognized opcode: " + ci.byteAt(originalIndex) + " at index " + originalIndex + " in method " + mi.getFullName());
        }
        opHandler.handle(ci, mi, asm, params, originalIndex, returnLocation);
    }
    if (returnLocation != null) {
        for (int i = 0; i < originalPositions.length; i++) {
            if (ci.byteAt(i) == Opcode.RETURN.getOpcode()) {
                int positionOfReturn = originalPositions[i];
                asm.branch(returnLocation, positionOfReturn);
            }
        }
    }
}

