                      bos.getShort();
                      bos.getShort();
                      plen = 6 + bos.getShort();
                      break;

                 default:
                      if ( pkcode == 0xAF1F  || pkcode == 16) {               
                          hedsiz += pcode_radial( bos, hoff, hedsiz, isZ, uncompdata, pinfo.threshold) ;

