                        }
                        s.ivBeforeActivationCookies[i] = cookie;
                    }
                    s.ivBeforeActivationPreInvoked++;  

                }
            }

            if (ivBeforeActivationAfterCompletionCollaborators != null) {
                int n = ivBeforeActivationAfterCompletionCollaborators.length;
                for (int i = 0; i < n; i++) {
