private static Object resolveMessage(Annotation[] parameterAnnotations, Class<?> parameterType, MessageStore messageStore) {
    Object messageSelector = null;
    MessageCorrelator correlator = null;
    for (Annotation annotation : parameterAnnotations) {
        if (annotation instanceof CitrusMessage) {
            CitrusMessage citrusMessage = (CitrusMessage) annotation;

            if (citrusMessage.selector().length() > 0) {
                messageSelector = citrusMessage.selector();
            }

            if (citrusMessage.correlator().length() > 0) {
                correlator = (MessageCorrelator) applicationContext.getBean(citrusMessage.correlator());
            }
        }
    }

    if (messageSelector != null) {
        if (correlator != null) {
            return parameterType.cast(messageStore.getMessage(messageSelector, correlator));
        } else {
            return parameterType.cast(messageStore.getMessage(messageSelector));
        }
    } else {
        return parameterType.cast(messageStore.getMessage(null, correlator));
    }
}

@SuppressWarnings({ "unchecked", "rawtypes" })
private static Object[] resolveMessages(Annotation[] parameterAnnotations, Class<?> parameterType, TestContext context) {
    CitrusMessages citrusMessages = null;

    for (Annotation annotation : parameterAnnotations) {
        if (annotation instanceof CitrusMessages) {
            citrusMessages = (CitrusMessages) annotation;
            break;
        }
    }

    if (citrusMessages != null) {
        String selector = citrusMessages.selector();
        Object[] messageIds = context.getMessageStore().getMessageIds(selector);
        Object[] messages = (Object[]) Array.newInstance(parameterType.getComponentType(), messageIds.length);

        MessageValidator messageValidator = citrusMessages.messageValidator().length() > 0 ?
                applicationContext.getBean(citrusMessages.messageValidator(), MessageValidator.class) :
                new DefaultMessageValidator();

        for (int i = 0; i < messageIds.length; i++) {
            Object messageId = messageIds[i];
            messages[i] = context.getMessageStore().getMessage(messageId);
            messageValidator.validateMessage(messages[i], context.getValidationContext());
        }

        return messages;
    }

    throw new CitrusRuntimeException("No messages specified for @CitrusMessage");
