            if (citrusResource.type() == CitrusResource.Type.ENDPOINT_RESOLVER) {
                return applicationContext.getBean(citrusResource.name(), EndpointFactory.class);
            } else if (citrusResource.type() == CitrusResource.Type.MESSAGE_CORRELATOR) {
                return applicationContext.getBean(citrusResource.name(), MessageCorrelator.class);
            } else if (citrusResource.type() == CitrusResource.Type.MESSAGE_STORE) {
                return applicationContext.getBean(citrusResource.name(), MessageStore.class);
