                return applicationContext.getBean(citrusResource.name(), GenericMessagingTemplate.class);
            } else if (citrusResource.type() == CitrusResource.Type.MESSAGE_SENDER) {
                String endpointName = citrusResource.endpointName();
                Endpoint endpoint;
                if (endpointName.length() > 0) {
                    CitrusEndpoint endpointAnnot = AnnotationUtils.findAnnotation(parameterType, CitrusEndpoint.class);
                    if (endpointAnnot != null) {
                        endpoint = applicationContext.getBean(endpointAnnot.name(), Endpoint.class);
                    } else {
                        endpoint = (Endpoint) applicationContext.getBean(endpointName);
                    }
                } else {
                    endpoint = applicationContext.getBean(Endpoint.class);
                }

                return parameterType.cast(new MessageSender(endpoint));
            } else if (citrusResource.type() == CitrusResource.Type.MESSAGE_RECEIVER) {
                String endpointName = citrusResource.endpointName();
                Endpoint endpoint;
                if (endpointName.length() > 0) {
                    CitrusEndpoint endpointAnnot = AnnotationUtils.findAnnotation(parameterType, CitrusEndpoint.class);
                    if (endpointAnnot != null) {
                        endpoint = applicationContext.getBean(endpointAnnot.name(), Endpoint.class);
                    } else {
                        endpoint = (Endpoint) applicationContext.getBean(endpointName);
                    }
                } else {
                    endpoint = applicationContext.getBean(Endpoint.class);
                }

                return parameterType.cast(new MessageReceiver(endpoint));
            } else {
                return applicationContext.getBean(citrusResource.name());
            }
        }
    }

    throw new CitrusRuntimeException("No Citrus resource annotations found on parameter annotations");
}

