                }
                break;
            case PARAMETER_TERMINATORS:
                return specific == RIGHT_PARENTHESIS || specific == COMMA;
            case ARRAY_ITEM_TERMINATORS:
                return specific == RIGHT_SQUARE_BRACKET || specific == COMMA;
            case TYPE_LIST_TERMINATORS:
                switch (specific) {
                    case KEYWORD_IMPLEMENTS:
                    case KEYWORD_THROWS:
                    case LEFT_CURLY_BRACE:
                    case COMMA:
                        return true;
                }
                break;
            case OPTIONAL_DATATYPE_FOLLOWERS:
                switch (specific) {
                    case IDENTIFIER:
                    case LEFT_SQUARE_BRACKET:
                    case DOT:
                        return true;
                }
                break;
            case SWITCH_BLOCK_TERMINATORS:
                if (specific == RIGHT_CURLY_BRACE) {
                    return true;
                }

            case SWITCH_ENTRIES:
                return specific == KEYWORD_CASE || specific == KEYWORD_DEFAULT;
            case METHOD_CALL_STARTERS:
                if (specific >= STRING && specific <= DECIMAL_NUMBER) {
                    return true;
                }
                switch (specific) {
                    case LEFT_PARENTHESIS:
                    case GSTRING_START:
                    case SYNTH_GSTRING:
                    case KEYWORD_NEW:
                        return true;
                }
                break;
            case UNSAFE_OVER_NEWLINES:
                if (ofType(specific, SYMBOL)) {
                    switch (specific) {
                        case LEFT_CURLY_BRACE:
                        case LEFT_PARENTHESIS:
                        case LEFT_SQUARE_BRACKET:
                        case PLUS:
                        case PLUS_PLUS:
                        case MINUS:
                        case MINUS_MINUS:
                        case REGEX_PATTERN:
                        case NOT:
                            return true;
                    }
                    return false;
                }
                switch (specific) {
                    case KEYWORD_INSTANCEOF:
                    case GSTRING_EXPRESSION_START:
                    case GSTRING_EXPRESSION_END:
                    case GSTRING_END:
                        return false;
                }
                return true;
            case PRECLUDES_CAST_OPERATOR:
                switch (specific) {
                    case PLUS:
                    case MINUS:
                    case PREFIX_MINUS:
                    case PREFIX_MINUS_MINUS:
                    case PREFIX_PLUS:
                    case PREFIX_PLUS_PLUS:
                    case LEFT_PARENTHESIS:
                        return false;
                }
                return !ofType(specific, COMPLEX_EXPRESSION);
            case OPERATOR_EXPRESSION:
                return specific >= DOT && specific <= RIGHT_SHIFT_UNSIGNED;
            case SYNTH_EXPRESSION:
                switch (specific) {
                    case SYNTH_CAST:
                    case SYNTH_CLOSURE:
                    case SYNTH_TERNARY:
                        return true;
                }
                break;
            case KEYWORD_EXPRESSION:
                switch (specific) {
                    case KEYWORD_NEW:
                    case KEYWORD_THIS:
                    case KEYWORD_SUPER:
                    case KEYWORD_INSTANCEOF:
                    case KEYWORD_TRUE:
                    case KEYWORD_FALSE:
                    case KEYWORD_NULL:
                        return true;
                }
                break;
            case ARRAY_EXPRESSION:
                return specific == LEFT_SQUARE_BRACKET;
            case EXPRESSION:
                if (specific >= DOT && specific <= RIGHT_SHIFT_UNSIGNED) {
                    return true;
                }
                if (specific >= STRING && specific <= DECIMAL_NUMBER) {
                    return true;
                }
                switch (specific) {
                    case SYNTH_CAST:
                    case SYNTH_CLOSURE:
                    case SYNTH_TERNARY:
                    case SYNTH_GSTRING:
                    case KEYWORD_NEW:
                    case KEYWORD_THIS:
                    case KEYWORD_SUPER:
                    case KEYWORD_INSTANCEOF:
                    case KEYWORD_TRUE:
                    case KEYWORD_FALSE:
                    case KEYWORD_NULL:
                    case LEFT_SQUARE_BRACKET:
                        return true;
                }
                break;
            case COMPLEX_EXPRESSION:
                switch (specific) {
                    case KEYWORD_NEW:
                    case SYNTH_METHOD_CALL:
                    case SYNTH_GSTRING:
                    case SYNTH_LIST:
                    case SYNTH_MAP:
                    case SYNTH_CLOSURE:
                    case SYNTH_TERNARY:
                    case SYNTH_VARIABLE_DECLARATION:
                        return true;
                }

            case SIMPLE_EXPRESSION:
                if (specific >= STRING && specific <= DECIMAL_NUMBER) {
                    return true;
                }
                switch (specific) {
                    case KEYWORD_SUPER:
                    case KEYWORD_THIS:
                    case KEYWORD_TRUE:
                    case KEYWORD_FALSE:
                    case KEYWORD_NULL:
                        return true;
                }
                break;
        }
        return false;
    }

