public static double biconjugateGradientMethod(double[][] Ap, double[] b, double[] x) {
    int n = Ap.length;
    double[] r = new double[n];
    double[] rt = new double[n];
    double[] p = new double[n];
    double[] pt = new double[n];
    double[] z = new double[n];
    double[] zt = new double[n];
    double[] q = new double[n];
    double[] qt = new double[n];
    double alpha = 1.0;
    double beta = 0.0;
    double rtr = 0.0;
    double rtrt = 0.0;
    double rtz = 0.0;
    double rtzt = 0.0;
    double pq = 0.0;
    double err = 0.0;
    for (int i = 0; i < n; i++) {
        x[i] = 0.0;
        r[i] = b[i];
        rt[i] = b[i];
        p[i] = 0.0;
        pt[i] = 0.0;
        z[i] = 0.0;
        zt[i] = 0.0;
        q[i] = 0.0;
        qt[i] = 0.0;
    }
    int maxIterations = n*100;
    for (int iter = 0; iter < maxIterations; iter++) {
        rtr = 0.0;
        rtrt = 0.0;
        rtz = 0.0;
        rtzt = 0.0;
        for (int i = 0; i < n; i++) {
            rtz += rt[i] * z[i];
            rtzt += rt[i] * zt[i];
            rtr += r[i]*r[i];
            rtrt += rt[i]*rt[i];
        }
        if (Math.sqrt(rtr) < 1e-10) {
            err = Math.sqrt(rtrt / rtzt);
            break;
        }
        if (iter == 0) {
            for (int i = 0; i < n; i++) {
                p[i] = r[i];
                pt[i] = rt[i];
            }
        } else {
            beta = rtr / rtrt;
            for (int i = 0; i < n; i++) {
                p[i] = r[i] + beta * p[i];
                pt[i] = rt[i] + beta * pt[i];
            }
        }
        for (int i = 0; i < n; i++) {
            z[i] = 0.0;
            for (int j = 0; j < n; j++) {
                z[i] += Ap[i][j] * p[j];
            }
            q[i] = 0.0;
            for (int j = 0; j < n; j++) {
                q[i] += Ap[j][i] * pt[j];
            }
        }
        pq = 0.0;
        for (int i = 0; i < n; i++) {
            pq += p[i]*q[i];
        }
        alpha = rtr / pq;
        for (int i = 0; i < n; i++) {
            x[i] += alpha * p[i];
            r[i] -= alpha * q[i];
            rt[i] -= alpha * z[i];
        }
        for (int i = 0; i < n; i++) {
            zt[i] = 0.0;
            for (int j = 0; j < n; j++) {
                zt[i] += Ap[j][i] * z[j];
            }
            qt[i] = 0.0;
            for (int j = 0; j < n; j++) {
                qt[i] += Ap[i][j] * pt[j];
            }
        }
        pq = 0.0;
        for (int i = 0; i < n; i++) {
            pq += pt[i]*qt[i];
        }
        beta = rtzt / pq;
        for (int i = 0; i < n; i++) {
            x[i] += beta * zt[i];
            r[i] -= beta * qt[i];
            rt[i] -= beta * z[i];
        }
    }
    return err;
}

