import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLEncoder;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

import org.json.JSONException;
import org.json.JSONObject;

public class OAuth {

    private static final String HMAC_SHA1 = "HMAC-SHA1";
    private static final String ENC = "UTF-8";

    /**
     * Send signed OAuth GET request
     *
     * @param url      Relative URL
     * @param params   Hash of parameters
     * @throws         JSONException If JSON object is invalid or request was abnormal
     * @return        {@link JSONObject} JSON Object that contains data from response
     */
    public static JSONObject sendSignedRequest(String url, String method, String consumerKey, String consumerSecret, String accessToken, String accessTokenSecret, SortedMap<String, String> params) throws IOException, JSONException {
        final String nonce = System.nanoTime() + "";
        final long ts = System.currentTimeMillis() / 1000;
        params.put("oauth_consumer_key", consumerKey);
        params.put("oauth_nonce", nonce);
        params.put("oauth_signature_method", HMAC_SHA1);
        params.put("oauth_timestamp", ts + "");
        params.put("oauth_token", accessToken);
        params.put("oauth_version", "1.0");
        final String baseString = getBaseString(url, method, params);
        final String signature = getSignature(baseString, consumerSecret, accessTokenSecret);
        final String authorizationHeader = getAuthorizationHeader(signature, nonce, consumerKey, accessToken, ts);
        final URL url = new URL(BASE_URL + url + "?" + getParamsString(params));
        final HttpURLConnection con = (HttpURLConnection) url.openConnection();
        con.setRequestMethod(method);
        con.setRequestProperty("Authorization", authorizationHeader);
        con.setRequestProperty("Content-Type", "application/json");
        con.setRequestProperty("User-Agent", USER_AGENT);
        final int responseCode = con.getResponseCode();
        final BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
        String inputLine;
        final StringBuilder response = new StringBuilder();
        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();
        final JSONObject jsonResponse = new JSONObject(response.toString());
        if (responseCode != 200) {
            throw new JSONException(jsonResponse.toString());
        }
        return jsonResponse;
    }

    private static String getBaseString(String url, String method, SortedMap<String, String> params) throws IOException {
        final StringBuilder base = new StringBuilder();
        base.append(method.toUpperCase()).append("&");
        base.append(urlEncode(url)).append("&");
        base.append(urlEncode(getParamsString(params)));
        return base.toString();
    }

    private static String getParamsString(SortedMap<String, String> params) {
        final StringBuilder paramsStr = new StringBuilder();
        for (final Map.Entry<String, String> entry : params.entrySet()) {
            paramsStr.append(entry.getKey()).append("=").append(entry.getValue()).append("&");
        }
        return paramsStr.toString().substring(0, paramsStr.length() - 1);
    }

    private static String getSignature(String baseString, String consumerSecret, String accessTokenSecret) throws UnsupportedEncodingException, NoSuchAlgorithmException, InvalidKeyException {
        final String key = urlEncode(consumerSecret) + "&" + urlEncode(accessTokenSecret);
        final SecretKeySpec keySpec = new SecretKeySpec(key.getBytes(ENC), HMAC_SHA1);
        final Mac mac = Mac.getInstance(HMAC_SHA1);
        mac.init(keySpec);
        final byte[] hmacBytes = mac.doFinal(baseString.getBytes(ENC));
        return new String(Base64.getEncoder().encode(hmacBytes), ENC)
                .replace("\r\n", "");
    }

    private static String getAuthorizationHeader(String signature, String nonce, String consumerKey, String accessToken, long ts) throws UnsupportedEncodingException {
        final StringBuilder buf = new StringBuilder("OAuth ");
        buf.append("oauth_nonce=\"").append(urlEncode(nonce)).append("\",");
        buf.append("oauth_signature_method=\"").append(HMAC_SHA1).append("\",");
        buf.append("oauth_timestamp=\"").append(ts).append("\",");
        buf.append("oauth_consumer_key=\"").append(urlEncode(consumerKey)).append("\",");
        buf.append("oauth_token=\"").append(urlEncode(accessToken)).append("\",");
        buf.append("oauth_signature=\"").append(urlEncode(signature)).append("\"");
        return buf.toString();
    }

    private static String urlEncode(String s) throws UnsupportedEncodingException {
        return s != null ? URLEncoder.encode(s, ENC)
                .replace("+", "%20")
                .replace("*", "%2A")
                .replace("%7E", "~") : null;
    }

}

