		    }
		    if (isHead) {
			((NonTerminal) childNode).setHead(isHead);
		    }
		}

		for (Map.Entry<String, Boolean> areRoot : rootNodes.entrySet()) {
		    if (areRoot.getValue()) {
			TreeNode rootNode = treeNodes.get(areRoot.getKey());
			if (type == null) {
			    kaf.newConstituent(rootNode);
