public static String extractNextFieldValue(byte[] packedBuffer, int position) {
    int intSize = packedBuffer[position] & 0xff;
    long longSize = 0;

    switch (intSize) {
        case 251:
            return null;
        case 252:
            intSize = packedBuffer[position + 1] & 0xff | (packedBuffer[position + 2] & 0xff) << 8;
            position += 3;
            break;
        case 253:
            intSize = packedBuffer[position + 1] & 0xff | (packedBuffer[position + 2] & 0xff) << 8 | (packedBuffer[position + 3] & 0xff) << 16;
            position += 4;
            break;
        case 254:
            longSize = (packedBuffer[position + 1] & 0xffL) | (packedBuffer[position + 2] & 0xffL) << 8 | (packedBuffer[position + 3] & 0xffL) << 16 | (packedBuffer[position + 4] & 0xffL) << 24 | (packedBuffer[position + 5] & 0xffL) << 32 | (packedBuffer[position + 6] & 0xffL) << 40 | (packedBuffer[position + 7] & 0xffL) << 48 | (packedBuffer[position + 8] & 0xffL) << 56;
            position += 9;
            break;
        default:
            position++;
    }

    byte[] bytes = new byte[intSize];
    System.arraycopy(packedBuffer, position, bytes, 0, intSize);
    return new String(bytes);
}

