public List<Plugin> getAvailablePluginsByCategory(List<Plugin> allPlugins) {
    Map<String, List<Plugin>> pluginsByCategory = new HashMap<>();
    List<Plugin> availablePlugins = new ArrayList<>();

    // group plugins by category
    for (Plugin plugin : allPlugins) {
        for (String category : plugin.getCategories()) {
            List<Plugin> pluginsInCategory = pluginsByCategory.getOrDefault(category, new ArrayList<>());
            pluginsInCategory.add(plugin);
            pluginsByCategory.put(category, pluginsInCategory);
        }
    }

    // create list of available plugins by category
    for (String category : pluginsByCategory.keySet()) {
        List<Plugin> pluginsInCategory = pluginsByCategory.get(category);
        for (Plugin plugin : pluginsInCategory) {
            if (plugin.isAvailable()) {
                availablePlugins.add(plugin);
            }
        }
    }

    return availablePlugins;
}

