public static WritableRaster applyFloydSteinbergDithering(Raster pSource, WritableRaster pDest) {
   final int width = pSource.getWidth();
   final int height = pSource.getHeight();
   if (pDest == null) { 
      pDest = pSource.createCompatibleWritableRaster();
   }
   final int[] pixel = new int[4];
   final int[][] errors = new int[width + 2][5];
   for (int y = 0; y < height; ++y) {
      for (int x = 0; x < width; ++x) {
         pSource.getPixel(x, y, pixel);
         final int oldR = pixel[0];
         final int oldG = pixel[1];
         final int oldB = pixel[2];
         final int newR = (oldR < 128) ? 0 : 255;
         final int newG = (oldG < 128) ? 0 : 255;
         final int newB = (oldB < 128) ? 0 : 255;
         pixel[0] = newR;
         pixel[1] = newG;
         pixel[2] = newB;
         pDest.setPixel(x, y, pixel);
         int quantErrorR = oldR - newR;
         int quantErrorG = oldG - newG;
         int quantErrorB = oldB - newB;
         errors[x + 1][0] += quantErrorR * 7;
         errors[x + 1][1] += quantErrorG * 7;
         errors[x + 1][2] += quantErrorB * 7;
         errors[x + 2][0] += quantErrorR * 1;
         errors[x    ][1] += quantErrorG * 3;
         errors[x + 1][1] += quantErrorG * 5;
         errors[x + 2][1] += quantErrorG * 1;
         errors[x    ][2] += quantErrorB * 3;
         errors[x + 1][2] += quantErrorB * 5;
         errors[x + 2][2] += quantErrorB * 1;
         for (int i = 0; i < 3; ++i) {
            errors[x + i][3] = errors[x + i][4];
            int newErrorR = Math.max(-errLimit, Math.min(errLimit, (int) Math.round(errors[x + i][0] / 16.0)));
            int newErrorG = Math.max(-errLimit, Math.min(errLimit, (int) Math.round(errors[x + i][1] / 16.0)));
            int newErrorB = Math.max(-errLimit, Math.min(errLimit, (int) Math.round(errors[x + i][2] / 16.0)));
            pixel[0] = pixel[0] + newErrorR;
            pixel[1] = pixel[1] + newErrorG;
            pixel[2] = pixel[2] + newErrorB;
            errors[x + i][4] = newErrorR;
            errors[x + i][0] -= newErrorR * 16;
            errors[x + i][1] -= newErrorG * 16;
            errors[x + i][2] -= newErrorB * 16;
         }
      }
      errors[0] = errors[1];
      errors[width + 1] = errors[width];
      errors[1][3] = errors[1][4];
      errors[1][0] = errors[1][1] = errors[1][2] = 0;
      errors[width][3] = errors[width][4];
      errors[width][0] = errors[width][1] = errors[width][2] = 0;
   }
   return pDest;
}

private static final int errLimit = 255;

