public static DFA orDFA(DFA dfa1, DFA dfa2, Set<Character> inputAlphabet) {

    DFAState startState = new DFAState(
            dfa1.getStartState().getStateName() + " ∨ " + dfa2.getStartState().getStateName(),
            dfa1.getStartState().isFinal() || dfa2.getStartState().isFinal());
    HashMap<Pair<DFAState, Character>, DFAState> transitionsMap = new HashMap<>();
    LinkedList<DFAState> unvisitedStates = new LinkedList<>();
    HashSet<DFAState> visitedStates = new HashSet<>();

    startState.setZeroTransition(getDFAStateFromBoth(dfa1.getStartState(), dfa2.getStartState(), inputAlphabet, transitionsMap));
    unvisitedStates.add(startState);

    while (!unvisitedStates.isEmpty()) {
        DFAState currentState = unvisitedStates.poll();
        visitedStates.add(currentState);

        for (Character symbol : inputAlphabet) {
            DFAState state1 = dfa1.getTransitionFor(currentState.getZeroTransition(), symbol);
            DFAState state2 = dfa2.getTransitionFor(currentState.getZeroTransition(), symbol);
            Pair<DFAState, Character> transitionKey = new Pair<>(currentState, symbol);
            DFAState existingTransition = transitionsMap.get(transitionKey);

            if (existingTransition == null) {
                DFAState newTransition = getDFAStateFromBoth(state1, state2, inputAlphabet, transitionsMap);
                transitionsMap.put(transitionKey, newTransition);
                currentState.addTransition(symbol, newTransition);
                if (!visitedStates.contains(newTransition)) {
                    unvisitedStates.add(newTransition);
                }
            } else {
                currentState.addTransition(symbol, existingTransition);
            }
        }
    }
    return new DFA(startState, inputAlphabet);
}

public static DFAState getDFAStateFromBoth(
        DFAState state1,
        DFAState state2,
        Set<Character> inputAlphabet,
        HashMap<Pair<DFAState, Character>, DFAState> transitionsMap) {

    String newStateName = state1.getStateName() + " ∨ " + state2.getStateName();
    boolean isFinalState = state1.isFinal() || state2.isFinal();

    DFAState newDFAState = new DFAState(newStateName, isFinalState);
    transitionsMap.put(new Pair<>(state1, null), newDFAState);
    transitionsMap.put(new Pair<>(state2, null), newDFAState);

    for (Character symbol : inputAlphabet) {
        DFAState transition1 = state1.getTransition(symbol);
        DFAState transition2 = state2.getTransition(symbol);

        if (transition1 != null && transition2 != null) {
            Pair<DFAState, Character> transitionKey = new Pair<>(newDFAState, symbol);
            DFAState existingTransition = transitionsMap.get(transitionKey);
            if (existingTransition == null) {
                newDFAState.addTransition(symbol, getDFAStateFromBoth(transition1, transition2, inputAlphabet, transitionsMap));
            } else {
                newDFAState.addTransition(symbol, existingTransition);
            }
        }
    }
    return newDFAState;
}

