protected void addDependencies(DependencyUtil.DependencyGraph<String> graph, List<String> schemas, Database database) throws DatabaseException {
	for (String schema : schemas) {
        for (String objectName : database.getObjectNames(schema)) {
            graph.addNode(schema + "." + objectName);
            for (String dependency : database.getDependencies(schema, objectName)) {
                graph.addEdge(schema + "." + objectName, dependency);
            }
        }
    }
}

