public static String getIdlContentFromClass(Class<?> cls, Set<Class<?>> cachedTypes, Set<Class<?>> cachedEnumTypes) {
    StringBuilder idlContent = new StringBuilder();
    List<Field> fields = getNonStaticFields(cls);
    Set<Class<?>> nestedTypes = new HashSet<>();
    Set<Class<?>> nestedEnums = new HashSet<>();

    idlContent.append("message ").append(cls.getSimpleName()).append(" {").append(System.lineSeparator());

    for (Field field : fields) {
        Class<?> fieldType = field.getType();
        if (isSerializable(fieldType)) {
            if (isCollection(fieldType)) {
                ParameterizedType collectionType = (ParameterizedType) field.getGenericType();
                Class<?> collectionGenericType = (Class<?>) collectionType.getActualTypeArguments()[0];
                if (isSerializable(collectionGenericType)) {
                    idlContent.append("repeated ").append(getTypeName(collectionGenericType, nestedTypes, nestedEnums, cachedTypes, cachedEnumTypes)).append(" ").append(field.getName()).append(" = ").append(getFieldNumber(field)).append(";").append(System.lineSeparator());
                }
            } else if (isMap(fieldType)) {
                ParameterizedType mapType = (ParameterizedType) field.getGenericType();
                Class<?> mapKeyType = (Class<?>) mapType.getActualTypeArguments()[0];
                Class<?> mapValueType = (Class<?>) mapType.getActualTypeArguments()[1];
                if (isSerializable(mapKeyType) && isSerializable(mapValueType)) {
                    idlContent.append("map<").append(getTypeName(mapKeyType, nestedTypes, nestedEnums, cachedTypes, cachedEnumTypes)).append(", ").append(getTypeName(mapValueType, nestedTypes, nestedEnums, cachedTypes, cachedEnumTypes)).append("> ").append(field.getName()).append(" = ").append(getFieldNumber(field)).append(";").append(System.lineSeparator());
                }
            } else {
                idlContent.append(getTypeName(fieldType, nestedTypes, nestedEnums, cachedTypes, cachedEnumTypes)).append(" ").append(field.getName()).append(" = ").append(getFieldNumber(field)).append(";").append(System.lineSeparator());
            }
        }
    }
    for (Class<?> nestedType : nestedTypes) {
        idlContent.append(getIdlContentFromClass(nestedType, cachedTypes, cachedEnumTypes));
    }
    for (Class<?> nestedEnum : nestedEnums) {
        idlContent.append(getEnumIdlContent(nestedEnum, cachedEnumTypes));
    }
    idlContent.append("}").append(System.lineSeparator());
    return idlContent.toString();
}

// Helper methods
private static List<Field> getNonStaticFields(Class<?> cls) {
    return Arrays.stream(cls.getDeclaredFields())
            .filter(f -> !Modifier.isStatic(f.getModifiers()))
            .collect(Collectors.toList());
}

private static boolean isSerializable(Class<?> cls) {
    return !(Modifier.isTransient(cls.getModifiers()) || Modifier.isStatic(cls.getModifiers()) || cls.isEnum());
}

private static boolean isCollection(Class<?> cls) {
    return Collection.class.isAssignableFrom(cls);
}

private static boolean isMap(Class<?> cls) {
    return Map.class.isAssignableFrom(cls);
}

private static String getTypeName(Class<?> cls, Set<Class<?>> nestedTypes, Set<Class<?>> nestedEnums, Set<Class<?>> cachedTypes, Set<Class<?>> cachedEnumTypes) {
    String typeName;
    if (cls.isArray()) {
        typeName = getTypeName(cls.getComponentType(), nestedTypes, nestedEnums, cachedTypes, cachedEnumTypes);
        for (int i = 0; i < cls.getDimensions(); i++) {
            typeName += "[]";
        }
    } else {
        typeName = cls.getSimpleName();
        if (!cachedTypes.contains(cls)) {
            if (isCollection(cls)) {
                ParameterizedType collectionType = (ParameterizedType) cls.getGenericSuperclass();
                Class<?> collectionGenericType = (Class<?>) collectionType.getActualTypeArguments()[0];
                nestedTypes.add(collectionGenericType);
            } else if (isMap(cls)) {
                ParameterizedType mapType = (ParameterizedType) cls.getGenericSuperclass();
                Class<?> mapKeyType = (Class<?>) mapType.getActualTypeArguments()[0];
                Class<?> mapValueType = (Class<?>) mapType.getActualTypeArguments()[1];
                nestedTypes.add(mapKeyType);
                nestedTypes.add(mapValueType);
            } else if (!cls.isPrimitive() && !cls.getPackageName().startsWith("java.")) {
                nestedTypes.add(cls);
            }
            cachedTypes.add(cls);
        }
        if (cls.isEnum()) {
            cachedEnumTypes.add(cls);
            nestedEnums.add(cls);
        }
    }
    return typeName;
}

private static String getEnumIdlContent(Class<?> cls, Set<Class<?>> cachedEnumTypes) {
    if (!cachedEnumTypes.contains(cls)) {
        StringBuilder enumContent = new StringBuilder();
        enumContent.append("enum ").append(cls.getSimpleName()).append(" { ").append(System.lineSeparator());
        for (Object constant : cls.getEnumConstants()) {
            Enum<?> enumConstant = (Enum<?>) constant;
            enumContent.append("  ").append(enumConstant.name()).append(" = ").append(enumConstant.ordinal()).append(";").append(System.lineSeparator());
        }
        enumContent.append("}").append(System.lineSeparator());
        cachedEnumTypes.add(cls);
        return enumContent.toString();
    }
    return "";
}

private static int getFieldNumber(Field field) {
    return field.getAnnotation(ProtobufField.class).value();
}

