import io.swagger.models.*;
import io.swagger.models.parameters.*;
import io.swagger.models.properties.*;
import io.swagger.util.Json;

import javax.ws.rs.*;
import java.lang.reflect.Method;
import java.util.*;

public static String generateSwaggerJson(List<Route> routes) {
  Swagger swagger = new Swagger();

  // Set swagger basic info
  Info info = new Info();
  info.setTitle("Swagger generated API");
  info.setVersion("1.0.0");
  Contact contact = new Contact();
  contact.setName("Your name");
  contact.setEmail("email@example.com");
  info.setContact(contact);  
  swagger.setInfo(info);

  // Generate definitions based on route responses
  Map<String, Model> definitions = new HashMap<>();
  for (Route route : routes) {
    Class<?> responseClass = route.getResponseType();
    if (responseClass != null) {
      Model model = ModelConverters.getInstance().readAsModel(responseClass);
      definitions.put(model.getTitle(), model);
    }
  }
  swagger.setDefinitions(definitions);

  // Add each route to the swagger
  for (Route route : routes) {
    Path path = new Path();

    Operation operation = new Operation();
    operation.setResponses(new HashMap<>());

    // Set operation method (GET, POST...)
    operation.setOperationId(route.getRequestType().name());
    switch (route.getRequestType()) {
      case GET:
        operation.setGet(new GetOperation());
        break;
      case POST:
        operation.setPost(new PostOperation());
        break;
      case PUT:
        operation.setPut(new PutOperation());
        break;
      case DELETE:
        operation.setDelete(new DeleteOperation());
        break;
      case PATCH:
        operation.setPatch(new PatchOperation());
        break;
      case HEAD:
        operation.setHead(new HeadOperation());
        break;
      case OPTIONS:
        operation.setOptions(new OptionsOperation());
        break;
      default:
        throw new RuntimeException("Invalid request type: " + route.getRequestType());
    }

    // Add path parameters
    for (RouteParameter routeParameter : route.getPathParameters()) {
      PathParameter parameter = new PathParameter();
      parameter.setName(routeParameter.getName());
      parameter.setType(routeParameter.getDataType());
      operation.addParameter(parameter);
    }

    // Add query parameters
    for (RouteParameter routeParameter : route.getQueryParameters()) {
      QueryParameter parameter = new QueryParameter();
      parameter.setName(routeParameter.getName());
      parameter.setType(routeParameter.getDataType());
      operation.addParameter(parameter);
    }

    // Add body parameter
    if (route.getBodyType() != null) {
      BodyParameter parameter = new BodyParameter();
      parameter.setSchema(new RefModel(route.getBodyType().getSimpleName()));
      operation.addParameter(parameter);
    }

    // Add headers
    for (RouteParameter routeParameter : route.getHeaderParameters()) {
      HeaderParameter parameter = new HeaderParameter();
      parameter.setName(routeParameter.getName());
      parameter.setType(routeParameter.getDataType());
      operation.addParameter(parameter);
    }

    // Set route response messages
    Response response = new Response();
    ResponseMessage responseMessage = new ResponseMessage();
    responseMessage.setCode(200);
    responseMessage.setMessage("");
    responseMessage.setResponseModel(new RefModel(route.getResponseType().getSimpleName()));
    response.addResponseMessage(200, responseMessage);
    operation.addResponse("200", response);

    // Add operation to path
    String pathString = route.getPath().replaceAll(":([^/]+)", "{$1}");
    path.set(route.getRequestType().getLowerCaseName(), operation);
    swagger.path(pathString, path);
  }

  return Json.mapper().writeValueAsString(swagger);
}

