public static DFA equivalence(DFA dfa1, DFA dfa2, Set<Character> inputAlphabet) {
    // Create a new DFA for the result of equivalence
    DFA equivalenceDFA = new DFA(inputAlphabet);

    // Set the initial state of the new DFA as the conjunction of the initial states of dfa1 and dfa2
    State initialEquivalenceState = new State(dfa1.getInitialState().getName() + "|" + dfa2.getInitialState().getName());
    equivalenceDFA.setInitialState(initialEquivalenceState);

    // Create a map to keep track of the visited states
    Map<String, State> visitedStates = new HashMap<>();

    // Create a queue for BFS traversal
    Queue<State> stateQueue = new LinkedList<>();
    stateQueue.add(initialEquivalenceState);
    visitedStates.put(initialEquivalenceState.getName(), initialEquivalenceState);

    // Perform BFS traversal on the new DFA until all states have been visited
    while (!stateQueue.isEmpty()) {
        State currentEquivalenceState = stateQueue.poll();

        // Get the corresponding states in dfa1 and dfa2
        String[] currentStateNames = currentEquivalenceState.getName().split("\\|");
        State currentDFA1State = dfa1.getStateByName(currentStateNames[0]);
        State currentDFA2State = dfa2.getStateByName(currentStateNames[1]);

        // Check if the pair of states is accepting or not
        if (currentDFA1State.isAccepting() != currentDFA2State.isAccepting()) {
            equivalenceDFA.addAcceptingState(currentEquivalenceState);
        }

        // Add transitions from the current equivalence state to the next equivalence state, based on input symbols
        for (char symbol : inputAlphabet) {
            State nextDFA1State = dfa1.getTransition(currentDFA1State, symbol);
            State nextDFA2State = dfa2.getTransition(currentDFA2State, symbol);

            if (nextDFA1State != null && nextDFA2State != null) {
                // Get the name of the next equivalence state
                String nextEquivalenceStateName = nextDFA1State.getName() + "|" + nextDFA2State.getName();

                // Add the next equivalence state to the new DFA, if it hasn't been visited yet
                if (!visitedStates.containsKey(nextEquivalenceStateName)) {
                    State nextEquivalenceState = new State(nextEquivalenceStateName);
                    stateQueue.add(nextEquivalenceState);
                    visitedStates.put(nextEquivalenceStateName, nextEquivalenceState);
                }

                // Add the transition from currentEquivalenceState to nextEquivalenceState
                equivalenceDFA.addTransition(currentEquivalenceState, nextEquivalenceState, symbol);
            }
        }
    }

    return equivalenceDFA;
}

