public String scanNext(Pattern pattern) throws IOException {
    StringBuilder sb = new StringBuilder();
    while (true) {
        int ch = reader.read();
        if (ch == -1) {
            break; // end of input
        }
        sb.append((char) ch);
        if (pattern.matcher(sb.toString()).matches()) {
            return sb.toString().trim();
        }
    }
    throw new IOException("I/O-Error occurred");
}

