public static Query copyQuery(User copier, Locale locale, Query originalQuery, String newName, Panel targetPanel, boolean copyAnswers, boolean copyComments) {
    // Create a new query with the new name and target panel
    Query newQuery = new Query(newName, targetPanel);

    // Copy the sections from the original query
    for (Section section : originalQuery.getSections()) {
        newQuery.addSection(section);
    }

    // Copy the pages from the original query
    for (Page page : originalQuery.getPages()) {
        newQuery.addPage(page);
    }

    // Copy the answers if specified
    if (copyAnswers) {
        for (Answer answer : originalQuery.getAnswers()) {
            newQuery.addAnswer(answer);
        }
    }

    // Copy the comments if specified
    if (copyComments) {
        for (Comment comment : originalQuery.getComments()) {
            newQuery.addComment(comment);
        }
    }

    return newQuery;
}

