public void writeSortKeyBytes(Builder collationBuffer, CollationIterator iter,
                            int minLevel, boolean writeCaseLevel, Callback callback) {
    int level = minLevel;
    while (level <= iter.getStrength()) {
        if (!callback.needToWrite(level)) {
            break;
        }

        if (writeCaseLevel && level == Collation.LEVEL_CASE) {
            collationBuffer.appendByte(iter.getCaseBits());
        }

        int before = collationBuffer.length();
        iter.getRawCollationKey(collationBuffer, level);

        if (collationBuffer.length() == before) {
            collationBuffer.appendByte(Collation.LEVEL_TERMINATOR_BYTE);
            break;
        }

        collationBuffer.appendByte(Collation.LEVEL_SEPARATOR_BYTE);
        level++;
    }
}

