public static AttributeValues fromKamolsMarkup(String tag) {
	// Split the tag into parts based on the delimiter
    String[] parts = tag.split("\\|");
    // Initialize the AttributeValues object
    AttributeValues attributeValues = new AttributeValues();
    // Iterate over the parts and populate the attributeValues object
    for (String part : parts) {
        // Split each part into key and value based on the '=' delimiter
        String[] keyValue = part.split("=");
        if (keyValue.length == 2) {
            // Add the key-value pair to the attributeValues object
            attributeValues.put(keyValue[0], keyValue[1]);
        }
    }
