public static double calculateMSE(double[] bins, int n) {
    double sum = 0.0;
    double average = 0.0;
    for (int i = 0; i < n; i++) {
        sum += bins[i];
    }
    average = sum / n;
    double mse = 0.0;
    for (int i = 0; i < n; i++) {
        mse += Math.pow((bins[i] - average), 2);
    }
    return mse / n;
}

