    public static List<LocalDateTime> createLocalDateTimeIterator(PropertyList rdata, LocalDateTime start, boolean strict) throws ParseException {
        try {
            Recur recur = buildRecur(rdata);

            if (recur == null) {
                return new ArrayList<>();
            }

            DateList exDates = buildDateList(rdata, Property.EXDATE);
            DateList rDates = buildDateList(rdata, Property.RDATE);

            List<Period> periods = recur.getDates(start.toLocalDate().atTime(LocalTime.MIN), null, Period.ofYears(10));
            List<LocalDateTime> localDateTimes = periods.stream()
                    .flatMap(period -> period.stream().map(LocalDate::atTime))
                    .filter(date -> {
                        LocalDate localDate = date.toLocalDate();
                        return !exDates.contains(new Date(localDate.toEpochDay() * 86400000L)) && (!rDates.isEmpty() || recur.isInRecurrence(localDate));
