    private static Recur buildRecur(PropertyList rdata) {
        Recur recur = null;

        for (Property property : rdata) {
            if (Property.RRULE.equals(property.getName())) {
                Recurrence recurrence = new Recurrence(property.getValue());
                recur = recurrence.getRecur();
            } else if (Property.EXRULE.equals(property.getName())) {
                Recurrence recurrence = new Recurrence(property.getValue());
                recur = recurrence.getRecur();
                recur.setInclude(false);
