    private static DateList buildDateList(PropertyList rdata, String propName) {
        Property property = rdata.getProperty(propName);
        DateList dateList = new DateList();

        if (property != null) {
            String value = property.getValue();

            if (!value.isEmpty()) {
                TimeZoneRegistry registry = TimeZoneRegistryFactory.getInstance().createRegistry();
                TimeZone timezone = registry.getTimeZone("UTC");
                List<String> values = Arrays.stream(value.split(",")).map(String::trim).collect(Collectors.toList());

                for (String string : values) {
                    try {
                        String[] parts = string.split("T");

                        if (parts.length == 1) {
                            dateList.add(new Date(parseDate(parts[0]).atStartOfDay(timezone).getTime()));
