                            dateList.add(new Date(parseDateTime(string).atZone(timezone).toInstant().toEpochMilli()));
                        }
                    } catch (Exception e) {
                        System.err.println("Cannot parse date string: " + string + ". Error: " + e.getMessage());
                    }
                }
            }
        }

        return dateList;
    }

    private static LocalDateTime parseDateTime(String dateTime) {
        try {
            return LocalDateTime.parse(dateTime, DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss"));
        } catch (DateTimeParseException e) {
            return LocalDateTime.parse(dateTime, DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'")).plus(1, ChronoUnit.HOURS);
        }
    }

    private static LocalDate parseDate(String s) {
        try {
            return LocalDate.parse(s, DateTimeFormatter.ofPattern("yyyyMMdd"));
        } catch (DateTimeParseException e) {
            return LocalDate.parse(s, DateTimeFormatter.ofPattern("yyyyMMdd'Z'")).plus(1, ChronoUnit.DAYS);
        }
    }
}

