import com.microsoft.azure.PagedList;
import com.microsoft.azure.management.Azure;
import com.microsoft.azure.management.network.VpnGateway;

public Observable<PagedList<VpnGateway>> listByResourceGroupAsync(final String resourceGroupName) {
    if (resourceGroupName == null || resourceGroupName.isEmpty()) {
        throw new IllegalArgumentException("Resource group name cannot be null or empty");
    }

    return Observable.create(subscriber -> {
        try {
            final Azure azure = Azure.authenticate(credFile).withDefaultSubscription();
            PagedList<VpnGateway> vpnGateways = azure.vpnGateways().listByResourceGroup(resourceGroupName);
            subscriber.onNext(vpnGateways);
            subscriber.onCompleted();
        } catch (Exception e) {
            subscriber.onError(e);
        }
    });
}

