public void writeMolecule(IAtomContainer container, OutputStream outputStream) throws Exception {
    PrintWriter writer = new PrintWriter(outputStream);

    // Write the header
    writer.println("MyMolecule");
    writer.println("");
    writer.println(" 00000000000000");

    // Write the atom block
    writer.println(container.getAtomCount());
    writer.println("");

    // Write the atom information
    for (IAtom atom : container.getAtoms()) {
        writer.println(atom.getSymbol() + " " + atom.getX() + " " + atom.getY() + " " + atom.getZ());
    }

    // Write the bond block
    writer.println(container.getBondCount());
    writer.println("");

    // Write the bond information
    for (IBond bond : container.getBonds()) {
        writer.println(bond.getAtom1().getIndex() + " " + bond.getAtom2().getIndex() + " " + bond.getOrder());
    }

    // Write the properties block
    writer.println("M  END");

    writer.flush();
}

