private Object extendArray(Object array, int currentSize, int requiredSize) {
        if (requiredSize < currentSize) {
            return array;
        } else {
            Object newArray = null;
            int newSize = currentSize * 2;
            if (newSize <= requiredSize) {
                newSize = requiredSize + 1;
