private static Document KAFToDOM(KAFDocument kaf) {
	// Create a new DOM document
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    DocumentBuilder builder;
    Document doc = null;
    try {
        builder = factory.newDocumentBuilder();
        doc = builder.newDocument();
    } catch (ParserConfigurationException e) {
        e.printStackTrace();
    }

    // Create the root element and append it to the document
    Element root = doc.createElement("KAF");
    doc.appendChild(root);

    // Add the KAFDocument's metadata to the root element
    Element metadata = doc.createElement("metadata");
    root.appendChild(metadata);
    for (Map.Entry<String, String> entry : kaf.getMetadata().entrySet()) {
        Element metaItem = doc.createElement("meta");
        metaItem.setAttribute("name", entry.getKey());
        metaItem.setAttribute("value", entry.getValue());
        metadata.appendChild(metaItem);
    }

    // Add the KAFDocument's linguistic layers to the root element
    for (Layer layer : kaf.getLayers()) {
        Element layerElement = doc.createElement(layer.getType().toString());
        root.appendChild(layerElement);
        for (Term term : layer.getTerms()) {
            Element termElement = doc.createElement("term");
            termElement.setAttribute("id", term.getId());
            termElement.setAttribute("lemma", term.getLemma());
            termElement.setAttribute("pos", term.getPos());
            layerElement.appendChild(termElement);
        }
    }

    return doc;
}

