public static <S, L> MinimizationResult<S, L> minimizeAutomaton(UniversalGraph<S, L> graph) {
    // initialize variables
    Map<Pair<S, S>, Boolean> eqClasses = new HashMap<>();
    Queue<Pair<S, S>> worklist = new LinkedList<>();

    // step 1: mark final and non-final states as different
    for (S s1 : graph.getStates()) {
        boolean s1IsFinal = graph.isFinalState(s1);
        for (S s2 : graph.getStates()) {
            if (s1 != s2) {
                boolean s2IsFinal = graph.isFinalState(s2);
                boolean areEqual = s1IsFinal == s2IsFinal;
                eqClasses.put(new Pair<>(s1, s2), areEqual);
                if (!areEqual) {
                    worklist.offer(new Pair<>(s1, s2));
                }
            }
        }
    }

    // step 2: iterate until no more classes are split
    while (!worklist.isEmpty()) {
        Pair<S, S> pair = worklist.poll();
        S s1 = pair.getFirst();
        S s2 = pair.getSecond();

        // iterate over all labels
        for (L label : graph.getLabels()) {
            S t1 = graph.getSuccessor(s1, label);
            S t2 = graph.getSuccessor(s2, label);

            if (t1 != null && t2 != null) {
                // get equivalence classes of successor states
                Pair<S, S> tPair = new Pair<>(t1, t2);
                boolean tEqual = eqClasses.getOrDefault(tPair, false);
                boolean sEqual = eqClasses.get(pair);

                // if successor states are not equivalent, put them in a different class
                if (!tEqual) {
                    eqClasses.put(tPair, true);
                    if (sEqual) {
                        worklist.offer(tPair);
                    }
                }
            }
        }
    }

    // create minimized graph
    UniversalGraph<Set<S>, L> minGraph = new UniversalGraph<>();
    Map<S, Set<S>> stateClasses = new HashMap<>();

    // add state classes to map
    for (S state : graph.getStates()) {
        Set<S> stateClass = new HashSet<>();
        for (S other : graph.getStates()) {
            if (eqClasses.get(new Pair<>(state, other))) {
                stateClass.add(other);
            }
        }
        if (!stateClasses.containsValue(stateClass)) {
            stateClasses.put(state, stateClass);
        }
    }

    // add states and transitions to minimized graph
    for (Set<S> stateClass : stateClasses.values()) {
        if (!stateClass.isEmpty()) {
            S representative = stateClass.iterator().next();
            minGraph.addState(stateClass);

            for (L label : graph.getLabels()) {
                S successor = graph.getSuccessor(representative, label);
                if (successor != null) {
                    Set<S> successorClass = stateClasses.get(successor);
                    minGraph.addTransition(stateClass, label, successorClass);
                }
            }
        }
    }

    // create result structure
    return new MinimizationResult<>(minGraph, stateClasses);
}

