        StringBuilder sb = new StringBuilder();

        // Add indentation
        for (int i = 0; i < indent; i++) {
            sb.append("  ");
        }

        // Add opening tag
        sb.append("<").append(element.getTagName()).append(">");

        // Add content
        sb.append(element.getContent());

        // Add closing tag
        sb.append("</").append(element.getTagName()).append(">");

        // Write to file or console
        System.out.println(sb.toString());
    }
}

