public static Type resolveReturnTypeForGenericMethod(Method method, Class<?> clazz) {
    Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(clazz);
    Type returnType = method.getGenericReturnType();
    return resolveType(returnType, typeVariableMap);
}

private static Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> clazz) {
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    while (clazz != null) {
        extractTypeVariablesFromGenericInterfaces(clazz.getGenericInterfaces(), typeVariableMap);
        Type genericSuperType = clazz.getGenericSuperclass();
        if (genericSuperType instanceof ParameterizedType) {
            extractTypeVariablesFromRawType(clazz.getSuperclass(), typeVariableMap);
            extractTypeVariablesFromType((ParameterizedType) genericSuperType, typeVariableMap);
        } else if (genericSuperType instanceof Class) {
            extractTypeVariablesFromRawType((Class<?>) genericSuperType, typeVariableMap);
        }
        clazz = clazz.getSuperclass();
    }
    return typeVariableMap;
}

private static void extractTypeVariablesFromGenericInterfaces(Type[] genericInterfaces, Map<TypeVariable<?>, Type> typeVariableMap) {
    for (Type genericInterface : genericInterfaces) {
        if (genericInterface instanceof ParameterizedType) {
            extractTypeVariablesFromType((ParameterizedType) genericInterface, typeVariableMap);
        } else if (genericInterface instanceof Class) {
            extractTypeVariablesFromRawType((Class<?>) genericInterface, typeVariableMap);
        }
    }
}

private static void extractTypeVariablesFromType(ParameterizedType type, Map<TypeVariable<?>, Type> typeVariableMap) {
    Type rawType = type.getRawType();
    extractTypeVariablesFromRawType((Class<?>) rawType, typeVariableMap);
    Type[] typeArguments = type.getActualTypeArguments();
    TypeVariable<?>[] typeVariables = ((Class<?>) rawType).getTypeParameters();
    for (int i = 0; i < typeVariables.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            typeVariableMap.put(typeVariables[i], typeArgument);
        } else if (typeArgument instanceof GenericArrayType) {
            Type componentType = ((GenericArrayType) typeArgument).getGenericComponentType();
            if (componentType instanceof Class) {
                typeVariableMap.put(typeVariables[i], Array.newInstance((Class<?>) componentType, 0).getClass());
            }
        }
    }
}

private static void extractTypeVariablesFromRawType(Class<?> clazz, Map<TypeVariable<?>, Type> typeVariableMap) {
    TypeVariable<?>[] typeVariables = clazz.getTypeParameters();
    for (TypeVariable<?> typeVariable : typeVariables) {
        typeVariableMap.put(typeVariable, Object.class);
    }
}

private static Type resolveType(Type type, Map<TypeVariable<?>, Type> typeVariableMap) {
    if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        type = typeVariableMap.get(typeVariable);
        if (type == null) {
            type = Object.class;
        }
        return resolveType(type, typeVariableMap);
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Type[] resolvedTypeArguments = new Type[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            resolvedTypeArguments[i] = resolveType(typeArgument, typeVariableMap);
        }
        return newParameterizedTypeWithOwner(parameterizedType.getOwnerType(), (Class<?>) parameterizedType.getRawType(), resolvedTypeArguments);
    } else if (type instanceof GenericArrayType) {
        GenericArrayType genericArrayType = (GenericArrayType) type;
        Type componentType = genericArrayType.getGenericComponentType();
        Type resolvedComponentType = resolveType(componentType, typeVariableMap);
        return new GenericArrayTypeImpl(resolvedComponentType);
    } else {
        return type;
    }
}

private static ParameterizedType newParameterizedTypeWithOwner(Type ownerType, Class<?> rawType, Type... typeArguments) {
    return new SimpleParameterizedType(ownerType, rawType, typeArguments);
}

private static class SimpleParameterizedType implements ParameterizedType {

    private final Type ownerType;

    private final Class<?> rawType;

    private final Type[] typeArguments;

    public SimpleParameterizedType(Type ownerType, Class<?> rawType, Type[] typeArguments) {
        this.ownerType = ownerType;
        this.rawType = rawType;
        this.typeArguments = typeArguments;
    }

    @Override
    public Type[] getActualTypeArguments() {
        return typeArguments.clone();
    }

    @Override
    public Type getRawType() {
        return rawType;
    }

    @Override
    public Type getOwnerType() {
        return ownerType;
    }

    @Override
    public String toString() {
        StringBuilder stringBuilder = new StringBuilder();
        if (ownerType != null) {
            stringBuilder.append(ownerType.getTypeName()).append('.');
            if (ownerType instanceof ParameterizedType && ((ParameterizedType) ownerType).getRawType() instanceof Class) {
                stringBuilder.append(((Class<?>) ((ParameterizedType) ownerType).getRawType()).getSimpleName()).append('$');
            }
        }
        stringBuilder.append(rawType.getSimpleName()).append('<');
        for (int i = 0; i < typeArguments.length; i++) {
            if (i != 0) {
                stringBuilder.append(", ");
            }
            Type typeArgument = typeArguments[i];
            stringBuilder.append(typeArgument.getTypeName());
        }
        stringBuilder.append('>');
        return stringBuilder.toString();
    }
}

private static final class GenericArrayTypeImpl implements GenericArrayType {

    private final Type componentType;

    public GenericArrayTypeImpl(Type componentType) {
        this.componentType = componentType;
