public static void modL(byte[] s) {
    int carry = 0;
    for (int i = 0; i < 32; i++) {
        carry |= s[i + 32];
        s[i] = (byte)(s[i] - ((carry << 4) & 0xff));
        carry = (carry >> 8) & 0xff;
    }
    carry |= s[32];
    int m = carry - 1;
    for (int i = 0; i < 32; i++) {
        s[i] = (byte)(s[i] ^ (m & (s[i] ^ s[i + 32])));
    }
    int coef = 0x8d;
    carry = 0;
    for (int i = 0; i < 63; i++) {
        int b = s[i] & 0xff;
        s[i] = (byte)(s[i] ^ ((coef * carry) & 0xff));
        carry = b;
    }
    s[63] = (byte)(s[63] ^ ((coef * carry) & 0xff));
    carry = 0;
    for (int i = 0; i < 32; i++) {
        s[i] = (byte)(s[i] ^ ((carry - 1) & (s[i] ^ s[i + 32])));
        carry = (s[i] >> 7) & 0xff;
    }
}

