public RequestTemplate resolve(Map<String, Object> unencoded, Map<String, String> alreadyEncoded) {
    RequestTemplate resolved = new RequestTemplate();
    for (Map.Entry<String, Collection<String>> entry : requestTemplate.headers().entrySet()) {
        Collection<String> resolvedValues = new ArrayList<String>();
        for (String unresolved : entry.getValue()) {
            resolvedValues.addAll(encodeAndResolve(unencoded, alreadyEncoded, unresolved));
        }
        resolved.headers(entry.getKey(), resolvedValues);
    }
    resolved.method(requestTemplate.method());
    resolved.decodeSlash(requestTemplate.decodeSlash());
    resolved.url(encodeAndResolve(unencoded, alreadyEncoded, requestTemplate.url()));
    resolved.queries(encodeAndResolveQueries(unencoded, alreadyEncoded, requestTemplate.queries()));
    resolved.body(encodeAndResolve(unencoded, alreadyEncoded, requestTemplate.bodyTemplate()));
    return resolved;
}

private Collection<String> encodeAndResolve(Map<String, Object> unencoded, Map<String, String> alreadyEncoded, String unresolved) {
    Matcher matcher = PATH_PATTERN.matcher(unresolved);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String key = matcher.group(1);
        String value = resolveVariable(unencoded, alreadyEncoded, key);
        if (value == null) {
            throw new IllegalArgumentException("Map has no value for " + key);
        }
        matcher.appendReplacement(sb, "");
        sb.append(value);
    }
    matcher.appendTail(sb);
    return Collections.singleton(encodedQuery(sb.toString()));
}

private Collection<Pair<String, Collection<String>>> encodeAndResolveQueries(Map<String, Object> unencoded, Map<String, String> alreadyEncoded, List<Pair<String, Collection<String>>> queries) {
    Collection<Pair<String, Collection<String>>> resolved = new ArrayList<Pair<String, Collection<String>>>();
    for (Pair<String, Collection<String>> nameAndValues : queries) {
        String name = encodedQuery(resolveVariable(unencoded, alreadyEncoded, nameAndValues.getLeft()));
        Collection<String> resolvedValues = new ArrayList<String>();
        for (String unresolvedValue : nameAndValues.getRight()) {
            String resolvedValue = resolveVariable(unencoded, alreadyEncoded, unresolvedValue);
            resolvedValues.add(resolvedValue == null ? null : encodedQuery(resolvedValue));
        }
        resolved.add(Pair.of(name, resolvedValues));
    }
    return resolved;
}

public String resolve(Object... variables) {
    if (variables.length % 2 != 0) {
        throw new IllegalArgumentException("variable arg length must be even: key, value, key, value");
    }
    Map<String, Object> variableMap = new LinkedHashMap<String, Object>();
    for (int i = 0; i < variables.length; i += 2) {
        Object key = variables[i];
        Object value = variables[i + 1];
        if (!(key instanceof String)) {
            throw new IllegalArgumentException("variable keys must be strings: " + key);
        }
        variableMap.put((String) key, value);
    }
    return resolve(variableMap);
}

