import org.apache.hadoop.io.BytesWritable;
import org.apache.spark.SparkConf;

public class BulkImport {

  public static void bulkImport(JavaPairRDD<String,String> data, SimpleConfiguration opts) throws Exception {

    FluoConfiguration config = new FluoConfiguration(opts);
    Connector conn = config.getAccumuloConnector();
    BatchWriterConfig bwConfig = new BatchWriterConfig();
    bwConfig.setMaxMemory(10000000L);  

    SparkConf sconf = new SparkConf().setAppName("BulkWriter");
    Configuration hadoopConf = new Configuration();

    final String instance = conn.getInstance().getInstanceName();
    final String zookeepers = conn.getInstance().getZooKeepers();
    final String user = conn.whoami();
    final String password = new String(conn.securityOperations().getUserAuthorizations(conn.whoami()).encodePass());
    final String table = opts.getString("table");

    final AccumuloOutputFormat outputFormat = new AccumuloOutputFormat();
    outputFormat.setZooKeeperInstance(hadoopConf,instance,zookeepers);
    outputFormat.setConnectorInfo(hadoopConf,user,password.getBytes());
    outputFormat.setCreateTables(true);
    outputFormat.setDefaultTableName(table);
    outputFormat.setBatchWriterConfig(bwConfig);

    final JavaPairRDD<Text,Mutation> rdd = data.mapToPair((Function<Tuple2<String,String>,Tuple2<Text,Mutation>>)
      new PairFunction<Tuple2<String,String>,Text,Mutation>() {
        public Tuple2<Text,Mutation> call(Tuple2<String,String> pair) {
          final Text row = new Text(pair._1());
          final Bytes colf = Bytes.of("data");
          final Bytes cq = Bytes.of("value");
          final Bytes cv = Bytes.of("1");
          final MutableBytes val = MutableBytes.wrap(pair._2().getBytes());
          final Mutation mutation = new Mutation(row);
          mutation.put(colf,cq,cv,val);
          return new Tuple2<Text,Mutation>(row,mutation);
        }
      }
    );

    rdd.saveAsNewAPIHadoopFile("/tmp/bulkimport","org.apache.hadoop.io.Text",Mutation.class,outputFormat,hadoopConf);
  }

}

