public static String getConversion(final ConversionType conversionType, final Object src) {
    if (src == null) {
        return null;
    }

    String result = null;

    switch (conversionType) {
        case INTEGER_TO_STRING:
            if (src instanceof Integer) {
                result = String.valueOf((Integer) src);
            }
            break;
        case DOUBLE_TO_STRING:
            if (src instanceof Double) {
                result = String.valueOf((Double) src);
            }
            break;
        case STRING_TO_INTEGER:
            if (src instanceof String) {
                result = String.valueOf(Integer.parseInt((String) src));
            }
            break;
        case STRING_TO_DOUBLE:
            if (src instanceof String) {
                result = String.valueOf(Double.parseDouble((String) src));
            }
            break;
        default:
            throw new IllegalArgumentException("Unsupported conversion type: " + conversionType);
    }

    return result;
}

