public static Table joinTable(Table table2, String[] col2Names, double joiner) {
    Table result = new Table();
    Set<Integer> joinedRows = new HashSet<Integer>();
    // iterate over table1
    for (int i = 0; i < table1.getNumRows(); i++) {
        // iterate over table2 and check if there's a match
        for (int j = 0; j < table2.getNumRows(); j++) {
            boolean match = true;
            String[] colNames = table2.getColumnNames();
            for (String colName : col2Names) {
                Column col = table2.getColumn(colName);
                if (col == null) {
                    throw new IllegalArgumentException("Column " + colName + " does not exist in table2.");
                }
                Object value = col.getValueAt(j);
                if (value == null || 
                        (value instanceof Double && Math.round((Double) value) != Math.round(joiner))) {
                    match = false;
                    break;
                }
            }
            // if match found, join the rows and add to result table
            if (match && !joinedRows.contains(j)) {
                for (String colName : table2.getColumnNames()) {
                    Column col = table2.getColumn(colName);
                    result.addColumn(colName, col.getType());
                }
                for (String colName : table1.getColumnNames()) {
                    Column col = table1.getColumn(colName);
                    result.addColumn(colName, col.getType());
                }
                for (String colName : table2.getColumnNames()) {
                    Column col = table2.getColumn(colName);
                    Object value = col.getValueAt(j);
                    result.getColumn(colName).addValue(value);
                }
                for (String colName : table1.getColumnNames()) {
                    Column col = table1.getColumn(colName);
                    Object value = col.getValueAt(i);
                    result.getColumn(colName).addValue(value);
                }
                joinedRows.add(j);
            }
        }
    }
    return result;
}

