public JarBuilder addDirectoryOrZipToJar(String path, File dirOrZip) throws IOException {
    try (JarOutputStream out = new JarOutputStream(new FileOutputStream(jarFile))) {
        if (dirOrZip.isDirectory()) {
            addDirectory(path, dirOrZip, out);
        } else {
            addZipOrJar(path, dirOrZip, out);
        }
    }
    return this;
}

private void addDirectory(String path, File dir, JarOutputStream out) throws IOException {
    if (!path.isEmpty()) {
        if (!path.endsWith("/")) {
            path += "/";
        }
        JarEntry entry = new JarEntry(path);
        entry.setTime(dir.lastModified());
        out.putNextEntry(entry);
        out.closeEntry();
    }
    if (dir.exists()) {
        File[] files = dir.listFiles();
        if (files != null) {
            for (File file : files) {
                String childPath = !path.isEmpty() ? path + file.getName() : file.getName();
                if (file.isDirectory()) {
                    addDirectory(childPath + "/", file, out);
                } else {
                    addFile(childPath, file, out);
                }
            }
        }
    }
}

private void addZipOrJar(String path, File zipOrJar, JarOutputStream out) throws IOException {
    try (ZipFile zipFile = new ZipFile(zipOrJar)) {
        Enumeration<? extends ZipEntry> entries = zipFile.entries();
        while (entries.hasMoreElements()) {
            ZipEntry entry = entries.nextElement();
            String childPath = !path.isEmpty() ? path + entry.getName() : entry.getName();
            if (entry.isDirectory()) {
                addDirectory(childPath + "/", new File(childPath), out);
            } else {
                InputStream in = zipFile.getInputStream(entry);
                addStream(childPath, in, out, entry.getTime());
            }
        }
    }
}

private void addFile(String path, File file, JarOutputStream out) throws IOException {
    try (InputStream in = new FileInputStream(file)) {
        addStream(path, in, out, file.lastModified());
    }
}

private void addStream(String path, InputStream in, JarOutputStream out, long lastModified) throws IOException {
    JarEntry entry = new JarEntry(path);
    entry.setTime(lastModified);
    out.putNextEntry(entry);
    byte[] buffer = new byte[1024];
    int count;
    while ((count = in.read(buffer)) != -1) {
        out.write(buffer, 0, count);
    }
    out.closeEntry();
}

