public SortedMap<K, V> filteredSortedMap(final Predicate<? super K> keyPredicate, final Predicate<? super V> valuePredicate) {
    Objects.requireNonNull(keyPredicate);
    Objects.requireNonNull(valuePredicate);

    return new FilteredSortedMap<>(this, keyPredicate, valuePredicate);
}

private static final class FilteredSortedMap<K, V> extends AbstractSortedMap<K, V> implements Serializable {

    private static final long serialVersionUID = 912986545866124060L;

    private final SortedMap<K, V> sortedMap;
    private final Predicate<? super K> keyPredicate;
    private final Predicate<? super V> valuePredicate;

    private Set<Map.Entry<K, V>> entrySetView;
    private Set<K> keySetView;

    FilteredSortedMap(SortedMap<K, V> sortedMap, final Predicate<? super K> keyPredicate, final Predicate<? super V> valuePredicate) {
        this.sortedMap = Objects.requireNonNull(sortedMap);
        this.keyPredicate = Objects.requireNonNull(keyPredicate);
        this.valuePredicate = Objects.requireNonNull(valuePredicate);
    }

    @Override
    public Comparator<? super K> comparator() {
        return sortedMap.comparator();
    }

    @Override
    public SortedMap<K, V> subMap(K fromKey, K toKey) {
        return new FilteredSortedMap<>(sortedMap.subMap(fromKey, toKey), keyPredicate, valuePredicate);
    }

    @Override
    public SortedMap<K, V> headMap(K toKey) {
        return new FilteredSortedMap<>(sortedMap.headMap(toKey), keyPredicate, valuePredicate);
    }

    @Override
    public SortedMap<K, V> tailMap(K fromKey) {
        return new FilteredSortedMap<>(sortedMap.tailMap(fromKey), keyPredicate, valuePredicate);
    }

    @Override
    public K firstKey() {
        final Iterator<Entry<K, V>> iterator = sortedMap.entrySet().iterator();
        while (iterator.hasNext()) {
            final Entry<K, V> entry = iterator.next();
            if (keyPredicate.test(entry.getKey()) && valuePredicate.test(entry.getValue())) {
                return entry.getKey();
            }
        }
        throw new NoSuchElementException();
    }

    @Override
    public K lastKey() {
        final Iterator<Entry<K, V>> descendingIterator = sortedMap.descendingMap().entrySet().iterator();
        while (descendingIterator.hasNext()) {
            final Entry<K, V> entry = descendingIterator.next();
            if (keyPredicate.test(entry.getKey()) && valuePredicate.test(entry.getValue())) {
                return entry.getKey();
            }
        }
        throw new NoSuchElementException();
    }

    @Override
    public int size() {
        return entrySet().size();
    }

    @Override
    public boolean isEmpty() {
        return entrySet().isEmpty();
    }

    @Override
    public boolean containsKey(Object key) {
        Objects.requireNonNull(key);
        return keyPredicate.test((K) key) && valuePredicate.test(sortedMap.get(key));
    }

    @Override
    public boolean containsValue(Object value) {
        Objects.requireNonNull(value);
        final Iterator<Entry<K, V>> iterator = entrySet().iterator();
        while (iterator.hasNext()) {
            final Entry<K, V> entry = iterator.next();
            if (Objects.equals(entry.getValue(), value)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public V get(Object key) {
        Objects.requireNonNull(key);
        if (!keyPredicate.test((K) key)) {
            return null;
        }
        final V value = sortedMap.get(key);
        if (value == null || !valuePredicate.test(value)) {
            return null;
        }
        return value;
    }

    @Override
    public V put(K key, V value) {
        Objects.requireNonNull(key);
        Objects.requireNonNull(value);

        if (!keyPredicate.test(key) || !valuePredicate.test(value)) {
            throw new IllegalArgumentException();
        }
        return sortedMap.put(key, value);
    }

    @Override
    public V remove(Object key) {
        Objects.requireNonNull(key);
        final V value = sortedMap.get(key);
        if (!keyPredicate.test((K) key) || value == null || !valuePredicate.test(value)) {
            return null;
        }
        return sortedMap.remove(key);
    }

    @Override
    public void clear() {
        final Iterator<Entry<K, V>> iterator = entrySet().iterator();
        while (iterator.hasNext()) {
            final Entry<K, V> entry = iterator.next();
            if (keyPredicate.test(entry.getKey()) && valuePredicate.test(entry.getValue())) {
                iterator.remove();
            }
        }
    }

    @Override
    public Set<Entry<K, V>> entrySet() {
        if (entrySetView == null) {
            entrySetView = new FilteredSortedSet<>(sortedMap.entrySet(), entry -> keyPredicate.test(entry.getKey()) && valuePredicate.test(entry.getValue()));
        }
        return entrySetView;
    }

    @Override
    public Set<K> keySet() {
        if (keySetView == null) {
            // This is a custom set implementation that is backed by the entry set view.
            keySetView = new AbstractSet<K>() {

                @Override
                public Iterator<K> iterator() {
                    final Iterator<Entry<K, V>> iterator = entrySet().iterator();
                    return new Iterator<K>() {

                        @Override
                        public boolean hasNext() {
                            return iterator.hasNext();
                        }

                        @Override
                        public K next() {
                            return iterator.next().getKey();
                        }

                        @Override
                        public void remove() {
                            iterator.remove();
                        }
                    };
                }

                @Override
                public int size() {
                    return FilteredSortedMap.this.size();
                }

                @Override
                public void clear() {
                    FilteredSortedMap.this.clear();
                }

                @Override
                public boolean contains(Object o) {
                    return FilteredSortedMap.this.containsKey(o);
                }

                @Override
                public boolean remove(Object o) {
                    if (FilteredSortedMap.this.containsKey(o)) {
                        FilteredSortedMap.this.remove(o);
                        return true;
                    }
                    return false;
                }
            };
        }
        return keySetView;
    }

    @Override
    public void forEach(BiConsumer<? super K, ? super V> action) {
        Objects.requireNonNull(action);

        entrySet().forEach(entry -> action.accept(entry.getKey(), entry.getValue()));
    }

    @Override
    public void replaceAll(BiFunction<? super K, ? super V, ? extends V> function) {
        Objects.requireNonNull(function);

        entrySet().forEach(entry -> {
            final V newValue = function.apply(entry.getKey(), entry.getValue());
            if (newValue != null && valuePredicate.test(newValue)) {
                sortedMap.put(entry.getKey(), newValue);
            } else {
                iterator.remove();
            }
        });
    }

    @Override
    public void putAll(Map<? extends K, ? extends V> map) {
        map.entrySet().forEach(entry -> {
            if (keyPredicate.test(entry.getKey()) && valuePredicate.test(entry.getValue())) {
                sortedMap.put(entry.getKey(), entry.getValue());
            }
        });
    }

    @Override
    public Collection<V> values() {
        return new FilteredCollection<>(sortedMap.values(), valuePredicate);
    }

    @Override
    public void removeAll(Collection<?> c) {
        c.forEach(this::remove);
    }

    @Override
    public void retainAll(Collection<?> c) {
        entrySet().removeIf(entry -> !c.contains(entry));
    }
}

private static final class FilteredSortedSet<E> extends AbstractSet<E> implements Serializable {

    private static final long serialVersionUID = 6230157263624069199L;

    private final SortedSet<E> filteredSet;
    private final Predicate<? super E> predicate;

    FilteredSortedSet(SortedSet<E> sortedSet, Predicate<? super E> predicate) {
        this.filteredSet = sortedSet;
        this.predicate = predicate;
    }

    @Override
    public boolean add(E element) {
        if (predicate.test(element)) {
            return filteredSet.add(element);
        }
        return false;
    }

    @Override
    public boolean remove(Object element) {
        if (predicate.test((E) element)) {
            return filteredSet.remove(element);
        }
        return false;
    }

    @Override
    public boolean contains(Object element) {
        return predicate.test((E) element) && filteredSet.contains(element);
    }

    @Override
    public Iterator<E> iterator() {
        final Iterator<E> iterator = filteredSet.iterator();
        return new Iterator<E>() {

            private E current;

            @Override
            public boolean hasNext() {
                while (iterator.hasNext()) {
                    final E next = iterator.next();
                    if (predicate.test(next)) {
                        current = next;
                        return true;
                    }
                }
                return false;
            }

            @Override
            public E next() {
                if (current == null && !hasNext()) {
                    throw new NoSuchElementException();
                }
                final E next = current;
                current = null;
                return next;
            }

            @Override
            public void remove() {
                iterator.remove();
            }
        };
    }

    @Override
    public int size() {
        int count = 0;
        for (E element : filteredSet) {
            if (predicate.test(element)) {
                count++;
            }
        }
        return count;
    }

    @Override
    public void clear() {
        final Iterator<E> iterator = iterator();
        while (iterator.hasNext()) {
            iterator.next();
            iterator.remove();
        }
    }
}

