public void mergeVariants(Variant current, List<Variant> varToAlts) {
    if (current == null || varToAlts == null || varToAlts.isEmpty()) {
        return;
    }
    List<Allele> alleles = new ArrayList<>(current.getAlleles());
    for (Variant var : varToAlts) {
        alleles.addAll(var.getAlleles());
    }
    current.setAlleles(alleles);
}

