private void mergeVariants(Variant current, List<Pair<Variant, List<AlternateCoordinate>>> varToAlts) {
    for (Pair<Variant, List<AlternateCoordinate>> pair : varToAlts) {
        Variant variant = pair.getFirst();
        List<AlternateCoordinate> altCoordinates = pair.getSecond();

        // Merge the variant properties
        current.setPosition(variant.getPosition());
        current.setReference(variant.getReference());
        current.setAlternate(variant.getAlternate());

        // Merge the alternate coordinates
        for (AlternateCoordinate altCoordinate : altCoordinates) {
            current.addAlternateCoordinate(altCoordinate);
        }
    }
}

