public static <T> Map<TypeVariable<?>, Type> adaptType(Type source, Type target, Type[] from, Type[] to) {
    Map<TypeVariable<?>, Type> substitution = new HashMap<>();
    if (source instanceof Class <?> && target instanceof Class <?>) {
        Class<?> sourceClass = (Class<?>) source;
        Class<?> targetClass = (Class<?>) target;
        if (!sourceClass.isAssignableFrom(targetClass)) {
            throw new IllegalArgumentException(target + " is not a subtype of " + source);
        }
        return substitution;
    }
    if (source instanceof TypeVariable<?>) {
        TypeVariable<?> sourceVariable = (TypeVariable<?>) source;
        int index = Arrays.asList(from).indexOf(sourceVariable.getGenericDeclaration());
        if (index != -1) {
            substitution.put(sourceVariable, to[index]);
            return substitution;
        }
    }
    if (source instanceof ParameterizedType && target instanceof ParameterizedType) {
        ParameterizedType sourceType = (ParameterizedType) source;
        ParameterizedType targetType = (ParameterizedType) target;
        if (!sourceType.getRawType().equals(targetType.getRawType())) {
            throw new IllegalArgumentException(target + " does not have the same raw type as " + source);
        }
        Type[] sourceArguments = sourceType.getActualTypeArguments();
        Type[] targetArguments = targetType.getActualTypeArguments();
        for (int i = 0; i < sourceArguments.length; i++) {
            Map<TypeVariable<?>, Type> childSubstitution = adaptType(sourceArguments[i], targetArguments[i], from, to);
            for (Map.Entry<TypeVariable<?>, Type> entry : childSubstitution.entrySet()) {
                TypeVariable<?> variable = entry.getKey();
                Type type = entry.getValue();
                if (!type.equals(sourceArguments[i])) {
                    substitution.put(variable, type);
                }
            }
        }
        return substitution;
    }
    if (source instanceof WildcardType && target instanceof WildcardType) {
        WildcardType sourceWildcard = (WildcardType) source;
        WildcardType targetWildcard = (WildcardType) target;
        Type[] sourceUpperBounds = sourceWildcard.getUpperBounds();
        Type[] sourceLowerBounds = sourceWildcard.getLowerBounds();
        Type[] targetUpperBounds = targetWildcard.getUpperBounds();
        Type[] targetLowerBounds = targetWildcard.getLowerBounds();
        if (sourceUpperBounds.length == 1 && sourceLowerBounds.length == 0) {
            if (targetLowerBounds.length != 0) {
                throw new IllegalArgumentException(target + " has incompatible lower bounds");
            }
            Map<TypeVariable<?>, Type> childSubstitution = adaptType(sourceUpperBounds[0], targetUpperBounds[0], from, to);
            for (Map.Entry<TypeVariable<?>, Type> entry : childSubstitution.entrySet()) {
                TypeVariable<?> variable = entry.getKey();
                Type type = entry.getValue();
                if (!type.equals(sourceUpperBounds[0])) {
                    substitution.put(variable, type);
                }
            }
            return substitution;
        }
        if (sourceUpperBounds.length == 0 && sourceLowerBounds.length == 1) {
            if (targetUpperBounds.length != 0) {
                throw new IllegalArgumentException(target + " has incompatible upper bounds");
            }
            Map<TypeVariable<?>, Type> childSubstitution = adaptType(targetLowerBounds[0], sourceLowerBounds[0], from, to);
            for (Map.Entry<TypeVariable<?>, Type> entry : childSubstitution.entrySet()) {
                TypeVariable<?> variable = entry.getKey();
                Type type = entry.getValue();
                if (!type.equals(targetLowerBounds[0])) {
                    substitution.put(variable, type);
                }
            }
            return substitution;
        }
    }
    throw new IllegalArgumentException("Incompatible types: " + source + " and " + target);
}

