public List<List<Integer>> minimumCycleBasis(Graph graph) {

    // First, find all simple cycles in the graph
    List<List<Integer>> cycles = new ArrayList<>();
    TarjanStronglyConnectedComponent tscc = new TarjanStronglyConnectedComponent();
    int[] visited = new int[graph.getVertexCount()];
    for (int i = 0; i < graph.getVertexCount(); i++) {
        if (visited[i] == 0) {
            tscc.dfs(i, i, cycles, visited, graph.getAdjacencyList());
        }
    }

    // Now, find the minimum cycle basis of the graph
    List<List<Integer>> basis = new ArrayList<>();
    int[] basisVertex = new int[graph.getVertexCount()];
    for (List<Integer> cycle : cycles) {
        int minimum = Integer.MAX_VALUE;
        for (int i = 0; i < cycle.size(); i++) {
            int curr = cycle.get(i);
            int next = cycle.get((i + 1) % cycle.size());
            int weight = graph.getEdgeWeight(curr, next);
            if (weight < minimum) {
                minimum = weight;
            }
        }
        for (int i = 0; i < cycle.size(); i++) {
            int curr = cycle.get(i);
            int next = cycle.get((i + 1) % cycle.size());
            int weight = graph.getEdgeWeight(curr, next);
            if (weight == minimum) {
                basisVertex[curr]++;
                basisVertex[next]++;
                List<Integer> basisCycle = new ArrayList<>();
                int j = i;
                do {
                    basisCycle.add(cycle.get(j));
                    basisVertex[cycle.get(j)]--;
                    j = (j + 1) % cycle.size();
                } while (j != i);
                basis.add(basisCycle);
                break;
            }
        }
    }

    // Finally, return the paths of all cycles in the minimum cycle basis
    List<List<Integer>> result = new ArrayList<>();
    for (List<Integer> cycle : basis) {
        List<Integer> path = new ArrayList<>();
        int start = -1;
        for (int vertex : cycle) {
            if (basisVertex[vertex] == 1) {
                start = vertex;
                path.add(vertex);
                break;
            }
        }
        int curr = start;
        int prev = -1;
        while (true) {
            path.add(curr);
            basisVertex[curr]--;
            List<Integer> neighbors = graph.getNeighbors(curr);
            for (int neighbor : neighbors) {
                if (basisVertex[neighbor] > 0 && neighbor != prev) {
                    prev = curr;
                    curr = neighbor;
                    break;
                }
            }
            if (curr == start) {
                result.add(path);
                break;
            }
        }
    }
    return result;
}

