public class ConvertPackageToHTML {

  public static void convertPackageToHTML(PackageDoc pkg, String outputdir)
      throws Exception {

    if(pkg == null || outputdir == null || outputdir.isEmpty()) {
      throw new IllegalArgumentException("Invalid argument(s) passed to convertPackageToHTML()");
    }

    String[] options = new String[]{"-d", outputdir};

    System.setProperty("jdk.javadoc.doclet", "javadoc.html.doclets.DocToHtml");
    System.setProperty("doc2html.outputDir", outputdir);

    ClassDoc[] classes = pkg.allClasses();

    if(classes.length == 0) {
      System.out.println("No classes to convert in the given package : "+pkg.name());
      return;
    }

    System.out.println("Converting "+classes.length+" classes to HTML...");

    for (ClassDoc cls : classes) {

      System.out.println("      Converting Class : "+cls.name());

      Path path = Paths.get(cls.position().file().toString());

      JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();

      DiagnosticCollector<JavaFileObject> collector = new DiagnosticCollector<>();

      StandardJavaFileManager fileManager = compiler.getStandardFileManager(collector, null, null);

      Iterable<? extends JavaFileObject> compilationUnits1 = fileManager.getJavaFileObjectsFromFiles(
        Files.walk(Paths.get(path.getParent())).filter(Files::isRegularFile)
        .filter((p) -> p.getFileName().toString().contains(cls.name())).map(Path::toFile).toArray(File[]::new));

      JavaCompiler.CompilationTask task = compiler.getTask(null, fileManager, collector, null, null, compilationUnits1);

      boolean result = task.call();

      if(!result) {
        throw new Exception("Unable to compile "+cls.name()+". Please check if the package can be compiled correctly on this environment.");
      }

