class SimpleDocletException extends DocletAbortException {
  private static final long serialVersionUID = -7975205321917351664L;

  SimpleDocletException(String msg) {
      super(msg);
  }
}

class RootDocLoader {

  public static PackageDoc load(String packageName) throws Exception {

    String fileName = packageName.replaceAll("\\.", "/") + "/";
    Path path = Paths.get(fileName);

    if(Files.notExists(path)) {
      throw new SimpleDocletException("Package not found");
    }

    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();

    DiagnosticCollector<JavaFileObject> collector = new DiagnosticCollector<>();

    StandardJavaFileManager fileManager = compiler.getStandardFileManager(collector, null, null);

    Iterable<? extends JavaFileObject> compilationUnit
            = fileManager.getJavaFileObjectsFromFiles(
                    Files.walk(path).filter(f->f.toString().endsWith(".java"))
                    .map(Path::toFile).toArray(File[]::new));

    JavaCompiler.CompilationTask task = compiler.getTask(null, fileManager, collector, null, null, compilationUnit);

    Iterable<? extends JavaFileObject> list = null;

    if(task.call()) {
      list = fileManager.getJavaFileObjectsFromFiles(
            Files.walk(path).filter(f->f.toString().endsWith(".class"))
            .map(Path::toFile).toArray(File[]::new));
    }

    return getPackageDoc(list, packageName);
  }


  public static PackageDoc getPackageDoc(Iterable<? extends JavaFileObject> files, String pkgName) throws Exception {

    JavaFileManager fileManager = new ClassFileManager(JavaCompiler.getSystemJavaCompiler().getStandardFileManager(null, null, null));
    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    DiagnosticCollector<JavaFileObject> collector = new DiagnosticCollector<>();

    JavaCompiler.CompilationTask task = compiler.getTask(null, fileManager, collector, null, null, files);

    task.call();

    for (JavaFileObject file : files) {

      if(file.getKind() != JavaFileObject.Kind.CLASS) {
          continue;
      }

      String className = file.getName().replaceAll("\\\\|/", ".");
      className = className.substring(className.indexOf(pkgName), className.length() - 6); 

      ClassLoader cl = fileManager.getClassLoader(null);
      Class<?> cls = cl.loadClass(className);

      if (cls == null) {
        throw new ClassNotFoundException(className);
      }

      Package pkg = cls.getPackage();
      if(pkg == null) {
        continue;
      } else if(pkg.getName().equalsIgnoreCase(pkgName)) {
      return PackageDocImpl.forPackage(pkgName, cls.getAnnotations(), cls);
      }

    }

    return null;
  }
}

class ClassFileManager extends ForwardingJavaFileManager<JavaFileManager> {
    private ClassLoader classLoader;

    ClassFileManager(JavaFileManager fileManager) {
        super(fileManager);
        this.classLoader = new ByteArrayClassLoader();
    }

    @Override
    public ClassLoader getClassLoader(Location location) {
        return classLoader;
    }

    private static class ByteArrayClassLoader extends ClassLoader {

        @Override
        public Class<?> findClass(String name) throws ClassNotFoundException {
            byte[] bytes = getClassBytes(name);
            return defineClass(name, bytes, 0, bytes.length);
        }

        private byte[] getClassBytes(String name) throws ClassNotFoundException {
            String path = name.replaceAll("\\.", "/") + ".class";
            try {
                byte[] bytes = Files.readAllBytes(Paths.get(path));
                return bytes;
            } catch (IOException ex) {
                throw new ClassNotFoundException(ex.getMessage(), ex);
            }
        }
    }
}

