public MtasTokenCollection createTokenCollection(Reader reader) throws MtasParserException, MtasConfigException {
	// Initialize the token collection
    MtasTokenCollection tokenCollection = new MtasTokenCollection();

    // Create a tokenizer to read from the input reader
    Tokenizer tokenizer = new StandardTokenizer(reader);

    // Set up a char filter to handle special characters
    CharFilter charFilter = new MappingCharFilter(new InputStreamReader(new FileInputStream("special_chars_mapping.txt")), reader);

    // Create a token stream to process the tokens
    TokenStream tokenStream = new StandardFilter(tokenizer);

    // Add a lower case filter to convert all tokens to lower case
    tokenStream = new LowerCaseFilter(tokenStream);

    // Add a stop word filter to remove common stop words
    CharArraySet stopWords = StopAnalyzer.ENGLISH_STOP_WORDS_SET;
    tokenStream = new StopFilter(tokenStream, stopWords);

    // Add a synonym filter to handle synonyms
    SynonymGraphFilter synonymFilter = new SynonymGraphFilter(tokenStream, new SynonymMap.Builder(true).build(), true);
    tokenStream = synonymFilter;

    // Reset the token stream
    tokenStream.reset();

    // Iterate over the tokens in the token stream
    CharTermAttribute charTermAttribute = tokenStream.addAttribute(CharTermAttribute.class);
    while (tokenStream.incrementToken()) {
        // Add each token to the token collection
        tokenCollection.addToken(charTermAttribute.toString());
    }

    // End the token stream
    tokenStream.end();

    // Close the token stream
    tokenStream.close();

    // Return the token collection
    return tokenCollection;
}

