                    boolean match = predicate.test(element);
                    if (match && matchKind != MatchKind.NONE || !match && matchKind == MatchKind.ALL) {
                        Boolean oldValue = map.putIfAbsent(Boolean.TRUE, Boolean.TRUE);
                        if (oldValue != null) {
                            throw new IllegalStateException("Multiple threads found a match: " + oldValue + " & " + Boolean.TRUE);
                        }
                    }
                }
            }, (map1, map2) -> {
                if (map1.containsKey(Boolean.TRUE) || map2.containsKey(Boolean.TRUE)) {
                    // if at least one map contains a true value, other threads should quit immediately
                    Boolean oldValue = map1.putIfAbsent(Boolean.TRUE, Boolean.TRUE);
                    if (oldValue != null) {
                        throw new IllegalStateException("Multiple threads found a match: " + oldValue + " & " + Boolean.TRUE);
                    }
                    return map1;
                } else {
                    // combine both maps
                    map2.forEach((key, value) -> {
                        Boolean oldValue2 = map1.putIfAbsent(key, value);
                        if (oldValue2 != null) {
                            throw new IllegalStateException("Multiple threads found a match: " + oldValue2 + " & " + value);
                        }
                    });
                    return map1;
                }
            }, map -> {
                if (map.getOrDefault(Boolean.TRUE, Boolean.FALSE)) {
                    return Boolean.TRUE; // return true if at least one element matched the predicate
                } else {
                    // determine result according to the kind of match
                    switch (matchKind) {
                        case ALL:
                            return Boolean.TRUE;
                        case ANY:
                        case NONE:
                            return Boolean.FALSE;
                        default:
                            throw new IllegalArgumentException("Match kind not supported: " + matchKind);
                    }
                }
