        private <S> boolean evaluate(PipelineHelper<T> helper, Spliterator<S> spliterator) {
            return collect(helper, spliterator).replace(Boolean.FALSE, Boolean.TRUE) == null;
        }

        @Override
        public Optional<TerminalOp<T, Boolean>> combine(TerminalOp<T, Boolean> op) {
            if (!(op instanceof QuantifiedOp)) {
                return Optional.empty();
            }
            QuantifiedOp<T> otherOp = (QuantifiedOp<T>) op;
            if (otherOp.predicate.equals(predicate) && otherOp.matchKind == matchKind) {
