        }
    }

    static final class TerminalOpImpl<T, R> implements TerminalOp<T, R> {

        private final PipelineOp<T> op;
        private final int opFlags;
        private final Supplier<R> emptyResultSupp;
        private final Function<TerminalOp<T, R>, Optional<TerminalOp<T, R>>> combiner;

        private TerminalOpImpl(PipelineOp<T> op, int opFlags,
                Supplier<R> emptyResultSupp, Function<TerminalOp<T, R>, Optional<TerminalOp<T, R>>> combiner) {
            this.op = op;
            this.opFlags = opFlags;
            this.emptyResultSupp = emptyResultSupp;
            this.combiner = combiner;
        }

        @Override
        public int getOpFlags() {
            return opFlags;
        }

        @Override
        public <S> R evaluateSequential(PipelineHelper<T> helper, Spliterator<S> spliterator) {
            return op.evaluateSequential(helper, spliterator);
        }

        @Override
        public <S> R evaluateParallel(PipelineHelper<T> helper, Spliterator<S> spliterator) {
            return op.evaluateParallel(helper, spliterator);
        }

        @Override
        public Collector<T, ?, R> getOpWithShape(StreamShape inputShape) {
            return op.getOpWithShape(inputShape);
        }

        @Override
        public Optional<TerminalOp<T, R>> combine(TerminalOp<T, R> op) {
            Optional<TerminalOp<T, R>> newOp = combiner.apply(op);
            return newOp.isPresent() ? newOp : op.combine(this);
        }

        @Override
        public <U> TerminalOp<T, U> andThen(Function<R, ? extends U> after) {
            return new TerminalOpImpl<>(op, opFlags, () -> after.apply(emptyResultSupp.get()), combiner);
        }

