protected boolean parseFields(ByteBuffer buffer) {
    // Assuming the headers are in the format "key: value"
    String headers = new String(buffer.array(), StandardCharsets.UTF_8);
    String[] headerArray = headers.split("\n");

    for (String header : headerArray) {
        String[] keyValue = header.split(":");
        if (keyValue.length != 2) {
            continue; // skip invalid headers
        }

        String key = keyValue[0].trim();
        String value = keyValue[1].trim();

        // Check if the handler has signalled for a return
        if (key.equals("Handler") && value.equals("Return")) {
            return true;
        }
    }

    return false;
}

