    // Read the TIFF header
    byte[] tiffHeader = reader.getBytes(0, 8);

    // Check if the header matches the TIFF signature
    if (tiffHeader[0] == 'M' && tiffHeader[1] == 'M' && tiffHeader[2] == 0x00 && tiffHeader[3] == 0x2a) {
        // Get the offset to the first IFD (Image File Directory)
        int ifdOffset = reader.getInt(4);

        // Loop through the IFDs
        while (ifdOffset != 0) {
            // Read the number of directory entries
            int numDirectoryEntries = reader.getShort(ifdOffset);

            // Loop through the directory entries
            for (int i = 0; i < numDirectoryEntries; i++) {
                // Get the tag type
                int tagType = reader.getShort(ifdOffset + 2 + i * 12);

                // Check if the tag is an Exif tag
                if (tagType == 0x8769) {
                    // Get the Exif IFD offset
                    int exifIFDOffset = reader.getInt(ifdOffset + 2 + i * 12 + 8);

                    // Loop through the Exif IFD
                    while (exifIFDOffset != 0) {
                        // Read the number of directory entries
                        int numExifDirectoryEntries = reader.getShort(exifIFDOffset);

                        // Loop through the Exif directory entries
                        for (int j = 0; j < numExifDirectoryEntries; j++) {
                            // Get the Exif tag type
                            int exifTagType = reader.getShort(exifIFDOffset + 2 + j * 12);

