public static boolean isValidFodselsnummer(String fodselsnummer) {
    // Regular expression to validate Fodselsnummer
    String regex = "\\d{6}-\\d{5}";

    // Check if fodselsnummer matches the regular expression
    if (fodselsnummer.matches(regex)) {
        // Extract the day, month, and year from the fodselsnummer
        int day = Integer.parseInt(fodselsnummer.substring(0, 2));
        int month = Integer.parseInt(fodselsnummer.substring(2, 4));
        int year = Integer.parseInt(fodselsnummer.substring(4, 6));

        // Check if the day, month, and year are valid
        return isValidDate(day, month, year);
    }

    return false;
}

// Function to validate the day, month, and year
private static boolean isValidDate(int day, int month, int year) {
    // Check if the year is in the valid range (1900-2099)
    if (year < 0 || year > 99)
        return false;

    // Check if the month is in the valid range (1-12)
    if (month < 1 || month > 12)
        return false;

    // Check if the day is in the valid range for the given month and year
    int maxDay = getMaxDay(month, year);
    if (day < 1 || day > maxDay)
        return false;

    return true;
}

// Function to return the maximum number of days for the given month and year
private static int getMaxDay(int month, int year) {
    int maxDay;
    switch (month) {
        case 2:
            maxDay = isLeapYear(year) ? 29 : 28;
            break;
        case 4:
        case 6:
        case 9:
        case 11:
            maxDay = 30;
            break;
        default:
            maxDay = 31;
            break;
    }
    return maxDay;
}

// Function to check if the given year is a leap year
private static boolean isLeapYear(int year) {
    // A year is a leap year if it is divisible by 4 but not divisible by 100,
    // or if it is divisible by 400.
    if (year % 4 != 0)
        return false;
    else if (year % 100 != 0)
        return true;
    else if (year % 400 != 0)
        return false;
    else
        return true;
}

