        }

        // Commit the transaction
        cnx.commit();
    } catch (Exception e) {
        try {
            // Rollback the transaction on exception
            cnx.rollback();
        } catch (SQLException ex) {
            throw new JqmEngineException("Failed to rollback transaction", ex);
        }
