public static void hessenbergToRealSchur(double[][] matrix) {
    int size = matrix.length;

    for (int j = 0; j < size - 1; j++) {
        for (int i = size - 1; i > j; i--) {
            double[] u = matrix[i];
            double[] v = matrix[i-1];

            // Apply Givens rotation
            double c, s;
            if (u[j] != 0) {
                double r = hypot(u[j], v[j]);
                c = u[j] / r;
                s = -v[j] / r;

                for (int k = j; k < size; k++) {
                    double t = c*u[k] - s*v[k];
                    v[k] = s*u[k] + c*v[k];
                    u[k] = t;
                }
            }
        }
    }
}

