    private MultiplePathBindingsDecorator(
            List<? extends UnaryOperator<Service<HttpRequest, HttpResponse>>> decorators) {
        this.decorators = decorators;
    }

    public static UnaryOperator<ServiceWithPathMappings> usingDecorators(
            List<? extends UnaryOperator<Service<HttpRequest, HttpResponse>>> decorators) {
        if (decorators.isEmpty()) {
            throw new IllegalArgumentException("decorators is empty");
        }

        return new MultiplePathBindingsDecorator(decorators);
