    @Override
    public ServiceWithPathMappings apply(ServiceWithPathMappings serviceWithPathMappings) {
        GlobalEventExecutor eventExecutor = GlobalEventExecutor.INSTANCE;

        Promise<Void> promise = eventExecutor.newPromise();
        PromiseAggregator<Void, Throwable> promiseAggregator = new PromiseAggregator<>(eventExecutor, false,
                decorators.size() + 1, null);
        MultiplePathBindingsDecoratorAsyncHttpService asyncService = new MultiplePathBindingsDecoratorAsyncHttpService(
                serviceWithPathMappings.service(), promiseAggregator, CharsetUtil.UTF_8);

        for (UnaryOperator<Service<HttpRequest, HttpResponse>> decorator : decorators) {
            asyncService = new MultiplePathBindingsDecoratorAsyncHttpService(decorator.apply(asyncService),
                    promiseAggregator, CharsetUtil.UTF_8);
