                PromiseAggregator<Void, Throwable> promiseAggregator,
                Charset defaultCharset) {
            super(delegate, promiseAggregator, defaultCharset);
        }

        @Override
        public HttpResponse serve(ServiceRequestContext ctx, HttpRequest req) throws Exception {
            Map<String, String> pathMapping = PathMappingContextPathMapper.INSTANCE
                    .apply(ctx.mappedPathContext());

            for (Map.Entry<String, String> entry : pathMapping.entrySet()) {
                req.headers().add(HttpHeaderNames.HOST, entry.getValue());
                req.setUri(entry.getKey());

                HttpResponse httpResponse;
                try {
                    httpResponse = delegate().serve(ctx, req);
                } finally {
                    req.headers().remove(HttpHeaderNames.HOST);
                    req.setUri(null);
