        private final int expectedCount;
        private final List<V> responses;
        private final List<T> errors;
        private final Promise<Void> promise;

        private int count;

        PromiseAggregator(EventExecutor executor,
                boolean allMustSucceed,
                int expectedCount,
                Promise<Void> promise) {
            assert expectedCount > 0;
            assert promise == null || expectedCount == 1 : "promise is allowed only when expectedCount is 1.";

            this.executor = executor;
            this.allMustSucceed = allMustSucceed;
            this.expectedCount = expectedCount;
            this.responses = new ArrayList<>(expectedCount);
            this.errors = new ArrayList<>(expectedCount);
            this.promise = promise;
