                    final RuntimeException aggregatedException;
                    if (errors.size() == 1) {
                        aggregatedException = new RuntimeException("Failed an operation", errors.get(0));
                    } else {
                        aggregatedException = new RuntimeException(errors.size() + " failed operations",
                                                                     new CompositeException(errors));
                    }
                    throw new CompletionException(aggregatedException);
                } else {
