        private static HttpData bodyString(HttpRequest request) {
            if (request == null) {
                return HttpData.empty();
            }
            final String s = request.headers().get(HttpHeaderNames.CONTENT_TYPE);
            final Charset charset =
                    s != null ? HttpUtil.getCharsetWithoutDefault(s) : StandardCharsets.UTF_8;;

            return HttpData.ofUtf8(request.content().toString(charset));
