            final FullHttpRequest fullRequest =
                    new DefaultFullHttpRequest(request.protocolVersion(), request.method(), request.uri(),
                            content,
                            request.headers(),
                            EmptyHttpHeaders.INSTANCE);

            ctx.write(fullRequest, ctx.voidPromise());
            ctx.flush();
