        CompletableFuture<HttpResponse> execute(Request req, boolean useProxy) {
            final EventLoopGroup eventLoopGroup = ClientFactory.eventLoopGroup();
            final InetSocketAddress address = InetSocketAddressResolver.groupOrSolo(eventLoopGroup).resolve(req.destination().host())
                    .filter(sa -> sa.getAddress().getClass() == Inet4Address.class)
                    .orElseThrow(() -> new IllegalArgumentException("cannot find an IPv4 address: " + req.destination().host()));
            final URI uri = URI.create(req.path());

            final RequestHeadersBuilder headersBuilder = req.headers().toBuilder();
            headersBuilder.set(HttpHeaderNames.CONNECTION, HttpHeaderValues.CLOSE);

            final HttpRequest request =
                    new DefaultHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.GET, uri.getRawPath());

            bodyString(req).content().ifPresent(request::setContent);

            request.headers().set(headersBuilder.build());
            final ClientBootstrap cb = getClient(eventLoopGroup, address, useProxy);

            final CompletableFuture<HttpResponse> responseFuture = new CompletableFuture<>();
            final MultiplePathBindingsDecoratorHttpClient handler =
                    new MultiplePathBindingsDecoratorHttpClient(request, MAX_RESPONSE_LENGTH, MAX_NUM_REDIRECTS);
            final ChannelFuture connectFuture = cb.connect(address.getAddress(), req.destination().port());

            connectFuture.addListener((ChannelFutureListener) future -> {
                if (future.isSuccess()) {
