public void bindService(ServiceWithPathMappings<HttpRequest, HttpResponse> serviceWithPathMappings, Iterable<Function<? super Service<HttpRequest, HttpResponse>, ? extends Service<HttpRequest, HttpResponse>>> decorators) {
    // Get the default VirtualHost
    VirtualHost defaultHost = getDefaultVirtualHost();

    // Iterate over the path mappings
    for (PathMapping pathMapping : defaultHost.getPathMappings()) {
        // Apply the decorators to the service
        Service<HttpRequest, HttpResponse> decoratedService = serviceWithPathMappings.getService();
        for (Function<? super Service<HttpRequest, HttpResponse>, ? extends Service<HttpRequest, HttpResponse>> decorator : decorators) {
            decoratedService = decorator.apply(decoratedService);
        }

        // Bind the decorated service to the path mapping
        pathMapping.bind(decoratedService);
    }
}

