import java.io.IOException;
import java.io.InputStream;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.util.Objects;
import opennlp.tools.util.TrainingParameters;

public static String generateFeatureDescriptorFromPropFile(TrainingParameters params) throws IOException {
    Objects.requireNonNull(params, "Training parameters must not be null");

    try (InputStream inputStream = params.getInputStream()) {
        int bufferSize = 1024;
        char[] buffer = new char[bufferSize];
        StringBuilder out = new StringBuilder();
        StringWriter stringWriter = new StringWriter();
        while (true) {
            int rsz = inputStream.read(buffer, 0, buffer.length);
            if (rsz < 0) {
                break;
            }
            stringWriter.write(buffer, 0, rsz);
        }
        out.append(stringWriter.toString());

        return out.toString();
    }
}

