public static String createXMLFeatureDescriptor( final TrainingParameters params) throws IOException {
	// Initialize a StringBuilder to build the XML content
    StringBuilder xmlContent = new StringBuilder();

    // Start the XML document
    xmlContent.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    xmlContent.append("<featureDescriptor>\n");

    // Append the feature name
    xmlContent.append("    <featureName>").append(params.getFeatureName()).append("</featureName>\n");

    // Append the feature type
    xmlContent.append("    <featureType>").append(params.getFeatureType()).append("</featureType>\n");

    // Append the feature description
    xmlContent.append("    <featureDescription>").append(params.getFeatureDescription()).append("</featureDescription>\n");

    // Append the feature parameters
    xmlContent.append("    <featureParameters>\n");
    for (String key : params.getParameterKeys()) {
        xmlContent.append("        <parameter key=\"").append(key).append("\" value=\"").append(params.getParameterValue(key)).append("\"/>\n");
    }
    xmlContent.append("    </featureParameters>\n");

    // Close the XML document
    xmlContent.append("</featureDescriptor>\n");

    // Return the XML content as a string
    return xmlContent.toString();
}

