public int scanForToken(StringBuilder aOut, String sIn, int nStart, char eToken) {
    if (eToken == 'NONE') {
        return -1;
    }
    char nextChar = sIn.charAt(nStart);
    if (nextChar == eToken) {
        return nStart;
    }
    if (nextChar == '\\') {
        aOut.append(sIn.charAt(nStart + 1));
        return scanForToken(aOut, sIn, nStart + 2, eToken);
    }
    aOut.append(nextChar);
    return scanForToken(aOut, sIn, nStart + 1, eToken);
}

