    //Create MultipartEntityBuilder object and add file parameter
    MultipartEntityBuilder builder = MultipartEntityBuilder.create();
    builder.addBinaryBody("file", file, ContentType.APPLICATION_OCTET_STREAM, file.getName());

    //Add all other parameters to MultipartEntityBuilder
    for (Map.Entry<String, String> entry : params.entrySet()) {
        builder.addTextBody(entry.getKey(), entry.getValue());
    }

    //Set entity to HttpPut object
    HttpEntity multipart = builder.build();
    httpPut.setEntity(multipart);

    //Create HttpClient object and execute request
    CloseableHttpClient httpClient = HttpClients.createDefault();
    CloseableHttpResponse httpResponse = null;
    Response response = null;
    try {
        httpResponse = httpClient.execute(httpPut);
        //Read response and create Response object
        HttpEntity responseEntity = httpResponse.getEntity();
        String responseBody = EntityUtils.toString(responseEntity);
        response = new Response(httpResponse.getStatusLine().getStatusCode(), responseBody);
    } catch (IOException e) {
        e.printStackTrace();
    } finally {
        try {
            httpClient.close();
            if(httpResponse != null) {
                httpResponse.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    //Write request and response info to output file
    try(FileWriter writer = new FileWriter("output.txt", true)) {
        writer.write("Request Info:\n");
        writer.write("Endpoint: " + endpoint + "\n");
        writer.write("Params: " + params.toString() + "\n");
        writer.write("File: " + file.getName() + "\n");
        writer.write("\nResponse Info:\n");
        writer.write("Status Code: " + response.getStatusCode() + "\n");
        writer.write("Response Body: " + response.getResponseBody() + "\n");
        writer.write("\n\n");
    } catch (IOException e) {
        e.printStackTrace();
    }

    //Return response object
    return response;
}

