public String convertToSemTiKamolsTag(Map<String, String> attributes, Map<String, String> defaultTags) {
    StringBuilder sb = new StringBuilder();
    sb.append("<SemTi-Kamols ");

    // Add attributes to the xml tag
    for(Map.Entry<String, String> entry : attributes.entrySet()) {
        sb.append(entry.getKey());
        sb.append("=\"");
        sb.append(entry.getValue());
        sb.append("\" ");
    }

    // Add default tags to the xml tag
    for(Map.Entry<String, String> entry : defaultTags.entrySet()) {
        if(attributes.containsKey(entry.getKey())) {
            continue; // Do not add if attribute is already added
        }

        sb.append(entry.getKey());
        sb.append("=\"");
        sb.append(entry.getValue());
        sb.append("\" ");
    }

    sb.append("/>"); // Close the xml tag
    return sb.toString();
}

