private static StringBuilder toKamolsMarkup( AttributeValues avs, boolean defaults) {
	StringBuilder sb = new StringBuilder();
    if (defaults) {
        sb.append("<SemTi-Kamols>");
    }
    for (AttributeValues.AttributeValue av : avs.getAttributeValues()) {
        sb.append("<").append(av.getAttribute()).append(">");
        sb.append(av.getValue());
        sb.append("</").append(av.getAttribute()).append(">");
    }
    if (defaults) {
        sb.append("</SemTi-Kamols>");
    }
    return sb;
}

