    private void startAsyncTestMode(Properties overrides) {
        class TestModeVerticle extends AbstractVerticle {
            private static final String OPEN_HEADERS_SLOT = "openHeaders";
            private static final String OPEN_HTTP1_SLOT = "openHttp1";
            private static final String HTTP2_SLOT = "http2";

            private final AtomicBoolean active = new AtomicBoolean(false);
            private final Set<String> activeEndpoints = Collections.synchronizedSet(new TreeSet<>());
            private final Queue<Runnable> queues[] = (Queue<Runnable>[]) new Queue[2];

            private Properties properties;
            private String server;
            private int port;

            private TestingProxy testingProxy;

            @Override
            public void start(Future<Void> startFuture) throws Exception {
                queues[0] = new LinkedList<>();
                queues[1] = new LinkedList<>();
                try {
                    JsonArray endpointsArray = getConfiguredTestModeEndpoints();
                    for (int i = 0; i < endpointsArray.size(); i++) {
                        String endpointName = endpointsArray.getString(i);
                        testEndpoint(new URI(endpointName));
                    }
                    active.set(true);
                    startFuture.complete();
                } catch (Throwable e) {
                    startFuture.fail(e);
                }
                messageLoop();
            }

            private void messageLoop() {
                //noinspection InfiniteLoopStatement
                while (true) {
                    try {
                        executeFromQueue(OPEN_HEADERS_SLOT);
                        executeFromQueue(OPEN_HTTP1_SLOT);
                        executeFromQueue(HTTP2_SLOT);
                        Thread.sleep(50);
                    } catch (InterruptedException e) {
                        logger.info("Shutting down client connection test mode message loop.");
                        break;
                    }
                }
            }

            private void executeFromQueue(String slot) {
                Runnable workItem = queues[getSlotId(slot)].poll();
                while (workItem != null) {
                    try {
                        workItem.run();
                    } catch (Throwable e) {
                        logger.error("Error running test mode task.", e);
                    } finally {
                        workItem = queues[getSlotId(slot)].poll();
                    }
                }
            }

            private int getSlotId(String slot) {
                switch (slot.toLowerCase()) {
                    case OPEN_HEADERS_SLOT:
                        return 0;
                    case OPEN_HTTP1_SLOT:
                        return 1;
                    case HTTP2_SLOT:
                        return 1;
                    default:
                        throw new NotImplementedException("Unknown slot [" + slot + "]");
                }
            }

            private void testEndpoint(URI endpoint) {
                switch (endpoint.getScheme()) {
                    case "http":
                        activeEndpoints.add(endpoint.toString());
                        break;
                    case "https":
                        throw new NotImplementedException("TLS test mode endpoint not yet implemented.");
                    default:
                        throw new NotImplementedException("Unsupported test mode endpoint scheme " + endpoint.getScheme());
                }
            }

