  float cosAngle = (float)Math.cos(-angle);
  float oneMinusCos = 1.0f - cosAngle;

  float xTimesOneMinusCos = x * oneMinusCos;
  float yTimesOneMinusCos = y * oneMinusCos;
  float zTimesOneMinusCos = z * oneMinusCos;

  float xyOneMinusCos = x * yTimesOneMinusCos;
  float xzOneMinusCos = x * zTimesOneMinusCos;
  float yzOneMinusCos = y * zTimesOneMinusCos;

