import java.io.*;
import java.util.*;

public class FileSorter {
   public static void sortFile(File inputFile, File outputFile, Comparator<String> comparator) throws IOException {

       // Default max bytes size and merge factor
       long maxFileSize = 1000000; // 1MB
       int mergeFactor = 10;

       // Create temporary directory for split files
       File tempDir = new File("temp");
       tempDir.mkdir();

       // Split big file into smaller sorted files
       List<File> splitFiles = splitFile(inputFile, tempDir, maxFileSize, comparator);

       // Merge sorted files into output file
       mergeFiles(splitFiles, outputFile, mergeFactor, comparator);

       // Delete temporary files
       deleteTemporaryFiles(tempDir);
   }

   private static List<File> splitFile(File inputFile, File tempDir, long maxFileSize, Comparator<String> comparator) throws IOException {
       List<File> splitFiles = new ArrayList<>();
       BufferedReader reader = new BufferedReader(new FileReader(inputFile));
       List<String> rows = new ArrayList<>();
       String line = reader.readLine();
       long fileSize = 0;
       while (line != null) {
           rows.add(line);
           fileSize += line.length();
           if (fileSize > maxFileSize) {
               Collections.sort(rows, comparator);
               splitFiles.add(writeSplitFile(tempDir, rows));
               rows.clear();
               fileSize = 0;
           }
           line = reader.readLine();
       }
       Collections.sort(rows, comparator);
       splitFiles.add(writeSplitFile(tempDir, rows));
       reader.close();
       return splitFiles;
   }

   private static File writeSplitFile(File tempDir, List<String> rows) throws IOException {
       File tempFile = File.createTempFile("split_", ".txt", tempDir);
       BufferedWriter writer = new BufferedWriter(new FileWriter(tempFile));
       for (String row : rows) {
           writer.write(row);
           writer.newLine();
       }
       writer.close();
       return tempFile;
   }

   private static void mergeFiles(List<File> files, File outputFile, int mergeFactor, Comparator<String> comparator) throws IOException {
       PriorityQueue<BufferedReader> queue = new PriorityQueue<>(mergeFactor, new Comparator<BufferedReader>() {
           @Override
           public int compare(BufferedReader br1, BufferedReader br2) {
               try {
                   String line1 = br1.readLine();
                   String line2 = br2.readLine();
                   if (line1 == null || line2 == null) {
                       throw new IllegalArgumentException("Input files are empty");
                   }
                   return comparator.compare(line1, line2);
               } catch (IOException e) {
                   throw new UncheckedIOException(e);
               }
           }
       });

       // Populate queue with top line of each file
       for (File file : files) {
           BufferedReader reader = new BufferedReader(new FileReader(file));
           queue.offer(reader);
       }

       // Merge files
       BufferedWriter writer = new BufferedWriter(new FileWriter(outputFile));
       try {
           while (!queue.isEmpty()) {
               BufferedReader reader = queue.poll();
               String line = reader.readLine();
               if (line != null) {
                   writer.write(line);
                   writer.newLine();
                   queue.offer(reader); // Replace used BufferedReader with new one
               }
           }
       } finally {
           for (BufferedReader reader : queue) {
               reader.close();
           }
           writer.close();
       }
   }

   private static void deleteTemporaryFiles(File directory) {
       for (File file : directory.listFiles()) {
           if (file.isDirectory()) {
               deleteTemporaryFiles(file);
           } else {
               file.delete();
           }
       }
       directory.delete();
   }
}

