public static double[][] inverseMatrix(double[][] matrix) throws ArithmeticException {
    int n = matrix.length;
    double[][] identity = new double[n][n];
    double[][] augmentedMatrix = new double[n][2*n];

    // Create an identity matrix
    for (int i = 0; i < n; i++) {
        identity[i][i] = 1;
    }

    // Create an augmented matrix
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            augmentedMatrix[i][j] = matrix[i][j];
        }
        for (int j = n; j < 2*n; j++) {
            augmentedMatrix[i][j] = identity[i][j - n];
        }
    }

    // Perform row operations to get the inverse matrix
    for (int i = 0; i < n; i++) {
        if (augmentedMatrix[i][i] == 0) {
            throw new ArithmeticException("Matrix is rank deficient.");
        }
        for (int j = 0; j < n; j++) {
            if (i != j) {
                double ratio = augmentedMatrix[j][i] / augmentedMatrix[i][i];
                for (int k = 0; k < 2*n; k++) {
