            connectionPropertyChanged = false;

            if (wasCleanupReturnTrue) {
                try {
                    currentAutoCommit = sqlConn.getAutoCommit();
                    if (cachedConnection != null) 
                        cachedConnection.setCurrentAutoCommit(currentAutoCommit, key);
                } catch (SQLException sqle) {
