            {
                try {
                    if (TraceComponent.isAnyTracingEnabled() && tc.isDebugEnabled()) {
                        Tr.debug(this, tc, "autoCommit on connection doesn't match the database default, setting it to: ",
                                 defaultAutoCommit); 
