@Override
    public void putAll(Map<? extends K, ? extends V> m) {
	int numKeysToBeAdded = m.size();
	if (numKeysToBeAdded == 0) return;

	if (numKeysToBeAdded > threshold) {
	    int targetCapacity = (int) (numKeysToBeAdded / loadFactor + 1);
	    if (targetCapacity > MAXIMUM_CAPACITY) targetCapacity = MAXIMUM_CAPACITY;
	    int newCapacity = table.length;
	    while (newCapacity < targetCapacity)
		newCapacity <<= 1;
	    if (newCapacity > table.length) resize(newCapacity);
	}
	for (Map.Entry<? extends K, ? extends V> e: m.entrySet())
	    put(e.getKey(), e.getValue());
    }

    @Override
    public V remove(Object key) {
	Object k = maskNull(key);
	int h = hash(k);
	Entry<K, V>[] tab = getTable();
	int i = indexFor(h, tab.length);
	Entry<K, V> prev = tab[i];
	Entry<K, V> e = prev;
	while (e != null) {
	    Entry<K, V> next = e.next;
	    if (h == e.hash && eq(k, e.get())) {
		modCount++;
		size--;
		if (prev == e) tab[i] = next;
		else prev.next = next;
		return e.value;
	    }
	    prev = e;
	    e = next;
	}
	return null;
    }
    @Override
    public V r(K key) throws PageException {
	Object k = maskNull(key);
	int h = hash(k);
	Entry<K, V>[] tab = getTable();
	int i = indexFor(h, tab.length);
	Entry<K, V> prev = tab[i];
	Entry<K, V> e = prev;
	while (e != null) {
	    Entry<K, V> next = e.next;
	    if (h == e.hash && eq(k, e.get())) {
		modCount++;
		size--;
		if (prev == e) tab[i] = next;
		else prev.next = next;
		return e.value;
	    }
	    prev = e;
	    e = next;
	}
	throw invalidKey(this, key, true);
    }
    @Override
    public V r(K key, V defaultValue) {
	Object k = maskNull(key);
	int h = hash(k);
	Entry<K, V>[] tab = getTable();
	int i = indexFor(h, tab.length);
	Entry<K, V> prev = tab[i];
	Entry<K, V> e = prev;
	while (e != null) {
	    Entry<K, V> next = e.next;
	    if (h == e.hash && eq(k, e.get())) {
		modCount++;
		size--;
		if (prev == e) tab[i] = next;
		else prev.next = next;
		return e.value;
	    }
	    prev = e;
	    e = next;
	}
	return defaultValue;
    }

    boolean removeMapping(Object o) {
	if (!(o instanceof Map.Entry)) return false;
	Entry<K, V>[] tab = getTable();
	Map.Entry<?, ?> entry = (Map.Entry<?, ?>) o;
	Object k = maskNull(entry.getKey());
	int h = hash(k);
	int i = indexFor(h, tab.length);
	Entry<K, V> prev = tab[i];
	Entry<K, V> e = prev;
	while (e != null) {
	    Entry<K, V> next = e.next;
	    if (h == e.hash && e.equals(entry)) {
		modCount++;
		size--;
		if (prev == e) tab[i] = next;
		else prev.next = next;
		return true;
	    }
	    prev = e;
	    e = next;
	}
	return false;
    }

    @Override
    public void clear() {


	while (queue.poll() != null)
	    ;
	modCount++;
	Arrays.fill(table, null);
	size = 0;



	while (queue.poll() != null)
	    ;
    }

    @Override
    public boolean containsValue(Object value) {
	if (value == null) return containsNullValue();
	Entry<K, V>[] tab = getTable();
	for (int i = tab.length; i-- > 0;)
	    for (Entry<K, V> e = tab[i]; e != null; e = e.next)
		if (value.equals(e.value)) return true;
	return false;
    }

    private boolean containsNullValue() {
	Entry<K, V>[] tab = getTable();
	for (int i = tab.length; i-- > 0;)
	    for (Entry<K, V> e = tab[i]; e != null; e = e.next)
		if (e.value == null) return true;
	return false;
    }

    private static class Entry<K, V> extends WeakReference<Object> implements Map.Entry<K, V> {
	V value;
	int hash;
	Entry<K, V> next;

	Entry(Object key, V value, ReferenceQueue<Object> queue, int hash, Entry<K, V> next) {
	    super(key, queue);
	    this.value = value;
	    this.hash = hash;
	    this.next = next;
	}
	@Override
	@SuppressWarnings("unchecked")
	public K getKey() {
	    return (K) WeakHashMapPro.unmaskNull(get());
	}
	@Override
	public V getValue() {
	    return value;
	}
