public HttpResponseInterceptor interceptRequest(final HttpContext context) {
    return new HttpResponseInterceptor() {
        @Override
        public void process(HttpResponse response, HttpContext context) {
            // Add Headers
            response.addHeader("Header1", "Value1");
            response.addHeader("Header2", "Value2");

            // Add Cookies
            BasicClientCookie cookie = new BasicClientCookie("Cookie1", "Value1");
            cookie.setDomain("example.com");
            cookie.setPath("/");
            context.getCookieStore().addCookie(cookie);

            // Add Parameters
            List<NameValuePair> params = new ArrayList<>();
            params.add(new BasicNameValuePair("param1", "value1"));
            params.add(new BasicNameValuePair("param2", "value2"));
            String paramString = URLEncodedUtils.format(params, "utf-8");
            HttpUriRequest request = (HttpUriRequest) context.getAttribute(HttpCoreContext.HTTP_REQUEST);
            request.setURI(URI.create(request.getURI().toString() + "?" + paramString));

            // Add Body Arguments
            HttpEntity entity = response.getEntity();
            if (entity != null) {
                try {
                    String body = EntityUtils.toString(entity, "UTF-8");
                    body += "&bodyArg1=value1&bodyArg2=value2";
                    response.setEntity(new StringEntity(body));
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    };
}

