        DMatrixRMaj R = new DMatrixRMaj(3,3);
        for( int i = 0; i < 3; i++ ) {
            for( int j = 0; j < 3; j++ ) {
                R.unsafe_set(i,j,nullspace.solution.data[i*4+j]);
            }
        }
        Vector3D_F64 T = new Vector3D_F64(nullspace.solution.data[3],nullspace.solution.data[7],nullspace.solution.data[11]);

        Se3_F64 ret = new Se3_F64();
        ret.getR().set(R);
        ret.getT().set(T);

        return ret;
