public Bitmap loadOptimizedBitmap(Uri uri, Context context) throws ImageLoadException {
    ContentResolver contentResolver = context.getContentResolver();
    String[] projection = { MediaStore.Images.Media.DATA };
    Cursor cursor = contentResolver.query(uri, projection, null, null, null);
    cursor.moveToFirst();
    String filePath = cursor.getString(cursor.getColumnIndex(projection[0]));
    cursor.close();

    BitmapFactory.Options options = new BitmapFactory.Options();
    options.inJustDecodeBounds = true;
    BitmapFactory.decodeFile(filePath, options);

    int bmpWidth = options.outWidth;
    int bmpHeight = options.outHeight;

    int reqWidth = 0;
    int reqHeight = 0;

    // find max side, 1.4 MPX optimized size
    int maxSide = Math.max(bmpWidth, bmpHeight);
    if (maxSide <= 0) {
        throw new ImageLoadException("Invalid bitmap dimensions (" + bmpWidth + ", " + bmpHeight + ")");
    } else if (maxSide <= 1400) {
        reqWidth = bmpWidth;
        reqHeight = bmpHeight;
    } else {
        double ratio = (double) bmpWidth / (double) bmpHeight;

        if (bmpWidth > bmpHeight) {
            reqWidth = 1400;
            reqHeight = (int) (reqWidth / ratio);
        } else {
            reqHeight = 1400;
            reqWidth = (int) (reqHeight * ratio);
        }
    }

    BitmapFactory.Options bitmapOptions = new BitmapFactory.Options();

    bitmapOptions.inJustDecodeBounds = false;
    bitmapOptions.inSampleSize = calculateInSampleSize(options, reqWidth, reqHeight);

    Bitmap bitmap = BitmapFactory.decodeFile(filePath, bitmapOptions);

    if (bitmap == null) {
        throw new ImageLoadException("Unable to load file: " + filePath);
    }

    return bitmap;
}

public static int calculateInSampleSize(BitmapFactory.Options options, int reqWidth, int reqHeight) {
    final int height = options.outHeight;
    final int width = options.outWidth;
    int inSampleSize = 1;

    if (height > reqHeight || width > reqWidth) {
        final int heightRatio = Math.round((float) height / (float) reqHeight);
        final int widthRatio = Math.round((float) width / (float) reqWidth);

        inSampleSize = heightRatio < widthRatio ? heightRatio : widthRatio;

        final float totalPixels = width * height;

        final float maxTotalPixels = reqWidth * reqHeight * 2;

        while (totalPixels / (inSampleSize * inSampleSize) > maxTotalPixels) {
            inSampleSize++;
        }
    }
    return inSampleSize;
}

class ImageLoadException extends Exception {
    ImageLoadException(String message) {
        super(message);
    }
}

