public void convertToFlatBuffer(String inFile, String outFile) throws IOException, org.nd4j.linalg.exception.ND4JIllegalStateException {
    FileInputStream fis = new FileInputStream(inFile);
    ExtensionRegistry extRegistry = com.google.protobuf.ExtensionRegistry.newInstance();
    Message message = Builder.parseFrom(fis, extRegistry);
    fis.close();

    FlatBufferBuilder fbb = new FlatBufferBuilder();
    fbb.clear();
    int root = packToFlatBuffer(fbb, message);

    File out = new File(outFile);
    FileOutputStream fos = new FileOutputStream(out);    
    fos.write(fbb.sizedByteArray());
    fos.close();
}

public static int packToFlatBuffer(FlatBufferBuilder builder, MessageOrBuilder message) {
