public Map<Node, Double> treeMessagePassing(boolean marginalize) {
    Map<Node, Double> messages = new HashMap<Node, Double>();

    // Pass messages down to the leaves
    for (Node leaf : leaves) {
        messages.put(leaf, marginalize ? marginalize(leaf) : calculateMAP(leaf));
    }

    // Pass messages up to the root
    for (Node node : nodes) {
        if (!node.isLeaf()) {
            double messageUp = 1.0;
            for (Node child : node.getChildren()) {
                double messageDown = messages.get(child);
                messageUp *= messageDown;
            }
            double message = marginalize ? marginalize(node, messageUp) : calculateMAP(node, messageUp);
            messages.put(node, message);
        }
    }

    return messages;
}

