public class MessagePassing {
    private class Node {
        int value;
        List<Node> children = new ArrayList<>();
        Node parent;

        public Node(int value) {
            this.value = value;
        }

        public void addChild(Node child) {
            children.add(child);
            child.parent = this;
        }

        public int passMessage() {
            if (children.isEmpty()) {
                return value;
            } else {
                int sum = value;
                for (Node child : children) {
                    sum += child.passMessage();
                }
                return sum;
            }
        }
    }

    private Node root;

    public MessagePassing(int rootValue) {
        root = new Node(rootValue);
    }

    public void addChild(Node parent, Node child) {
        parent.addChild(child);
    }

    public int passMessage() {
        return root.passMessage();
    }
}

