        if (dictionary.getItems().isEmpty()) {
            errors.add("Base dictionary must have at least one item");
        }
    }
    for (NaaccrDictionaryItem item : dictionary.getItems()) {
        if (item.getId() == null || item.getId().isEmpty()) {
            errors.add("Item ID cannot be null or empty");
        }
        if (item.getLength() <= 0) {
            errors.add("Item length must be greater than zero");
        }
        if (item.getStart() < 0) {
            errors.add("Item start position must be non-negative");
        }
        if (item.getNaaccrVersion().isEmpty()) {
            errors.add("Item NAACCR version cannot be empty");
        }
        if (!item.getNaaccrVersion().equals(naaccrVersion)) {
            errors.add("Item NAACCR version must match the dictionary NAACCR version");
        }
    }
    return errors;
}

