import java.util.*;

public class GraphTraversal {

    private int vertices;
    private List<Integer>[] adjacencyList;

    public GraphTraversal(int vertices) {
        this.vertices = vertices;
        this.adjacencyList = new ArrayList[vertices];
        for (int i = 0; i < vertices; i++) {
            this.adjacencyList[i] = new ArrayList<>();
        }
    }

    public void addEdge(int source, int destination) {
        this.adjacencyList[source].add(destination);
    }

    public void topologicalSort() {
        int[] inDegree = new int[vertices];

        for (int i = 0; i < vertices; i++) {
            List<Integer> neighbours = adjacencyList[i];
            for (int neighbour : neighbours) {
                inDegree[neighbour]++;
            }
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < vertices; i++) {
            if (inDegree[i] == 0) {
                queue.offer(i);
            }
        }

        int visited = 0;
        List<Integer> topologicalOrder = new ArrayList<>();
        while(!queue.isEmpty()) {
            int currentVertex = queue.poll();
            visited++;
            topologicalOrder.add(currentVertex);

            List<Integer> neighbours = adjacencyList[currentVertex];
            for (int neighbour : neighbours) {
                inDegree[neighbour]--;
                if (inDegree[neighbour] == 0) {
                    queue.offer(neighbour);
                }
            }
        }

        if (visited != vertices) {
            throw new RuntimeException("Graph contains a cycle.");
        }

        System.out.println("Topological order:");
        for (int vertex : topologicalOrder) {
            System.out.print(vertex + " ");
        }
    }
}

