@Override
public Iterable<QueryBasedHiveConversionEntity> convertRecord(Schema outputAvroSchema, QueryBasedHiveConversionEntity conversionEntity, WorkUnitState workUnit) throws DataConversionException {
	// Extract the table name from the conversion entity
    String tableName = conversionEntity.getTableName();

    // Generate the Avro schema to ORC conversion query
    String avroToOrcQuery = generateAvroToOrcQuery(tableName, outputAvroSchema);

    // Add the generated query to the conversion entity
    conversionEntity.getQueries().add(avroToOrcQuery);

    // Return the modified conversion entity
    return Collections.singletonList(conversionEntity);
}

private String generateAvroToOrcQuery(String tableName, Schema outputAvroSchema) {
    // Start building the query
    StringBuilder queryBuilder = new StringBuilder();

    // Append the CREATE TABLE statement for ORC
    queryBuilder.append("CREATE TABLE ").append(tableName).append("_orc AS\n");

    // Append the SELECT statement to convert Avro to ORC
    queryBuilder.append("SELECT * FROM ").append(tableName).append(";\n");

    // Return the complete query
    return queryBuilder.toString();
}

