													"pb").item(0);
											Node p  = pb;
											Node pp = pb.getParentNode()
															.getPreviousSibling();
											while (p != null) {
												Node tmp = p.getPreviousSibling();
												p.getParentNode()
													 .removeChild(p);
												p = tmp;
											}  
											while (pp != null) {
												Node tmp = pp.getPreviousSibling();
												if (tmp == null) {
													Node ppz = pp.getParentNode();
													if (ppz.getPreviousSibling() != null) {
														tmp = ppz.getPreviousSibling();
													}  
