														if (prev != null) {
															tmp = prev;
														}  
													}  
												}  
												pp.getParentNode()
													  .removeChild(pp);
												pp = tmp;
											}  
											if (node.getChildNodes()
														.getLength() == 0) {
												node.appendChild(c);
											}  
											else {
												node.insertBefore(c,
													node.getFirstChild());
											}  
										}  
										hasbeendes = true;
										break;
									}  
									Node n = ndoc.adoptNode(Sibling.cloneNode(
												true));
									if (node.getChildNodes().getLength() == 0) {
										node.appendChild(n);
									}  
									else {
										node.insertBefore(n,
											node.getFirstChild());
									}  
									Sibling = Sibling.getPreviousSibling();
								}  
							}  
							previousNode = node;
						}  
						else {
							previousNode = parentPb;
						}  
						ppr = parent;
					}  
					parent = parent.getParentNode();
				}  
				ndoc.appendChild(previousNode);
			}  

			copyHeader(doc, ndoc);
			array[i] = new DocumentAndSize(ndoc,tmpSize);
		}  
		return array;
	}

