    // create an array to hold the cut documents
    Document[] cutDocuments = new Document[2];

    // split the original document into two parts
    String[] parts = doc.getContent().split(" ", 2);

    // create the first cut document
    Document firstDoc = new Document();
    firstDoc.setTitle(doc.getTitle());
    firstDoc.setContent(parts[0]);
    cutDocuments[0] = firstDoc;

    // create the second cut document
    Document secondDoc = new Document();
    secondDoc.setTitle(doc.getTitle() + " - Part 2");
    secondDoc.setContent(parts[1]);
    cutDocuments[1] = secondDoc;

    return cutDocuments;
}

