public Vector rotateVector(double angle, double x, double y, double z, Vector vector) {
    double cosAngle = Math.cos(angle);
    double sinAngle = Math.sin(angle);
    double oneMinusCosAngle = 1 - cosAngle;
    double R[][] = new double[3][3];

    // Calculate rotation matrix
    R[0][0] = cosAngle + x * x * oneMinusCosAngle;
    R[0][1] = x * y * oneMinusCosAngle - z * sinAngle;
    R[0][2] = x * z * oneMinusCosAngle + y * sinAngle;
    R[1][0] = y * x * oneMinusCosAngle + z * sinAngle;
    R[1][1] = cosAngle + y * y * oneMinusCosAngle;
    R[1][2] = y * z * oneMinusCosAngle - x * sinAngle;
    R[2][0] = z * x * oneMinusCosAngle - y * sinAngle;
    R[2][1] = z * y * oneMinusCosAngle + x * sinAngle;
    R[2][2] = cosAngle + z * z * oneMinusCosAngle;

    // Apply rotation matrix to vector
    double v[] = new double[3];
    v[0] = vector.getX() * R[0][0] + vector.getY() * R[0][1] + vector.getZ() * R[0][2];
    v[1] = vector.getX() * R[1][0] + vector.getY() * R[1][1] + vector.getZ() * R[1][2];
    v[2] = vector.getX() * R[2][0] + vector.getY() * R[2][1] + vector.getZ() * R[2][2];

    return new Vector(v[0], v[1], v[2]);
}

