public class TOTPBuilder {
    private static final String HMAC_ALGORITHM = "HmacSHA1";
    private static final int DEFAULT_TIME_STEP_SECONDS = 30;
    private static final int DEFAULT_TOTP_LENGTH = 6;

    private final byte[] secretKey;
    private int timeStepSeconds;
    private int totpLength;

    public TOTPBuilder(byte[] secretKey) {
        this.secretKey = secretKey;
        this.timeStepSeconds = DEFAULT_TIME_STEP_SECONDS;
        this.totpLength = DEFAULT_TOTP_LENGTH;
    }

    public TOTPBuilder setTimeStepSeconds(int timeStepSeconds) {
        this.timeStepSeconds = timeStepSeconds;
        return this;
    }

    public TOTPBuilder setTotpLength(int totpLength) {
        this.totpLength = totpLength;
        return this;
    }

    public TOTP build() throws GeneralSecurityException {
        Instant now = Instant.now();
        return build(now.toEpochMilli());
    }

    public TOTP build(long timeInMillis) throws GeneralSecurityException {
        byte[] data = ByteBuffer.allocate(Long.SIZE / Byte.SIZE)
                .putLong(timeInMillis / (timeStepSeconds * 1000))
                .array();

        SecretKeySpec signingKey = new SecretKeySpec(secretKey, HMAC_ALGORITHM);
        Mac mac = Mac.getInstance(HMAC_ALGORITHM);
        mac.init(signingKey);

        byte[] hash = mac.doFinal(data);

        int offset = hash[hash.length - 1] & 0xf;
        int code = ((hash[offset] & 0x7f) << 24) |
                ((hash[offset + 1] & 0xff) << 16) |
                ((hash[offset + 2] & 0xff) << 8) |
                (hash[offset + 3] & 0xff);

        return new TOTP(String.format("%0" + totpLength + "d", code % (int) Math.pow(10, totpLength)));
    }
}

