public static <T> T refreshFields(Connection connection, T target) throws SQLException {
    String tableName = target.getClass().getSimpleName();
    Map<String, Object> idMap = retrieveIdValues(target);
    String sql = "SELECT * FROM " + tableName + " WHERE " + buildWhereClause(idMap);
    try (PreparedStatement stmt = connection.prepareStatement(sql)) {
        setPreparedStatementParams(stmt, idMap);
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            fillObjectFields(rs, target);
            return target;
        } else {
            return null;
        }
    }
}

private static <T> Map<String, Object> retrieveIdValues(T target) throws SQLException {
    Map<String, Object> idMap = new HashMap<>();
    for (Field field : target.getClass().getDeclaredFields()) {
        if (field.isAnnotationPresent(Id.class)) {
            try {
                field.setAccessible(true);
                idMap.put(field.getName(), field.get(target));
            } catch (IllegalAccessException e) {
                throw new SQLException("Error retrieving Id values from target object", e);
            }
        }
    }
    return idMap;
}

private static String buildWhereClause(Map<String, Object> idMap) {
    StringBuilder sb = new StringBuilder();
    for (String fieldName : idMap.keySet()) {
        sb.append(fieldName).append(" = ? AND ");
    }
    sb.setLength(sb.length() - 5); // remove last 'AND'
    return sb.toString();
}

private static void setPreparedStatementParams(PreparedStatement stmt, Map<String, Object> idMap) throws SQLException {
    int index = 1;
    for (Object value : idMap.values()) {
        stmt.setObject(index++, value);
    }
}

private static <T> void fillObjectFields(ResultSet rs, T target) throws SQLException {
    for (Field field : target.getClass().getDeclaredFields()) {
        try {
            field.setAccessible(true);
            Object value = rs.getObject(field.getName());
            if (value != null) {
                field.set(target, value);
            }
        } catch (IllegalAccessException e) {
            throw new SQLException("Error filling object fields", e);
        }
    }
}

