public void updateDependencyCheckSettings(Properties properties) {
    // Set Dependency Check properties
    Enumeration<?> propertyNames = properties.propertyNames();
    while (propertyNames.hasMoreElements()) {
        String key = (String) propertyNames.nextElement();
        String value = properties.getProperty(key);
        System.setProperty(key, value);
    }

    // Set system properties for proxy URL, port, and connection timeout
    System.setProperty("http.proxyHost", properties.getProperty("http.proxyHost"));
    System.setProperty("http.proxyPort", properties.getProperty("http.proxyPort"));
    System.setProperty("http.connection.timeout", properties.getProperty("http.connection.timeout"));
}

