public void populateObjectFromJsonObject(Object objectInstance, Type objectResolvedType, JsonObject jsonVal, Map<Class<?>, Map<String, Field>> classFieldCache, Map<String, Object> idToObjectInstance, Map<Type, BiConsumer<Object, Object>> collectionElementAdders) {
    Class<?> objectClass = objectInstance.getClass();
    Map<String, Field> fieldCache = classFieldCache.computeIfAbsent(objectClass, this::buildFieldCache);
    for (Map.Entry<String, JsonElement> entry : jsonVal.entrySet()) {
        String memberName = entry.getKey();
        Field targetField = fieldCache.get(memberName);
        if (targetField != null) {
            Object targetFieldValue = fromJsonTree(entry.getValue(), targetField.getGenericType(), classFieldCache, idToObjectInstance, collectionElementAdders);
            boolean isFieldAccessible = targetField.canAccess(objectInstance);
            if (!isFieldAccessible) {
                targetField.trySetAccessible();
            }
            try {
                targetField.set(objectInstance, targetFieldValue);
            } catch (IllegalAccessException e) {
                throw new RuntimeException("Unable to set value to the field " + memberName + " of the class " + objectClass.getSimpleName(), e);
            }
        }
    }
}

