public static Map<String, Object> loadSequenceResources( final TrainingParameters params) throws IOException {
	Map<String, Object> resources = new HashMap<>();
    // Load gazetters
    String gazetterPath = params.getGazetterPath();
    if (gazetterPath != null && !gazetterPath.isEmpty()) {
        List<String> gazetters = Files.readAllLines(Paths.get(gazetterPath));
        resources.put("gazetters", gazetters);
    }
    // Load clustering lexicons
    String lexiconPath = params.getLexiconPath();
    if (lexiconPath != null && !lexiconPath.isEmpty()) {
        List<String> lexicons = Files.readAllLines(Paths.get(lexiconPath));
        resources.put("lexicons", lexicons);
    }
    return resources;
}

