static <T> T cast(Object obj, Class<T> type) {
        if (type == String.class) {
            if (obj == null)
                obj = "";
            obj = obj.toString();
        } else if (type == BigInteger.class) {
            if (obj == null || (""+obj).isEmpty())
                obj = "0";
            obj = new BigInteger("" + obj);
        } else if (type == BigDecimal.class) {
            if (obj == null || (""+obj).isEmpty())
                obj = "0";
            obj = new BigDecimal(("" + obj).replace(",","."));
        } else if (type == Integer.class || type == int.class) {
            if (obj == null || (""+obj).isEmpty())
                obj = "0";
            if(obj instanceof Integer){
            }else
                obj = new BigDecimal(""+obj).intValue();
        } else if (type == Long.class || type==long.class) {
            if (obj == null || (""+obj).isEmpty())
                obj = "0";
            if(obj instanceof Long){
            }else
                obj = new BigDecimal(("" + obj).replace(",",".")).longValue();
        } else if (type == Float.class || type==float.class) {
            if (obj == null || (""+obj).isEmpty())
                obj = "0";
            if(obj instanceof Float){
            }else
                obj = new BigDecimal(("" + obj).replace(",",".")).floatValue();
        } else if (type == Double.class || type==double.class) {
            if (obj == null || (""+obj).isEmpty())
                obj = "0";
            if(obj instanceof Double){
            }else
                obj = new BigDecimal(("" + obj).replace(",",".")).doubleValue();
        } else if (type == Boolean.class || type==boolean.class) {
            if (obj == null || (""+obj).isEmpty())
                obj = "false";
            if(obj instanceof Number){
                obj = ((Number) obj).intValue()!=0;
            }else
                obj = Boolean.parseBoolean("" + obj);
        } else if (type == Date.class) {
            if((""+obj).isEmpty())
                obj = null;
            if (obj != null) {
                if (obj instanceof String) {
                    Date dt = null;
                    SimpleDateFormat[] sdf = new SimpleDateFormat[]{
                            new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS"),
                            new SimpleDateFormat("yyyy-MM-dd HH:mm:ss"),
                            new SimpleDateFormat("yyyy-MM-dd HH:mm"),
                            new SimpleDateFormat("yyyy-MM-dd")
                    };
                    for(SimpleDateFormat s:sdf){
                        try {
                            dt = s.parse("" + obj);
                            break;
                        }catch (Throwable e){}
                    }
                    if(dt==null)
                        dt = new Date(Long.parseLong("" + obj));
                    obj = dt;
                } else if (obj instanceof Long) {
                    obj = new Date((Long) obj);
                }
            }
        } else if(type.isEnum()){
            if(obj != null && obj instanceof String){
                obj = Enum.valueOf((Class<? extends Enum>)type,((String) obj).toUpperCase());
            }
        }
        return (T) obj;
    }

