import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.concurrent.Callable;

public class ConcurrentFileSearch implements Callable<Long> {
    private final File file;
    private final byte[] searchBytes;
    private final long startOffset;
    private final long endOffset;
    private final ProgressCallback progressCallback;

    public ConcurrentFileSearch(File file, byte[] searchBytes, long startOffset, long endOffset, ProgressCallback progressCallback) {
        this.file = file;
        this.searchBytes = searchBytes;
        this.startOffset = startOffset;
        this.endOffset = endOffset;
        this.progressCallback = progressCallback;
    }

    @Override
    public Long call() throws IOException {
        long count = 0;
        FileInputStream fis = new FileInputStream(file);
        fis.skip(startOffset);
        byte[] buffer = new byte[searchBytes.length];
        int readBytes;
        while ((readBytes = fis.read(buffer)) != -1 && fis.getChannel().position() <= endOffset) {
            for (int i = 0; i < readBytes - searchBytes.length + 1; i++) {
                boolean match = true;
                for (int j = 0; j < searchBytes.length; j++) {
                    if (buffer[i + j] != searchBytes[j]) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    count++;
                }
            }
            progressCallback.reportProgress(fis.getChannel().position());
        }
        fis.close();
        return count;
    }

    interface ProgressCallback {
        void reportProgress(long bytesRead);
    }
}

