public static void sort(int[] arr, int start, int end) {
    int size = end - start;
    if (size < 7) {
        insertionSort(arr, start, end);
        return;
    }
    if (size <= 1) {
        return;
    }
    if (size <= 30) {
        int pivot = medianOfThree(arr, start, start + size/2, end);
        int index = partition(arr, start, end, pivot);
        sort(arr, start, index - 1);
        sort(arr, index, end);
    } else {
        int pivot = medianOfThree(arr, start, start + size/4, start + size/2, end - size/4, end);
        int index = partition(arr, start, end, pivot);
        sort(arr, start, index - 1);
        sort(arr, index, end);
    }
}

private static void insertionSort(int[] arr, int start, int end) {
    for (int i = start + 1; i <= end; i++) {
        int value = arr[i];
        int hole = i;
        while (hole > start && arr[hole-1] > value) {
            arr[hole] = arr[hole-1];
            hole--;
        }
        arr[hole] = value;
    }
}

private static int medianOfThree(int[] arr, int a, int b, int c) {
    return (arr[a] < arr[b] ? (arr[b] < arr[c] ? b : arr[a] < arr[c] ? c : a )
            : (arr[b] > arr[c] ? b : arr[a] > arr[c] ? c : a ));
