public void setActiveDocumentHelpers(JTextComponent textComponent, Validator validator, Transformer transformer) {
    if (textComponent == null) {
        throw new IllegalArgumentException("Text component cannot be null.");
    }
    Document doc = textComponent.getDocument();
    if (doc instanceof AbstractDocument) {
        AbstractDocument abstractDoc = (AbstractDocument) doc;
        if (validator != null) {
            abstractDoc.setDocumentFilter(new DocumentValidatorFilter(validator));
        }
        if (transformer != null) {
            abstractDoc.setDocumentListener(new DocumentTransformerListener(transformer));
        }
    }
}

private static class DocumentValidatorFilter extends DocumentFilter {

    private final Validator validator;

    public DocumentValidatorFilter(Validator validator) {
        this.validator = validator;
    }

    @Override
    public void insertString(FilterBypass fb, int offset, String string, AttributeSet attr) throws BadLocationException {
        String newText = fb.getDocument().getText(0, fb.getDocument().getLength()) + string;
        if (validator.validate(newText)) {
            super.insertString(fb, offset, string, attr);
        }
    }

    @Override
    public void remove(FilterBypass fb, int offset, int length) throws BadLocationException {
        String newText = fb.getDocument().getText(0, fb.getDocument().getLength());
        newText = newText.substring(0, offset) + newText.substring(offset + length);
        if (validator.validate(newText)) {
            super.remove(fb, offset, length);
        }
    }

    @Override
    public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attrs) throws BadLocationException {
        String newText = fb.getDocument().getText(0, fb.getDocument().getLength());
        newText = newText.substring(0, offset) + text + newText.substring(offset + length);
        if (validator.validate(newText)) {
            super.replace(fb, offset, length, text, attrs);
        }
    }
}

private static class DocumentTransformerListener implements DocumentListener {

    private final Transformer transformer;

    public DocumentTransformerListener(Transformer transformer) {
        this.transformer = transformer;
    }

    @Override
    public void insertUpdate(DocumentEvent e) {
        transform(e, transformer);
    }

    @Override
    public void removeUpdate(DocumentEvent e) {
        transform(e, transformer);
    }

    @Override
    public void changedUpdate(DocumentEvent e) {
        transform(e, transformer);
    }

    private void transform(DocumentEvent e, Transformer transformer) {
        Document doc = e.getDocument();
        try {
            String originalText = doc.getText(0, doc.getLength());
            String transformedText = transformer.transform(originalText);
            if (!transformedText.equals(originalText)) {
                doc.removeDocumentListener(this);
                doc.remove(0, doc.getLength());
                doc.insertString(0, transformedText, null);
                doc.addDocumentListener(this);
            }
        } catch (BadLocationException ex) {
            // ignore silently
        }
    }
}

public interface Validator {
    boolean validate(String text);
}

public interface Transformer {
    String transform(String text);
}

