    public static void verifyHtmlAccessibity(HtmlPage htmlPage, AccessibilityRule... testableRules) throws Exception {
        String html = htmlPage.asXml();
        Document document = Jsoup.parse(html);
        Iterator<AccessibilityRule> iterator;

        if (testableRules.length != 0) {
            iterator = Arrays.asList(testableRules).iterator();
