import org.apache.flink.api.common.typeinfo.*;
import org.apache.flink.table.types.logical.*;
import org.apache.parquet.hadoop.metadata.*;
import org.apache.parquet.schema.*;

public static MessageType toParquetSchema(TypeInformation<?> typeInformation, boolean legacyMode) {
    LogicalTypeRoot typeRoot = fromTypeInfo(typeInformation);
    switch (typeRoot) {
        case INTEGER:
            return new MessageType("parquet.schema",
                    Types.buildMessage()
                            .required(INT32).named("int_field")
                            .named("parquet.schema"));
        case LONG:
            return new MessageType("parquet.schema",
                    Types.buildMessage()
                            .required(INT64).named("long_field")
                            .named("parquet.schema"));
        case FLOAT:
            return new MessageType("parquet.schema",
                    Types.buildMessage()
                            .required(FLOAT).named("float_field")
                            .named("parquet.schema"));
        case DOUBLE:
            return new MessageType("parquet.schema",
                    Types.buildMessage()
                            .required(DOUBLE).named("double_field")
                            .named("parquet.schema"));
        case BOOLEAN:
            return new MessageType("parquet.schema",
                    Types.buildMessage()
                            .required(BOOLEAN).named("boolean_field")
                            .named("parquet.schema"));
        case CHAR:
        case VARCHAR:
            return new MessageType("parquet.schema",
                    Types.buildMessage()
                            .required(BINARY).as(UTF8).named("string_field")
                            .named("parquet.schema"));
        case ARRAY:
            LogicalType elementLogicalType = ((ArrayType) typeInformation.getLogicalType()).getElementType();
            GroupType arrayType = Types.buildGroup(REPEATED)
                    .add(toParquetType(elementLogicalType, new StringBuilder("element"), legacyMode))
                    .named("array_field");
            return new MessageType("parquet.schema", Types.buildMessage().addFields(arrayType).named("parquet.schema"));
        case MAP:
            MapType mapType = (MapType) typeInformation.getLogicalType();
            GroupType mapGroupType = Types.buildGroup(REPEATED)
                    .add(toParquetType(mapType.getKeyType(), new StringBuilder("key"), legacyMode))
                    .add(toParquetType(mapType.getValueType(), new StringBuilder("value"), legacyMode))
                    .named("map_field");
            if (legacyMode) { // standard LIST and MAP schema
                GroupType result = Types.buildGroup(REPEATED)
                        .add(Types.required(BINARY).as(UTF8).named("key"))
                        .add(Types.optional(mapGroupType).named("value"))
                        .named("map_field");
                return new MessageType("parquet.schema",
                        Types.buildMessage()
                                .addFields(result)
                                .named("parquet.schema"));
            } else { // back-compatible schema
                GroupType result = Types.buildGroup(REPEATED)
                        .add(Types.optional(mapGroupType).named("map"))
                        .named("map_field");
                return new MessageType("parquet.schema",
                        Types.buildMessage()
                                .addFields(result)
                                .named("parquet.schema"));
            }
        case ROW:
            RowType rowType = (RowType) typeInformation.getLogicalType();
            Types.MessageBuilder<GroupType> messageBuilder = Types.buildMessage().setId("parquet.schema");
            Type[] fieldTypes = rowType.getFields().stream()
                    .map(RowType.RowField::getType)
                    .map(t -> toParquetType(t, new StringBuilder(), legacyMode))
                    .toArray(Type[]::new);
            String[] fieldNames = rowType.getFieldNames().toArray(new String[0]);
            if (legacyMode) { // standard LIST and MAP schema
                for (int i = 0; i < rowType.getFieldCount(); i++) {
                    if (fieldTypes[i] instanceof GroupType) {
                        messageBuilder.addGroup(REPEATED).addField(Types.required(fieldTypes[i]).named(fieldNames[i])).named(fieldNames[i] + "_field");
                    } else {
                        messageBuilder.addPrimitive(REPEATED, ((PrimitiveType) fieldTypes[i]).getPrimitiveTypeName()).as(((PrimitiveType) fieldTypes[i]).getOriginalType()).named(fieldNames[i] + "_field");
                    }
                }
            } else { // back-compatible schema
                messageBuilder.addFields(Types.buildGroup(REPEATED).addFields(fieldTypes).named("row")).named("row_field");
            }
            return new MessageType("parquet.schema", messageBuilder.named("parquet.schema"));
        default:
            throw new UnsupportedOperationException("Unsupported type: " + typeRoot.toString());
    }
}

private static LogicalTypeRoot fromTypeInfo(TypeInformation<?> typeInformation) {
    if (typeInformation instanceof BasicTypeInfo) {
        if (typeInformation.equals(BasicTypeInfo.INT_TYPE_INFO)) {
            return LogicalTypeRoot.INTEGER;
        }
        if (typeInformation.equals(BasicTypeInfo.LONG_TYPE_INFO)) {
            return LogicalTypeRoot.BIGINT;
        }
        if (typeInformation.equals(BasicTypeInfo.FLOAT_TYPE_INFO)) {
            return LogicalTypeRoot.FLOAT;
        }
        if (typeInformation.equals(BasicTypeInfo.DOUBLE_TYPE_INFO)) {
            return LogicalTypeRoot.DOUBLE;
        }
        if (typeInformation.equals(BasicTypeInfo.BOOLEAN_TYPE_INFO)) {
            return LogicalTypeRoot.BOOLEAN;
        }
        if (typeInformation.equals(BasicTypeInfo.STRING_TYPE_INFO)) {
            return LogicalTypeRoot.VARCHAR;
        }
    }
    if (typeInformation instanceof DecimalTypeInfo) {
        return LogicalTypeRoot.DECIMAL;
    }
    if (typeInformation instanceof ArrayTypeInfo) {
        return LogicalTypeRoot.ARRAY;
    }
    if (typeInformation instanceof MapTypeInfo) {
        return LogicalTypeRoot.MAP;
    }
    if (typeInformation instanceof RowTypeInfo) {
        return LogicalTypeRoot.ROW;
    }
    throw new IllegalArgumentException("Unsupported type: " + typeInformation.getClass().getCanonicalName());
}

private static Type toParquetType(LogicalType logicalType, StringBuilder nameBuilder, boolean legacyMode) {
    LogicalTypeRoot typeRoot = logicalType.getTypeRoot();
    switch (typeRoot) {
        case INTEGER:
            return Types.required(INT32).named(nameBuilder.append("int").toString());
        case BIGINT:
            return Types.required(INT64).named(nameBuilder.append("long").toString());
        case FLOAT:
            return Types.required(FLOAT).named(nameBuilder.append("float").toString());
        case DOUBLE:
            return Types.required(DOUBLE).named(nameBuilder.append("double").toString());
        case BOOLEAN:
            return Types.required(BOOLEAN).named(nameBuilder.append("boolean").toString());
        case VARCHAR:
            return Types.required(BINARY).as(UTF8).named(nameBuilder.append("string").toString());
        case DECIMAL:
            DecimalType decimalType = (DecimalType) logicalType;
            return Types.required(primitiveTypeNameForDecimal(decimalType).primitiveType).as(DECIMAL).precision(decimalType.getPrecision()).scale(decimalType.getScale()).named(nameBuilder.append("decimal").toString());
        case ARRAY:
            ArrayType arrayType = (ArrayType) logicalType;
            nameBuilder.append("array");
            GroupType arrayGroupType = Types.buildGroup(REPEATED)
                    .add(toParquetType(arrayType.getElementType(), nameBuilder, legacyMode))
                    .named(nameBuilder.toString());
            nameBuilder.setLength(nameBuilder.length() - "array".length()); //reset it back to the state before
            return arrayGroupType;
        case MAP:
            MapType mapType = (MapType) logicalType;
            nameBuilder.append("map");
            GroupType mapGroupType = Types.buildGroup(REPEATED)
                    .add(toParquetType(mapType.getKeyType(), new StringBuilder("key"), legacyMode))
                    .add(toParquetType(mapType.getValueType(), new StringBuilder("value"), legacyMode))
                    .named(nameBuilder.toString());
            StringBuilder mapFieldTypeBuilder = new StringBuilder();
            if (legacyMode) { // standard LIST and MAP schema
                mapFieldTypeBuilder.append(mapGroupType.getType(0).getName()).append("_").append(mapGroupType.getType(0).getOriginalType());
                GroupType result = Types.buildGroup(REQUIRED)
                        .add(Types.required(BINARY).as(UTF8).named("key"))
                        .add(Types.optional(mapGroupType).as(mapFieldTypeBuilder.toString()).named("value"));
                return result;
            } else { // back-compatible schema
                return Types.required(mapGroupType).named(nameBuilder.toString());
            }
        case ROW:
            RowType rowType = (RowType) logicalType;
            Types.GroupBuilder<GroupType> rowGroupBuilder = Types.buildGroup(REQUIRED).asGroup();
            nameBuilder.append("row");
            for (int i = 0; i < rowType.getFieldCount(); i++) {
                RowType.RowField rowField = rowType.getFields().get(i);
                Type field = toParquetType(rowField.getType(), new StringBuilder(nameBuilder).append("_").append(rowField.getName()), legacyMode);
                if (legacyMode && (field instanceof GroupType)) {
                    rowGroupBuilder.addGroup(REPEATED)
                            .addField(Types.required(field).named(rowField.getName()))
                            .named(rowField.getName() + "_field");
                } else {
                    rowGroupBuilder.addField(field).as(field.getRepetition()).named(rowField.getName());
                }
            }
            nameBuilder.setLength(nameBuilder.length() - "row".length()); //reset it back to the state before
            return rowGroupBuilder.named(nameBuilder.toString());
        default:
            throw new UnsupportedOperationException("Unsupported type: " + typeRoot.toString());
    }
}

private static PrimitiveTypeNameForDecimal primitiveTypeNameForDecimal(DecimalType decimalType) {
    switch (decimalType.getPrecision()) {
        case 9:
            return PrimitiveTypeNameForDecimal.INT32;
        case 18:
            return PrimitiveTypeNameForDecimal.INT64;
        default:
            return PrimitiveTypeNameForDecimal.BINARY;
    }
}

private enum PrimitiveTypeNameForDecimal {
    INT32(PrimitiveTypeName.INT32),
    INT64(PrimitiveTypeName.INT64),
    BINARY(PrimitiveTypeName.BINARY);

    private final PrimitiveTypeName primitiveType;

    PrimitiveTypeNameForDecimal(PrimitiveTypeName primitiveType) {
        this.primitiveType = primitiveType;
    }
}

