public float[] generateNormals(float[] positions, int[] indices) {
    float[] normals = new float[positions.length];

    for (int i = 0; i < indices.length; i += 3) {
        int index1 = indices[i];
        int index2 = indices[i + 1];
        int index3 = indices[i + 2];

        float x1 = positions[3 * index1];
        float y1 = positions[3 * index1 + 1];
        float z1 = positions[3 * index1 + 2];

        float x2 = positions[3 * index2];
        float y2 = positions[3 * index2 + 1];
        float z2 = positions[3 * index2 + 2];

        float x3 = positions[3 * index3];
        float y3 = positions[3 * index3 + 1];
        float z3 = positions[3 * index3 + 2];

        float ux = x2 - x1;
        float uy = y2 - y1;
        float uz = z2 - z1;

        float vx = x3 - x1;
        float vy = y3 - y1;
        float vz = z3 - z1;

        float nx = (uy * vz) - (uz * vy);
        float ny = (uz * vx) - (ux * vz);
        float nz = (ux * vy) - (uy * vx);

        normals[3 * index1] += nx;
        normals[3 * index1 + 1] += ny;
        normals[3 * index1 + 2] += nz;

        normals[3 * index2] += nx;
        normals[3 * index2 + 1] += ny;
        normals[3 * index2 + 2] += nz;

        normals[3 * index3] += nx;
        normals[3 * index3 + 1] += ny;
        normals[3 * index3 + 2] += nz;
    }

    for (int i = 0; i < normals.length; i += 3) {
        float nx = normals[i];
        float ny = normals[i + 1];
        float nz = normals[i + 2];

        float length = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);

        normals[i] /= length;
        normals[i + 1] /= length;
        normals[i + 2] /= length;
    }

    return normals;
}

