public static void convolveBlock(float[] kernel, int[] inPixels, int[] outPixels, int width, int height, int edgeAction) {
    int index = 0;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            float r = 0, g = 0, b = 0, a = 0;
            for (int k = 0; k < kernel.length; k++) {
                int pixelIndex = index + k - kernel.length / 2;
                if (pixelIndex < 0 || pixelIndex >= inPixels.length) {
                    switch (edgeAction) {
                        case CLAMP_EDGES:
                            pixelIndex = Math.max(0, Math.min(pixelIndex, inPixels.length - 1));
                            break;
                        case WRAP_EDGES:
                            int wrapIndex = pixelIndex % inPixels.length;
                            pixelIndex = wrapIndex < 0 ? wrapIndex + inPixels.length : wrapIndex;
                            break;
                        case RGB_EDGES:
                            int edgeR = 0, edgeG = 0, edgeB = 0, edgeA = 255;
                            if (x == 0) {
                                edgeR = inPixels[index];
                                edgeG = inPixels[index];
                                edgeB = inPixels[index];
                            } else if (x == width - 1) {
                                edgeR = inPixels[index + k - 1];
                                edgeG = inPixels[index + k - 1];
                                edgeB = inPixels[index + k - 1];
                            } else if (y == 0) {
                                edgeR = inPixels[index];
                                edgeG = inPixels[index];
                                edgeB = inPixels[index];
                            } else if (y == height - 1) {
                                edgeR = inPixels[index + (width - 1) * kernel.length];
                                edgeG = inPixels[index + (width - 1) * kernel.length];
                                edgeB = inPixels[index + (width - 1) * kernel.length];
                            }
                            r += edgeR * kernel[k];
                            g += edgeG * kernel[k];
                            b += edgeB * kernel[k];
                            a += edgeA * kernel[k];
                            break;
                    }
                } else {
                    r += ((inPixels[pixelIndex] >> 16) & 0xff) * kernel[k];
                    g += ((inPixels[pixelIndex] >> 8) & 0xff) * kernel[k];
                    b += (inPixels[pixelIndex] & 0xff) * kernel[k];
                    a += (inPixels[pixelIndex] >>> 24) * kernel[k];
                }
            }
            outPixels[index++] = ((int) r) << 16 | ((int) g) << 8 | ((int) b) | ((int) a) << 24;
        }
    }
}

