public enum Directionality {
    LEFT_TO_RIGHT,
    RIGHT_TO_LEFT,
    MIXED,
    NEUTRAL
}

public Directionality estimateDirectionality(String str, boolean isHtml) {
    if (isHtml) {
        str = org.apache.commons.text.StringEscapeUtils.unescapeHtml4(str);
    }

    int ltrCount = 0;
    int rtlCount = 0;

    boolean hasText = false;

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (c == '<') {
            int closeTagIndex = str.indexOf('>', i + 1);

            if (closeTagIndex > 0) {
                String tag = str.substring(i, closeTagIndex + 1);

                if (tag.contains("dir=")) {
                    if (tag.contains("dir=\"rtl\"")) {
                        rtlCount += 1;
                    } else if (tag.contains("dir=\"ltr\"")) {
                        ltrCount += 1;
                    }
                }
                i += tag.length() - 1;
            }
        } else {
            hasText = true;

            Character.UnicodeBlock block = Character.UnicodeBlock.of(c);

            if (block == Character.UnicodeBlock.ARABIC || block == Character.UnicodeBlock.ARABIC_PRESENTATION_FORMS_A || block == Character.UnicodeBlock.ARABIC_PRESENTATION_FORMS_B) {
                rtlCount += 1;
            } else if (block == Character.UnicodeBlock.BASIC_LATIN || block == Character.UnicodeBlock.LATIN_1_SUPPLEMENT || block == Character.UnicodeBlock.LATIN_EXTENDED_A || block == Character.UnicodeBlock.LATIN_EXTENDED_ADDITIONAL) {
                ltrCount += 1;
            } else if (block == Character.UnicodeBlock.HEBREW || block == Character.UnicodeBlock.HEBREW_PRESENTATION_FORMS_A || block == Character.UnicodeBlock.HEBREW_PRESENTATION_FORMS_B) {
                rtlCount += 1;
            }
        }
    }

    if (!hasText) {
        return Directionality.NEUTRAL;
    } else if (rtlCount == 0 && ltrCount == 0) {
        return Directionality.NEUTRAL;
    } else if (rtlCount > ltrCount) {
        return Directionality.RIGHT_TO_LEFT;
    } else if (ltrCount > rtlCount) {
        return Directionality.LEFT_TO_RIGHT;
    } else {
        return Directionality.MIXED;
    }
}

