    Stack<Object> stateStack = new Stack<>();
    Stack<Object> valueStack = new Stack<>();
    int currentState = 0;

    while (true) {
        int nextState = getNextState(currentState, yyLex.getNextToken());

        if (nextState == ERROR_STATE) {
            throw new RuntimeException("Syntax error");
        }

        if (nextState == REDUCE_STATE) {
            int rule = getReduceRule(currentState, yyLex.getLastToken());

            Object[] args = new Object[rule.length - 1];

            for (int i = 0; i < args.length; i++) {
                args[args.length - i - 1] = valueStack.pop();
                stateStack.pop();
            }

            Object result = reduce(rule[0], args);

            int reducedState = getGotoState(stateStack.peek(), rule[0]);
            stateStack.push(reducedState);
            valueStack.push(result);
            currentState = reducedState;
