public void walkOstStreamAndSendNacks(int doubtHorizon, int stamp) throws GDException {
    for (int i = doubtHorizon; i <= stamp; i++) {
        if (oststream.containsKey(i)) {
            int tickStatus = oststream.get(i);
            if (tickStatus == TickStatus.REQUESTED || tickStatus == TickStatus.UNKNOWN) {
                sendNack(i);
                oststream.put(i, TickStatus.REQUESTED);
            }
        } else {
            oststream.put(i, TickStatus.REQUESTED);
            sendNack(i);
        }
    }
}

