public void processAckExpected(long stamp) {
	try {
        long current = doubtHorizon;
        while (current <= stamp) {
            Tick tick = getTick(current);
            if (tick.getStatus() == TickStatus.UNKNOWN) {
                tick.setStatus(TickStatus.REQUESTED);
                writeRange(current, current);
            } else if (tick.getStatus() == TickStatus.REQUESTED) {
                writeRange(current, current);
            }
            current++;
        }
