import org.w3c.dom.*;
import javax.xml.parsers.*;
import javax.xml.transform.*;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;
import java.io.StringWriter;
import java.util.Arrays;
import java.util.HashSet;

public class XmlFileRewriter {

    public static String rewriteXmlFile(String xmlFile, String[] aloneTags) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();

        InputSource is = new InputSource();
        is.setCharacterStream(new java.io.StringReader(xmlFile));

        Document doc = builder.parse(is);
        NodeList elements = doc.getElementsByTagName("*");

        HashSet<String> tagsSet = new HashSet<>(Arrays.asList(aloneTags));

        for (int i = 0; i < elements.getLength(); i++) {
            Element element = (Element) elements.item(i);
            Node parent = element.getParentNode();

            if (hasNoChildren(element) && tagsSet.contains(element.getNodeName())) {
                parent.removeChild(element);
            } else if (hasOnlyEmptyChildren(element)) {
                element.appendChild(doc.createTextNode(""));
            }
        }

        Transformer transformer = TransformerFactory.newInstance().newTransformer();
        transformer.setOutputProperty(OutputKeys.INDENT, "yes");

        StreamResult result = new StreamResult(new StringWriter());
        DOMSource source = new DOMSource(doc);
        transformer.transform(source, result);

        return result.getWriter().toString();
    }

    private static boolean hasNoChildren(Element element) {
        return !element.hasChildNodes();
    }

    private static boolean hasOnlyEmptyChildren(Element element) {
        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (child instanceof Element && !((Element) child).getTagName().equals(""))) {
                return false;
            }
            if (child.getNodeType() == Node.TEXT_NODE && !child.getNodeValue().trim().isEmpty()) {
                return false;
            }
        }
        return true;
    }

}

