import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.stat.StatUtils;
import org.apache.commons.math3.util.Pair;
import org.apache.commons.math3.util.Precision;
import org.apache.commons.math3.util.ResizableDoubleArray;

public class AUC {

    public static double calculateMacroAUC(List<Pair<Integer, ResizableDoubleArray>> classPredictions) {
        List<Integer> classLabels = new ArrayList<>();
        List<double[]> classScores = new ArrayList<>();

        classPredictions.forEach(classPrediction -> {
            int label = classPrediction.getKey();
            ResizableDoubleArray predictions = classPrediction.getValue();

            double[] scores = predictions.getElements();
            classLabels.add(label);
            classScores.add(scores);
        });

        double[] AUCs = new double[classLabels.size()];
        double[] pos = new double[classLabels.size()];
        double[] neg = new double[classLabels.size()];

        for (int i = 0; i < classLabels.size(); i++) {
            int label = classLabels.get(i);
            double[] scores = classScores.get(i);

            int posCount = 0;
            int negCount = 0;

            for (int j = 0; j < scores.length; j++) {
                if (label == 1) {
                    if (scores[j] == 1.0) {
                        posCount++;
                    } else {
                        negCount++;
                    }
                } else {
                    if (scores[j] == 0.0) {
                        negCount++;
                    } else {
                        posCount++;
                    }
                }
            }

            if (posCount == 0 || negCount == 0) {
                AUCs[i] = Double.NaN;
            } else {
                double[] tempScores = new double[scores.length];
                double[] sortedScores = new double[scores.length];
                System.arraycopy(scores, 0, tempScores, 0, scores.length);
                System.arraycopy(scores, 0, sortedScores, 0, scores.length);
                for (int j = 0; j < scores.length; j++) {
                    sortedScores[j] = tempScores[StatUtils.minIndex(tempScores)];
                    tempScores[StatUtils.minIndex(tempScores)] = Double.POSITIVE_INFINITY;
                }

                double[] tp = new double[scores.length];
                double[] fp = new double[scores.length];
                for (int j = 0; j < scores.length; j++) {
                    if (label == 1) {
                        tp[j] = Precision.round(StatUtils.sum(tp), 3) + sortedScores[j] == 1.0 ? 1 : 0;
                        fp[j] = Precision.round(StatUtils.sum(fp), 3) + sortedScores[j] == 0.0 ? 1 : 0;
                    } else {
                        fp[j] = Precision.round(StatUtils.sum(fp), 3) + sortedScores[j] == 1.0 ? 1 : 0;
                        tp[j] = Precision.round(StatUtils.sum(tp), 3) + sortedScores[j] == 0.0 ? 1 : 0;
                    }
                }
                double auc = ComputeAuc(tp, fp);
                AUCs[i] = auc;
                pos[i] = posCount;
                neg[i] = negCount;
            }
        }

        double[] aucArray = new double[AUCs.length];
        double macroAucSum = 0.0;
        int totalCount = 0;
        for (int i = 0; i < AUCs.length; i++) {
            if (!Double.isNaN(AUCs[i])) {
                aucArray[i] = AUCs[i] * pos[i];
                macroAucSum += aucArray[i];
                totalCount += pos[i] + neg[i];
            }
        }

        double macroAuc = macroAucSum / totalCount;

        return macroAuc;

    }

    private static double ComputeAuc(final double[] tp, final double[] fp) {
        double auc = 0.;
        for (int i = 1; i < tp.length; i++) {
            final double deltaFp = fp[i] - fp[i - 1];
            final double avgTp = (tp[i] + tp[i - 1]) / 2.;
            auc += deltaFp * avgTp;
        }
        return auc;
    }

}

