public double calculateEntropy(double[] vector) {
    double entropy = 0.0;
    Map<Double, Integer> valueCounts = new HashMap<>();

    int totalValues = vector.length;
    for (double value : vector) {
        if (!valueCounts.containsKey(value)) {
            valueCounts.put(value, 0);
        }
        valueCounts.put(value, valueCounts.get(value) + 1);
    }

    for (double value : valueCounts.keySet()) {
        double probability = ((double) valueCounts.get(value)) / totalValues;
        entropy -= probability * (Math.log(probability) / Math.log(2));
    }

    return entropy;
}

