import java.lang.reflect.Array;

public static Object convertArray(Class<?> dsttype, Class<?> srctype, Object src) {
    if (!src.getClass().isArray()) {
        throw new IllegalArgumentException("src is not an array");
    }

    int srcLength = Array.getLength(src);
    Object dst = Array.newInstance(dsttype, srcLength);

    for (int i = 0; i < srcLength; i++) {
        Object srcElement = Array.get(src, i);
        if (srcElement.getClass() != srctype) {
            throw new IllegalArgumentException("src element is not of the expected type");
        }

        if (!dsttype.isAssignableFrom(srcElement.getClass())) {
            throw new IllegalArgumentException("src element is not assignable to the target type");
        }

        Array.set(dst, i, srcElement);
    }

    return dst;
}

