public List<Object> parseRLP(byte[] rlpEncoded) {
    List<Object> rlpList = new ArrayList<>();
    if (rlpEncoded.length == 0) {
        return rlpList;
    }
    int prefix = rlpEncoded[0] & 0xFF;
    int length = prefix - OFFSET_SHORT_ITEM;
    if (prefix == OFFSET_SHORT_ITEM) {
        return rlpList;
    } else if (prefix < OFFSET_SHORT_ITEM) {
        rlpList.add(rlpEncoded);
    } else if (length == 1) {
        rlpList.add(rlpEncoded[1] & 0xFF);
    } else {
        int dataLen;
        int copyLen;
        byte[] data;
        if (length == 0) {
            dataLen = rlpEncoded.length - 1;
            copyLen = dataLen;
            data = rlpEncoded;
        } else {
            dataLen = length;
            copyLen = rlpEncoded.length - 1 - length;
            data = new byte[dataLen];
            System.arraycopy(rlpEncoded, 1 + length, data, 0, dataLen);
        }
        int offset = 0;
        int i = 0;
        if (data[0] == OFFSET_LONG_ITEM) {
            do {
                offset += length(data[offset + 1]);
                i++;
            } while (offset < data.length && i < 8);
            if (i == 8 && length(data[offset + 1]) > 0) {
                throw new RuntimeException("Input too long");
            }
            if (i != 0) {
                i *= -1;
            }
        } else {
            i = 1;
        }
        for (; i < 0; i++) {
            int endIndex = offset + length(data[offset + 1]) + 1;
            rlpList.add(parseRLP(Arrays.copyOfRange(data, offset, endIndex)));
            offset += length(data[offset + 1]) + 1;
        }
        for (; offset < data.length; offset += copyLen) {
            int len = length(data[offset]);
            len = len == 1 && (data[offset + 1] & 0xff) < OFFSET_SHORT_ITEM ? 1 : length(data[offset + 1]);
            len += offset + len + 1 <= data.length ? 1 : 0;
            copyLen = len;
            rlpList.add(Arrays.copyOfRange(data, offset, offset + copyLen));
        }
    }
    return rlpList;
}

private int length(final byte lead) {
    return lead & 0xFF == OFFSET_LONG_ITEM ? (lead & 0xFF) ^ OFFSET_LONG_ITEM + 1 : lead & 0xFF;
}

