public static Set<Edge> maximiseMatching(Set<Edge> matching, Map<Integer, Set<Integer>> graph, Set<Integer> subset){
    Set<Edge> result = new HashSet<>();
    Set<Integer> visited = new HashSet<>();

    for(Edge edge : matching){
        if(subset.contains(edge.getSource()) && subset.contains(edge.getDestination())){
            visited.add(edge.getSource());
            visited.add(edge.getDestination());
            result.add(edge);
        }
    }

    while(true){
        Map<Integer, List<Edge>> candidates = new HashMap<>();
        boolean foundAugmentingPath = false;

        for(int vertex : subset){
            if(!visited.contains(vertex)){
                List<Edge> edges = new ArrayList<>();
                for(int neighbour : graph.get(vertex)){
                    if(!visited.contains(neighbour)){
                        edges.add(new Edge(vertex, neighbour));
                    }
                }
                candidates.put(vertex, edges);
            }
        }

        Map<Integer, Integer> paths = new HashMap<>();
        for(int vertex : candidates.keySet()){
            if(assignPath(vertex, candidates, visited, paths)){
                foundAugmentingPath = true;
                break;
            }
        }

        if(!foundAugmentingPath){
            break;
        }

        for(int vertex : paths.keySet()){
            visited.add(vertex);
            int neighbour = paths.get(vertex);
            visited.add(neighbour);
            result.add(new Edge(vertex, neighbour));
        }
    }

    return result;
}

private static boolean assignPath(int vertex, Map<Integer, List<Edge>> candidates, Set<Integer> visited, Map<Integer, Integer> paths){
    for(Edge edge : candidates.get(vertex)){
        int neighbour = edge.getDestination();
        if(!visited.contains(neighbour)){
            visited.add(neighbour);
            if(!paths.containsKey(neighbour) || assignPath(paths.get(neighbour), candidates, visited, paths)){
                paths.put(neighbour, vertex);
                return true;
            }
        }
    }
    return false;
}

