public static int compareValues(Object iField1, Object iField2) {
    if(iField1 instanceof Comparable && iField2 instanceof Comparable) {
        // Attempt to convert to same type
        if(!iField1.getClass().equals(iField2.getClass())) {
            iField1 = convertValueToType(iField1, iField2.getClass());
        }
        // Compare values
        return ((Comparable) iField1).compareTo(iField2);
    } else {
        throw new IllegalArgumentException("Parameters must implement Comparable interface.");
    }
}

private static Object convertValueToType(Object value, Class<?> destType) {
    if(destType == String.class) {
        return value.toString();
    } else if(destType == Integer.class) {
        return Integer.parseInt(value.toString());
    } else if(destType == Long.class) {
        return Long.parseLong(value.toString());
    } else if(destType == Float.class) {
        return Float.parseFloat(value.toString());
    } else if(destType == Double.class) {
        return Double.parseDouble(value.toString());
    } else if(destType == Boolean.class) {
        return Boolean.parseBoolean(value.toString());
    } else {
        throw new IllegalArgumentException("Destination type not supported.");
    }
}

