        RSAPrivateCrtKey privateKey = getRsaPrivateKey(jwk.get("d"), publicKey.getModulus(), jwk.get("p"), jwk.get("q"), jwk.get("dp"), jwk.get("dq"), jwk.get("qi"), provider);
        return new RsaKey(publicKey, privateKey);
    }

    private static RSAPublicKey getRsaPublicKey(JsonValue n, JsonValue e) throws NoSuchAlgorithmException, InvalidKeySpecException {
        return (RSAPublicKey) KeyFactory.getInstance("RSA").generatePublic(new RSAPublicKeySpec(convertBase64UrlToBigInt(n.asJsonString().getString()), convertBase64UrlToBigInt(e.asJsonString().getString())));
    }

    private static RSAPrivateCrtKey getRsaPrivateKey(JsonValue d, JsonValue n, JsonValue p, JsonValue q, JsonValue dp, JsonValue dq, JsonValue qi, Provider provider) throws NoSuchAlgorithmException, InvalidKeySpecException {
        return (RSAPrivateCrtKey) KeyFactory.getInstance("RSA", provider).generatePrivate(new RSAPrivateCrtKeySpec(convertBase64UrlToBigInt(n.asJsonString().getString()), convertBase64UrlToBigInt(p.asJsonString().getString()), convertBase64UrlToBigInt(q.asJsonString().getString()), convertBase64UrlToBigInt(d.asJsonString().getString()), convertBase64UrlToBigInt(dp.asJsonString().getString()), convertBase64UrlToBigInt(dq.asJsonString().getString()), convertBase64UrlToBigInt(qi.asJsonString().getString())));
    }

    private static byte[] convertBase64UrlToBigInt(String value) {
        String base64 = value.replace('-', '+').replace('_', '/');
        int padding = 4 - base64.length() % 4;
        if (padding < 4) {
            base64 += "====".substring(padding);
        }
        return java.util.Base64.getDecoder().decode(base64.getBytes());
    }
}

class RsaKey {
    private RSAPublicKey publicKey;
    private RSAPrivateCrtKey privateKey;

    public RsaKey(RSAPublicKey publicKey) {
        this.publicKey = publicKey;
    }

    public RsaKey(RSAPublicKey publicKey, RSAPrivateCrtKey privateKey) {
        this.publicKey = publicKey;
        this.privateKey = privateKey;
    }

    public RSAPublicKey getPublicKey() {
        return publicKey;
    }

    public RSAPrivateCrtKey getPrivateKey() {
        return privateKey;
    }
}

