static public double zeta1(final int n) {
	if (n <= 1) {
        throw new IllegalArgumentException("n must be greater than 1");
    }
    double sum = 0.0;
    for (int k = 1; k <= Integer.MAX_VALUE; k++) {
        sum += 1.0 / Math.pow(k, n);
        if (sum == Double.POSITIVE_INFINITY) {
            break;
        }
    }
    return sum - 1.0;
}

