public void skipObject(Node node) {
    if (node == null) {
        return;
    }
    Node child = node.getChild();
    if (child != null) {
        skipObject(child); // recursively skip the child and all its children
    }
    node.setVisited(true); // mark the current node as visited if necessary
}

