public ExecType execute(DatabaseChangeLog databaseChangeLog, ChangeExecListener listener, Database database) throws MigrationFailedException {
    // Get the list of changes
    List<Change> changes = databaseChangeLog.getChanges();

    // Execute each change
    for (Change change : changes) {
        // Execute the change
        change.execute(database);

        // Notify the listener
        listener.changeExecuted(change);
    }

    // Mark the change set as ran
    databaseChangeLog.setRan(true);

    // Return the execution type
    return ExecType.EXECUTED;
}

