public void reconstituteDestinations() throws MessageStoreException {
    try {
        // Check that initializeNonPersistent() has been called before
        if (messageStore == null) {
            throw new MessageStoreException("InitializeNonPersistent method must be called first");
        }

        // Retrieve all destionations from messageStore
        List<String> destinationNames = messageStore.getAllDestinations();

        // Loop through all destination names and reconstitute each destination
        for (String destinationName : destinationNames) {
            Destination destination = destinations.get(destinationName);
            if (destination == null) {
                // If the destination does not exist, create it and add it to the map
                destination = new Destination(destinationName);
                destinations.put(destinationName, destination);
            } else {
                // Otherwise, just reinitialize the destination
                destination.initialize();
            }
        }
    } catch (Exception e) {
        throw new MessageStoreException("Failed to reconstitute destinations", e);
    }
}

