public static <T> BoundedAsyncPool<T> createBoundedAsyncPool(Supplier<? extends T> connectionSupplier, AsyncPoolConfig config) {
    Objects.requireNonNull(connectionSupplier, "Connection supplier must not be null.");
    Objects.requireNonNull(config, "AsyncPoolConfig must not be null.");

    return new BoundedAsyncPool<T>() {
        private final PooledRefQueue<T> queue = new PooledRefQueue<>();
        private final Semaphore semaphore = new Semaphore(config.getMaxPermits());

        @Override
        public CompletableFuture<Void> closeAsync() {
            queue.close();
            semaphore.drainPermits();
            return CompletableFuture.completedFuture(null);
        }

        @Override
        public int size() {
            return queue.size();
        }

        @Override
        public CompletableFuture<Void> warmupAsync() {
            int warmup = config.getMinSize() - queue.size();
            if (warmup <= 0) {
                return CompletableFuture.completedFuture(null);
            }

            final CompletableFuture<Void> future = new CompletableFuture<>();

            final AtomicInteger counter = new AtomicInteger(0);

            for (int i = 0; i < warmup; i++) {
                if (semaphore.tryAcquire()) {
                    try {
                        T element = connectionSupplier.get();
                        if (element != null) {
                            counter.incrementAndGet();

                            // Wrap the element in a non-releasable ref and enqueue it.
                            NonReleasableRef<T> ref = new NonReleasableRef<>(element);
                            queue.add(ref);
                        } else {
                            semaphore.release();
                        }
                    } catch (Throwable t) {
                        semaphore.release();
                    }
                } else {
                    break;
                }
            }

            if (counter.get() == warmup) {
                future.complete(null);
            } else {
                future.completeExceptionally(new IllegalStateException("Could not warm up the pool to the desired size."));
            }

            return future;
        }

        @Override
        public Mono<Void> acquire(Consumer<PooledRef<T>> onAcquire) {
            Objects.requireNonNull(onAcquire, "On acquire consumer must not be null.");

            return Mono.fromRunnable(() -> semaphore.acquire())
                    .then(Mono.defer(() -> {
                        PooledRef<T> ref = queue.poll();
                        if (ref == null) {
                            semaphore.release();
                            return Mono.error(new IllegalStateException("No connections available."));
                        }

                        onAcquire.accept(ref);
                        return Mono.just(ref);
                    }));
        }

        @Override
        public CompletableFuture<Void> release(PooledRef<T> pooledRef) {
            Objects.requireNonNull(pooledRef, "PooledRef must not be null.");

            if (!(pooledRef instanceof NonReleasableRef)) {
                throw new IllegalArgumentException("PooledRef is not a NonReleasableRef, probably from another pool: " + pooledRef);
            }

            NonReleasableRef<T> ref = (NonReleasableRef<T>) pooledRef;
            semaphore.release();
            return CompletableFuture.completedFuture(null);
        }
    };
}

