public static double[][] reduceToSchur(double[][] matrix) {
    int n = matrix.length;
    double[][] result = matrix.clone();
    for (int i = 0; i < n - 2; i++) {
        for (int j = i + 2; j < n; j++) {
            double scale = 0.0;
            for (int k = i + 1; k < j; k++) {
                scale += Math.abs(result[k][j]);
            }
            if (scale != 0.0) {
                double h = 0.0;
                for (int k = j - 1; k > i; k--) {
                    result[k + 1][j] = result[k][j] / scale;
                    h += result[k][j] * result[k][j];
                }
                double g = Math.sqrt(h + result[i + 1][j] * result[i + 1][j]);
                if (result[i + 1][j] > 0.0) {
                    g = -g;
                }
                result[i + 1][j] -= g;
                h -= result[i + 1][j] * g;
                for (int k = j - 1; k > i; k--) {
                    double f = 0.0;
                    for (int l = k; l <= j; l++) {
                        f += result[k][l] * result[l][j];
