                    f /= h;
                    for (int l = k; l <= j; l++) {
                        result[k][l] -= f * result[l][j];
                    }
                }
                for (int l = i; l <= j; l++) {
                    result[l][j] *= scale;
                }
            }
        }
    }
    return result;
}

