import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class Helper {
    public static String runProcess(String cmd, String... args) throws StartupException, TimeoutException, ExternalProcessFailureException {
        List<String> processArgs = new ArrayList<>();
        processArgs.add(cmd);
        // add any additional args
        for (String arg : args) {
            processArgs.add(arg);
        }
        try {
            ProcessBuilder pb = new ProcessBuilder(processArgs);
            Process process = pb.start();

            InputStream inputStream = process.getInputStream();
            BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));

            StringBuilder output = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line + "\n");
            }

            int exitCode = process.waitFor(5, TimeUnit.SECONDS);
            if (exitCode != 0) {
                throw new ExternalProcessFailureException(String.format("External process exited with exit code %d", exitCode));
            }

            return output.toString();
        } catch (IOException | InterruptedException e) {
            throw new StartupException("Failed to start process", e);
        } catch (java.util.concurrent.TimeoutException e) {
            throw new TimeoutException("Timeout waiting for process to complete", e);
        }
    }
}

class StartupException extends Exception {
    public StartupException(String message, Throwable cause) {
        super(message, cause);
    }
}

class TimeoutException extends Exception {
    public TimeoutException(String message, Throwable cause) {
        super(message, cause);
    }
}

class ExternalProcessFailureException extends Exception {
    public ExternalProcessFailureException(String message) {
        super(message);
    }
}

