import java.util.*;

public <T extends Comparable<? super T>> Iterator<T> mergeIterators(List<Iterator<T>> iterators) {
    PriorityQueue<PeekingIterator<T>> queue = new PriorityQueue<>(Comparator.comparing(PeekingIterator::peek));

    for (Iterator<T> iterator : iterators) {
        if (iterator.hasNext()) {
            queue.add(new PeekingIterator<>(iterator));
        }
    }

    return new Iterator<T>() {
        @Override
        public boolean hasNext() {
            return !queue.isEmpty();
        }

        @Override
        public T next() {
            PeekingIterator<T> iterator = queue.poll();
            T next = iterator.next();

            if (iterator.hasNext()) {
                queue.add(iterator);
            }

            return next;
        }
    };
}

final class PeekingIterator<T extends Comparable<? super T>> implements Iterator<T> {
    private final Iterator<T> iterator;
    private T peekedValue;
    private boolean hasPeeked;

    PeekingIterator(Iterator<T> iterator) {
        this.iterator = Objects.requireNonNull(iterator, "iterator");
    }

    @Override
    public boolean hasNext() {
        return hasPeeked || iterator.hasNext();
    }

    @Override
    public T next() {
        if (hasPeeked) {
            hasPeeked = false;
            return peekedValue;
        } else {
            return iterator.next();
        }
    }

    public T peek() {
        if (!hasPeeked) {
            peekedValue = iterator.next();
            hasPeeked = true;
        }

        return peekedValue;
    }
}

