private void fixGetSet(HashMap<String, HashMap> propertyTable) throws IntrospectionException {
	// Iterate over each property in the propertyTable
    for (String propertyName : propertyTable.keySet()) {
        HashMap<String, Object> propertyDetails = propertyTable.get(propertyName);

        // Check if both getter and setter are specified
        if (propertyDetails.containsKey("getter") && propertyDetails.containsKey("setter")) {
            Method getter = (Method) propertyDetails.get("getter");
            Method setter = (Method) (propertyDetails.get("setter"));

            // Check if the return type of the getter matches the parameter type of the setter
            if (!getter.getReturnType().equals(setter.getParameterTypes()[0])) {
                throw new IntrospectionException("Incompatible getter and setter for property: " + propertyName);
            }
        }
    }
