import org.openqa.selenium.*;
import org.openqa.selenium.interactions.Actions;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;

public class ScreenshotUtils {

    public static BufferedImage takeScreenshotOfElementInIFrame(WebDriver driver, WebElement iframe, WebElement element) throws IOException {
        driver.switchTo().frame(iframe);

        //Scroll to the element to capture the complete screenshot.
        ((JavascriptExecutor) driver).executeScript("arguments[0].scrollIntoView();", element);

        // Get entire page screenshot
        byte[] screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.BYTES);
        BufferedImage fullImage = ImageIO.read(new ByteArrayInputStream(screenshot));

        //Get the location of element on the page
        Point point = element.getLocation();

        //Get width and height of the element
        int width = element.getSize().getWidth();
        int height = element.getSize().getHeight();

        //Crop the entire page screenshot to get only element screenshot
        BufferedImage elementScreenshot = fullImage.getSubimage(point.getX(), point.getY(), width, height);

        //If the element is only partially visible, a horizontal scrollbar will be present
        //Get the horizontal scrollbar width and add it to the element screenshot width to get the full length.
        int horizontalScrollbarWidth = 0;
        if (elementScreenshot.getWidth() < element.getSize().getWidth()) {
            horizontalScrollbarWidth = (int) ((element.getSize().getWidth() - elementScreenshot.getWidth()) * 0.6);
        }
        int fullWidth = elementScreenshot.getWidth() + horizontalScrollbarWidth;
        BufferedImage finalImg = new BufferedImage(fullWidth, elementScreenshot.getHeight(), fullImage.getType());
        finalImg.createGraphics().drawImage(elementScreenshot, 0, 0, null);

        //Return the buffered image
        return finalImg;
    }
}

