public static double[][] convolution2D(double[][] input, double[][] kernel, String type) {
    int inRows = input.length;
    int inCols = input[0].length;
    int kRows = kernel.length;
    int kCols = kernel[0].length;
    int outRows = inRows - kRows + 1;
    int outCols = inCols - kCols + 1;
    double[][] output = new double[outRows][outCols];

    for (int i = 0; i < outRows; ++i) {
        for (int j = 0; j < outCols; ++j) {
            double sum = 0;
            for (int k = 0; k < kRows; ++k) {
                for (int l = 0; l < kCols; ++l) {
                    int r = i + k;
                    int c = j + l;
                    if (type.equals("full")) {
                        r = r - kRows + 1;
                        c = c - kCols + 1;
                        if (r < 0 || r >= inRows || c < 0 || c >= inCols) {
                            sum += kernel[k][l] * 0;
                        } else {
                            sum += kernel[k][l] * input[r][c];
                        }
                    } else if (type.equals("same")) {
                        if (r < 0 || r >= inRows || c < 0 || c >= inCols) {
                            sum += kernel[k][l] * 0;
                        } else {
                            sum += kernel[k][l] * input[r][c];
                        }
                    } else if (type.equals("valid")) {
                        r = r - kRows + 1;
                        c = c - kCols + 1;
                        if (r < 0 || r >= outRows || c < 0 || c >= outCols) {
                            sum += kernel[k][l] * 0;
                        } else {
                            sum += kernel[k][l] * input[r][c];
                        }
                    }
                }
            }
            output[i][j] = sum;
        }
    }
    return output;
}

