import org.fcrepo.client.FcrepoClient;
import org.fcrepo.client.FcrepoClient.FcrepoClientBuilder;
import org.fcrepo.client.FcrepoLink;
import org.apache.http.client.HttpClient;
import org.apache.http.impl.client.HttpClientBuilder;
import org.apache.jena.rdf.model.Model;
import org.apache.jena.rdf.model.ModelFactory;
import org.apache.jena.rdfconnection.RDFConnection;
import org.apache.jena.rdfconnection.RDFConnectionFactory;
import org.apache.jena.riot.RDFLanguages;

public class LDClientConfigurer {
    public static LDClient configureClient(String endpoint, String provider) {
        // Create HTTP client
        HttpClient httpClient = HttpClientBuilder.create().build();

        // Create Fedora client builder
        FcrepoClientBuilder clientBuilder = FcrepoClient.clientBuilder()
                .httpClient(httpClient)
                .useLdp();

        // Enable specified endpoint on the client
        if (endpoint != null && !endpoint.isEmpty()) {
            clientBuilder.addLinkHeader(new FcrepoLink(endpoint, "type"));
        }

        // Enable specified provider on the client
        if (provider != null && !provider.isEmpty()) {
            clientBuilder.addLinkHeader(new FcrepoLink(provider, "rel", "http://fedora.info/definitions/v4/repository#hasProvider"));
        }

        // Build the client
        FcrepoClient fcrepoClient = clientBuilder.build();

        // Create the LD client config
        Model model = ModelFactory.createDefaultModel();

        if (endpoint != null && !endpoint.isEmpty()) {
            model.add(model.createResource()
                    .addProperty(model.createProperty("http://fedora.info/definitions/v4/repository#ldpEndpoint"), model.createResource(endpoint)));
        }

        if (provider != null && !provider.isEmpty()) {
            model.add(model.createResource()
                    .addProperty(model.createProperty("http://fedora.info/definitions/v4/repository#provider"), model.createResource(provider)));
        }

        RDFConnection rdfConnection = RDFConnectionFactory.connect(fcrepoClient.getBaseUrl());
        rdfConnection.put(model, RDFLanguages.TURTLE);
        rdfConnection.close();

        return new LDClient(fcrepoClient, model);
    }
}

