public int getRotationType(double[][] m) {
    int n = m.length;
    double det = getDeterminant(m);
    double trace = 0;
    for (int i = 0; i < n; i++) {
        trace += m[i][i];
    }
    if (Math.abs(det - 1.0) > 1e-8) {
        if (Math.abs(det + 1.0) < 1e-8) {
            return -1;
        } else {
            return -2;
        }
    } else {
        if (Math.abs(trace - n) < 1e-8) {
            return 1;
        } else if (Math.abs(trace + n) < 1e-8) {
            return -3;
        } else {
            boolean proper = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < i; j++) {
                    if (Math.abs(m[i][j] - m[j][i]) > 1e-8) {
                        proper = false;
                        break;
                    }
                }
                if (!proper) {
                    break;
                }
            }
            if (proper) {
                int fold = getFold(m);
                return fold > 0 ? fold : -fold;
            } else {
                int fold = getFold(m);
                return fold > 0 ? -fold : fold;
            }
        }
    }
}

private double getDeterminant(double[][] m) {
    int n = m.length;
    if (n == 2) {
        return m[0][0] * m[1][1] - m[0][1] * m[1][0];
    }
    double det = 0;
    for (int i = 0; i < n; i++) {
        double[][] submatrix = new double[n - 1][n - 1];
        for (int j = 1; j < n; j++) {
            for (int k = 0; k < n; k++) {
                if (k < i) {
                    submatrix[j - 1][k] = m[j][k];
                } else if (k > i) {
                    submatrix[j - 1][k - 1] = m[j][k];
                }
            }
        }
        if (i % 2 == 0) {
            det += m[0][i] * getDeterminant(submatrix);
        } else {
            det -= m[0][i] * getDeterminant(submatrix);
        }
    }
    return det;
}

private int getFold(double[][] m) {
    int n = m.length;
    while (n > 1 && Math.abs(m[n - 1][n - 1] - 1.0) < 1e-8) {
        n--;
    }
    double[][] rm = new double[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            rm[i][j] = m[i][j];
        }
    }
    double eps = 1e-8;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (Math.abs(rm[i][j]) < eps) {
                rm[i][j] = 0.0;
            }
        }
    }
    double[][] rot = new double[n][n];
    double[][] tmp = new double[n][n];
    for (int i = 0; i < n; i++) {
        rot[i][i] = 1.0;
    }
    boolean isRotational = true;
    for (int k = 0; k < 12; k++) { // Repeat at most 12 times
        boolean found = false;
        int i0 = 0, j0 = 0;
        for (int i = 0; i < n && !found; i++) {
            for (int j = i + 1; j < n && !found; j++) {
                if (Math.abs(rm[i][j] - rm[j][i]) > eps) {
                    i0 = i;
                    j0 = j;
                    found = true;
                }
            }
        }
        if (!found) {
            break;
        }
        double aii = rm[i0][i0], ajj = rm[j0][j0];
        double aij = rm[i0][j0], aji = rm[j0][i0];
        double sgn = Math.signum(aii - ajj);
        double t = sgn / (2 * Math.sqrt(aij * aji));
        double c = 1.0 / Math.sqrt(1 + t * t);
        double s = c * t;
        for (int i = 0; i < n; i++) {
            if (i != i0 && i != j0) {
                tmp[i][i] = 1.0;
            } else {
                tmp[i][i] = c;
                tmp[i0][j0] = sgn * s;
                tmp[j0][i0] = -s;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                rot[i][j] = 0.0;
                for (int k = 0; k < n; k++) {
                    rot[i][j] += tmp[i][k] * rot[k][j];
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double sum = 0.0;
                for (int k = 0; k < n; k++) {
                    sum += rot[i][k] * rm[k][j];
                }
                rm[i][j] = sum;
            }
        }
        double tr = 0;
        for (int i = 0; i < n; i++) {
            tr += rm[i][i];
        }
        if (Math.abs(Math.abs(tr) - n) > eps) {
            isRotational = false;
            break;
        }
    }
    if (isRotational) {
        double[][] v = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                v[i][j] = m[i][j];
            }
        }
        double[][] vv = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                vv[i][j] = 0.0;
                for (int k = 0; k < n; k++) {
                    vv[i][j] += rot[i][k] * v[k][j];
