private void eigenvalueDecomposition(double[][] a, double[] eval, double[][] evec) {
    int n = a.length;
    double[] d = new double[n];
    double[] e = new double[n];
    double[][] v = new double[n][n];
    for (int j = 0; j < n; j++) {
        eval[j] = a[n - 1][j];
        v[n - 1][j] = 0.0;
    }
    v[n - 1][n - 1] = 1.0;
    for (int i = n - 2; i >= 0; i--) {
        double scale = 0.0;
        double h = 0.0;
        for (int k = 0; k <= i; k++) {
            scale = scale + Math.abs(eval[k]);
        }
        if (scale == 0.0) {
            e[i] = eval[i];
            for (int j = 0; j < i; j++) {
                eval[j] = a[i - 1][j];
                a[i][j] = 0.0;
                a[j][i] = 0.0;
            }
        } else {
            for (int k = 0; k <= i; k++) {
                eval[k] /= scale;
                h += eval[k] * eval[k];
            }
            double f = eval[i];
            double g = Math.sqrt(h);
            if (f > 0) {
                g = -g;
            }
            e[i] = scale * g;
            h = h - f * g;
            eval[i] = f - g;
            for (int j = 0; j < n; j++) {
                evec[i][j] = 0.0;
            }
            for (int j = 0; j <= i; j++) {
                eval[j] = eval[j] - eval[i];
                evec[i][j] = eval[j];
            }
            f = 0.0;
            for (int j = 0; j <= i; j++) {
                eval[j] /= h;
                f += eval[j] * evec[i][j];
            }
            double hh = f / (h + h);
            for (int j = 0; j <= i; j++) {
                eval[j] -= hh * evec[i][j];
            }
            for (int j = 0; j < n; j++) {
                f = evec[i][j];
                evec[i][j] = v[j][i] + hh * evec[i][j];
                v[j][i] = -hh * f + v[j][i];
            }
        }
    }
    for (int i = 0; i < n; i++) {
        eval[i] = eval[i] + e[i];
    }
    for (int i = 0; i < n; i++) {
        int k = i;
        double p = eval[i];
        for (int j = i + 1; j < n; j++) {
            if (eval[j] < p) {
                k = j;
                p = eval[j];
            }
