public String parseDataBuffer(char[] data, int offset, int length) throws SerializationException {
    if (data == null || offset < 0 || length < 0 || offset+length > data.length) {
        throw new SerializationException("Invalid data buffer, offset, or length");
    }

    StringBuilder resultBuilder = new StringBuilder();
    for (int i = offset; i < offset + length; i++) {
        resultBuilder.append(data[i]);
    }

    String result = resultBuilder.toString();
    if (result.isEmpty()) {
        throw new SerializationException("Empty or invalid data buffer");
    }

    return result;
}

