  public List<SAXParseException> validate(File file) throws IOException, SAXException {
    List<SAXParseException> exceptions = new ArrayList<>();
    SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
    Schema schema = schemaFactory.newSchema(new StreamSource(getClass().getResourceAsStream(SCHEMA_FILE)));
    Validator validator = schema.newValidator();
    validator.setErrorHandler(new ErrorHandler() {
      @Override
      public void warning(SAXParseException e) throws SAXException {
        exceptions.add(e);
      }

      @Override
      public void error(SAXParseException e) throws SAXException {
        exceptions.add(e);
      }

      @Override
      public void fatalError(SAXParseException e) throws SAXException {
        exceptions.add(e);
      }
    });
    validator.validate(new StreamSource(file));
    return exceptions;
  }
}

