public class Opcoder {
  public static void operation(Stack<Integer> stack, String opcode) {
    switch (opcode) {
      case "dup":
        int duplicate = stack.peek();
        stack.push(duplicate);
        break;
      case "pop":
        stack.pop();
        break;
      case "swap":
        int x = stack.pop();
        int y = stack.pop();
        stack.push(x);
        stack.push(y);
        break;
      case "add":
        int sum = stack.pop() + stack.pop();
        stack.push(sum);
        break;
      case "sub":
        int b = stack.pop();
        int a = stack.pop();
        int difference = a - b;
        stack.push(difference);
        break;
      case "mult":
        int product = stack.pop() * stack.pop();
        stack.push(product);
        break;
      case "div":
        int divisor = stack.pop();
        int dividend = stack.pop();
        int quotient = dividend / divisor;
        stack.push(quotient);
        break;
      default:
        // handle unknown opcode
        throw new IllegalArgumentException("Unknown opcode: " + opcode);
    }
  }
}

