public class UnaryExpression {
    private char operator;
    private int operand;

    public UnaryExpression(char operator, int operand) {
        this.operator = operator;
        this.operand = operand;
    }

    public int evaluate() {
        switch (operator) {
            case '-':
                return -operand;
            case '+':
                return operand;
            default:
                throw new IllegalArgumentException("Invalid operator: " + operator);
        }
    }
}

