import javax.jms.JMSException;
import java.util.ArrayList;
import java.util.Enumeration;
import java.util.List;

public class BrowserManager {
    private List<Browser> browsers = new ArrayList<>();

    private Enumeration<Browser> instantiateBrowser() throws JMSException {
        Browser browser = new Browser(); // Assuming Browser is a class you have
        browsers.add(browser);
        return new Enumeration<Browser>() {
            private int index = 0;

            @Override
            public boolean hasMoreElements() {
                return index < browsers.size();
            }

            @Override
            public Browser nextElement() {
                return browsers.get(index++);
            }
        };
    }
}

