public int kroneckerSymbol(int a, int p) {
    if (a == 0) {
        return 0; // 0|p = 0 for all p
    } else if (a == 1 || p == 1) {
        return 1; // 1|p and a|1 = 1 for all a and p
    } else if (a == 2 && (p % 8 == 3 || p % 8 == 5)) {
        return -1; // Special case if a=2 and p mod 8 = 3 or 5
    } else if (a >= p) {
        return kroneckerSymbol(a % p, p); // Recurse with a mod p
    } else if (a % 2 == 0) {
        return kroneckerSymbol(2, p) * kroneckerSymbol(a / 2, p); // Property of kronecker symbol
    } else if (a % 4 == 3 && p % 4 == 3) {
        return -kroneckerSymbol(p, a); // Quadratic reciprocity law
    } else {
        return kroneckerSymbol(p, a % p); // Recurse with swapped arguments
    }
}

