public static void callRemoteService(List<String> values) throws IOException {
    // Set up the URL and connection
    URL url = new URL("http://example.com/service");
    HttpURLConnection connection = (HttpURLConnection)url.openConnection();
    connection.setRequestMethod("POST");
    connection.setDoOutput(true);

    // Encode the values as a query string
    String data = encodeQueryString(values);

    // Set the content type and length headers
    connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
    connection.setRequestProperty("Content-Length", Integer.toString(data.length()));

    // Write the data to the connection's output stream
    try (OutputStream out = connection.getOutputStream()) {
        out.write(data.getBytes());
    }

    // Check the response code and handle errors if necessary
    int responseCode = connection.getResponseCode();
    if (responseCode != HttpURLConnection.HTTP_OK) {
        throw new IOException("Remote service returned error code " + responseCode);
    }

    // Read and print the response from the service
    try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
        String line;
        while ((line = in.readLine()) != null) {
            System.out.println(line);
        }
    }
}

private static String encodeQueryString(List<String> values) throws UnsupportedEncodingException {
    StringBuilder sb = new StringBuilder();
    for (String value : values) {
        if (sb.length() > 0) {
            sb.append('&');
        }
        sb.append(URLEncoder.encode(value, "UTF-8"));
    }
    return sb.toString();
}

