public static Data load(Reader reader, double sparseRatio, int vectorLength, boolean classification) throws IOException {
    BufferedReader br = new BufferedReader(reader);
    List<double[]> data = new ArrayList<double[]>();
    List<Double> labels = new ArrayList<Double>();
    String line = br.readLine();
    while (line != null) {
        String[] parts = line.split("\\s+");
        double[] vector = new double[vectorLength];
        int label = Integer.parseInt(parts[0]);
        for (int i = 0; i < vectorLength; i++) {
            String[] keyValuePair = parts[i + 1].split(":");
            vector[i] = Double.parseDouble(keyValuePair[1]);
        }
        data.add(vector);
        labels.add((double) label);
        line = br.readLine();
    }
    br.close();
    double[][] dataArray = data.toArray(new double[data.size()][vectorLength]);
    double[] labelArray = new double[labels.size()];
    for (int i = 0; i < labelArray.length; i++) {
        labelArray[i] = labels.get(i);
    }

    if (classification) {
        return new ClassificationData(dataArray, labelArray, sparseRatio);
    } else {
        return new RegressionData(dataArray, labelArray);
    }
}

