import java.util.LinkedList;

public LinkedList<Patch> computePatches(Diff[] diffs) {
    LinkedList<Patch> patches = new LinkedList<>();
    if (diffs.length == 0) {
        return patches;
    }
    Patch patch = new Patch();
    int charCount1 = 0;
    int charCount2 = 0;
    for (Diff diff : diffs) {
        if (patch.getDeltas().isEmpty() && diff.getType() != DiffType.EQUAL) {
            patch.getStart1 = charCount1;
            patch.getStart2 = charCount2;
        }

        if (diff.getType() == DiffType.INSERT) {
            patch.getInserts().add(diff.getText());
            charCount2 += diff.getText().length();
        }

        if (diff.getType() == DiffType.DELETE) {
            patch.getDeletes().add(diff.getText().length());
            charCount1 += diff.getText().length();
        }

        if (diff.getType() == DiffType.EQUAL && patch.getDeltas().size() > 0 && patch.getDeltas().getLast().getType() == DeltaType.CHANGE) {
            patch.addDelta(new Delta(DeltaType.CHANGE, new Range(patch.getStart1, charCount1), new Range(patch.getStart2, charCount2)));
        }
        if (diff.getType() != DiffType.EQUAL && patch.getDeltas().size() > 0 && patch.getDeltas().getLast().getType() != DeltaType.DELETE) {
            patch.addDelta(new Delta(DeltaType.DELETE, new Range(patch.getStart1, charCount1), null));
            patch.addDelta(new Delta(DeltaType.INSERT, null, new Range(patch.getStart2, charCount2)));
        }

        if (diff.getType() != DiffType.EQUAL) {
            patch.setLength1(charCount1);
            patch.setLength2(charCount2);
        }

        if (patch.getDeletes().size() > 0 && patch.getInserts().size() > 0) {
            patch.addDelta(new Delta(DeltaType.CHANGE, new Range(patch.getStart1, patch.getLength1()), new Range(patch.getStart2, patch.getLength2())));
            patch.getDeletes().clear();
            patch.getInserts().clear();
            patch.getStart1 = charCount1;
            patch.getStart2 = charCount2;
        }
        patches.add(patch);
        patch = new Patch();
    }
    return patches;
}

