public static Set<String> getInAppProducts(Context context) throws XmlPullParserException, IOException {
    Set<String> inAppProducts = new HashSet<>();
    AssetManager assets = context.getAssets();
    String[] list = assets.list("");
    boolean found = false;
    for (String file : list) {
        if (file.equals(FortumoStore.IN_APP_PRODUCTS_FILE_NAME)) {
            found = true;
            break;
        }
    }
    if (!found) {
        throw new FileNotFoundException("In-app product file not found in assets folder.");
    }
    InputStream stream = assets.open(FortumoStore.IN_APP_PRODUCTS_FILE_NAME);
    XmlPullParser parser = XmlPullParserFactory.newInstance().newPullParser();
    parser.setInput(stream, null);
    int eventType = parser.getEventType();
    String sku = null;
    while (eventType != XmlPullParser.END_DOCUMENT) {
        String tagName = parser.getName();
        switch (eventType) {
            case XmlPullParser.START_TAG:
                if (tagName.equals("product") || tagName.equals("subscription")) {
                    sku = parser.getAttributeValue(null, "sku");
                }
                break;
            case XmlPullParser.END_TAG:
                if (tagName.equals("product") || tagName.equals("subscription")) {
                    inAppProducts.add(sku);
                    sku = null;
                }
                break;
        }
        eventType = parser.next();
    }
    return inAppProducts;
}

