import com.google.android.material.color.MaterialColors;
import com.google.android.material.resources.MaterialResources;

import org.commonmark.ext.gfm.strikethrough.Strikethrough;
import org.commonmark.node.AbstractVisitor;
import org.commonmark.node.BlockQuote;
import org.commonmark.node.BulletList;
import org.commonmark.node.Code;
import org.commonmark.node.Emphasis;
import org.commonmark.node.FencedCodeBlock;
import org.commonmark.node.HardLineBreak;
import org.commonmark.node.Heading;
import org.commonmark.node.HtmlBlock;
import org.commonmark.node.HtmlInline;
import org.commonmark.node.Image;
import org.commonmark.node.IndentedCodeBlock;
import org.commonmark.node.Link;
import org.commonmark.node.ListBlock;
import org.commonmark.node.ListItem;
import org.commonmark.node.Node;
import org.commonmark.node.OrderedList;
import org.commonmark.node.Paragraph;
import org.commonmark.node.SoftLineBreak;
import org.commonmark.node.StrongEmphasis;
import org.commonmark.node.Text;
import org.commonmark.parser.Parser;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class MarkdownUtils {

    private static final Pattern ESCAPED_CHARACTER = Pattern.compile(
            "\\\\\\p{Alnum}{1}"
    );

    private static final Pattern ANCHOR_WITH_MARKERS = Pattern.compile(
            "\\[(.+)\\]\\((.+)\\)"
    );

    private static final Map<String, String> ENTITIES_MAP;

    static {
        ENTITIES_MAP = new HashMap<>();
        ENTITIES_MAP.put("amp", "&");
        ENTITIES_MAP.put("apos", "'");
        ENTITIES_MAP.put("gt", ">");
        ENTITIES_MAP.put("lt", "<");
        ENTITIES_MAP.put("quot", "\"");
    }

    public static BootstrapText toTextViewMarkdown(@NonNull Context context,
                                                    @NonNull String markdown,
                                                    boolean editMode) {

        final BootstrapText.Builder builder = new BootstrapText.Builder(context);
        final Parser parser = Parser.builder().build();
        final Node parsed = parser.parse(markdown);

        final MarkdownToSpannableVisitor visitor = new MarkdownToSpannableVisitor(context,
                builder, editMode);

        parsed.accept(visitor);

        return builder.build();
    }

    private static class MarkdownToSpannableVisitor extends AbstractVisitor {
        private int listItemCounter = 0;

        private final Context context;
        private final BootstrapText.Builder builder;
        private final boolean editMode;
        private final List<Integer> listIndents;

        public MarkdownToSpannableVisitor(@NonNull Context context,
                                          @NonNull BootstrapText.Builder builder,
                                          boolean editMode) {
            this.context = context;
            this.builder = builder;
            this.editMode = editMode;

            listIndents = new ArrayList<>();
        }

        @Override
        public void visit(Text text) {
            builder.append(text.getLiteral());
        }

        @Override
        public void visit(Emphasis emphasis) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownEmphasisEdit :
                                    R.style.BootstrapTextAppearanceMarkdownEmphasis),
                    () -> true);
            openSpan();
            visitChildren(emphasis);
            closeSpan();
        }

        @Override
        public void visit(StrongEmphasis strongEmphasis) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownStrongEdit :
                                    R.style.BootstrapTextAppearanceMarkdownStrong),
                    () -> true);
            openSpan();
            visitChildren(strongEmphasis);
            closeSpan();
        }

        @Override
        public void visit(Paragraph paragraph) {
            visitChildren(paragraph);
            builder.append("\n");
        }

        @Override
        public void visit(Link link) {
            final String url = link.getDestination();
            builder.setSpan(new ClickableSpan() {
                @Override
                public void onClick(@NonNull View view) {
                    if (!TextUtils.isEmpty(url)) {
                        context.startActivity(new Intent(Intent.ACTION_VIEW,
                                Uri.parse(url)));
                    }
                }
            }, () -> true);
            openSpan();
            visitChildren(link);
            closeSpan();
        }

        @Override
        public void visit(Image image) {
            final String url = image.getDestination();
            if (editMode && TextUtils.isEmpty(url)) {
                builder.append("[image]");
            } else if (url != null) {
                builder.setSpan(new ImageSpan(context, url), () -> true);
            }
        }

        @Override
        public void visit(FencedCodeBlock fencedCodeBlock) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownCodeEdit :
                                    R.style.BootstrapTextAppearanceMarkdownCode),
                    () -> true);

            builder.append(fencedCodeBlock.getLiteral());
        }

        @Override
        public void visit(Code code) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownCodeEdit :
                                    R.style.BootstrapTextAppearanceMarkdownCode),
                    () -> true);

            builder.append(code.getLiteral());
        }

        @Override
        public void visit(BlockQuote blockQuote) {
            builder.setSpan(new TextAppearanceSpan(context,
                            R.style.BootstrapTextAppearanceMarkdownBlockquote),
                    () -> true);
            builder.startBlockQuote();
            visitChildren(blockQuote);
            builder.endBlockQuote();
        }

        @Override
        public void visit(Heading heading) {
            final int fontWeight;
            final int fontSizeResId;

            switch (heading.getLevel()) {
                case 1:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH1;
                    break;
                case 2:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH2;
                    break;
                case 3:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH3;
                    break;
                case 4:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH4;
                    break;
                case 5:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH5;
                    break;
                case 6:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH6;
                    break;
                default:
                    throw new IllegalStateException("Unknown header level: " + heading.getLevel());
            }

            builder.setSpan(new TextAppearanceSpan(context, fontWeight), () -> true);
            builder.setSpan(new TextAppearanceSpan(context, fontSizeResId), () -> true);

            visitChildren(heading);
            builder.append("\n");
        }

        @Override
        public void visit(HardLineBreak hardLineBreak) {
            builder.append("\n");
        }

        @Override
        public void visit(SoftLineBreak softLineBreak) {
            builder.append(" ");
        }

        @Override
        public void visit(IndentedCodeBlock indentedCodeBlock) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownCodeEdit :
                                    R.style.BootstrapTextAppearanceMarkdownCode),
                    () -> true);
            builder.append(indentedCodeBlock.getLiteral());
        }

        @Override
        public void visit(Strikethrough strikethrough) {
            builder.setSpan(new StrikethroughSpan(), () -> true);
            visitChildren(strikethrough);
            closeSpan();
        }

        @Override
        public void visit(BulletList bulletList) {
            final int listItemIndent = listIndents.size() * 2;

            listIndents.add(listItemIndent);

            visitChildren(bulletList);

            listIndents.remove(listIndents.size() - 1);
        }

        @Override
        public void visit(OrderedList orderedList) {
            final int listItemIndent = listIndents.size() * 2;

            listIndents.add(listItemIndent);

            visitChildren(orderedList);

            listIndents.remove(listIndents.size() - 1);
        }

        @Override
        public void visit(ListItem listItem) {
            final int listItemIndent = listIndents.size() * 2;

            final int bulletPointWidth = 4;

            // Add bullet point line:
            for (int i = 0; i < listItemIndent; i++) {
                builder.append(" ");
            }
            if (listItem.getParent() instanceof BulletList) {
                builder.append("\u2022 ");
            } else if (listItem.getParent() instanceof OrderedList) {
                listItemCounter++;
                builder.append(listItemCounter + ". ");
                if (listItem.getPrevious() != null && listItem.getPrevious() instanceof ListItem) {
                    listItemCounter = Integer.parseInt(
                            listItem.getPrevious().getFirstChild().getLiteral()) + 1;
                }
            }

            // Bullet point ends at this position, so that nested lists start on a new line:
            final int bulletPointEndPosition = builder.length();

            visitChildren(listItem);

            // Indent nested list elements:
            final int blockQuoteWitdth = 2;
            for (final Integer listItemIndentation : listIndents) {
                for (int i = 0; i < listItemIndentation + bulletPointWidth +
                        blockQuoteWitdth; i++) {
                    builder.insert(bulletPointEndPosition, " ");
                }
            }

            // Add new line after list item:
            builder.append("\n");
        }

        @Override
        public void visit(HtmlInline htmlInline) {
            final Matcher escapedCharacterMatcher = ESCAPED_CHARACTER.matcher(htmlInline.getLiteral());

            if (htmlInline.getLiteral().equals("&nbsp;")) {
                builder.append(" ");
            } else if (escapedCharacterMatcher.find()) {
                builder.append(escapedCharacterMatcher.group(1));
            }
        }

        @Override
        public void visit(HtmlBlock htmlBlock) {
            // Do nothing.
        }

        @Override
        public void visit(ListBlock listBlock) {
            visitChildren(listBlock);
        }

        public void openSpan() {
            builder.openSpan();
        }

        public void closeSpan() {
            builder.closeSpan();
        }

        public void appendIcon(@NonNull String iconCode) {
            final int iconSize = context.getResources()
                    .getDimensionPixelSize(R.dimen.bootstrap_glyphicons_font_size);
            final float iconBaselineOffset = 0.23f;
            final int iconColor;
            if (editMode) {
                iconColor = MaterialColors.getColor(context, R.attr.colorControlActivated, R.color.bootstrap_glyphicon_default_foreground);
            } else {
                iconColor = MaterialColors.getColor(context, R.attr.colorOnSurface, R.color.bootstrap_glyphicon_default_foreground);
            }
            final int iconBackgroundColor = MaterialColors.getColor(context, android.R.attr.colorTransparent, R.color.bootstrap_glyphicon_background);

            final Typeface glyphiconTypeface = ResourcesCompat.getFont(context, R.font.glyphicon_halflings_regular);
            final int iconCharCode = Integer.parseInt(iconCode, 16);
            final char iconChar = (char) iconCharCode;

            final StaticLayout glyphLayout = new StaticLayout(Character.toString(iconChar), new TextPaint(), iconSize, Layout.Alignment.ALIGN_NORMAL, 1.0f, iconBaselineOffset, false);
            final Bitmap bmp = Bitmap.createBitmap(glyphLayout.getWidth(), glyphLayout.getHeight(), Bitmap.Config.ARGB_8888);
            final Canvas canvas = new Canvas(bmp);
            canvas.drawColor(iconBackgroundColor);

            final int saveCount = canvas.save();
            glyphLayout.draw(canvas);
            canvas.restoreToCount(saveCount);

            final Drawable drawable = new BitmapDrawable(context.getResources(), bmp);
            drawable.setBounds(0, 0, bmp.getWidth(), bmp.getHeight());
            drawable.setColorFilter(iconColor, PorterDuff.Mode.SRC_ATOP);

            final GlobalColorSpan span = new GlobalColorSpan(drawable);

            builder.setSpan(span, () -> true);
        }

        public void resolveHtmlEntity(@NonNull String entityName) {
            final String resolvedEntity = ENTITIES_MAP.get(entityName);

            if (resolvedEntity != null) {
                builder.append(resolvedEntity);
            } else {
                builder.append(String.format("&#x%s;", entityName));
            }
        }

        @Override
        protected void visitChildren(Node parent) {
            Node node = parent.getFirstChild();

            while (node != null) {
                Node next = node.getNext();
                node.accept(this);
                node = next;
            }
        }

        @Override
        public void visit(org.commonmark.node.Text text) {
            builder.append(text.getLiteral());
        }

        @Override
        public void visit(org.commonmark.node.Code code) {
            builder.append("`")
                    .append(code.getLiteral())
                    .append("`");
        }

        @Override
        public void visit(org.commonmark.node.SoftLineBreak softLineBreak) {
            builder.append(" \n");
        }

        @Override
        public void visit(HtmlInline htmlInline) {
            builder.append(htmlInline.getLiteral());
        }

        @Override
        public void visit(HtmlBlock htmlBlock) {
            builder.append(htmlBlock.getLiteral());
        }

        @Override
        public void visit(ThematicBreak thematicBreak) {
            builder.startBlockQuote().append("***").endBlockQuote();
        }

        @Override
        public void visit(org.commonmark.node.Link link) {
            builder.append(" [")
                    .append(link.getTitle() == null ? link.getDestination() : link.getTitle())
                    .append("](");
            openSpan();
            builder.append(link.getDestination());
            closeSpan();
            builder.append(") ");
        }

        @Override
        public void visit(Image image) {
            builder.append(" ![").append(image.getTitle()).append("](");
            openSpan();
            builder.append(image.getDestination());
            closeSpan();
            builder.append(")");
        }

        @Override
        public void visit(org.commonmark.node.Heading heading) {
            builder.append("\n\n");
            switch (heading.getLevel()) {
                case 1:
                    builder.startBlockQuote().append("# ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 2:
                    builder.startBlockQuote().append("## ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 3:
                    builder.startBlockQuote().append("### ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 4:
                    builder.startBlockQuote().append("#### ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 5:
                    builder.startBlockQuote().append("##### ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 6:
                    builder.startBlockQuote().append("###### ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
            }
        }

        @Override
        public void visit(ThematicBreak thematicBreak) {
            builder.startBlockQuote().append("***").endBlockQuote();
        }

        @Override
        public void visit(org.commonmark.node.BlockQuote blockQuote) {
            builder.startBlockQuote().append("> ");
            visitChildren(blockQuote);
            builder.endBlockQuote();
        }

        @Override
        public void visit(org.commonmark.node.BulletList bulletList) {
            final List<ListItem> listItems = bulletList.getMutableChildren();
            final int numListItems = listItems.size();
            final Integer[] indents = Arrays.copyOf(listIndents.toArray(new Integer[0]), listIndents.size(), Integer[].class);

            for (int i = 0; i < numListItems; i++) {
                if (i > 0) {
                    indentNewItem(indents, true);
                }
                visit(listItems.get(i));
                if (i < (numListItems - 1)) {
                    builder.append("\n");
                }
            }
        }

        @Override
        public void visit(org.commonmark.node.OrderedList orderedList) {
            final List<ListItem> listItems = orderedList.getMutableChildren();
            final boolean isOrdered = true;
            final int numListItems = listItems.size();
            final Integer[] indents = Arrays.copyOf(listIndents.toArray(new Integer[0]), listIndents.size(), Integer[].class);

            for (int i = 0; i < numListItems; i++) {
                if (i > 0) {
                    indentNewItem(indents, false);
                }
                final String listItemMarker = orderedList.getDelimiter().toString() + " ";
                visitChildren(new ListItem(Arrays.asList(new Text(listItemMarker)), orderedList.getBulletMarker(), null));
                visit(listItems.get(i));
                if (i < (numListItems - 1)) {
                    builder.append("\n");
                }
            }
        }

        private void indentNewItem(@NonNull Integer[] indents, boolean createBullet) {
            // the standard is four spaces, but that may depend on font prefs
            int listIndent = indents.length * 4;
            // create the bullet point
            if (createBullet) {
                builder.append("> ");
                listIndent += 2;
            }
            // add indentation for list nesting
            for (int i = 0; i < indents.length; i++) {
                listIndent += indents[i];
            }
            builder.append(Strings.repeat(' ', listIndent));
        }
    }
}

