    List<FieldSchema> columns = hiveTable.getCols();
    for (FieldSchema column : columns) {
        Referenceable columnInstance = new Referenceable("hive_column");
        columnInstance.set("name", column.getName());
        columnInstance.set("description", column.getComment());
        columnInstance.set("type", column.getType());
