import org.nd4j.linalg.api.ndarray.INDArray;
import org.nd4j.linalg.factory.Nd4j;

public INDArray maxPool3d(String name, INDArray inputs, int[] pooling3DConfig) {
    int kT = pooling3DConfig[0]; // Kernel size of the time dimension
    int kW = pooling3DConfig[1]; // Kernel size of the width dimension
    int kH = pooling3DConfig[2]; // Kernel size of the height dimension
    int dT = pooling3DConfig[3]; // Stride of the time dimension
    int dW = pooling3DConfig[4]; // Stride of the width dimension
    int dH = pooling3DConfig[5]; // Stride of the height dimension
    int pT = pooling3DConfig[6]; // Padding of the time dimension
    int pW = pooling3DConfig[7]; // Padding of the width dimension
    int pH = pooling3DConfig[8]; // Padding of the height dimension

    int[] inShape = inputs.shape();
    int n = inShape[0];
    int c = inShape[1];
    int inT = inShape[2];
    int inH = inShape[3];
    int inW = inShape[4];
    int outT = (inT - kT + 2*pT) / dT + 1;
    int outH = (inH - kH + 2*pH) / dH + 1;
    int outW = (inW - kW + 2*pW) / dW + 1;

    INDArray output = Nd4j.create(n, c, outT, outH, outW);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < c; j++) {
            for (int t = 0; t < outT; t++) {
                for (int h = 0; h < outH; h++) {
                    for (int w = 0; w < outW; w++) {
                        int ttStart = t * dT - pT;
                        int hhStart = h * dH - pH;
                        int wwStart = w * dW - pW;

                        double maxVal = Double.MIN_VALUE;
                        for (int tt = ttStart; tt < ttStart + kT; tt++) {
                            for (int hh = hhStart; hh < hhStart + kH; hh++) {
                                for (int ww = wwStart; ww < wwStart + kW; ww++) {
                                    if (tt >= 0 && hh >= 0 && ww >= 0 && 
                                        tt < inT && hh < inH && ww < inW) {
                                        double val = inputs.getDouble(i, j, tt, hh, ww);
                                        maxVal = Math.max(maxVal, val);
                                    }
                                }
                            }
                        }

                        output.putScalar(i, j, t, h, w, maxVal);
                    }
                }
            }
        }
    }

    return output;
}

