public List<Sgroup> findEnabledAbbreviations(Molecule mol) {
    List<Sgroup> abbreviations = new ArrayList<>();
    for (Atom atom : mol.atoms()) {
        Map<Integer, Bond> bonds = atom.bonds();
        for (Map.Entry<Integer, Bond> entry : bonds.entrySet()) {
            int bondIndex = entry.getKey();
            Bond bond = entry.getValue();
            if (bond.type() == BondType.SINGLE && bond.stereo() == BondStereo.NONE
                    && bond.topology() != BondTopology.RING) {
                Sgroup abbreviation = new Sgroup(SgroupType.ABBREVIATION);
                abbreviation.setAtoms(Arrays.asList(atom));
                abbreviation.setBonds(Arrays.asList(bondIndex));
                abbreviations.add(abbreviation);
            }
        }
    }
    return abbreviations;
}

