import java.util.ArrayList;
import java.util.List;

public class Diff {

    public static List<DiffBase> computeDiff(String text1, String delta) {

        if (text1 == null || delta == null) {
            throw new IllegalArgumentException("Input cannot be null");
        }

        List<DiffBase> diffs = new ArrayList<>();
        int start = 0;

        String[] tokens = delta.split(";");
        for (String token : tokens) {
            if (token.length() == 0) {
                continue;
            }

            char operation = token.charAt(0);
            String value = token.substring(1);

            switch (operation) {
                case '+':
                    diffs.add(new DiffAdd(start, value));
                    start += value.length();
                    break;
                case '-':
                    diffs.add(new DiffDelete(start, value.length()));
                    break;
                case '=':
                    int length = Integer.parseInt(value);
                    start += length;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid operation: " + operation);
            }
        }

        return diffs;
    }
}

abstract class DiffBase {

    private int start;

    public DiffBase(int start) {
        this.start = start;
    }

    public int getStart() {
        return start;
    }

    public abstract int getLength();
}


class DiffAdd extends DiffBase {

    private String value;

    public DiffAdd(int start, String value) {
        super(start);
        this.value = value;
    }

    public String getValue() {
        return value;
    }

    public int getLength() {
        return value.length();
    }
}


class DiffDelete extends DiffBase {

    private int length;

    public DiffDelete(int start, int length) {
        super(start);
        this.length = length;
    }

    public int getLength() {
        return length;
    }
}

