import java.io.File;
import java.io.IOException;
import java.net.URISyntaxException;
import java.net.URL;
import java.util.HashSet;
import java.util.Set;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;

public class ClassPathScanner {

    public static Set<String> scanClassPath(String classPath, Set<String> excludeJarSet) throws IOException, URISyntaxException {

        Set<String> packagePaths = new HashSet<>();
        String[] pathElements = classPath.split(System.getProperty("path.separator"));
        for (String pathElement : pathElements) {

            File pathElementFile = new File(pathElement);
            if (pathElementFile.isDirectory()) {
                collectPackagePathsFromDirectory(packagePaths, pathElementFile, "");
            } else {
                collectPackagePathsFromJar(packagePaths, pathElementFile, excludeJarSet);
            }
        }
        return packagePaths;
    }

    private static void collectPackagePathsFromDirectory(Set<String> packagePaths, File directory, String currentPath) {
        File[] fileList = directory.listFiles();
        if (fileList != null) {
            for (File file : fileList) {
                if (file.isDirectory()) {
                    collectPackagePathsFromDirectory(packagePaths, file, currentPath + file.getName() + "/");
                } else if (file.getName().endsWith(".class")) {
                    String packageName = currentPath.replaceAll("/", ".");
                    packageName = packageName.substring(0, packageName.length() - 1);
                    packagePaths.add(packageName);
                }
            }
        }
    }

    private static void collectPackagePathsFromJar(Set<String> packagePaths, File file, Set<String> excludeJarSet) throws IOException {
        try (JarFile jarFile = new JarFile(file)) {
            for (JarEntry jarEntry : Collections.list(jarFile.entries())) {
                if (jarEntry.isDirectory()) {
                    continue;
                }
                String packageName = getPackageName(jarEntry.getName());
                if (!excludeJarSet.contains(file.getName()) && packageName != null) {
                    packagePaths.add(packageName);
                }
            }
        }
    }

    private static String getPackageName(String entryName) {
        if (!entryName.endsWith(".class")) {
            return null;
        }
        String packageName = entryName.substring(0, entryName.lastIndexOf("/"));
        if (packageName.startsWith("/") || packageName.endsWith("/")) {
            return null;
        }
        packageName = packageName.replaceAll("/", ".");
        return packageName;
    }
}

