        W3.data[i*9+1] = triple.p1.y * triple.p2.x;
        W3.data[i*9+2] = triple.p2.x;
        W3.data[i*9+3] = triple.p1.x * triple.p2.y;
        W3.data[i*9+4] = triple.p1.y * triple.p2.y;
        W3.data[i*9+5] = triple.p2.y;
        W3.data[i*9+6] = triple.p1.x;
        W3.data[i*9+7] = triple.p1.y;
        W3.data[i*9+8] = 1;
    }

    // Compute the smallest singular value decomposition of each W matrix
    SimpleMatrix w1 = SimpleMatrix.wrap(W1);
    SimpleMatrix w2 = SimpleMatrix.wrap(W2);
    SimpleMatrix w3 = SimpleMatrix.wrap(W3);

