    CommonOps_DDRM.svd(W2.data, numPts, 9, null, true, true, U2.getDDRM(), D2.getDDRM(), V2.getDDRM());
    CommonOps_DDRM.svd(W3.data, numPts, 9, null, true, true, U3.getDDRM(), D3.getDDRM(), V3.getDDRM());

    int rank = 9;

