private static void applyFundamental(DMatrixRMaj F,
                                      Point2D_F64 a, Point2D_F64 b, DMatrixRMaj g )
{
    double x = a.x;
    double y = a.y;
    double x1 = b.x;
    double y1 = b.y;

    g.data[0] = x * x1;
    g.data[1] = y * x1;
    g.data[2] = x1;
    g.data[3] = x * y1;
