    tau.data[1] = F.get(1,0)*x + F.get(1,1)* y  + F.get(1,2);
    tau.data[2] = F.get(2,0)*x + F.get(2,1)* y  + F.get(2,2);

    tau.data[3] = F.get(0,0)*x1 + F.get(0,1)*y1 + F.get(0,2)*x2 +
