public static Tag internCustomTagTypes(Tag tag) {
    if(tag instanceof BasicTag) {
        return tag;
    }
    if(tag instanceof StringTag) {
        return Tag.of(tag.getKey(), ((StringTag) tag).getValue());
    }
    if(tag instanceof IntTag) {
        return Tag.of(tag.getKey(), ((IntTag) tag).getIntValue());
    }
    if(tag instanceof LongTag) {
        return Tag.of(tag.getKey(), ((LongTag) tag).getLongValue());
    }
    if(tag instanceof DoubleTag) {
        return Tag.of(tag.getKey(), ((DoubleTag) tag).getDoubleValue());
    }
    if(tag instanceof FloatTag) {
        return Tag.of(tag.getKey(), ((FloatTag) tag).getFloatValue());
    }
    if(tag instanceof ListTag) {
        ListTag newListTag = new ListTag(tag.getKey());
        for(Tag t : ((ListTag)tag)) {
            newListTag.add(internCustomTagTypes(t));
        }
        return newListTag;
    }
    if(tag instanceof CompoundTag) {
        CompoundTag newCompoundTag = new CompoundTag(tag.getKey());
        for(Tag t : ((CompoundTag)tag).getAllTags()) {
            newCompoundTag.put(internCustomTagTypes(t));
        }
        return newCompoundTag;
    }
    return tag;
}

