private boolean hasNextLazy() {
	// Check if there are more elements to process
    if (currentElementIndex < elements.size()) {
        // Check if the current element meets the condition
        if (condition.test(elements.get(currentElementIndex))) {
            return true;
        } else {
            // Move to the next element and check again
            currentElementIndex++;
            return hasNextLazy();
        }
    }
    // No more elements to process
    return false;
}

private T nextLazy() {
    if (!hasNextLazy()) {
        throw new NoSuchElementException("No more elements that meet the condition");
    }
    // Return the current element and move to the next
    T element = elements.get(currentElementIndex);
    currentElementIndex++;
    return element;
}

