              }
              if (isDebugLogging ())
                if (LOGGER.isDebugEnabled ())
                  LOGGER.debug ("Trying to recover object [" + i + "] with " + sElement.length () + " chars");
              switch (eActionType)
              {
                case CREATE:
                  try
