                    ref--;

                    output[outOffset + op++] = output[outOffset + ref++];
                    output[outOffset + op++] = output[outOffset + ref++];
                    output[outOffset + op++] = output[outOffset + ref++];
                    while (len != 0) {
                        output[outOffset + op++] = output[outOffset + ref++];
