	// Initialize the starting offset for the raster data
    int soff = hoff + hedsiz;

    // Write the packet code to the buffer
    bos.putShort(pkcode);

    // Write the header size to the buffer
    bos.putShort((short) hedsiz);

    // Write the horizontal offset to the buffer
    bos.putInt(hoff);

    // Write the flag indicating if the data includes Z values
    bos.put((byte) (isZ ? 1 : 0));

    // Write the raster data to the buffer
    bos.put(data);

    // Return the starting offset for the raster data
    return soff;
}

