                operations.add(ContentProviderOperation.newDelete(contentUri)
                        .withSelection(BaseColumns._ID + " != ?", new String[1])
                        .withSelectionBackReference(0, 0)
                        .build());
                try {
                    ContentProviderResult[] results = contentResolver.applyBatch(
