public static String deduceSurtPrefix(String u) {
    if(u == null) return null;

    URL url;
    String host = "";
    String path = "";

    try {
        url = new URL(u);
        host = url.getHost();
        path = url.getPath();
    } catch (MalformedURLException e) {
        // not a valid URL, try to parse as a hostname/hostname+path
        int index = u.indexOf("/");
        if(index > 0) {
            host = u.substring(0, index);
            path = u.substring(index);
        } else {
            host = u;
        }
    }

    // ignore default port in the host
    if(host.contains(":")) {
        String[] parts = host.split(":");
        if(parts.length == 2) {
            try {
                int port = Integer.parseInt(parts[1]);
                if((url != null && url.getPort() != port) || (url == null && port != 80)) {
                    host = parts[0];
                }
            } catch (NumberFormatException e) {
                // ignore and use the original host
            }
        }
    }

    // remove www prefix from the host
    if(host.toLowerCase().startsWith("www.")) {
        host = host.substring(4);
    }

    // remove https protocol prefix from path
    if(url != null && "https".equalsIgnoreCase(url.getProtocol())) {
        path = path.replaceFirst("^/+", "");
    }

    // fix up the URI
    u = "http://" + host + path;
    u = UURIFixer.fix(u, UURIFixer.INFER_HTTP);

    // create the SURT prefix
    String surt = host.startsWith("(") ? host : "(" + host + ")";
    surt += path.isEmpty() ? "/" : path.replaceAll("/+", "/");
    surt = surt.replaceAll("\\)", ")\\)");

    return surt;
}

