import org.apache.bcel.*;
import org.apache.bcel.classfile.*;
import org.apache.bcel.generic.*;
import java.util.*;

public void addCopyBridgeMethods(File cf, Class<?> leaf) throws IOException {
  JavaClass javaClass = Repository.lookupClass(leaf);
  List<JavaClass> classChain = getClassChain(javaClass);
  ConstantPoolGen cpg = new ConstantPoolGen(javaClass.getConstantPool());
  for(int i = 1; i < classChain.size(); i++) {
    JavaClass superClass = classChain.get(i-1);
    JavaClass subClass = classChain.get(i);
    if(superClass.isInterface()) {
      addCopyBridgeMethodsForInterface(cf, superClass, subClass, cpg);
    } else {
      addCopyBridgeMethodsForClass(cf, superClass, subClass, cpg);
    }
  }
  Repository.saveClass(javaClass);
}

private List<JavaClass> getClassChain(JavaClass javaClass) {
   List<JavaClass> classChain = new ArrayList<JavaClass>();
   classChain.add(javaClass);
   while(javaClass.getSuperclassName() != null) {
      javaClass = javaClass.getSuperClass();
      classChain.add(javaClass);
   }
   return classChain;
}

private void addCopyBridgeMethodsForInterface(File cf, JavaClass superClass, JavaClass subClass, ConstantPoolGen cpg) throws IOException {
   ClassGen superClassGen = new ClassGen(superClass);
   ClassGen subClassGen = new ClassGen(subClass);
   for(Method method : superClass.getMethods()) {
      if(!method.isAbstract()) {
         continue;
      }
      int accessFlags = method.getAccessFlags();
      accessFlags &= ~(AccessFlags.ABSTRACT | AccessFlags.STATIC | AccessFlags.NATIVE | AccessFlags.FINAL);
      MethodGen mg = new MethodGen(method, superClass.getClassName(), cpg);
      mg.setAccessFlags(accessFlags);
      mg.setName(method.getName() + "$copy");
      InstructionList il = mg.getInstructionList();
      il.append(new RETURN());
      mg.setMaxLocals();
      mg.setMaxStack();
      subClassGen.addMethod(mg.getMethod());
   }
   subClassGen.getJavaClass().dump(cf);
}

private void addCopyBridgeMethodsForClass(File cf, JavaClass superClass, JavaClass subClass, ConstantPoolGen cpg) throws IOException {
   ClassGen superClassGen = new ClassGen(superClass);
   ClassGen subClassGen = new ClassGen(subClass);
   Map<String, Type> typeArgs = new HashMap<>();
   JavaType[] superTypeArgs = superClass.getGenericTypes();
   JavaType[] subTypeArgs = subClass.getGenericTypes();
   for(int i = 0; i < superTypeArgs.length && i < subTypeArgs.length; i++) {
      String typeArgName = superClass.getConstantPool().constantToString(superTypeArgs[i].getSignatureIndex());
      Type argType = subTypeArgs[i];
      typeArgs.put(typeArgName, argType);
   }
   for(Method method : superClass.getMethods()) {
      if(!method.isPublic() || method.isFinal() || method.isStatic() || method.isPrivate()) {
         continue;
      }
      MethodGen subsMg = subClassGen.containsMethod(method.getName(), method.getSignature());
      if(subsMg != null) {
         continue;
      }
      int accessFlags = method.getAccessFlags();
      Type returnType = TypeUtils.translate(cpg, method.getReturnType(), typeArgs); // Returns the translated return type, putting any Strings with a period to the front of the type param list.
      accessFlags &= ~(AccessFlags.FINAL | AccessFlags.PROTECTED | AccessFlags.ABSTRACT | AccessFlags.NATIVE | AccessFlags.SYNCHRONIZED | AccessFlags.STRICT);
      accessFlags |= AccessFlags.PUBLIC | AccessFlags.BRIDGE;
      MethodGen mg = new MethodGen(method, superClass.getClassName(), cpg);
      mg.setAccessFlags(accessFlags);
      mg.setName(method.getName() + "$copy");
      mg.setReturnType(returnType);
      InstructionList il = new InstructionList();
      il.append(new ALOAD(0));
      Type[] argTypes = TypeUtils.translate(cpg, method.getArgumentTypes(), typeArgs);
      StringBuilder descriptor = new StringBuilder("(");
      for(int i = 0; i < argTypes.length; i++) {
         descriptor.append(argTypes[i].getSignature());
         il.append(new ALOAD(i + 1));
         Type srcType = method.getArgumentTypes()[i];
         Type destType = argTypes[i];
         if(srcType.equals(Type.OBJECT) && destType.equals(Type.OBJECT)) {
            il.append(new CHECKCAST(cpg.addClass(srcType.getClassName())));
         } else {
            il.append(new CHECKCAST(cpg.addClass(TypeUtils.getPackageName(destType.getClassName()) + ".Bridge")));
            if(TypeUtils.getPackageName(srcType.getClassName()).equals(TypeUtils.getPackageName(destType.getClassName()))) {
               il.append(InstructionFactory.createDup(srcType.getSize()));
               if(srcType instanceof ObjectType) {
                  il.append(new CHECKCAST(cpg.addClass(srcType.getClassName())));
               } else {
                  il.append(new CHECKCAST(cpg.addClass(TypeUtils.getPackageName(srcType.getClassName()) + ".Bridge")));
                  il.append(new GETFIELD(cpg.addFieldref(TypeUtils.getPackageName(srcType.getClassName()) + ".Bridge", "src", srcType.getSignature())));
                  il.append(InstructionFactory.createDup());
                  il.append(InstructionFactory.createDup());
                  il.append(new GETFIELD(cpg.addFieldref(TypeUtils.getPackageName(destType.getClassName()) + ".Bridge", "dest", destType.getSignature())));
                  il.append(new CHECKCAST(cpg.addClass(destType.getClassName())));
               }
            } else {
               il.append(new InvokeInstruction(cpg.addMethodref(TypeUtils.getPackageName(destType.getClassName()) + ".Bridge", TypeUtils.getTranslateMethodName(srcType), TypeUtils.getTranslateMethodSig(srcType, destType)), 1));
            }
         }
      }
      descriptor.append(')').append(returnType.getSignature());
      il.append(new INVOKEVIRTUAL(cpg.addMethodref(subClass.getClassName(), method.getName(), descriptor.toString())));
      il.append(InstructionFactory.createReturn(returnType));
      mg.setInstructionList(il);
      mg.setMaxLocals();
      mg.setMaxStack();
      subClassGen.addMethod(mg.getMethod());
   }
   subClassGen.getJavaClass().dump(cf);
}

