import com.google.common.annotations.VisibleForTesting;
import org.apache.cassandra.concurrent.TPC;
import org.apache.cassandra.config.DatabaseDescriptor;
import org.apache.cassandra.db.ColumnFamilyStore;
import org.apache.cassandra.db.Directories;
import org.apache.cassandra.utils.FBUtilities;
import org.apache.cassandra.utils.JVMStabilityInspector;
import org.apache.cassandra.utils.concurrent.SimpleCondition;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.annotation.Nullable;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;

import static java.lang.Math.max;

public class CompactionRateLimiter {
    private static final Logger logger = LoggerFactory.getLogger(CompactionRateLimiter.class);
    private static final Supplier<Long> NANO_TIME_SUPPLIER = System::nanoTime;
    private static final ThreadLocal<Boolean> ALLOW_PAUSES = ThreadLocal.withInitial(() -> true);

    private final ColumnFamilyStore cfs;
    private final Directories directories;
    private final int minThroughput;
    private final int maxThroughput;
    private final AtomicReference<RateLimiter> rateLimiterRef;
    private final SimpleCondition rateLimiterChanged;
    private final SimpleCondition pauseRequested;
    private final SimpleCondition paused;
    private final SimpleCondition resumeRequested;
    private final SimpleCondition resumed;

    enum State {
        RUNNING, PAUSED_REQUESTED, PAUSED, RESUME_REQUESTED
    }

    private volatile State state = State.RUNNING;

    /**
     * @param cfs ColumnFamilyStore for which rate limiter is created
     * @param directories Directories associated with the column family store
     * @param minThroughput Compaction minimum throughput in MB/sec. 0 denotes no minimum.
     * @param maxThroughput Compaction maximum throughput in MB/sec. 0 denotes no maximum.
     */
    CompactionRateLimiter(ColumnFamilyStore cfs, Directories directories, int minThroughput, int maxThroughput) {
        this.cfs = cfs;
        this.directories = directories;
        this.minThroughput = minThroughput;
        this.maxThroughput = maxThroughput;
        this.rateLimiterRef = new AtomicReference<>(RateLimiter.create(Double.MAX_VALUE));
        this.rateLimiterChanged = new SimpleCondition();
        this.pauseRequested = new SimpleCondition();
        this.paused = new SimpleCondition();
        this.resumeRequested = new SimpleCondition();
        this.resumed = new SimpleCondition();
    }

    /**
     * Initializes the rate limiter. Spawns a daemon thread which adjusts the rate limiter limit
     * every DatabaseDescriptor.getCompactionRateLimiterUpdateIntervalInMs() milliseconds.
     */
    void initialize() {
        if (DatabaseDescriptor.getCompactionThroughputMbPerSec() == 0 || cfs.isBootstrapping()) {
            return;
        }
        Thread updateThread = new Thread(this::rateLimit);
        updateThread.setName("CompactionRateLimiter");
        updateThread.setDaemon(true);
        updateThread.start();
    }

    /**
     * Returns current rate limiter associated with CompactionRateLimiter instance.
     * Might return RateLimiter with positive infinite rate.
     */
    public RateLimiter get() {
        return rateLimiterRef.get();
    }

    /**
     * Signal that compaction is started.
     * This method is blocking and should be called in a synchronous way, previous call must have returned.
     * Switches to PAUSED_REQUESTED state if limit is reached.
     */
    public void start() {
        if (state == State.RUNNING && rateLimiterRef.get().tryAcquire()) {
            return;
        }
        while (true) {
            double nextSleep = tryPause();
            if (nextSleep == 0) return;
            await(nextSleep, pauseRequested, paused);
            if (state != State.RUNNING) {
                logger.debug("Compaction pausing");
                state = State.PAUSED;
                rateLimiterRef.get().setRate(0);
                break;
            }
        }
    }

    /**
     * Signal that compaction is over.
     * Updates the rate limiter with the actual performed throughput (in bytes).
     * Switches back to RUNNING state.
     *
     * @param throughputBytesPerSecond actual performed throughput (in bytes).
     */
    public void finish(long throughputBytesPerSecond) {
        double MBps = FBUtilities.convertBytesToMB(throughputBytesPerSecond);
        rateLimiterRef.get().setRate(max(1, maxThroughput == 0 ? Double.MAX_VALUE : MBps * 1024 * 1024));
        unblockPauseResume();
    }

    /**
     * Signal that compaction is aborted due to an exception.
     * Switches back to RUNNING state.
     * Clear the current limiter to avoid rate computation based on a small elapsed time in the next iterations.
     */
    public void abort() {
        state = State.RUNNING;
        rateLimiterRef.set(RateLimiter.create(Double.MAX_VALUE));
        unblockPauseResume();
    }

    /**
     * Signal that compaction must be paused before next start() call.
     * This is a request which may not be granted immediately if some rate is still available.
     * Note: the pause can still be canceled after returning from this function.
     * @param durationMs time to pause
     * @return true if the pause was granted immediately, false otherwise.
     */
    public boolean requestPause(long durationMs) {
        if (state != State.RUNNING) return true;
        double nextSleep = tryPause();
        if (nextSleep == 0) {
            doPause(durationMs);
            return true;
        } else {
            await(nextSleep, pauseRequested, paused);
            if (state != State.RUNNING) return true;
        }
        return doPause(durationMs);
    }

    /**
     * Cancel any pause request.
     */
    public void cancelPauseRequest() {
        state = State.RUNNING;
        rateLimiterChanged.signalAll();
    }

    /**
     * Releases the rate limiter limit, allowing other compactions to proceed.
     */
    public void resume() {
        synchronized (rateLimiterRef) {
            state = State.RESUME_REQUESTED;
            paused.signalAll();
            await(0, resumeRequested, resumed);
            state = State.RUNNING;
            rateLimiterRef.get().setRate(Double.MAX_VALUE);
            rateLimiterChanged.signalAll();
        }
    }

    /**
     * Waits for the rate limiter to reach the target rate.
     */
    void waitForTarget() {
        if (cfs.getCompactionThroughput() == 0 || cfs.isBootstrapping()) {
            return;
        }
        long startNanos = NANO_TIME_SUPPLIER.get();
        double maxRate = cfs.getCompactionThroughput() * 1024 * 1024;
        RateLimiter rateLimiter = rateLimiterRef.get();
        while (state == State.RUNNING) {
            double sleepTimeMs = rateLimiter.acquire(1) * 1000;
            if (sleepTimeMs == 0) {
                return;
            }
            long elapsedNanos = NANO_TIME_SUPPLIER.get() - startNanos;
            double elapsedSeconds = max(elapsedNanos, 1) / 1000000000d;
            double actualRate = cfs.getRecentCompactionThroughput() / elapsedSeconds;
            if (actualRate > maxRate) {
                pause();
                rateLimiter.setRate(actualRate);
                startNanos = NANO_TIME_SUPPLIER.get();
            }
        }
    }

    private void rateLimit() {
        final RateLimiter rateLimiter = rateLimiterRef.get();
        final double epsilon = 0.0001d; // within 0.01%
        while (state == State.RUNNING) {
            double newRate = ACQUIRE_DELAY / (double) bandwidthInBytesPerSecond();
            if (rateLimiter.getRate() - newRate > epsilon) {
                rateLimiter.setRate(newRate);
                rateLimiterChanged.signalAll();
            }
            try {
                TimeUnit.MILLISECONDS.sleep(DatabaseDescriptor.getCompactionRateLimiterUpdateIntervalInMs());
            } catch (InterruptedException e) {
                JVMStabilityInspector.inspectThrowable(e);
            }
        }
    }

    private double tryPause() {
        synchronized (rateLimiterRef) {
            while (rateLimiterRef.get().getRate() > 0 && state != State.PAUSED_REQUESTED && state != State.PAUSED) {
                if (rateLimiterRef.get().tryAcquire()) {
                    return 0; // can pause immediately if there is no rate to claim
                }
                long startNanos = NANO_TIME_SUPPLIER.get();
                if (await(10, rateLimiterChanged)) { // could not claim rate on first try
                    continue;
                }
                long elapsedNanos = NANO_TIME_SUPPLIER.get() - startNanos;
                double elapsedSeconds = max(elapsedNanos, 1) / 1000000000d;
                double localBandwidth = bandwidthInBytesPerSecond();
                double newRate = max(0, rateLimiterRef.get().getRate() - localBandwidth * elapsedSeconds);
                rateLimiterRef.get().setRate(newRate);
                rateLimiterChanged.signalAll();
                return ACQUIRE_DELAY / localBandwidth;
            }
            return 0;
        }
    }

    private boolean doPause(long durationMs) {
        synchronized (rateLimiterRef) {
            state = State.PAUSED_REQUESTED;
            if (rateLimiterRef.get().tryAcquire()) {
                state = State.PAUSED;
                rateLimiterRef.get().setRate(0);
                return true;
            } else {
                rateLimiterChanged.signalAll();
                await(durationMs, pauseRequested, paused);
                if (state != State.RUNNING) return true;
                state = State.PAUSED;
                rateLimiterRef.get().setRate(0);
                return true;
            }
        }
    }

    @VisibleForTesting
    void setLimit(double limit) {
        rateLimiterRef.set(RateLimiter.create(limit));
    }

    private void unblockPauseResume() {
        synchronized (rateLimiterRef) {
            rateLimiterChanged.signalAll();
            resumed.signalAll();
            pauseRequested.signalAll();
        }
    }

    private void pause() {
        synchronized (rateLimiterRef) {
            rateLimiterRef.get().setRate(0);
            state = State.PAUSED;
        }
    }

    private double bandwidthInBytesPerSecond() {
        int active = TPC.getNumCores();
        int totalDirectories = directories.size();
        int bufferSizeBytes = DatabaseDescriptor.getCompactionLargePartitionWarningThreshold() * 1024 * 1024;
        if (cfs.metadata.params.compaction.splitRowThreshold() > bufferSizeBytes) {
            bufferSizeBytes = (int)cfs.metadata.params.compaction.splitRowThreshold();
        }
        long totalBytesPerSecond = maxThroughput == 0 ? Long.MAX_VALUE : maxThroughput * 1024 * 1024;
        int concurrentCompactors = cfs.getCompactionStrategyManager().getActiveCompactions();
        if (concurrentCompactors == 0) {
            logger.warn("No active compactions for {}.{} ?", cfs.keyspace.getName(), cfs.getTableName());
        }
        return max(
                minThroughput * 1024 * 1024,
                // disks could be heterogeneous, calculate each one and sum up
                directories.getWriteableLocations()
                        .parallelStream()
                        .mapToLong(d -> d.getEstimatedRemainingSpace() / active)
                        .filter(sz -> sz > 0)
                        .map(sz -> (long)(sz / (double)totalDirectories))
                        .map(bps -> bps / concurrentCompactors)
                        .max()
                        .orElse(0),
                totalBytesPerSecond / (double)concurrentCompactors);
    }

    private boolean await(double durationMs, SimpleCondition... conds) {
        ALLOW_PAUSES.set(false);
        try {
            return SimpleCondition.await(FBUtilities.waitingFor(DebuggableThreadPoolExecutor.awaitingMessage("Compaction rate limiter"), durationMs, TimeUnit.MILLISECONDS), conds);
        } finally {
            ALLOW_PAUSES.set(true);
        }
    }
}

