import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

public class RateLimiter {
    private final Semaphore semaphore;
    private final int maxPermits;
    private final int rate;
    private final TimeUnit timeUnit;

    public RateLimiter(int maxPermits, int rate, TimeUnit timeUnit) {
        this.semaphore = new Semaphore(maxPermits, true);
        this.maxPermits = maxPermits;
        this.rate = rate;
        this.timeUnit = timeUnit;
    }

    public void acquire() throws InterruptedException {
        semaphore.acquire();
    }

    public void release() {
        if (semaphore.availablePermits() < maxPermits) {
            semaphore.release();
        }
    }

    public void setRate(int rate) {
        int permitsToRelease = maxPermits - semaphore.availablePermits();
        for (int i = 0; i < permitsToRelease; i++) {
            semaphore.release();
        }
    }

    public int getRate() {
        return rate;
    }

    public TimeUnit getTimeUnit() {
        return timeUnit;
    }
}

