public Group replaceGroup(String id, Group group, AccessToken accessToken) throws IOException {
    URL url = new URL(endpoint + "/Groups/" + id);
    Gson gson = new GsonBuilder().create();
    String json = gson.toJson(group);

    HttpURLConnection connection = (HttpURLConnection) url.openConnection();
    connection.setDoOutput(true);
    connection.setRequestMethod("PUT");
    connection.setRequestProperty("Content-Type", "application/json");
    connection.setRequestProperty("Authorization", "Bearer " + accessToken.getToken());

    OutputStream outputStream = connection.getOutputStream();
    outputStream.write(json.getBytes());

    int responseCode = connection.getResponseCode();
    if (responseCode == HttpURLConnection.HTTP_OK) {
        InputStream inputStream = connection.getInputStream();
        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(inputStream));
        Group updatedGroup = gson.fromJson(bufferedReader, Group.class);

        outputStream.close();
        bufferedReader.close();
        connection.disconnect();

        return updatedGroup;
    } else if (responseCode == HttpURLConnection.HTTP_UNAUTHORIZED || responseCode == HttpURLConnection.HTTP_FORBIDDEN) {
        throw new UnauthorizedAccessException("Unable to update group. Access token is invalid or not authorized to perform the operation.");
    } else {
        throw new IOException("Unable to update group. Server returned HTTP response code: " + responseCode);
    }
}

