public Pair findNearestItems(ItemDistance itemDist) {
  // initialize variables to hold the nearest items
  Object nearestItem1 = null;
  Object nearestItem2 = null;
  double minDistance = Double.POSITIVE_INFINITY;

  // create a stack to hold the nodes to visit
  Stack stack = new Stack();
  stack.push(this);

  while (!stack.isEmpty()) {
    STRNode node = (STRNode) stack.pop();

    // if the node is a leaf, compare its items with the current nearest items
    if (node.isLeaf()) {
      for (int i = 0; i < node.size(); i++) {
        Object currentItem = node.getItem(i);

        for (int j = i + 1; j < node.size(); j++) {
          Object otherItem = node.getItem(j);

          double distance = itemDist.distance(currentItem, otherItem);

          if (distance < minDistance) {
            minDistance = distance;
            nearestItem1 = currentItem;
            nearestItem2 = otherItem;
          }
        }
      }
    }
    // if the node is not a leaf, calculate the distance to the node's children
    else {
      STRNode left = node.getLeft();
      STRNode right = node.getRight();

      double leftDistance = itemDist.distance(left.getEnvelope(), nearestItem1, nearestItem2);
      double rightDistance = itemDist.distance(right.getEnvelope(), nearestItem1, nearestItem2);

      // push the child node with the smallest distance on top of the stack
      if (leftDistance < rightDistance) {
        if (leftDistance < minDistance) {
          stack.push(left);
        }
        if (rightDistance < minDistance) {
          stack.push(right);
        }
      } else {
        if (rightDistance < minDistance) {
          stack.push(right);
        }
        if (leftDistance < minDistance) {
          stack.push(left);
        }
      }
    }
  }

  return new Pair(nearestItem1, nearestItem2);
}

