public class JpaDocumentBuilder<E> {

    private final MappingContext<? extends PersistentEntity<?, ?,?>, MongoPersistentProperty> mappingContext;
    private final Class<E> entityClass;

    public JpaDocumentBuilder(Class<E> entityClass, MappingContext<? extends PersistentEntity<?, ?,?>, MongoPersistentProperty> mappingContext) {
        this.mappingContext = mappingContext;
        this.entityClass = entityClass;
    }

    public static <E> JpaDocumentBuilder<E> forEntityClass(Class<E> entityClass, MappingContext<? extends PersistentEntity<?,?,?>,MongoPersistentProperty> mappingContext) {
        return new JpaDocumentBuilder<E>(entityClass, (MappingContext<? extends PersistentEntity<?,?,?>, MongoPersistentProperty>) mappingContext);
    }

    public MongoJsonSchema build() {
        JpaPersistentEntity<?> jpaPersistentEntity = (JpaPersistentEntity<?>) mappingContext.getPersistentEntity(entityClass);
        MongoPersistentEntity<?> mongoPersistentEntity = mappingContext.getPersistentEntity(entityClass);
        MongoJsonSchema.MongoJsonSchemaBuilder builder = MongoJsonSchema.builder();

        jpaPersistentEntity.doWithProperties((PropertyFunction<JpaPersistentProperty>) property -> {
            String fieldName = property.getName();
            builder.property(fieldName, mongoPersistentEntity.getType().isEnumType(property.getType()) ?
                    MongoSimpleTypes.STRING : mapToMongoType(property.getType()));
            return true;
        });

        return builder.build();
    }

    private static MongoJsonSchemaType mapToMongoType(Class propertyType) {
        if (propertyType.isAssignableFrom(String.class)) {
            return MongoJsonSchemaType.STRING;
        } else if (propertyType.isAssignableFrom(Integer.class) || propertyType.isAssignableFrom(int.class)
                || propertyType.isAssignableFrom(Long.class) || propertyType.isAssignableFrom(long.class)) {
            return MongoJsonSchemaType.NUMBER;
        } else if (propertyType.isAssignableFrom(Float.class) || propertyType.isAssignableFrom(Double.class) || propertyType.isAssignableFrom(double.class) || propertyType.isAssignableFrom(float.class)) {
            return MongoJsonSchemaType.NUMBER;
        } else if (propertyType.isAssignableFrom(Boolean.class) || propertyType.isAssignableFrom(boolean.class)) {
            return MongoJsonSchemaType.BOOLEAN;
        } else if (propertyType.isAssignableFrom(java.time.LocalDateTime.class) || propertyType.isAssignableFrom(java.time.LocalDate.class)) {
            return MongoJsonSchemaType.DATE;
        } else if (propertyType.isAssignableFrom(ObjectId.class)) {
            return MongoJsonSchemaType.OBJECT_ID;
        }
        return MongoJsonSchemaType.OBJECT;
    }

    enum MongoJsonSchemaType {
        ARRAY("array"),
        BOOLEAN("boolean"),
        INTEGER("number"),
        NUMBER("number"),
        NULL("null"),
        OBJECT("object"),
        OBJECT_ID("objectId"),
        STRING("string"),
        DATE("date");

        private final String rawType;

        MongoJsonSchemaType(String rawType) {
            this.rawType = rawType;
        }

        public String getRawType() {
