public static void writeMultigraphToFile(File f, Multigraph<String, DefaultEdge> graph) {
    String graphId = "G";
    String xmlns = "http://www.gexf.net/1.2draft";
    String xmlnsViz = "http://www.gexf.net/1.2draft/viz";
    String version = "1.2";
    String encoding = "UTF-8";

    GraphWriter<DefaultVertex, DefaultEdge> gexfWriter = new GexfWriterFactory<DefaultVertex, DefaultEdge>()
            .createGexfWriter();
    gexfWriter.getConfig().setWriterName("multigraph-writer");
    gexfWriter.getConfig().setXmlns(xmlns);
    gexfWriter.getConfig().setVisualizationEnabled(true);

    Gexf gexf = new GexfImpl(graphId, xmlns, version);
    Graph graphViz = gexf.getGraph();
    graphViz.setDefaultEdgeType(EdgeType.UNDIRECTED);

    AttributeList attrListOfEdges = new AttributeListImpl(AttributeClass.EDGE);
    Attribute attColor = new AttributeImpl("color", AttributeType.STRING, "edge color");
    attrListOfEdges.add(attColor);
    graphViz.getAttributeLists().add(attrListOfEdges);

    HashMap<DefaultVertex, Node> vertexNodeMap = new HashMap<>();

    // add nodes
    for (DefaultVertex v : graph.vertexSet()) {
        Node node = graphViz.createNode(v.toString());
        node.setLabel(v.toString());
        Color color = Color.BLACK;
        node.setSize(10);
        node.setPosition(0, 0, 0);
        node.setColor(color);
        vertexNodeMap.put(v, node);
    }

    // add edges
    for (DefaultEdge e : graph.edgeSet()) {
        Node source = vertexNodeMap.get(graph.getEdgeSource(e));
        Node target = vertexNodeMap.get(graph.getEdgeTarget(e));
        Edge edge = source.connectTo(target);
        edge.setColor(Color.BLACK);
        edge.setWeight(1);
        edge.getAttributeValues().addValue(attColor, "#000000");
    }

    try {
        gexfWriter.writeToStream(gexf, f.getOutputStream(), encoding);
    } catch (IOException e) {
        e.printStackTrace();
    }
}

