        synonyms.add(w.getLemma());
    }
    for (IWordID id : idxWord.getWordIDs()) {
        List<String> baseForms = morpho.lookupAllBaseForms(POS.NOUN, w.getLemma());
        for (String baseForm : baseForms) {
            idxWord = dict.getIndexWord(baseForm, POS.NOUN);
            if (idxWord == null) {
                continue;
            }
            for (IWordID baseId : idxWord.getWordIDs()) {
                iword = dict.getWord(baseId);
                synset = iword.getSynset();
                for (IWord syn : synset.getWords()) {
                    synonyms.add(syn.getLemma());
                }
            }
        }
    }
    dict.close();
    return synonyms;
}

