import java.awt.Point;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public static Polygon computeConvexHull(List<Point> points) {
    int n = points.size();
    if (n < 3) {
        throw new IllegalArgumentException("At least 3 points are required to compute the convex hull");
    }

    // Find the point with the minimum y-coordinate (ties broken by minimum x-coordinate)
    Point minYPoint = points.get(0);
    for (int i = 1; i < n; i++) {
        Point p = points.get(i);
        if (p.y < minYPoint.y || (p.y == minYPoint.y && p.x < minYPoint.x)) {
            minYPoint = p;
        }
    }

    // Sort the points by polar angle with respect to the minYPoint
    final Point minYCopy = minYPoint;
    Comparator<Point> angleComparator = new Comparator<Point>() {
        public int compare(Point p1, Point p2) {
            double angle1 = Math.atan2(p1.y - minYCopy.y, p1.x - minYCopy.x);
            double angle2 = Math.atan2(p2.y - minYCopy.y, p2.x - minYCopy.x);
            if (angle1 < angle2) {
                return -1;
            } else if (angle1 > angle2) {
                return 1;
            } else {
                return 0;
            }
        }
    };
    List<Point> sortedPoints = new ArrayList<>(points);
    sortedPoints.remove(minYPoint);
    Collections.sort(sortedPoints, angleComparator);
    sortedPoints.add(0, minYPoint);

    // Perform the Graham scan algorithm
    List<Point> hull = new ArrayList<>();
    hull.add(sortedPoints.get(0));
    hull.add(sortedPoints.get(1));
    for (int i = 2; i < n; i++) {
        Point p = sortedPoints.get(i);
        while (hull.size() >= 2) {
            Point top = hull.get(hull.size() - 1);
            Point nextToTop = hull.get(hull.size() - 2);
            if ((p.x - nextToTop.x) * (top.y - nextToTop.y) >= (p.y - nextToTop.y) * (top.x - nextToTop.x)) {
                hull.remove(hull.size() - 1);
            } else {
                break;
            }
        }
        hull.add(p);
    }

    // Convert the list of points to a Polygon object
    int[] xCoords = new int[hull.size()];
    int[] yCoords = new int[hull.size()];
    for (int i = 0; i < hull.size(); i++) {
        Point p = hull.get(i);
        xCoords[i] = p.x;
        yCoords[i] = p.y;
    }
    return new Polygon(xCoords, yCoords, hull.size());
}

