public static SparseVector parseFromMatrixMarket(InputStream is) throws IOException {
    BufferedReader reader = new BufferedReader(new InputStreamReader(is));
    String[] header = reader.readLine().split(" ");

    if (!header[0].equals("%%MatrixMarket") || !header[1].equals("matrix")) {
        throw new IOException("Invalid header in Matrix Market file");
    }

    String object = reader.readLine().trim();

    if (!"coordinate".equals(object) && !"array".equals(object)) {
        throw new IOException("Invalid object type in Matrix Market file");
    }

    SparseVector sv = null;

    if ("coordinate".equals(object)) {
        String[] tokens;

        do {
            tokens = reader.readLine().split(" ");
        } while (tokens[0].startsWith("%"));

        int rows = Integer.parseInt(tokens[0]);
        int cols = Integer.parseInt(tokens[1]);
        int nnz = Integer.parseInt(tokens[2]);

        sv = new SparseVector(rows);

        for (int i = 0; i < nnz; i++) {
            tokens = reader.readLine().split(" ");
            int row = Integer.parseInt(tokens[0]);
            int col = Integer.parseInt(tokens[1]);
            double value = Double.parseDouble(tokens[2]);
            sv.set(row - 1, value);
        }
    } else if ("array".equals(object)) {
        String[] tokens;

        do {
            tokens = reader.readLine().split(" ");
        } while (tokens[0].startsWith("%"));

        int size = Integer.parseInt(tokens[0]);

        sv = new SparseVector(size);

        for (int i = 0; i < size; i++) {
            double value = Double.parseDouble(reader.readLine());
            sv.set(i, value);
        }
    }

    return sv;
}

