public void applyExtrusion(Vector3D extrusionVector, Shape3D[] objects) {
    for (Shape3D object : objects) {
        if (object.getGeometry() instanceof Polygon) {
            Polygon polygon = (Polygon) object.getGeometry();
            polygon.setExtrusion(extrusionVector);
            object.setGeometry(polygon);
        } else if (object.getGeometry() instanceof Mesh) {
            Mesh mesh = (Mesh) object.getGeometry();
            int[] faceSmoothingGroups = new int[mesh.getFaceCount()];
            Arrays.fill(faceSmoothingGroups, 0);
            int[] edgeSmoothingGroups = new int[mesh.getEdgeCount()];
            Arrays.fill(edgeSmoothingGroups, 0);
            mesh.setExtrusion(extrusionVector, faceSmoothingGroups, edgeSmoothingGroups);
            object.setGeometry(mesh);
        }
    }
}

