import org.apache.commons.math3.stat.correlation.PearsonsCorrelation;
import org.apache.commons.math3.stat.descriptive.rank.Percentile;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.util.ArrayList;
import java.util.Collections;

import javax.swing.JFrame;

import org.math.plot.Plot2DPanel;

public class QQPlot {
    public static void createPlot(double[] x) {
        int n = x.length;

        ArrayList<Double> sortedX = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            sortedX.add(x[i]);
        }
        Collections.sort(sortedX);

        double[] normX = new double[n];
        Percentile percentile = new Percentile();
        for (int i = 0; i < n; i++) {
            normX[i] = percentile.evaluate(sortedX, (double) (i + 1) * 100 / (n + 1));
        }

        PearsonsCorrelation pearsonsCorr = new PearsonsCorrelation();
        double corr = pearsonsCorr.correlation(normX, sortedX.stream().mapToDouble(Double::doubleValue).toArray());

        double[] minY = new double[n];
        double[] maxY = new double[n];
        for (int i = 0; i < n; i++) {
            minY[i] = Math.min(sortedX.get(i), normX[i]);
            maxY[i] = Math.max(sortedX.get(i), normX[i]);
        }

        Plot2DPanel plot = new Plot2DPanel();

        plot.addLinePlot("y = x", Color.BLUE, new double[] { -4, 4 }, new double[] { -4, 4 });

        plot.addScatterPlot("Sample", Color.BLACK, sortedX.stream().mapToDouble(Double::doubleValue).toArray(),
                normX);
        plot.addLinePlot("Fitted", Color.RED, sortedX.stream().mapToDouble(Double::doubleValue).toArray(),
                sortedX.stream().mapToDouble(Double::doubleValue).map(x_i -> x_i * corr).toArray());
        plot.addIntervalPlot("Confidence bounds", Color.GREEN, minY, maxY);

        plot.getPlot(0).setLabelX("y");
        plot.getPlot(0).setLabelY("x");
        plot.getPlot(1).setLabelX("Sorted data");
        plot.getPlot(1).setLabelY("Quantiles of normal distribution");
        plot.getPlot(2).setLabelX("Sorted data");
        plot.getPlot(2).setLabelY("Fitted quantiles of normal distribution");
        plot.getPlot(3).setLabelX("Sorted data");
        plot.getPlot(3).setLabelY("Confidence bounds");

        plot.getPlot(0).setFixedBounds(-4, 4, -4, 4);
        plot.getPlot(1).setFixedBounds(-4, 4, -4, 4);
        plot.getPlot(2).setFixedBounds(-4, 4, -4, 4);
        plot.getPlot(3).setFixedBounds(-4, 4, -4, 4);

        plot.getPlot(1).setColor(Color.BLACK);
        plot.getPlot(2).setColor(Color.RED);
        plot.getPlot(3).setFillColor(new Color(100, 255, 100, 50));

        JFrame frame = new JFrame("Q-Q Plot");
        frame.setContentPane(plot);
        frame.setPreferredSize(new Dimension(800, 600));
        frame.pack();
        frame.setVisible(true);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
    }
}

