public void assertInsertedOnly(String message, DataSet dataSet) throws DBAssertionError {
    try {
        // create connection
        Connection connection = dataSource.getConnection();
        connection.setAutoCommit(false);

        // execute query to retrieve data before insertion
        Statement statement = connection.createStatement();
        ResultSet resultSetBefore = statement.executeQuery("SELECT * FROM mytable");
        List<Map<String, Object>> rowsBefore = new ArrayList<>();
        while (resultSetBefore.next()) {
            Map<String, Object> row = new HashMap<>();
            row.put("id", resultSetBefore.getInt("id"));
            row.put("name", resultSetBefore.getString("name"));
            rowsBefore.add(row);
        }

        // insert data
        PreparedStatement preparedStatement = connection.prepareStatement("INSERT INTO mytable (id, name) VALUES (?, ?)");
        for (Map<String, Object> row : dataSet.getValues()) {
            preparedStatement.setInt(1, (int) row.get("id"));
            preparedStatement.setString(2, (String) row.get("name"));
            preparedStatement.addBatch();
        }
        preparedStatement.executeBatch();
        connection.commit();

        // execute query to retrieve data after insertion
        ResultSet resultSetAfter = statement.executeQuery("SELECT * FROM mytable");
        List<Map<String, Object>> rowsAfter = new ArrayList<>();
        while (resultSetAfter.next()) {
            Map<String, Object> row = new HashMap<>();
            row.put("id", resultSetAfter.getInt("id"));
            row.put("name", resultSetAfter.getString("name"));
            rowsAfter.add(row);
        }

        // compare data sets
        if (!DataSet.compare(DataSet.of(rowsBefore), dataSet.insertedOnly(rowsAfter))) {
            throw new DBAssertionError(message);
        }
    } catch (SQLException e) {
        throw new DBAssertionError(message, e);
    }
}

