import java.util.ArrayList;
import java.util.List;

public class Scanner {
    private String input;

    public Scanner(String input) {
        this.input = input;
    }

    public List<List<Selector>> scan() throws ScannerException {
        List<List<Selector>> selectorGroups = new ArrayList<>();

        // Split the input into lines
        String[] lines = input.split("\n");

        for (String line : lines) {
            // Split each line into selectors
            String[] selectors = line.split(",");

            List<Selector> selectorGroup = new ArrayList<>();

            for (String selector : selectors) {
                // Create a new selector and add it to the group
                selectorGroup.add(new Selector(selector));
            }

            // Add the group to the list of selector groups
            selectorGroups.add(selectorGroup);
        }

        return selectorGroups;
    }
}

