public static String convertBase(String num, int fromBase, int toBase) {
    // Convert input number from 'fromBase' to decimal
    int decimal = 0;
    for (int i = 0; i < num.length(); i++) {
        int digit = Character.digit(num.charAt(i), fromBase);
        decimal = decimal * fromBase + digit;
    }
    // Convert decimal number to 'toBase'
    StringBuilder sb = new StringBuilder();
    while (decimal > 0) {
        int digit = decimal % toBase;
        sb.append(Character.forDigit(digit, toBase));
        decimal /= toBase;
    }
    return sb.reverse().toString();
}

