    List<DAGNode<?>> outNodes = new ArrayList<>(leftNodes.size() + rightNodes.size());

    outNodes.addAll(leftNodes);
    outNodes.addAll(rightNodes);

    Set<DAGNode<?>> outputNodes = buildOutputNodes(outNodes, joinerTransformer.getImplicitOutputs());

    DAG1x1<ConcatenatedDAGInputs, ConcatenatedDAGOutputs> concatenatedDAG =
