            .withName(getUniqueName(dagLeft.getName(), dagRight.getName()))
            .withInputs(dagLeft.internalAPI().getInput(0), dagRight.internalAPI().getInput(0));

    for (int i = 0; i < outNodes.size(); i++) {
      DAGNode<?> node = outNodes.get(i);

      @SuppressWarnings("unchecked")
      DAGNode<Object> out = (DAGNode<Object>) outputNodes.stream().filter(n -> n.getValue() == node.getValue())
                              .findFirst().orElse(null);

      Optional<? extends Transformer<?, ?>> maybeTransformer = node.getValue() instanceof Transformer ? Optional.of(
          (Transformer<?, ?>) node.getValue()) : Optional.empty();

      if (out == null) {
        throw new IllegalStateException("Could not get the output node for " + node.getName());
      }

      if (maybeTransformer.isPresent()) {
        Transformer<?, ?> transformer = maybeTransformer.get();
        if (transformer.getInputArity() == 0) {
          concatenatedDAG.internalAPI().addNoInputProducer(transformer);
        } else {
          Node[] dependencies = Arrays.stream(node.getParents()).map(p -> {
            @SuppressWarnings("unchecked")
            DAGNode<Object> parentOutput =
                (DAGNode<Object>) outputNodes.stream().filter(o -> o.getValue() == p.getValue()).findFirst()
                    .orElse(null);

            if (parentOutput == null) {
              throw new IllegalStateException("Could not get the parent output for " + p.getName());
            }
            return new Dependency<>(parentOutput, p.getDependentInputIndex());
          }).toArray(Node[]::new);

          Transformer inPlace = maybeTransformer.get().withInputs(dependencies).withOutputs(out);

          if (inPlace instanceof DAGTransformer) {
            DAGTransformer<?, ?> inPlaceDAGTransformer = (DAGTransformer<?, ?>) inPlace;
            concatenatedDAG.internalAPI().addDAGTransformer(inPlaceDAGTransformer);
          } else {
