  private static List<DAGNode<?>> getNodes(DAG<?> dag) {
    return dag.internalAPI().getNodes().stream()
               .filter(n -> !n.getValue().getClass().equals(Constant.class)).collect(Collectors.toList()); 
  }

  private static List<DAGNode<?>> getShiftedNodes(List<DAGNode<?>> nodes, int shift) {
    return nodes.stream()
               .map(n -> n.internalAPI().withOutputIndex(n.internalAPI().getOutputIndex(0) + shift))
               .collect(Collectors.toList());
  }

  private static Set<DAGNode<?>> buildOutputNodes(List<DAGNode<?>> nodes, List<? extends Node<?>> implicitOutputs) {

    Set<DAGNode<?>> inNodes = nodes.stream().filter(n -> implicitOutputs.stream()
                                                          .map(Node::getValue).noneMatch(v -> v == n.getValue()))
                               .collect(Collectors.toSet());

    Set<DAGNode<?>> outNodes = nodes.stream().filter(n -> implicitOutputs.stream().map(Node::getValue)
                                                                   .anyMatch(v -> v == n.getValue()))
                                .collect(Collectors.toSet());

    Map<Node<?>, DAGNode<?>> translate = new IdentityHashMap<>();
    for (DAGNode<?> node : inNodes) {
      translate.put(node, new DAGNode<>(node.getValue()));
    }

    DAGLink.inOrder(translate.values());

    // Link the inNodes and outNodes.
    for (Node<?> node : implicitOutputs) {
      DAGNode<?> out = translate.get(node.getProducer());
      if (out != null) {
        for (int i = 0; i < node.getConsumerCount(); i++) {
          DAGNode<?> in = translate.get(node.getConsumer(i));
          if (in != null) {
            out.connectTo(in, node.getConsumerInputIndex(i));
          }
        }
      }
    }

    DAGNode<?> last = null;
    for (DAGNode<?> node : outNodes) {
      last = node;
      DAGNode<?> in = translate.get(node.getProducer());
      if (in != null) {
        in.connectTo(node, 0);
      }
    }

    // no output exists yet.
    DAGNode<Object> outputNode = new DAGNode<>(null, null);
    outputNode.setName("Output");
    outputNode.connectTo(last);
    return Collections.singleton(outputNode);
  }

  private static String getUniqueName(String parentName, String childName) {
    return parentName + "_" + childName;
