import com.datastax.driver.core.Cluster; 
import com.datastax.driver.core.Cluster.Builder; 
import com.datastax.driver.core.Metadata; 
import com.datastax.driver.core.Session; 

public class CassandraConnector {

    public static ClusterIdentifier getClusterIdentifier(String hostsAndPorts, String username, String password) {
        Cluster cluster = null;
        try {
            Builder builder = Cluster.builder().addContactPointsWithPorts(parseHostsAndPorts(hostsAndPorts));

            if (username != null && password != null) {
                builder.withCredentials(username, password);
            }

            cluster = builder.build();
            Metadata metadata = cluster.getMetadata();
            return new ClusterIdentifier(cluster, metadata.getClusterName());
        } catch (Exception e) {
            if (cluster != null) {
                cluster.close();
            }
            throw new RuntimeException("Failed to connect to cluster with hostsAndPorts=" + hostsAndPorts, e);
        }
    }

    private static List<InetSocketAddress> parseHostsAndPorts(String hostsAndPorts) {
        return Arrays.stream(hostsAndPorts.split(","))
                .map(hostAndPort -> {
                    String[] tokens = hostAndPort.split(":");
                    String host = tokens.length > 0 ? tokens[0] : null;
                    Integer port = tokens.length > 1 ? Integer.parseInt(tokens[1]) : null;
                    return new InetSocketAddress(host, port);
                })
                .collect(Collectors.toList());
    }

    public static class ClusterIdentifier {
        private final Cluster cluster;
        private final String clusterName;

        public ClusterIdentifier(Cluster cluster, String clusterName) {
            this.cluster = cluster;
            this.clusterName = clusterName;
        }

        public Cluster getCluster() {
            return cluster;
        }

        public String getClusterName() {
            return clusterName;
        }
    }
}

