import java.io.File;
import java.io.IOException;
import java.io.FileOutputStream;
import java.io.BufferedOutputStream;
import java.nio.file.Files;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;

public void compressToTar(File[] sources, File target, String mode) throws IOException {
    try (FileOutputStream fOutStream = new FileOutputStream(target);
         BufferedOutputStream buffOutStream = new BufferedOutputStream(fOutStream);
         GzipCompressorOutputStream gzOutStream = new GzipCompressorOutputStream(buffOutStream);
         TarArchiveOutputStream tarOutStream = new TarArchiveOutputStream(gzOutStream)) {
        tarOutStream.setBigNumberMode(TarArchiveOutputStream.BIGNUMBER_POSIX);
        tarOutStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_POSIX);
        if (mode.equalsIgnoreCase("directory")) {
            for (File source : sources) {
                File parentDir = source.getParentFile();
                String sourcePath = source.getPath();
                String pathPrefix = parentDir.getPath() + File.separator;
                TarArchiveEntry tarEntry = new TarArchiveEntry(source, sourcePath.replace(pathPrefix, ""));
                tarOutStream.putArchiveEntry(tarEntry);
                Files.copy(source.toPath(), tarOutStream);
                tarOutStream.closeArchiveEntry();
            }
        } else if (mode.equalsIgnoreCase("file")) {
            String sourcePath = sources[0].getPath();
            TarArchiveEntry tarEntry = new TarArchiveEntry(sources[0], sources[0].getName());
            tarOutStream.putArchiveEntry(tarEntry);
            Files.copy(sources[0].toPath(), tarOutStream);
            tarOutStream.closeArchiveEntry();
        } else {
            throw new IllegalArgumentException("Invalid mode specified.");
        }
        tarOutStream.finish();
    }
}

