import java.util.*;

public class ArborescenceFinder {

    public static class Edge {
        public int from, to, weight;
        public Edge(int from, int to, int weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }
    }

    // finds the minimum-weight incoming edge for each node
    private static int[] findMinimumIncomingEdges(List<Edge> edgeList, int n, int root) {
        int[] minimumIncomingEdge = new int[n];
        Arrays.fill(minimumIncomingEdge, Integer.MAX_VALUE);
        for (Edge edge : edgeList) {
            if (edge.to == root) continue;
            minimumIncomingEdge[edge.to] = Math.min(minimumIncomingEdge[edge.to], edge.weight);
        }
        return minimumIncomingEdge;
    }

    // finds the incoming edge in edgeList for each node
    private static Edge[] findIncomingEdges(List<Edge> edgeList, int n) {
        Edge[] incomingEdge = new Edge[n];
        for (Edge edge : edgeList) {
            if (incomingEdge[edge.to] == null || incomingEdge[edge.to].weight > edge.weight) {
                incomingEdge[edge.to] = edge;
            }
        }
        return incomingEdge;
    }

    // builds the arborescence
    private static List<Edge> buildArborescence(int[] minimumIncomingEdge, Edge[] incomingEdge, int root) {
        List<Edge> arborescence = new ArrayList<>();
        for (int i = 0; i < minimumIncomingEdge.length; i++) {
            if (i == root) continue;
            if (incomingEdge[i] == null) return null;
            if (minimumIncomingEdge[i] == incomingEdge[i].weight) {
                arborescence.add(incomingEdge[i]);
            } else {
                return null;
            }
        }
        return arborescence;
    }

    public static List<Edge> findOptimalArborescence(List<Edge> edgeList, int n, int root) {
        int[] minimumIncomingEdge = findMinimumIncomingEdges(edgeList, n, root);
        Edge[] incomingEdge = findIncomingEdges(edgeList, n);
        return buildArborescence(minimumIncomingEdge, incomingEdge, root);
    }
}

