import org.bouncycastle.util.io.pem.PemWriter;

public static void convertKeyFormat(String keyFile, String toFormat, String toFile) throws IOException, InvalidPassphraseException {
    InputStream inputStream = new FileInputStream(keyFile);
    String extension = getFileExtension(keyFile);

    switch (extension) {
        case "pem":
            PemReader pemReader = new PemReader(new InputStreamReader(inputStream));
            PemObject pemObject = pemReader.readPemObject();
            inputStream.close();

            File outputFile = new File(toFile);
            Writer writer = new FileWriter(outputFile);

            if (toFormat.equals("der")) {
                byte[] derBytes = pemObject.getContent();
                writer.write(new String(Base64.encodeBase64(derBytes), "UTF-8"));
            }
            else if (toFormat.equals("pem")) {
                PemWriter pemWriter = new PemWriter(writer);
                pemWriter.writeObject(pemObject);
                pemWriter.close();
            }

            writer.close();
            break;
        case "asc":
        case "pgp":
            PGPSecretKeyRing secretKeyRing = readSecretKeyRing(inputStream);
            inputStream.close();

            if (toFormat.equals("asc") || toFormat.equals("pgp")) {
                FileOutputStream fileOutputStream = new FileOutputStream(toFile);
                if (toFormat.equals("asc")) {
                    secretKeyRing.encode(fileOutputStream);
                }
                else if (toFormat.equals("pgp")) {
                    secretKeyRing.encode(fileOutputStream, true);
                }
                fileOutputStream.close();
            }
            else if (toFormat.equals("pem")) {
                PGPPrivateKey privateKey = secretKeyRing.getSecretKey().extractPrivateKey(passphrase, "BC");
                PEMWriter pemWriter = new PEMWriter(writer);
                pemWriter.writeObject(privateKey);
                pemWriter.close();
            }

            break;
        default:
            throw new IOException("File format not supported");
    }
}

private static PGPSecretKeyRing readSecretKeyRing(InputStream inputStream) throws IOException, InvalidPassphraseException {
    PGPSecretKeyRing secretKeyRing = null;
    try {
        PGPSecretKeyRingCollection secretKeyRingCollection = new PGPSecretKeyRingCollection(inputStream, new JcaKeyFingerprintCalculator());
        secretKeyRing = secretKeyRingCollection.iterator().next();
        if (secretKeyRing.getSecretKey().isPrivateKeyEmpty()) {
            throw new InvalidPassphraseException("Private key is empty");
        }
    } catch (PGPException e) {
        throw new RuntimeException(e);
    }
    return secretKeyRing;
}

private static String getFileExtension(String filePath) {
    int index = filePath.lastIndexOf('.');
    if (index == -1) {
        return null;
    }
    return filePath.substring(index + 1);
}

