public static void hessenbergToSchur(double[][] H) {
    int n = H.length;

    for (int i = n-1; i >= 2; i--) {
        double scale = 0.0;
        for (int k = 0; k <= i-1; k++) {
            scale = scale + Math.abs(H[i][k]);
        }
        if (scale == 0.0) {
            continue;
        }
        double h = 0.0;
        for (int k = 0; k <= i-1; k++) {
            H[i][k] /= scale;
            h += H[i][k] * H[i][k];
        }
        double g = Math.sqrt(h);
        if (H[i][i-1] > 0) {
            g = -g;
        }
        h -= H[i][i-1] * g;
        H[i][i-1] -= g;
        for (int j = 0; j <= i-1; j++) {
            double f = 0.0;
            for (int k = 0; k <= j; k++) {
                f += H[j][k] * H[i][k];
            }
            f /= h;
            for (int k = 0; k <= j; k++) {
                H[j][k] -= f * H[i][k];
            }
        }
        for (int k = 0; k <= i-1; k++) {
            H[i][k] *= scale;
        }
    }
}

