import com.google.inject.AbstractModule;
import com.google.inject.Module;
import com.typesafe.config.Config;
import io.github.classgraph.ClassGraph;
import io.github.classgraph.ClassInfo;
import io.github.classgraph.ScanResult;

import java.lang.annotation.Annotation;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class TypesafeConfigModuleBuilder {

    public static Module build(Config config, String... packages) {
        List<Class<?>> classes = filterAnnotatedClasses(loadClasses(packages), Config.class);
        return createModule(config, classes);
    }

    private static List<Class<?>> loadClasses(String... packages) {
        List<Class<?>> classes = new ArrayList<>();
        try (ScanResult scanResult =
                     new ClassGraph()
                             .enableAllInfo()
                             .whitelistPackages(packages)
                             .scan()) {
            Set<Class<?>> classSet = scanResult.getAllClasses()
                    .stream()
                    .map(ClassInfo::loadClass)
                    .collect(Collectors.toSet());
            classes.addAll(classSet);
        }
        return classes;
    }

    private static <T extends Annotation> List<Class<?>> filterAnnotatedClasses(List<Class<?>> classes, Class<T> annotationClass) {
        List<Class<?>> annotatedClasses = new ArrayList<>();
        for (Class<?> cls : classes) {
            if (cls.isAnnotationPresent(annotationClass)) {
                annotatedClasses.add(cls);
            }
        }
        return annotatedClasses;
    }

    private static Module createModule(Config config, List<Class<?>> classes) {
        return new AbstractModule() {
            @Override
            protected void configure() {
                for (Class<?> cls : classes) {
                    Config annotationConfig = cls.getAnnotation(Config.class);
                    bind(cls).toProvider(new ConfigProvider<>(annotationConfig, config, cls));
                }
            }
        };
    }
}

