import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.List;

public class ConstructorInvoker {

    public static <T> List<T> explodeArguments(Class<T> clazz, Object... args) throws NoSuchMethodException,
            SecurityException, InstantiationException, IllegalAccessException, IllegalArgumentException, InvocationTargetException {
        List<T> result = new ArrayList<>();
        Constructor<T> constructor = clazz.getConstructor(getParameterTypes(args));
        Class<?>[] parameterTypes = constructor.getParameterTypes();
        int constructorArgCount = parameterTypes.length;
        int numCombinations = (int) Math.pow(2, constructorArgCount);
        for (int i = 0; i < numCombinations; i++) {
            Object[] explodedArgs = getExplodedArgs(i, constructorArgCount, args);
            if (isValidCombination(explodedArgs, parameterTypes)) {
                result.add(constructor.newInstance(explodedArgs));
            }
        }
        return result;
    }

    private static Class<?>[] getParameterTypes(Object... args) {
        Class<?>[] parameterTypes = new Class<?>[args.length];
        for (int i = 0; i < args.length; i++) {
            parameterTypes[i] = args[i].getClass();
        }
        return parameterTypes;
    }

    private static Object[] getExplodedArgs(int combination, int constructorArgCount, Object[] originalArgs) {
        Object[] result = new Object[constructorArgCount];
        for (int i = 0; i < constructorArgCount; i++) {
            result[i] = (combination & (1 << i)) != 0 ? originalArgs[i] : null;
        }
        return result;
    }

    private static boolean isValidCombination(Object[] args, Class<?>[] parameterTypes) {
        if (args.length != parameterTypes.length) {
            return false;
        }
        for (int i = 0; i < args.length; i++) {
            if (args[i] != null && !parameterTypes[i].isAssignableFrom(args[i].getClass())) {
                return false;
            }
        }
        return true;
    }
}

