Compute {@code m * Math.pow(10,e)} on the bit representation, for
assembling a floating point decimal value.

@param m Mantisse
@param n Exponent to base 10.
@return Double value.

human_code:
public static double lpow10(long m, int n) {
    if(m == 0) {
      return 0.0;
    }
    if(m == Long.MIN_VALUE) {
      return lpow10(Long.MIN_VALUE / 10, n + 1);
    }
    if(m < 0) {
      return -lpow10(-m, n);
    }
    if(n >= 0) {  
      if(n > 308) {
        return Double.POSITIVE_INFINITY;
      }

      long x0 = 0;  
      long x1 = 0;  
      long x2 = m & LONG_32_BITS;  
      long x3 = m >>> 32;  
      int pow2 = 0;
      while(n != 0) {
        int i = (n >= POW5_INT.length) ? POW5_INT.length - 1 : n;
        int coef = POW5_INT[i];  
        if(((int) x0) != 0) {
          x0 *= coef;  
        }
        if(((int) x1) != 0) {
          x1 *= coef;  
        }
        x2 *= coef;  
        x3 *= coef;  
        x1 += x0 >>> 32;
        x0 &= LONG_32_BITS;
        x2 += x1 >>> 32;
        x1 &= LONG_32_BITS;
        x3 += x2 >>> 32;
        x2 &= LONG_32_BITS;

        pow2 += i;
        n -= i;

        long carry = x3 >>> 32;
        if(carry != 0) {  
          x0 = x1;
          x1 = x2;
          x2 = x3 & LONG_32_BITS;
          x3 = carry;
          pow2 += 32;
        }
      }

      assert (x3 >= 0);
      int shift = 31 - magnitude(x3);  
      pow2 -= shift;
      long mantissa = (shift < 0) ? (x3 << 31) | (x2 >>> 1) :  
          (((x3 << 32) | x2) << shift) | (x1 >>> (32 - shift));
      return lpow2(mantissa, pow2);
    }
    else {  
      if(n < -324 - 20) {
        return 0.;
      }

      long x1 = m;  
      long x0 = 0;  
      int pow2 = 0;
      while(true) {

        assert (x1 >= 0);
        int shift = 63 - magnitude(x1);
        x1 <<= shift;
        x1 |= x0 >>> (63 - shift);
        x0 = (x0 << shift) & LONG_63_BITS;
        pow2 -= shift;

        if(n == 0) {
          break;  
        }

        int i = (-n >= POW5_INT.length) ? POW5_INT.length - 1 : -n;
        int divisor = POW5_INT[i];

        long wh = (x1 >>> 32);
        long qh = wh / divisor;
        long r = wh - qh * divisor;
        long wl = (r << 32) | (x1 & LONG_32_BITS);
        long ql = wl / divisor;
        r = wl - ql * divisor;
        x1 = (qh << 32) | ql;
        wh = (r << 31) | (x0 >>> 32);
        qh = wh / divisor;
        r = wh - qh * divisor;
        wl = (r << 32) | (x0 & LONG_32_BITS);
        ql = wl / divisor;
        x0 = (qh << 32) | ql;

        n += i;
        pow2 -= i;
      }
      return lpow2(x1, pow2);
    }
  }

