public static void processSentences( CMMClassifier<CoreLabel> cmm, PrintStream out, String text) {
	// Split the text into sentences
    List<CoreLabel> tokens = new ArrayList<>();
    String[] sentences = text.split("[.!?]");
    for (String sentence : sentences) {
        // Tokenize each sentence
        List<CoreLabel> sentenceTokens = tokenizeSentence(sentence);
        tokens.addAll(sentenceTokens);
    }
    // Output each sentence
    for (CoreLabel token : tokens) {
        outputSentence(cmm, out, token);
    }
}

private static List<CoreLabel> tokenizeSentence(String sentence) {
    // Tokenize the sentence into words
    List<CoreLabel> tokens = new ArrayList<>();
    String[] words = sentence.split("\\s+");
    for (String word : words) {
        CoreLabel token = new CoreLabel();
        token.setWord(word);
        tokens.add(token);
    }
    return tokens;
}

private static void outputSentence(CMMClassifier<CoreLabel> cmm, PrintStream out, CoreLabel token) {
    // Output the token with its features
    String features = cmm.getFeatures(token);
    out.println(token.word() + " " + features);
}

