@Controller
public class UserDefinedJSHandlerController implements ApplicationContextAware {

    @Resource(name = "userDefinedJsDirectory")
    private Resource[] userDefinedJsDirectory;

    private ScriptEngine engine;

    private ApplicationContext context;

    @RequestMapping(value = {"/**"}, method = RequestMethod.POST)
    public void handlePost(HttpServletRequest request, HttpServletResponse response) {
        handleRequest(request, response);
    }

    @RequestMapping(value = {"/**"}, method = RequestMethod.GET)
    public void handleGet(HttpServletRequest request, HttpServletResponse response) {
        handleRequest(request, response);
    }

    private void handleRequest(HttpServletRequest request, HttpServletResponse response) {
        String path = request.getServletPath();
        try {
            Map<String, String> variables = new HashMap<>();
            variables.put("request", request);
            variables.put("response", response);

            Object result = ((Invocable) engine).invokeFunction(getFunctionName(request), variables);
            if (result != null) {
                response.getWriter().append(result.toString());
            }
        } catch (Exception e) {
            // Handle exception
            e.printStackTrace();
        }
    }

    /**
     * Initialize the user-defined JS handler.
     *
     * @throws IOException
     * @throws ScriptException
     */
    public void init() throws IOException, ScriptException {
        engine = new ScriptEngineManager().getEngineByName("javascript");

        ScriptSourceLocator locator = context.getBean("scriptSourceLocator", ScriptSourceLocator.class);
        for (Resource directory : userDefinedJsDirectory) {
            for (ScriptSource scriptSource : locator.getScriptSources(directory)) {
                engine.eval(new StandardScriptEvaluator().evaluate(scriptSource));
            }
        }
    }

    private String getFunctionName(HttpServletRequest request) {
        String path = (String) request.getAttribute(HandlerMapping.PATH_WITHIN_HANDLER_MAPPING_ATTRIBUTE);
        String[] tokens = path.split("/");
        String functionName = tokens[tokens.length - 1];
        return functionName;
    }

    @Override
    public void setApplicationContext(ApplicationContext applicationContext) {
        this.context = applicationContext;
    }
}

