public void replaceInstructions(MethodNode methodNode, InsnList oldInsnList, int index, InsnList newInsnList) {
    if (newInsnList == null) {
        return;
    }

    // Remove old instructions
    for (int i = 0; i < oldInsnList.size(); i++) {
        methodNode.instructions.remove(index);
    }

    // Insert new instructions
    for (int i = 0; i < newInsnList.size(); i++) {
        methodNode.instructions.insertBefore(newInsnList.get(i), index + i);
    }
}

