public static double[] convertFLIIItoFL93(double x, double y) {
    // Define the parameters for the conversion
    double n = 0.7289686274;
    double C = 11754255.426;
    double XS = 700000.0;
    double YS = 12655612.050;

    // Convert the input coordinates
    double delX = x - XS;
    double delY = y - YS;
    double gamma = Math.atan(-delX / delY);
    double R = Math.sqrt(delX * delX + delY * delY);
    double latiso = Math.log(C / R) / n;
    double sinPhi = Math.tanh(latiso + Math.sin(gamma)) * Math.tan(0.7853981634 + 0.5 * n);
    double phi = Math.asin(sinPhi);
    double sinU = Math.sin(gamma) / Math.cosh(latiso);
    double cosU = Math.cos(gamma) * Math.tanh(latiso);
    double sinV = Math.sin(phi) / Math.cos(0.7853981634 + 0.5 * n);
    double cosV = Math.cos(phi);
    double cosT = cosU * cosV - sinU * sinV;
    double sinT = Math.sqrt(1.0 - cosT * cosT);
    double sinSigma = sinV * sinU + cosV * cosU * cosT;
    double sigma = Math.asin(sinSigma);
    double sinAlpha = cosU * cosV * sinT / (1.0 - sinSigma * sinSigma);
    double alpha = Math.asin(sinAlpha);
    double cosSqAlpha = 1.0 - sinAlpha * sinAlpha;
    double cos2SigmaM = cosSigma(-sinSigma, cosSigma(cosU, cosV * sinT, sinV * cosU), -cosAlpha(sinU, sinV * sinT, cosV * cosU));
    double C1 = n / Math.sqrt(cosSqAlpha) * C / Math.sin(sigma);
    double L = alpha - (1.0 - C1) * n * sinAlpha * (sigma + C1 * Math.sin(sigma) *
        (cos2SigmaM + C1 * Math.cos(sigma) * (-1.0 + 2.0 * cos2SigmaM * cos2SigmaM)));
    double lambda = 0.04079234433198 + gamma + Math.atan(sinU / cosU);
    lambda = lambda * 180.0 / Math.PI;
    L = L * 180.0 / Math.PI;

    // Return the converted coordinates
    return new double[]{lambda, L};
}

private static double cosSigma(double sinSigma, double cosU, double cosV) {
    return Math.sqrt(sinSigma * sinSigma + cosU * cosU * cosV * cosV);
}

private static double cosAlpha(double sinU, double sinV, double cosUcosV) {
    return Math.sqrt(sinU * sinU + sinV * sinV * cosUcosV * cosUcosV);
}

