import java.io.IOException;
import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import javax.xml.validation.Validator;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;

public class XmlValidator {

  public Document loadXmlWithXsdValidation(String _xmlStr, boolean _namespaceAware) throws IOException {
    try {
      // Create a document builder factory
      DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
      factory.setNamespaceAware(_namespaceAware);

      // Set up validation against an XSD schema
      SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
      Schema schema = schemaFactory.newSchema(new StreamSource(getClass().getResourceAsStream("my-schema.xsd")));

      // Create a document builder
      DocumentBuilder builder = factory.newDocumentBuilder();

      // Set up an XmlErrorHandlerQuiet to suppress all errors/warnings
      XmlErrorHandlerQuiet errorHandler = new XmlErrorHandlerQuiet();

      // Use the schema to validate the XML content
      Validator validator = schema.newValidator();
      validator.setErrorHandler(errorHandler);
      validator.validate(new StreamSource(new InputSource(new StringReader(_xmlStr))));

      // Build the document
      Document document = builder.parse(new ByteArrayInputStream(_xmlStr.getBytes()));

      // Return the validated document
      return document;
    } catch (ParserConfigurationException | SAXException e) {
      throw new IOException("Error parsing XML: " + e.getMessage());
    }
  }
}

class XmlErrorHandlerQuiet extends DefaultHandler {
  @Override
  public void warning(SAXParseException e) throws SAXException { }

  @Override
  public void error(SAXParseException e) throws SAXException { }

  @Override
  public void fatalError(SAXParseException e) throws SAXException {
    throw e;
  }
}

