public class FileUtil {

    public static List<String> readFile(String _fileName, Charset _charset, SearchOrder _searchOrder) {
        List<String> fileContents = new ArrayList<String>();
        List<File> files = searchFiles(_fileName, _searchOrder);
        for(File file : files) {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file), _charset))) {
                String line;
                while ((line = reader.readLine()) != null)  {
                    fileContents.add(line);
                }
                return fileContents;
            } catch (IOException e) {
                // Could not load file, try with next file
            }
        }
        return null;
    }

    private static List<File> searchFiles(String _fileName, SearchOrder _searchOrder) {
        List<File> files = new ArrayList<File>();
        switch(_searchOrder) {
            case CLASSPATH_FIRST:
                files.addAll(Arrays.asList(getFromClasspath(_fileName)));
                files.addAll(Arrays.asList(getFromCustomPath(_fileName)));
                files.addAll(Arrays.asList(getFromSystemPath(_fileName)));
                break;
            case CUSTOMPATH_FIRST:
                files.addAll(Arrays.asList(getFromCustomPath(_fileName)));
                files.addAll(Arrays.asList(getFromClasspath(_fileName)));
                files.addAll(Arrays.asList(getFromSystemPath(_fileName)));
                break;
            case SYSTEMPATH_FIRST:
            default:
                files.addAll(Arrays.asList(getFromSystemPath(_fileName)));
                files.addAll(Arrays.asList(getFromCustomPath(_fileName)));
                files.addAll(Arrays.asList(getFromClasspath(_fileName)));
                break;
        }
        return files;
    }

    private static File getFromClasspath(String _fileName) {
        ClassLoader classLoader = FileUtil.class.getClassLoader();
        return new File(classLoader.getResource(_fileName).getFile());
    }

    private static File getFromCustomPath(String _fileName) {
        return new File(_fileName);
    }

    private static File getFromSystemPath(String _fileName) {
        return new File(System.getProperty("user.dir"), _fileName);
    }

    public enum SearchOrder {
        SYSTEMPATH_FIRST,
        CUSTOMPATH_FIRST,
        CLASSPATH_FIRST
    }
}

