import org.apache.avro.Schema;
import org.apache.avro.Schema.Field;
import org.apache.avro.Schema.Type;

public static Schema removeProblematicFields(Schema originalSchema) {
    String schemaName = originalSchema.getName();
    Field[] fields = originalSchema.getFields().toArray(new Field[0]);
    Schema newSchema =
        Schema.createRecord(schemaName, originalSchema.getDoc(), originalSchema.getNamespace(),
                            originalSchema.isError());

    for (Field field : fields) {
        Schema fieldSchema = field.schema();
        Type fieldType = fieldSchema.getType();
        if (fieldType.equals(Type.MAP) || fieldType.equals(Type.ARRAY) || fieldType.equals(Type.ENUM)) {
            continue;
        } else if (fieldType.equals(Type.UNION)) {
            Schema nonProblematicUnionSchema = Schema.createUnion();
            for (Schema unionSchema : fieldSchema.getTypes()) {
                if (!(unionSchema.getType().equals(Type.MAP) || unionSchema.getType().equals(Type.ARRAY) ||
                      unionSchema.getType().equals(Type.ENUM))) {
                    nonProblematicUnionSchema =
                        Schema.createUnion(nonProblematicUnionSchema, unionSchema);
                }
            }
            fieldSchema = nonProblematicUnionSchema;
        }
        Schema.Field newField =
            new Schema.Field(field.name(), fieldSchema, field.doc(), field.defaultVal(),
                             field.order());
        newSchema.addField(newField);
    }
    return newSchema;
}

