public static Object[][] getCountTable(Object[][] data, int col1, int col2, int n, int m) {
    // create a Map to store the count of each unique combination
    Map<String, Integer> countMap = new HashMap<>();

    // iterate over the table data and update the countMap
    for (int i = 0; i < data.length; i++) {
        String key = data[i][col1] + "-" + data[i][col2]; // create a key by concatenating the values of the two columns
        countMap.put(key, countMap.getOrDefault(key, 0) + 1); // increment the count of the key by 1
    }

    // create the result table with n by m+1 cells
    Object[][] result = new Object[n][m+1];

    // populate the first column with labels
    result[0][0] = "Columns " + col1 + "-" + col2;
    for (int i = 1; i < n; i++) {
        result[i][0] = i; // assuming the labels are just numbers starting from 1
    }

    // populate the rest of the table with the count values
    int k = 0; // tracks the index of the next key to be processed
    for (int i = 0; i < n; i++) {
        for (int j = 1; j <= m; j++) {
            if (k >= countMap.keySet().size()) {
                result[i][j] = 0; // there are no more unique combinations, so fill the remaining cells with 0
            } else {
                String key = (String) countMap.keySet().toArray()[k]; // get the next key from the countMap
                int count = countMap.get(key); // get the count for the key
                result[i][j] = count; // add the count to the table
                k++; // increment the index of the next key to be processed
            }
        }
    }

    return result;
}

