public void deleteLocalDurableSubscription(String subscriptionId) throws SIResourceException, SIMPDestinationLockedException, SIDurableSubscriptionNotFoundException {
    WsDestinationManager destinationManager = WsDestinationManagerFactory.getDestinationManager();
    WsDestination destination = destinationManager.getDestination(subscriptionId, DestinationType.DURABLE_SUBSCRIPTION);

    if (destination == null) {
        throw new SIDurableSubscriptionNotFoundException("Durable subscription not found: " + subscriptionId);
    }

    if (destination.isLocked(LockType.WRITE)) {
        throw new SIMPDestinationLockedException("Durable subscription is locked: " + subscriptionId);
    }

    destinationManager.deleteDestination(destination);
}

