public static Vector rotateVectorAroundAxis(double angle, double x, double y, double z, Vector vectorToRotate) {

    double sinHalfAngle = Math.sin(angle / 2);
    double cosHalfAngle = Math.cos(angle / 2);

    double rx = x * sinHalfAngle;
    double ry = y * sinHalfAngle;
    double rz = z * sinHalfAngle;
    double rw = cosHalfAngle;

    Quaternion rotation = new Quaternion(rx, ry, rz, rw);
    Quaternion conjugate = rotation.conjugate();

    Quaternion quaternion = new Quaternion(vectorToRotate.getX(), vectorToRotate.getY(), vectorToRotate.getZ(), 0);
    Quaternion rotatedQuaternion = rotation.multiply(quaternion).multiply(conjugate);

    return new Vector(rotatedQuaternion.getX(), rotatedQuaternion.getY(), rotatedQuaternion.getZ());
}

