import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Map;

public class UrlContentFetcher {

    public static byte[] getContentFromUrl(String url, Map<String, String> inCookies, Map<String, String> outCookies) throws Exception {
        URL obj = new URL(url);
        HttpURLConnection con = (HttpURLConnection) obj.openConnection();
        if (inCookies != null) {
            StringBuilder cookieBuilder = new StringBuilder();
            for (Map.Entry<String, String> entry : inCookies.entrySet()) {
                cookieBuilder.append(entry.getKey()).append("=").append(entry.getValue()).append(";");
            }
            con.setRequestProperty("Cookie", cookieBuilder.toString());
        }
        con.setRequestMethod("GET");
        if (outCookies != null) {
            String headerName;
            for (int i = 1; (headerName = con.getHeaderFieldKey(i)) != null; i++) {
                if (headerName.equals("Set-Cookie")) {
                    String cookie = con.getHeaderField(i);
                    String cookieName = cookie.split("=")[0];
                    String cookieValue = cookie.split("=")[1];
                    outCookies.put(cookieName, cookieValue);
                }
            }
        }
        BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
        String inputLine;
        StringBuilder response = new StringBuilder();
        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();
        return response.toString().getBytes();
    }
}

