public Trie populateTrie(String[] data) {
    Trie trie = new Trie();
    for(String s : data) {
        String compacted = compactString(s);
        trie.addWord(compacted);
    }
    trie.optimize();
    return trie;
}

private String compactString(String s) {
    StringBuilder result = new StringBuilder();
    for(int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if(Character.isLetterOrDigit(c)) {
            result.append(c);
        }
    }
    return result.toString();
}

