public static double[] solveEquation(double[][] A, double[] b) {
    int n = A.length;
    if (b.length != n) {
        throw new IllegalArgumentException("Matrix row dimensions must agree.");
    }

    // Check if A is symmetric and positive definite
    for (int i = 0; i < n; i++) {
        if (A[i][i] <= 0) {
            throw new RuntimeException("Matrix is not symmetric positive definite.");
        }
        for (int j = i + 1; j < n; j++) {
            if (A[i][j] != A[j][i]) {
                throw new RuntimeException("Matrix is not symmetric positive definite.");
            }
        }
    }

    // Cholesky decomposition
    double[][] L = new double[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
            double sum = 0;
            for (int k = 0; k < j; k++) {
                sum += L[i][k] * L[j][k];
            }
            if (i == j) {
                L[i][j] = Math.sqrt(A[i][i] - sum);
            } else {
                L[i][j] = (A[i][j] - sum) / L[j][j];
            }
        }
    }

    // Forward substitution
    double[] y = new double[n];
    for (int i = 0; i < n; i++) {
        double sum = 0;
        for (int j = 0; j < i; j++) {
            sum += L[i][j] * y[j];
        }
        y[i] = (b[i] - sum) / L[i][i];
    }

    // Backward substitution
    double[] x = new double[n];
    for (int i = n - 1; i >= 0; i--) {
        double sum = 0;
        for (int j = i + 1; j < n; j++) {
            sum += L[j][i] * x[j];
        }
        x[i] = (y[i] - sum) / L[i][i];
    }

    return x;
}

