public SyncToolConfig parseCommandLineConfig(String[] args) {
    Options options = new Options();

    // add command line options
    Option sourceDir = new Option("s", "source", true, "source directory path (required)");
    sourceDir.setRequired(true);
    options.addOption(sourceDir);

    Option destDir = new Option("d", "destination", true, "destination directory path (required)");
    destDir.setRequired(true);
    options.addOption(destDir);

    Option port = new Option("p", "port", true, "port number (optional)");
    options.addOption(port);

    Option interval = new Option("i", "interval", true, "sync interval in seconds (required)");
    interval.setRequired(true);
    options.addOption(interval);

    // parse command line arguments into CommandLine object
    CommandLineParser parser = new BasicParser();
    CommandLine cmd;
    try {
        cmd = parser.parse(options, args);
    } catch (ParseException e) {
        System.err.println("Error parsing command line arguments: " + e.getMessage());
        printHelpMessage(options);
        System.exit(1);
        return null; // unreachable code
    }

    // convert CommandLine object to SyncToolConfig object
    SyncToolConfig config = new SyncToolConfig();
    config.setSourceDir(cmd.getOptionValue("source"));
    config.setDestDir(cmd.getOptionValue("destination"));
    config.setSyncInterval(Integer.parseInt(cmd.getOptionValue("interval")));

    if (cmd.hasOption("port")) {
        config.setPort(Integer.parseInt(cmd.getOptionValue("port")));
    }

    // validate config values
    if (config.getSourceDir() == null || config.getDestDir() == null) {
        System.err.println("Error: source and destination directories are required.");
        printHelpMessage(options);
        System.exit(1);
    }

    if (config.getSyncInterval() <= 0) {
        System.err.println("Error: sync interval must be greater than 0.");
        printHelpMessage(options);
        System.exit(1);
    }

    return config;
}

private void printHelpMessage(Options options) {
    HelpFormatter formatter = new HelpFormatter();
    formatter.printHelp("SyncTool", options);
}

