public void addColumnsFromSecondWorksheet(Sheet worksheet) throws Exception {
    Sheet masterWorksheet = workbook.getSheetAt(0); // assuming master worksheet is always the first one
    int numColumnsInMaster = masterWorksheet.getRow(0).getLastCellNum();
    int numColumnsInAppend = worksheet.getRow(0).getLastCellNum();

    // create a mapping of the common row values to their index in the master worksheet
    Map<String, Integer> rowMapping = new HashMap<>();
    for (int i = 1; i <= masterWorksheet.getLastRowNum(); i++) {
        Row row = masterWorksheet.getRow(i);
        String commonValue = row.getCell(0).getStringCellValue(); // assuming the common value is in the first column
        rowMapping.put(commonValue, i);
    }

    // loop through the rows in the appended worksheet
    for (int i = 1; i <= worksheet.getLastRowNum(); i++) {
        Row row = worksheet.getRow(i);
        String commonValue = row.getCell(0).getStringCellValue(); // assuming the common value is in the first column
        if (rowMapping.containsKey(commonValue)) {
            int rowIndex = rowMapping.get(commonValue);
            Row masterRow = masterWorksheet.getRow(rowIndex);
            // copy each column from the appended worksheet to the corresponding column in the master worksheet
            for (int j = 1; j < numColumnsInAppend; j++) {
                Cell appendCell = row.getCell(j);
                Cell masterCell = masterRow.getCell(numColumnsInMaster + j, Row.MissingCellPolicy.CREATE_NULL_AS_BLANK);
                if (appendCell.getCellType() == CellType.NUMERIC) {
                    masterCell.setCellValue(appendCell.getNumericCellValue());
                } else {
                    masterCell.setCellValue(appendCell.getStringCellValue());
                }
            }
        } else {
            // common value not found in master worksheet, use default value of ""
            Row newRow = masterWorksheet.createRow(masterWorksheet.getLastRowNum() + 1);
            newRow.createCell(0).setCellValue(commonValue);
            for (int j = 1; j < numColumnsInAppend; j++) {
                Cell appendCell = row.getCell(j);
                Cell newCell = newRow.createCell(numColumnsInMaster + j, CellType.STRING);
                newCell.setCellValue("");
            }
        }
    }
}

