import java.util.ArrayList;
import java.util.List;

public static List<String> findAllClassesInPackage(String pkg, boolean recursive) {
    List<String> classes = new ArrayList<>();
    String pkgDirName = pkg.replace('.', '/');

    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    try {
        for (URL url : Collections.list(classLoader.getResources(pkgDirName))) {
            File directory = new File(url.getFile());
            if (directory.exists()) {
                String[] files = directory.list();
                for (String fileName : files) {
                    if (fileName.endsWith(".class")) {
                        String className = pkg + '.' + fileName.substring(0, fileName.length() - 6);
                        classes.add(className);
                    }
                    if (recursive) {
                        String fullFileName = directory + "/" + fileName;
                        File file = new File(fullFileName);
                        if (file.isDirectory()) {
                            classes.addAll(findAllClassesInPackage(pkg + "." + fileName, true));
                        }
                    }
                }
            }
        }
    } catch (IOException ex) {
        ex.printStackTrace();
    }
    return classes;
}

