public static String generateXMLFromProperties(File params) throws IOException {
    Properties properties = new Properties();
    properties.load(new FileReader(params));

    DocumentBuilderFactory docFactory = DocumentBuilderFactory.newInstance();
    DocumentBuilder docBuilder;
    try {
        docBuilder = docFactory.newDocumentBuilder();
    } catch (ParserConfigurationException e) {
        throw new RuntimeException("Error creating DocumentBuilder", e);
    }

    Document doc = docBuilder.newDocument();
    Element rootElement = doc.createElement("features");
    doc.appendChild(rootElement);

    for (String key : properties.stringPropertyNames()) {
        String value = properties.getProperty(key);

        Element feature = doc.createElement("feature");
        feature.setAttribute("name", key);
        feature.setAttribute("enabled", value);
        rootElement.appendChild(feature);
    }

    StringWriter writer = new StringWriter();
    TransformerFactory transformerFactory = TransformerFactory.newInstance();
    Transformer transformer = transformerFactory.newTransformer();
    transformer.transform(new DOMSource(doc), new StreamResult(writer));

    return writer.getBuffer().toString();
}

