import java.io.File;
import java.io.FileFilter;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Spider {

    public Map<String, Object> spiderDirectory(File directory, List<File> snapshots, FileFilter filter, boolean validate) throws Exception {

        Map<String, Object> summary = new HashMap<>();

        // count of partitions
        int partitionCount = 0;

        // list of partition information
        List<Map<String, Object>> partitionInfoList = new ArrayList<>();

        // list of files
        List<File> fileList = new ArrayList<>();

        // list of file digests
        Map<File, String> fileDigestMap = new HashMap<>();

        // traverse the directory tree and apply the filter 
        traverseDirectory(directory, filter, fileList);

        // generate digests for each file if validate is enabled
        if (validate) {
            for (File file : fileList) {
                String fileDigest = generateDigest(file);
                fileDigestMap.put(file, fileDigest);
            }
        }

        // loop through the snapshot files and verify them against the file digests
        for (File snapshot : snapshots) {
            boolean isValid = true;
            for (File file : fileList) {
                if (snapshot.getName().equals(file.getName())) {
                    // file found, compare digests
                    String fileDigest = fileDigestMap.get(file);
                    String digest = generateDigest(snapshot);
                    if (!fileDigest.equals(digest)) {
                        // digest does not match, snapshot is not valid
                        isValid = false;
                        break;
                    }
                }
            }
            if (isValid) {
                // snapshot is valid, extract partition information
                partitionCount++;
                Map<String, Object> partitionInfo = extractPartitionInfo(snapshot);
                partitionInfoList.add(partitionInfo);
            }
        }

        summary.put("partitionCount", partitionCount);
        summary.put("partitionInfoList", partitionInfoList);
        summary.put("fileList", fileList);
        summary.put("fileDigestMap", fileDigestMap);

        return summary;
    }

    private void traverseDirectory(File directory, FileFilter filter, List<File> fileList) {
        if (directory.isDirectory()) {
            File[] files = directory.listFiles(filter);
            if (files != null) {
                for (File file : files) {
                    if (file.isDirectory()) {
                        traverseDirectory(file, filter, fileList);
                    } else {
                        fileList.add(file);
                    }
                }
            }
        }
    }

    private String generateDigest(File file) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        FileInputStream fis = new FileInputStream(file);
        byte[] dataBytes = new byte[1024];
        int nread = 0;
        while ((nread = fis.read(dataBytes)) != -1) {
            md.update(dataBytes, 0, nread);
        };
        byte[] mdbytes = md.digest();
        StringBuffer hexString = new StringBuffer();
        for (int i = 0; i < mdbytes.length; i++) {
            String hex = Integer.toHexString(0xff & mdbytes[i]);
            if (hex.length() == 1)
                hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private Map<String, Object> extractPartitionInfo(File snapshot) {
        // assume this method extracts partition information from the snapshot file
        return new HashMap<>();
    }
}

