public final AntlrDatatypeRuleToken ruleNumber() throws RecognitionException {
    AntlrDatatypeRuleToken current = new AntlrDatatypeRuleToken();

    if (this.match(RULE_HEX)) {
        current.setValue(this.getHexValue());
    } else if (this.match(RULE_INT) || this.match(RULE_DECIMAL)) {
        StringBuilder sb = new StringBuilder();
        sb.append(this.getText());

        if (this.match('.')) {
            sb.append('.');

            if (this.match(RULE_INT) || this.match(RULE_DECIMAL)) {
                sb.append(this.getText());
            } else {
                throw new RecognitionException("Expected INT or DECIMAL after '.'");
            }
        }

        current.setValue(sb.toString());
    } else {
        throw new RecognitionException("Expected HEX, INT or DECIMAL");
    }

    return current;
}

