private void removeUnwantedMsgs(List<SIMPMessage> unwantedMsgList, TransactionCommon tran) throws SIResourceException {
    Iterator<SIMPMessage> iterator = unwantedMsgList.iterator();
    while (iterator.hasNext()) {
