public Tensor conv3d(Tensor inputs, Conv3DConfig conv3DConfig) {
    int batchSize = inputs.getShape()[0];
    int inDepth = inputs.getShape()[1];
    int inHeight = inputs.getShape()[2];
    int inWidth = inputs.getShape()[3];

    int outDepth = conv3DConfig.getKernelDepth();
    int outHeight = conv3DConfig.getKernelHeight();
    int outWidth = conv3DConfig.getKernelWidth();

    int strideDepth = conv3DConfig.getStrideDepth();
    int strideHeight = conv3DConfig.getStrideHeight();
    int strideWidth = conv3DConfig.getStrideWidth();

    int paddingDepth = conv3DConfig.getPaddingDepth();
    int paddingHeight = conv3DConfig.getPaddingHeight();
    int paddingWidth = conv3DConfig.getPaddingWidth();

    int dilationDepth = conv3DConfig.getDilationDepth();
    int dilationHeight = conv3DConfig.getDilationHeight();
    int dilationWidth = conv3DConfig.getPaddingWidth();

    int filterCount = conv3DConfig.getFilterCount();
    int filterDepth = conv3DConfig.getKernelDepth();
    int filterHeight = conv3DConfig.getKernelHeight();
    int filterWidth = conv3DConfig.getKernelWidth();
    int bias = conv3DConfig.getBias();

    // perform convolution
    Tensor output = new Tensor(batchSize, filterCount, convolveOutputSize(inDepth, outDepth, strideDepth, paddingDepth, dilationDepth),
            convolveOutputSize(inHeight, outHeight, strideHeight, paddingHeight, dilationHeight), convolveOutputSize(inWidth, outWidth, strideWidth, paddingWidth, dilationWidth));
    for (int b = 0; b < batchSize; b++) {
        for (int f = 0; f < filterCount; f++) { 
            for (int z = 0; z < outDepth; z++) {
                for (int y = 0; y < outHeight; y++) {
                    for (int x = 0; x < outWidth; x++) {
                        float result = bias;
                        for (int d = 0; d < filterDepth; d++) {
                            for (int h = 0; h < filterHeight; h++) {
                                for (int w = 0; w < filterWidth; w++) {
                                    int originZ = z * strideDepth + d * dilationDepth - paddingDepth;
                                    int originY = y * strideHeight + h * dilationHeight - paddingHeight;
                                    int originX = x * strideWidth + w * dilationWidth - paddingWidth;
                                    if (originZ >= 0 && originZ < inDepth && originY >= 0 && originY < inHeight && originX >= 0 && originX < inWidth) {
                                        float inputValue = inputs.get(b, originZ, originY, originX, f);
                                        float filterValue = conv3DConfig.getFilter().get(d, h, w, f);
                                        result += inputValue * filterValue;
                                    }
                                }
                            }
                        }
                        output.set(b, f, z, y, x, result);
                    }
                }
            }
        }
    }
    return output;
}

private int convolveOutputSize(int inSize, int kernelSize, int stride, int padding, int dilation) {
    return ((inSize + 2 * padding - dilation * (kernelSize - 1) - 1) / stride + 1);
}

