import android.content.ContentResolver;
import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.net.Uri;
import android.os.Build;

import java.io.IOException;
import java.io.InputStream;

public class BitmapLoader {

    public static Bitmap loadBitmap(Uri uri, Bitmap dest, Context context) throws ImageLoadException {
        ContentResolver resolver = context.getContentResolver();

        try (InputStream is = resolver.openInputStream(uri)) {
            BitmapFactory.Options options = new BitmapFactory.Options();

            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
                if (dest != null) {
                    int width = dest.getWidth();
                    int height = dest.getHeight();

                    options.inBitmap = dest;
                    options.inMutable = true;
                    options.inSampleSize = calculateInSampleSize(width, height, options);
                }

                options.inPreferredConfig = Bitmap.Config.ARGB_8888;
                options.inPremultiplied = true;

            } else {
                options.inPreferredConfig = Bitmap.Config.RGB_565;
            }

            return BitmapFactory.decodeStream(is, null, options);
        } catch (IOException e) {
            throw new ImageLoadException("Unable to load file", e);
        }
    }

    private static int calculateInSampleSize(int reqWidth, int reqHeight, BitmapFactory.Options options) {
        final int height = options.outHeight;
        final int width = options.outWidth;

        int inSampleSize = 1;

        if (height > reqHeight || width > reqWidth) {
            final int halfHeight = height / 2;
            final int halfWidth = width / 2;

            while ((halfHeight / inSampleSize) >= reqHeight && (halfWidth / inSampleSize) >= reqWidth) {
                inSampleSize *= 2;
            }
        }

        return inSampleSize;
    }
}

class ImageLoadException extends Exception {
    public ImageLoadException(String message, Throwable cause) {
        super(message, cause);
    }
}

