public double[] fastCosineTransform(double[] data) {
  int n = data.length;
  double[] result = new double[n];

  for (int k = 0; k < n; k++) {
    double sum = 0;
    for (int j = 0; j < n; j++) {
      sum += data[j] * Math.cos(Math.PI * k * (j + 0.5) / n);
    }
    result[k] = sum;
  }

  return result;
}

