public void writeCatalogToXML(Catalog catalog, OutputStream os, boolean raw) throws IOException {
    // Create a new Document
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    DocumentBuilder builder = factory.newDocumentBuilder();
    DOMImplementation impl = builder.getDOMImplementation();
    Document doc = impl.createDocument(null, "catalog", null);

    // Root Element
    Element root = doc.getDocumentElement();

    // Add Elements to the Catalog
    for (Product product : catalog.getProducts()) {
        Element productElement = doc.createElement("product");
        productElement.setAttribute("id", String.valueOf(product.getId()));
        productElement.setAttribute("name", product.getName());
        productElement.setAttribute("price", String.valueOf(product.getPrice()));
        productElement.setAttribute("description", product.getDescription());
        root.appendChild(productElement);
    }

    // Write XML to Stream
    TransformerFactory tfactory = TransformerFactory.newInstance();
    Transformer xform = tfactory.newTransformer();
    xform.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION, "no");
    xform.setOutputProperty(OutputKeys.METHOD, "xml");
    xform.setOutputProperty(OutputKeys.ENCODING, "UTF-8");
    if (raw)
        xform.setOutputProperty(OutputKeys.INDENT, "no");
    else
        xform.setOutputProperty(OutputKeys.INDENT, "yes");
    xform.setOutputProperty(OutputKeys.DOCTYPE_SYSTEM, "catalog.dtd");
    xform.setOutputProperty("{http://xml.apache.org/xslt}indent-amount", "4");

    DOMSource source = new DOMSource(doc);

    StreamResult result = new StreamResult(new OutputStreamWriter(os, "UTF-8"));

    xform.transform(source, result);
}

