import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class ConfigurationParser {

    public List<Long> getConfigurations(String config, String path, TimeUnit timeUnit) {
        List<Long> durations = new ArrayList<>();
        String[] pathSplit = path.split("\\.");

        try {
            // Get nested configuration
            for (String pathSegment : pathSplit) {
                if (config == null || config.isEmpty()) {
                    return null;
                }
                config = config.substring(config.indexOf(pathSegment) + pathSegment.length());
            }
            // Get list of durations
            String durationsString = config.split(":")[1];
            for (String dur : durationsString.split(",")) {
                durations.add(parseDurationString(dur.trim(), timeUnit));
            }
            return durations;
        } catch (Exception ex) {
            return null;
        }
    }

    private long parseDurationString(String durationString, TimeUnit timeUnit) {
        long duration = Long.parseLong(durationString.replaceAll("[^0-9]", ""));
        String timeUnitString = durationString.replaceAll("[^a-zA-Z]", "");
        TimeUnit unit = TimeUnit.SECONDS;
        switch (timeUnitString.toLowerCase()) {
            case "d":
                unit = TimeUnit.DAYS;
                break;
            case "h":
                unit = TimeUnit.HOURS;
                break;
            case "m":
                unit = TimeUnit.MINUTES;
                break;
            case "s":
                unit = TimeUnit.SECONDS;
                break;
            case "ms":
                unit = TimeUnit.MILLISECONDS;
                break;
            case "us":
                unit = TimeUnit.MICROSECONDS;
                break;
            case "ns":
                unit = TimeUnit.NANOSECONDS;
                break;
        }
        return timeUnit.convert(duration, unit);
    }
}

