import com.google.common.collect.Multimap;
import com.google.common.collect.Synchronized;
import com.google.common.collect.Synchronized$SynchronizedAsMapEntries;
import com.google.common.collect.Synchronized.SynchronizedMultimap;

import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

import static java.util.stream.Collectors.toList;
import static java.util.stream.Collectors.toConcurrentMap;
import static java.util.stream.Collectors.toList;

public class ParallelIterate {

    public static <T, K> Multimap<K, T> groupBy(Iterable<T> iterable, Function<T, K> function, int batchSize) {
        SynchronizedMultimap<K, T> multimap = Synchronized.multimap(Synchronized.fastListMultimap());
        iterable.forEach(elem -> multimap.put(function.apply(elem), elem));

        Map<K, Collection<T>> map = multimap.asMap();
        return map.keySet().parallelStream()
                .flatMap(key -> partition(map.get(key), batchSize).stream().map(list -> Pair.of(key, list)))
                .collect(toConcurrentMap(Pair::getLeft, pair -> pair.getRight(), ParallelIterate::mergeList))
                .entrySet().stream()
                .collect(toConcurrentMap(Map.Entry::getKey, entry -> Synchronized.listMultimap(entry.getValue()).asMap().values().stream().flatMap(Collection::stream).collect(toList())))
                .entrySet().stream()
                .collect(toConcurrentMap(Map.Entry::getKey, Map.Entry::getValue, ParallelIterate::mergeList));

    }

    private static <T> List<List<T>> partition(Collection<T> collection, int batchSize) {
        return collection.stream()
                .collect(toList())
                .stream()
                .collect(toPartition(batchSize));
    }

    private static <K, V> ListMultimap<K, V> mergeList(ListMultimap<K, V> left, ListMultimap<K, V> right) {
        left.putAll(right);
        return left;
    }

    private static <T> Collector<T, ?, List<List<T>>> toPartition(int batchSize) {
        return Collector.of(ArrayList::new,
                (list, elem) -> {
                    List<T> last = list.isEmpty() ? null : list.get(list.size() - 1);
                    if (last == null || last.size() == batchSize) {
                        last = new ArrayList<>();
                        list.add(last);
                    }
                    last.add(elem);
                },
                (left, right) -> {
                    // Only required in parallel streams.
                    throw new UnsupportedOperationException("Parallel streams not supported.");
                });
    }

    private static class Pair<L, R> {
        private final L left;
        private final R right;

        private Pair(L left, R right) {
            this.left = left;
            this.right = right;
        }

        public static <L, R> Pair<L, R> of(L left, R right) {
            return new Pair<>(left, right);
        }

        public L getLeft() {
            return left;
        }

        public R getRight() {
            return right;
        }
    }
}

