import java.lang.ref.WeakReference;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.WatchKey;
import java.nio.file.WatchService;
import java.nio.file.StandardWatchEventKinds;
import java.nio.file.WatchEvent.Kind;

public class Watcher {

    public static void startWatching(String file, WatcherService watcher) throws IOException {
        Path path = Paths.get(file);
        WatchService watchService = path.getFileSystem().newWatchService();
        WatchKey watchKey = path.register(watchService, StandardWatchEventKinds.ENTRY_MODIFY);
        while (true) {
            try {
                watchService.take();
                watcher.onFileChanged();
            } catch (InterruptedException e) {
                return;
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}

public interface WatcherService {
    void onFileChanged();
}

class WeakWatcher implements WatcherService {

    private final WeakReference<WatcherService> watcherRef;

    public WeakWatcher(WatcherService watcher) {
        watcherRef = new WeakReference<>(watcher);
    }

    public void onFileChanged() {
        WatcherService watcher = watcherRef.get();
        if (watcher != null) {
            watcher.onFileChanged();
        }
    }
}

