        transformer.transform(new DOMSource(component), new StreamResult(writer));
        String xmlString = writer.getBuffer().toString();
        File outputFile = new File(deploymentDir, componentJarFileName + ".xml");
        try (FileWriter fileWriter = new FileWriter(outputFile)) {
            fileWriter.write(xmlString);
        }
    } catch (IOException | ParserConfigurationException | SAXException | TransformerException ex) {
        throw new DeploymentException("Error building component from jar " + componentJarFileName + " in " + deployableUnitJar, ex);
