public void generateMapFile(File jarFile, String mapFileName, boolean mapClassMethods) throws XMLStreamException, IOException, ClassNotFoundException, IntrospectionException {
    try (JarFile jar = new JarFile(jarFile)) {
        Map<String, List<Member>> map = new HashMap<>();
        for (Enumeration<JarEntry> entries = jar.entries(); entries.hasMoreElements(); ) {
            JarEntry entry = entries.nextElement();
            if (entry.getName().endsWith(".class")) {
                String className = entry.getName().replace('/', '.');
                className = className.substring(0, className.length() - ".class".length());
                Class<?> clazz = Class.forName(className);
                if (clazz.isSynthetic()) continue;
                List<Member> members = new ArrayList<>();
                if (mapClassMethods) {
                    members.addAll(Arrays.asList(clazz.getMethods()));
                    members.addAll(Arrays.asList(clazz.getDeclaredMethods()));
                } else {
                    members.addAll(Arrays.asList(clazz.getConstructors()));
                    members.addAll(Arrays.asList(clazz.getDeclaredConstructors()));
                    members.addAll(Arrays.asList(clazz.getFields()));
                    members.addAll(Arrays.asList(clazz.getDeclaredFields()));
                }
                members.removeIf(member -> member.isSynthetic() || member.isBridge());
                map.put(className, members);
            }
        }
        try (OutputStreamWriter writer = new OutputStreamWriter(new FileOutputStream(mapFileName), StandardCharsets.UTF_8)) {
            XMLStreamWriter xmlWriter = XMLOutputFactory.newFactory().createXMLStreamWriter(writer);
            xmlWriter.writeStartDocument();
            xmlWriter.writeStartElement("map");
            for (Map.Entry<String, List<Member>> entry : map.entrySet()) {
                xmlWriter.writeStartElement("class");
                xmlWriter.writeAttribute("name", entry.getKey());
                for (Member member : entry.getValue()) {
                    if (member instanceof Constructor) {
                        xmlWriter.writeStartElement("constructor");
                    } else if (member instanceof Method) {
                        xmlWriter.writeStartElement("method");
                    } else if (member instanceof Field) {
                        xmlWriter.writeStartElement("field");
                    }
                    xmlWriter.writeAttribute("name", member.getName());
                    xmlWriter.writeAttribute("declaringClass", member.getDeclaringClass().getName());
                    xmlWriter.writeEndElement();
                }
                xmlWriter.writeEndElement();
            }
            xmlWriter.writeEndElement();
            xmlWriter.writeEndDocument();
        }
    }
}

