@SuppressWarnings("unchecked") public <INKEY,INVALUE,OUTKEY,OUTVALUE, T extends org.apache.hadoop.mapreduce.InputSplit> void run() throws Exception {
	// Get the input splits
    List<T> splits = (List<T>) jobContext.getInputSplit();
    // Create map tasks
    List<Callable<Void>> tasks = new ArrayList<>();
    for (T split : splits) {
        tasks.add(new MapTask<>(jobContext, split));
    }
    // Submit tasks to thread pool or run them sequentially
    if (threadPool != null) {
        threadPool.invokeAll(tasks);
    } else {
        for (Callable<Void> task : tasks) {
            task.call();
        }
    }
}

