import java.util.ArrayList;
import java.util.List;

public class CrossProductIterator {

    public static Generator iterateOverCrossProduct(SpecifiedIndex[] indexes) throws IllegalArgumentException {
        for (SpecifiedIndex index : indexes) {
            if (index.opType != SpecifiedIndex.OpType.SPECIFIED) {
                throw new IllegalArgumentException("All elements of the array should be of opType Specified.");
            }
        }
        List<Integer[]> combinations = new ArrayList<>();
        generateCombinations(indexes, 0, new Integer[indexes.length], combinations);
        return new Generator(combinations);
    }

    private static void generateCombinations(SpecifiedIndex[] indexes, int position, Integer[] current, List<Integer[]> combinations) {
        if (position == indexes.length) {
            combinations.add(current.clone());
        } else {
            for (int i = 0; i < indexes[position].values.length; i++) {
                current[position] = indexes[position].values[i];
                generateCombinations(indexes, position + 1, current, combinations);
            }
        }
    }

    public static class SpecifiedIndex {
        public enum OpType {SPECIFIED, WILDCARD}
        public OpType opType;
        public Integer[] values;
    }

    public static class Generator {
        private List<Integer[]> combinations;
        private int pointer;

        public Generator(List<Integer[]> combinations) {
            this.combinations = combinations;
            pointer = 0;
        }

        public boolean hasNext() {
            return pointer < combinations.size();
        }

        public Integer[] getNext() {
            return combinations.get(pointer++);
        }
    }
}

