public double[][] createProportionsTable(Object[][] data, int column1, int column2) {
    int numRows = getUniqueValues(data, column1).size();
    int numCols = getUniqueValues(data, column2).size() + 1;
    double[][] table = new double[numRows][numCols];

    ArrayList<Object> labels = getUniqueValues(data, column1);
    for (int i = 0; i < numRows; i++) {
        table[i][0] = labels.get(i).toString();
    }

    for (int i = 0; i < numRows; i++) {
        Object value1 = labels.get(i);
        for (int j = 1; j < numCols; j++) {
            Object value2 = getUniqueValues(data, column2).get(j - 1);
            table[i][j] = getProportion(data, column1, value1, column2, value2);
        }
    }

    return table;
}

private ArrayList<Object> getUniqueValues(Object[][] data, int column) {
    ArrayList<Object> values = new ArrayList<Object>();
    for (int i = 0; i < data.length; i++) {
        Object value = data[i][column];
        if (!values.contains(value)) {
            values.add(value);
        }
    }
    return values;
}

private double getProportion(Object[][] data, int column1, Object value1, int column2, Object value2) {
    int count = 0;
    int total = 0;
    for (int i = 0; i < data.length; i++) {
        if (data[i][column1].equals(value1)) {
            total++;
            if (data[i][column2].equals(value2)) {
                count++;
            }
        }
    }
    return (double) count / total;
}

