public static void repackageToLaunch(File destination, File[] libraries) throws IOException {
    final Manifest manifest = new Manifest();
    final Attributes attributes = manifest.getMainAttributes();
    attributes.put(Attributes.Name.MANIFEST_VERSION, "1.0");
    attributes.put(Attributes.Name.MAIN_CLASS, destination.getName());
    attributes.put(Attributes.Name.CLASS_PATH, getClassPath(libraries));
    final FileOutputStream outputStream = new FileOutputStream(destination);
    try (final JarOutputStream jarOutputStream = new JarOutputStream(outputStream, manifest)) {
        jarOutputStream.putNextEntry(new ZipEntry(destination.getName()));
        final FileInputStream fileInputStream = new FileInputStream(destination);
        try {
            final byte[] buffer = new byte[1024];
            int length;
            while ((length = fileInputStream.read(buffer)) > 0) {
                jarOutputStream.write(buffer, 0, length);
            }
        } finally {
            fileInputStream.close();
        }
    }
}

// get the class path as a string separated by quotes
private static String getClassPath(final File[] libraries) {
    final StringBuilder stringBuilder = new StringBuilder();
    for (final File library : libraries) {
        stringBuilder.append(library.getName()).append(" ");
    }
    return stringBuilder.toString().trim();
}

