public static Object squeeze(Object array) {
    int[] shape = getShape(array);
    int numDims = shape.length;
    boolean[] squeezedDims = new boolean[numDims];
    int numTotalElements = 1;
    for (int i = 0; i < numDims; i++) {
        if (shape[i] == 1) {
            squeezedDims[i] = true;
        } else {
            numTotalElements *= shape[i];
        }
    }
    if (numTotalElements == 0) {
        numTotalElements = 1;
    }
    Class<?> type = array.getClass().getComponentType();
    Object result = Array.newInstance(type, numTotalElements);
    if (numTotalElements > 0) {
        int[] indices = new int[numDims];
        int resultIndex = 0;
        while (incrementIndices(indices, shape)) {
            if (!squeezed(indices, squeezedDims)) {
                Array.set(result, resultIndex++, getElement(array, indices));
            }
        }
    }
    return reshape(result, getShapeWithoutSqueezedDims(shape, squeezedDims));
}

private static boolean[] getShapeWithoutSqueezedDims(boolean[] squeezedDims, int[] oldShape) {
    int oldNumDims = oldShape.length;
    int newNumDims = 0;
    for (boolean squeezed : squeezedDims) {
        if (!squeezed) {
            newNumDims++;
        }
    }
    boolean[] newShape = new boolean[newNumDims];
    for (int oldDim = 0, newDim = 0; oldDim < oldNumDims; oldDim++) {
        if (!squeezedDims[oldDim]) {
            newShape[newDim++] = oldShape[oldDim] > 1;
        }
    }
    return newShape;
}

private static boolean squeezed(int[] indices, boolean[] squeezedDims) {
    int numDims = indices.length;
    for (int i = 0; i < numDims; i++) {
        if (!squeezedDims[i] && indices[i] != 0) {
            return false;
        }
    }
    return true;
}

private static boolean incrementIndices(int[] indices, int[] shape) {
    int numDims = indices.length;
    indices[numDims - 1]++;
    if (indices[numDims - 1] >= shape[numDims - 1]) {
        indices[numDims - 1] = 0;
        for (int i = numDims - 2; i >= 0; i--) {
            indices[i]++;
            if (indices[i] < shape[i]) {
                return true;
            }
            indices[i] = 0;
        }
        return false;
    }
    return true;
}

private static Object getElement(Object array, int[] indices) {
    Object result = array;
    for (int index : indices) {
        result = Array.get(result, index);
    }
    return result;
}

private static Object reshape(Object array, boolean[] newShape) {
    int oldNumDims = getShape(array).length;
    int newNumDims = newShape.length;
    if (oldNumDims == newNumDims) {
        return array;
    } else if (oldNumDims < newNumDims) {
        Object result = array;
        for (int i = oldNumDims; i < newNumDims; i++) {
            result = Array.newInstance(result.getClass(), newShape[i] ? 1 : 0);
        }
        return result;
    } else {
        int[] oldShape = getShape(array);
        Object result = array;
        for (int i = oldNumDims - 1; i >= newNumDims; i--) {
            if (oldShape[i] != 1) {
                throw new IllegalArgumentException("Cannot reshape array");
            }
        }
        int[] newRealShape = new int[newNumDims];
        for (int i = 0; i < newNumDims; i++) {
            for (int j = 0; j < oldNumDims; j++) {
                if (newShape[i] && !Array.get(oldShape, j).equals(1)) {
                    newRealShape[i] *= Array.get(oldShape, j);
                }
            }
            result = Array.newInstance(result.getClass().getComponentType(), newRealShape[i]);
        }
        incrementShape(result, newShape, 0, new int[newNumDims], oldShape, new AtomicInteger(0));
        return result;
    }
}

private static void incrementShape(Object array, boolean[] newShape, int newDim, int[] newIndices,
                                    int[] oldShape, AtomicInteger oldIndex) {
    if (newDim == newShape.length) {
        Array.set(array, newIndices.clone(), oldIndex.getAndIncrement());
    } else if (newShape[newDim]) {
        for (int i = 0; i < oldShape.length; i++) {
            newIndices[newDim] = i;
            incrementShape(array, newShape, newDim + 1, newIndices, oldShape, oldIndex);
        }
    } else {
        newIndices[newDim] = 0;
        incrementShape(array, newShape, newDim + 1, newIndices, oldShape, oldIndex);
    }
}

private static int[] getShape(Object array) {
    List<Integer> shapeList = new ArrayList<>();
    Object current = array;
    while (current.getClass().isArray()) {
        shapeList.add(Array.getLength(current));
        current = Array.get(current, 0);
    }
    int[] shape = new int[shapeList.size()];
    for (int i = 0; i < shape.length; i++) {
        shape[i] = shapeList.get(i);
    }
    return shape;
}

