    TextChunk lastChunk = new TextChunk(elements.get(0));
    textChunks.add(lastChunk);
    for (int i = 1; i < elements.size(); i++) {
        TextElement element = elements.get(i);
        if (lastChunk.shouldMerge(element)) {
            lastChunk.merge(element);
        } else {
            TextChunk newChunk = new TextChunk(element);
            textChunks.add(newChunk);
            lastChunk = newChunk;
        }
    }
    return textChunks;
