        Coordinate[] coordinates = new Coordinate[polyline.getPath().size()];
        for (int i = 0; i < polyline.getPath().size(); i++) {
            coordinates[i] = new Coordinate(polyline.getPath().get(i).lat, polyline.getPath().get(i).lng);
        }
        LineString lineString = new LineString(coordinates, new GeometryFactory());
        return lineString;
    }
    else if (shape instanceof GoogleMapPolygon) {
        GoogleMapPolygon polygon = (GoogleMapPolygon) shape;
        Coordinate[] coordinates = new Coordinate[polygon.getPaths().get(0).size()];
        for (int i = 0; i < polygon.getPaths().get(0).size(); i++) {
