public Geometry toGeometry(GoogleMapShape shape) {
    Geometry geometry = new Geometry();

    if(shape instanceof GoogleMapPoint) {
        GoogleMapPoint point = (GoogleMapPoint) shape;
        geometry.setType("Point");
        geometry.setCoordinates(new double[]{point.getX(), point.getY()});
    } else if(shape instanceof GoogleMapLine) {
        GoogleMapLine line = (GoogleMapLine) shape;
        geometry.setType("LineString");
        List<double[]> coordinates = new ArrayList<>();
        for(GoogleMapPoint point : line.getPoints()) {
            coordinates.add(new double[]{point.getX(), point.getY()});
        }
        geometry.setCoordinates(coordinates.toArray(new double[0][]));
    } else if(shape instanceof GoogleMapPolygon) {
        GoogleMapPolygon polygon = (GoogleMapPolygon) shape;
        geometry.setType("Polygon");
        List<double[]> coordinates = new ArrayList<>();
        for(GoogleMapPoint point : polygon.getPoints()) {
            coordinates.add(new double[]{point.getX(), point.getY()});
        }
        geometry.setCoordinates(coordinates.toArray(new double[0][]));
    }

    return geometry;
}

