public float parseFloat() {
	// Assume buffer is a byte array containing the float representation
    if (buffer == null || buffer.length != 4) {
        throw new IllegalArgumentException("Buffer must be exactly 4 bytes long");
    }
    int intBits = (buffer[0] & 0xFF) << 24 |
                  (buffer[1] & 0xFF) << 16 |
                  (buffer[2] & 0xFF) << 8  |
                  (buffer[3] & 0xFF);
    return Float.intBitsToFloat(intBits);
}

