public void populateArrays(List<ActivitySession> activitySessionList, List<Transaction> transactionList, List<EjbMethod> ejbMethods, String[] transactionAttrs, String[] activitySessionAttrs) {
    // Populating transactionAttrs array
    int i = 0;
    for (Transaction transaction : transactionList) {
        transactionAttrs[i++] = transaction.getMetadata();
    }

    // Populating activitySessionAttrs array
    i = 0;
    for (ActivitySession activitySession : activitySessionList) {
        activitySessionAttrs[i++] = activitySession.getMetadata();
    }

    // Populating transactionAttrs and activitySessionAttrs arrays from EjbMethod annotation data
    for (EjbMethod ejbMethod : ejbMethods) {
        TransactionAttribute transactionAttribute = ejbMethod.getAnnotation(TransactionAttribute.class);
        if (transactionAttribute != null) {
            transactionAttrs[i] = transactionAttribute.value().name();
        }

        ActivitySessionAttribute activitySessionAttribute = ejbMethod.getAnnotation(ActivitySessionAttribute.class);
        if (activitySessionAttribute != null) {
            activitySessionAttrs[i] = activitySessionAttribute.value().name();
        }
        i++;
    }
}

