                                                getInstanceKey(), (FieldTable) field);
                                uiFieldTable.setPagePosition(getPagePosition());
                                uiFieldTable.setMode(getMode());
                                this.elements.add(new Element(UIForm.ElementType.TABLE, uiFieldTable));
