public static Table joinTables(Table joiner, Table table2, String[] col2Names) {

    // Round the double columns mentioned in col2Names
    for (int i = 0; i < col2Names.length; i++) {
        if (table2.getColumn(col2Names[i]).getType() == ColumnType.DOUBLE) {
            table2.getColumn(col2Names[i]).applyFunction(Math::round);
        }
    }

    // Combine table2 columns with joiner columns based on column names
    for (String col : table2.getColumnNames()) {
        if (joiner.containsColumn(col) && !Arrays.asList(col2Names).contains(col)) {
            throw new IllegalArgumentException("Column '" + col + "' already exists in joiner table");
        }
        if (!joiner.addColumn(table2.getColumn(col))) {
            throw new IllegalArgumentException("Column '" + col + "' could not be added to joiner table");
        }
    }

    // Perform join operation based on specified columns
    for (String col : col2Names) {
        if (!joiner.containsColumn(col)) {
            throw new IllegalArgumentException("Column '" + col + "' does not exist in joiner table");
        }
        joiner = joiner.groupBy(col);
    }

    return joiner;
}

