public boolean removePeriodKeyObjectFromTree(Entry entry) {
    if (entry == null) {
        return false;
    }
    Node node = findNodeByPeriodAndKey(entry.p, entry.key);
    if (node == null) {
        return false;
    }
    return removeEntryFromNode(node, entry);
}

private Node findNodeByPeriodAndKey(int period, int key) {
    Node node = root;
    while (node != null) {
        if (period < node.period) {
            node = node.left;
        } else if (period > node.period) {
            node = node.right;
        } else {
            int cmp = key - node.key;
            if (cmp == 0) {
                return node;
            } else if (cmp < 0) {
                node = node.left;
            } else {
                node = node.right;
            }
        }
    }
    return null;
}

private boolean removeEntryFromNode(Node node, Entry entry) {
    for (Iterator<Entry> it = node.entries.iterator(); it.hasNext();) {
        Entry e = it.next();
        if (e.equals(entry)) {
            it.remove();
            return true;
        }
    }
    return false;
}

public class Node {
    int period;
    int key;
    Set<Entry> entries;
    Node left;
    Node right;

    public Node(int period, int key, Entry entry) {
        this.period = period;
        this.key = key;
        this.entries = new HashSet<>();
        this.entries.add(entry);
    }
}

