        } else {
          throw constructConvertNotSupportedException(descriptor, column);
        }
        break;
      case BINARY:




        for (int i = rowId; i < rowId + num; ++i) {
          if (!column.isNullAt(i)) {
            Binary v = dictionary.decodeToBinary(dictionaryIds.getDictId(i));
