public void initializeQueryAndTargetAtoms(String sourceMolFileName, String targetMolFileName, boolean removeHydrogen, boolean cleanAndConfigureMolecule) throws CDKException {
    // First, read the source mol file
    File sourceMolFile = new File(sourceMolFileName);
    MDLV2000Reader sourceMolReader = new MDLV2000Reader(new FileInputStream(sourceMolFile));
    IChemObjectBuilder builder = DefaultChemObjectBuilder.getInstance();
    IAtomContainer sourceMol = builder.newInstance(IAtomContainer.class);
    sourceMolReader.read(sourceMol);
    sourceMolReader.close();

    // If necessary, remove hydrogen atoms from the source molecule
    if (removeHydrogen) {
        AtomContainerManipulator.percieveAtomTypesAndConfigureAtoms(sourceMol);
        sourceMol = AtomContainerManipulator.removeHydrogens(sourceMol);
    }

    // Clean and configure the source molecule if necessary
    if (cleanAndConfigureMolecule) {
        CDKHydrogenAdder adder = CDKHydrogenAdder.getInstance(builder);
        adder.addImplicitHydrogens(sourceMol);
        Aromaticity aromaticity = new Aromaticity(ElectronDonation.cdk(), CyclizationFinder.all());
        aromaticity.apply(sourceMol);
    }

    // Read the target mol file
    File targetMolFile = new File(targetMolFileName);
    MDLV2000Reader targetMolReader = new MDLV2000Reader(new FileInputStream(targetMolFile));
    IAtomContainer targetMol = builder.newInstance(IAtomContainer.class);
    targetMolReader.read(targetMol);
    targetMolReader.close();

    // If necessary, remove hydrogen atoms from the target molecule
    if (removeHydrogen) {
        AtomContainerManipulator.percieveAtomTypesAndConfigureAtoms(targetMol);
        targetMol = AtomContainerManipulator.removeHydrogens(targetMol);
    }

    // Clean and configure the target molecule if necessary
    if (cleanAndConfigureMolecule) {
        CDKHydrogenAdder adder = CDKHydrogenAdder.getInstance(builder);
        adder.addImplicitHydrogens(targetMol);
        Aromaticity aromaticity = new Aromaticity(ElectronDonation.cdk(), CyclizationFinder.all());
        aromaticity.apply(targetMol);
    }
}

