import java.util.Iterator;
import java.util.stream.IntStream;
import java.util.stream.StreamSupport;

public class IntSetFactory {

    public static IntSet fromIterator(Iterator<Integer> iterator) {
        int[] values = StreamSupport.stream(((Iterable<Integer>) () -> iterator).spliterator(), false)
                                    .mapToInt(Integer::intValue)
                                    .toArray();
        return fromArray(values);
    }

    public static IntSet fromArray(int[] values) {
        if (values.length == 0) {
            return new BitIntSet(0);
        } else if (values.length == 1) {
            return new SingleIntSet(values[0]);
        } else if (values.length < 64) {
            return new BitIntSet(values);
        } else {
            return new HashIntSet(IntStream.of(values).boxed().distinct().toArray(Integer[]::new));
        }
    }
}

interface IntSet extends Iterable<Integer> {
    int size();
    boolean add(int value);
    boolean contains(int value);
    boolean remove(int value);
}

class SingleIntSet implements IntSet {
    private int value;

    public SingleIntSet(int value) {
        this.value = value;
    }

    public int size() {
        return 1;
    }

    public boolean add(int value) {
        if (this.value == value) {
            return false;
        } else {
            throw new UnsupportedOperationException();
        }
    }

    public boolean contains(int value) {
        return this.value == value;
    }

    public boolean remove(int value) {
        if (this.value == value) {
            this.value = 0;
            return true;
        } else {
