            }

            public Integer next() {
                if (hasNext) {
                    hasNext = false;
                    return value;
                } else {
                    throw new UnsupportedOperationException();
                }
            }

            public void remove() {
                if (hasNext) {
                    throw new UnsupportedOperationException();
                }
            }
        };
    }
}

class BitIntSet implements IntSet {
    private long bits = 0;

    public BitIntSet(int value) {
        add(value);
    }

    public BitIntSet(int[] values) {
        for (int value : values) {
            add(value);
        }
    }

    public int size() {
        return Long.bitCount(bits);
    }

    public boolean add(int value) {
        long mask = 1L << value;
        boolean modified = (bits & mask) == 0;
        bits |= mask;
        return modified;
    }

    public boolean contains(int value) {
        return (bits & (1L << value)) != 0;
    }

    public boolean remove(int value) {
        long mask = 1L << value;
        boolean modified = (bits & mask) != 0;
        bits &= ~mask;
        return modified;
    }

    public Iterator<Integer> iterator() {
        return new Iterator<Integer>() {
            private int index = -1;

            public boolean hasNext() {
                return index < 63;
            }

            public Integer next() {
                if (index < 63) {
                    do {
                        index++;
                    } while (index < 64 && !contains(index));
                    return index;
                } else {
                    throw new UnsupportedOperationException();
                }
            }

            public void remove() {
                if (index >= 0 && contains(index)) {
                    BitIntSet.this.remove(index);
                    index--;
                } else {
                    throw new UnsupportedOperationException();
                }
            }
        };
    }
}

class HashIntSet implements IntSet {
    private Integer[] elements;
    private int size;

    public HashIntSet(Integer[] elements) {
        this.elements = elements;
        this.size = elements.length;
    }

    public int size() {
        return size;
    }

    public boolean add(int value) {
        if (!contains(value)) {
            Integer[] newElements = new Integer[size + 1];
            System.arraycopy(elements, 0, newElements, 0, size);
            newElements[size] = value;
            elements = newElements;
            size++;
            return true;
        } else {
            return false;
        }
    }

    public boolean contains(int value) {
        for (int i = 0; i < size; i++) {
            if (elements[i] == value) {
                return true;
            }
        }
        return false;
    }

    public boolean remove(int value) {
        for (int i = 0; i < size; i++) {
            if (elements[i] == value) {
                Integer[] newElements = new Integer[size - 1];
                System.arraycopy(elements, 0, newElements, 0, i);
                System.arraycopy(elements, i + 1, newElements, i, size - i - 1);
                elements = newElements;
                size--;
                return true;
            }
        }
        return false;
    }

    public Iterator<Integer> iterator() {
        return new Iterator<Integer>() {
            private int index = -1;

            public boolean hasNext() {
                return index < size - 1;
            }

            public Integer next() {
