private String convertLessThanOneThousand(int n, String[] numNames, String[] tenNames, String[] teenNames) {
    StringBuilder resultBuilder = new StringBuilder();

    if (n % 100 < 10){
        resultBuilder.append(numNames[n % 100]);
        n /= 100;
    } else if (n % 100 < 20) {
        resultBuilder.append(teenNames[n % 10 - 1]);
        n /= 100;
    } else {
        resultBuilder.append(numNames[n % 10]);
        n /= 10;

        resultBuilder.insert(0, tenNames[n % 10] + " ");
        n /= 10;
    }

    if (n == 0) {
