import java.io.IOException;
import java.nio.file.FileSystem;
import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.ZipOutputStream;

public class ZipFileSystemHandler {

    public static Handle createZipFileSystem(Path zipFile, Path mountPoint, TempFileProvider tempFileProvider)
            throws IOException {

        // Create a zip file system
        Map<String, String> env = new HashMap<>(); 
        env.put("create", "true"); 
        Path zipfsPath = zipFile.toAbsolutePath(); 
        FileSystem zipfs = FileSystems.newFileSystem(zipfsPath, env);

        // Mount the zip file system
        Path root = zipfs.getPath("/");
        Path mount = mountPoint.toAbsolutePath();
        Files.createDirectories(mount);
        zipfs.provider().checkAccess(root);
        zipfs.provider().checkAccess(mount.getParent());
        zipfs.provider().newFileSystem(mount, Collections.emptyMap());

        // Create a temporary file to represent the handle and respond with it
        Path tempFile = tempFileProvider.createTempFile();
        Files.deleteIfExists(tempFile);
        Files.createFile(tempFile);

        // Write handle information to the temporary file
        try (ZipOutputStream zipOutputStream = new ZipOutputStream(Files.newOutputStream(tempFile, StandardOpenOption.WRITE))) {
            zipOutputStream.write(zipFile.toString().getBytes());
            zipOutputStream.write("\n".getBytes());
            zipOutputStream.write(mountPoint.toString().getBytes());
        }

        // Return a new handle
        return new Handle(tempFile, zipfs);
    }

    public static class Handle {
        private final Path tempFile;
        private final FileSystem zipfs;

        public Handle(Path tempFile, FileSystem zipfs) {
            this.tempFile = tempFile;
            this.zipfs = zipfs;
        }

        public void close() throws IOException {
            zipfs.close();
            Files.deleteIfExists(tempFile);
        }
    }

    public interface TempFileProvider {
        Path createTempFile() throws IOException;
    }
}

