private StringBuilder buildElementCollectionValue(Field field, Object record, MetamodelImpl metaModel, Attribute attribute) {
    StringBuilder sb = new StringBuilder();

    // Assuming that the field is a collection
    if (field.getType().isAssignableFrom(Collection.class)) {
        try {
            field.setAccessible(true);
            Collection<?> collection = (Collection<?>) field.get(record);

            for (Object obj : collection) {
                // Assuming that the collection contains strings
                if (obj instanceof String) {
                    sb.append((String) obj);
                    sb.append(", ");
                }
            }
        } catch (IllegalAccessException e) {
            e.printStackTrace();
        }
    }

    return sb;
}

