public Tensor deconv2d(Tensor inputs, Deconv2DConfig deconv2DConfig) {

    int batchSize = inputs.shape()[0];
    int inChannels = inputs.shape()[1];
    int inHeight = inputs.shape()[2];
    int inWidth = inputs.shape()[3];

    int kernelHeight = deconv2DConfig.getFilterHeight();
    int kernelWidth = deconv2DConfig.getFilterWidth();
    int outChannels = deconv2DConfig.getNumFilters();
    int strideHeight = deconv2DConfig.getStrideHeight();
    int strideWidth = deconv2DConfig.getStrideWidth();
    int padHeight = deconv2DConfig.getPadHeight();
    int padWidth = deconv2DConfig.getPadWidth();

    int outputHeight = (inHeight - 1) * strideHeight + kernelHeight - 2 * padHeight;
    int outputWidth =  (inWidth - 1) * strideWidth + kernelWidth - 2 * padWidth;

    Tensor output = new Tensor(batchSize, outChannels, outputHeight, outputWidth);

    for(int b = 0; b < batchSize; b++) {
        for(int k = 0; k < outChannels; k++) {
            for(int h = 0; h < outputHeight; h++) {
                for(int w = 0; w < outputWidth; w++) {

                    float sum = 0.0f;

                    for(int c = 0; c < inChannels; c++) {
                        for(int i = 0; i < kernelHeight; i++) {
                            int hIndex = h + i - padHeight;
                            if(hIndex < 0 || hIndex >= inHeight) continue;

                            for(int j = 0; j < kernelWidth; j++) {
                                int wIndex = w + j - padWidth;
                                if(wIndex < 0 || wIndex >= inWidth) continue;

                                sum += inputs.get(b, c, hIndex, wIndex) *
                                        deconv2DConfig.getFilter(k, c, i, j);
                            }
                        }
                    }

                    output.set(b, k, h, w, sum);
                }
            }
        }
    }

    return output;
}

