import java.util.*;

public class Main {
  public static <T extends Comparable<T>> Iterator<T> mergeIterators(Iterable<Iterator<T>> iterables) {
    Queue<T> queue = new PriorityQueue<>();
    for (Iterator<T> iterator : iterables) {
      if (iterator.hasNext()) queue.add(iterator.next());
    }
    return new Iterator<T>() {
      @Override
      public boolean hasNext() {
        return !queue.isEmpty();
      }
      @Override
      public T next() {
        T element = queue.poll();
        Iterator<T> iterator = iterables.iterator();
        while (iterator.hasNext()) {
          T nextElem = iterator.next().next();
          if (nextElem != null) queue.add(nextElem);
        }
        return element;
      }
    };
  }

  public static void main(String[] args) {
    List<Integer> list1 = Arrays.asList(1, 3, 5, 7, 9);
    List<Integer> list2 = Arrays.asList(2, 4, 6, 8, 10);
    Iterator<Integer> iter1 = list1.iterator();
    Iterator<Integer> iter2 = list2.iterator();
    Iterator<Integer> mergedIter = mergeIterators(Arrays.asList(iter1, iter2));
    while (mergedIter.hasNext()) {
      System.out.print(mergedIter.next() + " ");
    }
  }
}

