public ArrayList<Triple> createTriples(String graphName, Graph graph) {
    ArrayList<Triple> triples = new ArrayList<>();
    Node graphNode = NodeFactory.createURI(graphName);
    Iterator<Triple> it = graph.find(Node.ANY, Node.ANY, Node.ANY);
    while (it.hasNext()) {
        Triple triple = it.next();
        Node subject = triple.getSubject();
        Node predicate = triple.getPredicate();
        Node object = triple.getObject();
        Triple newTriple = new Triple(subject, predicate, object, graphNode);
        triples.add(newTriple);
    }
    return triples;
}

