public static Geometry toNormalForm(Geometry geometry) {
    if (geometry instanceof Point) {
        return (Point) geometry;
    } else if (geometry instanceof LineString) {
        CoordinateSequence seq = ((LineString) geometry).getCoordinateSequence();
        int count = seq.size();

        // ensure there are at least 2 distinct points
        Coordinate distinctCoord = null;
        for (int i = 0; i < count; i++) {
            Coordinate c = seq.getCoordinate(i);
            if (distinctCoord == null || !c.equals2D(distinctCoord)) {
                if (distinctCoord != null) {
                    break;
                }
                distinctCoord = new Coordinate(c);
            }
        }

        if (distinctCoord == null) {
            return createPoint(geometry.getFactory(), seq.getCoordinate(0));
        } else if (count == 2) {
            return createLineString(geometry.getFactory(), seq);
        } else {
            // now check if all points are on the line defined by the first two distinct points
            boolean isOnLine = true;
            LineSegment line = new LineSegment(distinctCoord, seq.getCoordinate(1));
            for (int i = 2; i < count; i++) {
                if (!line.isOnLine(seq.getCoordinate(i))) {
                    isOnLine = false;
                    break;
                }
            }
            if (isOnLine) {
                return createLineString(geometry.getFactory(), new Coordinate[]{distinctCoord, seq.getCoordinate(count - 1)});
            } else {
                return createLineString(geometry.getFactory(), seq);
            }
        }
    } else if (geometry instanceof Polygon) {
        Polygonal polygon = (Polygonal) geometry;
        LinearRing shell = (LinearRing) toNormalForm(polygon.getExteriorRing());
        int holes = polygon.getNumInteriorRing();
        LinearRing[] holesLR = new LinearRing[holes];
        for (int i = 0; i < holes; i++) {
            holesLR[i] = (LinearRing) toNormalForm(polygon.getInteriorRingN(i));
        }
        return createPolygon(geometry.getFactory(), shell, holesLR);
    } else if (geometry instanceof MultiPolygon) {
        MultiPolygon mp = (MultiPolygon) geometry;
        Polygon[] normalPolys = new Polygon[mp.getNumGeometries()];
        for (int i = 0; i < normalPolys.length; i++) {
            normalPolys[i] = (Polygon) toNormalForm(mp.getGeometryN(i));
        }
        return createMultiPolygon(geometry.getFactory(), normalPolys);
    } else if (geometry instanceof GeometryCollection) {
        GeometryCollection gc = (GeometryCollection) geometry;
        int n = gc.getNumGeometries();
        Geometry[] result = new Geometry[n];
        for (int i = 0; i < n; i++) {
            result[i] = toNormalForm(gc.getGeometryN(i));
        }
        return createGeometryCollection(result, geometry.getFactory());
    } else {
        return geometry;
    }
}

private static Point createPoint(GeometryFactory factory, Coordinate coordinate) {
    return factory.createPoint(coordinate);
}

private static LineString createLineString(GeometryFactory factory, Coordinate[] coordinates) {
    return factory.createLineString(coordinates);
}

private static Polygon createPolygon(GeometryFactory factory, LinearRing shell, LinearRing[] holes) {
    return factory.createPolygon(shell, holes);
}

private static MultiPolygon createMultiPolygon(GeometryFactory factory, Polygon[] polygons) {
    return factory.createMultiPolygon(polygons);
}

private static GeometryCollection createGeometryCollection(Geometry[] geometries, GeometryFactory factory) {
    return factory.createGeometryCollection(geometries);
}

