import java.sql.*;
import java.util.*;

public List<Object> getListOfBeans(String sql, Class<?> beanType, Object... params) throws SQLException {
    List<Object> listOfBeans = new ArrayList<>();
    try (Connection conn = getConnectionFromDefaultPool();
         PreparedStatement stmt = conn.prepareStatement(sql)) {
        for (int i = 0; i < params.length; i++) {
            stmt.setObject(i + 1, params[i]);
        }
        try (ResultSet rs = stmt.executeQuery()) {
            ResultSetMetaData meta = rs.getMetaData();
            Map<String, String> columnNameMap = new HashMap<>();
            for (int i = 1; i <= meta.getColumnCount(); i++) {
                String columnName = meta.getColumnName(i);
                columnNameMap.put(columnName, columnName);
            }
            while (rs.next()) {
                Object beanObject = beanType.getDeclaredConstructor().newInstance();
                for (String columnName : columnNameMap.keySet()) {
                    String propertyName = columnNameToPropertyName(columnNameMap.get(columnName));
                    Object value = rs.getObject(columnName);
                    setProperty(beanObject, propertyName, value);
                }
                listOfBeans.add(beanObject);
            }
        }
    } catch (InstantiationException | IllegalAccessException | NoSuchMethodException | InvocationTargetException e) {
        throw new SQLException("Error getting list of beans from ResultSet", e);
    }
    return listOfBeans;
}

private Connection getConnectionFromDefaultPool() throws SQLException {
    return DriverManager.getConnection("jdbc:default:connection");
}

private String columnNameToPropertyName(String columnName) {
    return columnName.toLowerCase();
}

private void setProperty(Object bean, String propertyName, Object value) throws IllegalAccessException, InvocationTargetException {
    BeanUtils.setProperty(bean, propertyName, value);
}

