import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import org.apache.commons.io.FileUtils;

public class AnnotatedClassFinder {

    public static void findAndWriteConfigFile(String searchDir, String configFile) throws IOException {
        List<Class<?>> annotatedClasses = new ArrayList<Class<?>>();
        File root = new File(searchDir);
        for (File file : FileUtils.listFiles(root, null, true)) {
            Class<?> clazz = getClassFromFile(file);
            if (clazz.isAnnotationPresent(Configurable.class)) {
                annotatedClasses.add(clazz);
            }
        }
        writeConfigFile(annotatedClasses, configFile);
    }

    private static Class<?> getClassFromFile(File file) {
        Class<?> clazz = null;
        try {
            String path = file.getPath().replace(File.separatorChar, '.');
            String className = path.substring(path.indexOf('.') + 1, path.lastIndexOf('.'));
            clazz = Class.forName(className);
        } catch (ClassNotFoundException e) {
            e.printStackTrace();
        }
        return clazz;
    }

    private static void writeConfigFile(List<Class<?>> annotatedClasses, String configFile) throws IOException {
        FileWriter writer = new FileWriter(configFile);
        for (Class<?> clazz : annotatedClasses) {
            Configurable annotation = clazz.getAnnotation(Configurable.class);
            writer.write(annotation.value() + ":" + clazz.getName() + "\n");
        }
        writer.close();
    }
}

