public TransportMethod resolveIP(String ipAddress) throws SmackException, InterruptedException {
    InetAddress inetAddress = InetAddress.getByName(ipAddress);
    TransportMethod transportMethod = null;
    if (inetAddress instanceof Inet4Address) {
        transportMethod = TransportMethod.TCP;
    } else if (inetAddress instanceof Inet6Address) {
        transportMethod = TransportMethod.UDP;
    } else {
        throw new SmackException("Unsupported IP address type");
    }
    return transportMethod;
}

