public void tableToShapefile(Connection connection, String fileName, String tableReference, String encoding) throws IOException, SQLException {
    Statement statement = connection.createStatement();
    String selectQuery = tableReference.replaceAll("'", "");
    ResultSet resultSet = statement.executeQuery(selectQuery);
    ShapefileDataStoreFactory dataStoreFactory = new ShapefileDataStoreFactory();
    Map<String, Serializable> params = new HashMap<>();
    File file = new File(fileName);
    params.put("url", file.toURI().toURL());
    params.put("create spatial index", Boolean.TRUE);
    ShapefileDataStore dataStore = (ShapefileDataStore) dataStoreFactory.createNewDataStore(params);
    SimpleFeatureType featureType = DataUtilities.createFeatureType(resultSet.getMetaData().getTableName(), getGeometryClass(resultSet.getMetaData()), CRS.decode("EPSG:4326"));
    dataStore.createSchema(featureType);
    Transaction transaction = new DefaultTransaction("create");
    String typeName = dataStore.getTypeNames()[0];
    FeatureWriter<SimpleFeatureType, SimpleFeature> writer = dataStore.getFeatureWriter(typeName, transaction);
    while (resultSet.next()) {
        SimpleFeature feature = createFeature(resultSet, featureType);
        SimpleFeature copy = writer.next();
        copy.setAttributes(feature.getAttributes());
        writer.write();
    }
    transaction.commit();
    writer.close();
    transaction.close();
    dataStore.dispose();
}

private SimpleFeature createFeature(ResultSet resultSet, SimpleFeatureType featureType) throws IOException, SQLException {
    SimpleFeatureBuilder featureBuilder = new SimpleFeatureBuilder(featureType);
    List<AttributeDescriptor> attributeDescriptors = featureType.getAttributeDescriptors();
    for (AttributeDescriptor attributeDescriptor : attributeDescriptors) {
        String name = attributeDescriptor.getLocalName();
        if (Geometry.class.isAssignableFrom(attributeDescriptor.getType().getBinding())) {
            Geometry geometry = geometryFromWKT(resultSet.getString(name));
            featureBuilder.add(geometry);
        } else {
            featureBuilder.add(resultSet.getObject(name));
        }
    }
    SimpleFeature feature = featureBuilder.buildFeature(null);
    return feature;
}

private Class<?> getGeometryClass(ResultSetMetaData metaData) throws SQLException {
    int columnCount = metaData.getColumnCount();
    for (int i = 1; i <= columnCount; i++) {
        String columnName = metaData.getColumnLabel(i);
        int columnType = metaData.getColumnType(i);
        if (columnType == Types.CLOB) {
            return Geometry.class;
        }
    }
    return null;
}

private Geometry geometryFromWKT(String wkt) throws SQLException {
    WKTReader reader = new WKTReader();
    Geometry geometry;
    try {
        geometry = reader.read(wkt);
    } catch (ParseException e) {
        throw new SQLException(e.getMessage());
    }
    return geometry;
}

