        throws IOException
    {
        int tag = read();
        switch (tag) {
            case 'N':
                return null;
            case 'T':
                return Boolean.valueOf(true);
            case 'F':
                return Boolean.valueOf(false);
            case 'I':
                return Integer.valueOf(parseInt());
            case 'L':
                return Long.valueOf(parseLong());
            case 'D':
