public Optional<RowFilter> adapt(FilterAdapterContext context, Filter filter)throws IOException{
    if (filter instanceof FilterList) {
        FilterList filterList = (FilterList) filter;
        Operator operator = filterList.getOperator() == FilterList.Operator.MUST_PASS_ALL ? Operator.MUST_PASS_ALL: Operator.MUST_PASS_ONE;
        ImmutableList.Builder<RowFilter> rowFilters = ImmutableList.builder();
        for (Filter subFilter : filterList.getFilters()){
            Optional<RowFilter> rowFilterResult = adapt(context, subFilter);
            if (rowFilterResult.isPresent()) {
                rowFilters.add(rowFilterResult.get());
            }
        }
        return Optional.<RowFilter> of(new RowFilter(operator, rowFilters.build()));
    } else if (filter instanceof SingleColumnValueFilter) {
        SingleColumnValueFilter scvf = (SingleColumnValueFilter) filter;
        return Optional.<RowFilter> of(new ValueFilter(FilterAdapterHelper.convertByteArrayToByteString(scvf.getColumnFamily()), FilterAdapterHelper.convertByteArrayToByteString(scvf.getQualifier()), scvf.getOperator(), scvf.getComparator().getValue()));
    } else if (filter instanceof FamilyFilter) {
        FamilyFilter ff = (FamilyFilter) filter;
        return Optional.<RowFilter> of(new FamilyNameFilter(FilterAdapterHelper.convertByteArrayToByteString(ff.getComparator().getValue()), FilterAdapterHelper.convertCompareOp(ff.getOperator())));
    } else if (filter instanceof ColumnPrefixFilter) {
        ColumnPrefixFilter cpf = (ColumnPrefixFilter) filter;
        return Optional.<RowFilter> of(new ColumnQualifierFilter(FilterAdapterHelper.convertByteArrayToByteString(cpf.getPrefix())));
    } else if (filter instanceof ValueFilter) {
        ValueFilter vf = (ValueFilter) filter;
        // There is no direct equivalent filter for ValueFilter in Bigtable, so use RowFilter.
        return Optional.<RowFilter> of(new RowFilter(Operator.MUST_PASS_ALL, ImmutableList.of(new ValueFilter(FilterAdapterHelper.EMPTY_BYTE_STRING, FilterAdapterHelper.EMPTY_BYTE_STRING, vf.getOperator(), vf.getComparator().getValue()))));
    } else if (filter instanceof QualifierFilter) {
        QualifierFilter qf = (QualifierFilter) filter;
        // There is no direct equivalent filter for QualifierFilter in Bigtable, so use ColumnQualifierRegexFilter.
        String regexString = FilterBase.getRegex(qf);
        if (regexString == null) {
            throw new IllegalArgumentException("Unable to get regex string from QualifierFilter: " + qf);
        }
        return Optional.<RowFilter> of(new ColumnQualifierRegexFilter(Pattern.compile(regexString)));
    } else if (filter instanceof KeyOnlyFilter) {
        return Optional.<RowFilter> of(new RowFilter(Operator.MUST_PASS_ALL, ImmutableList.of(new FamilyNameRegexFilter(".*", FilterSupport.OP_ALWAYS))));
    } else if (filter instanceof FirstKeyOnlyFilter) {
        // FirstKeyOnly filter should have been converted to a FilterList with a filter that matches all rows.
        return Optional.<RowFilter> empty();
    } else if (filter instanceof PageFilter) {
        PageFilter pf = (PageFilter) filter;
        return Optional.<RowFilter> of(new RowFilter(Operator.MUST_PASS_ALL, ImmutableList.of(new OffsetFilter(pf.getOffset()), new LimitFilter(pf.getPageSize()))));
    } else if (filter instanceof InclusiveStopFilter) {
        InclusiveStopFilter sf = (InclusiveStopFilter) filter;
        ByteString stopRowKey = ByteString.copyFrom(sf.getStopRow());
        return Optional.<RowFilter> of(new RowFilter(Operator.MUST_PASS_ALL, ImmutableList.of(new RowKeyRegexFilter(RegExPatterns.exactly(stopRowKey)))));// Stop row is included
    } else if (filter instanceof SkipFilter) {
        SkipFilter skipFilter = (SkipFilter) filter;
        return adapt(context, skipFilter.getFilter());
    } else if (filter instanceof fuzzyrowfilter) {
        FuzzyRowFilter fuzzyRowFilter = (FuzzyRowFilter) filter;
        List<ByteString> rowKeys = fuzzyRowFilter.getFuzzyKeysData();
        RowFilter.Builder rowFilterBuilder = RowFilter.newBuilder();
        rowFilterBuilder.setRowKeyRegexFilter(Filters.RegexFilter.newBuilder().setRegex(fuzzyRowFilter.getFuzzyValue().getRegexString()));
        for (ByteString rowKey : rowKeys) {
            rowFilterBuilder.addInterleave(
                    Filters.RowFilter.newBuilder()
                            .setChain(
                                    Filters.RowFilter.Chain.newBuilder().addFilters(
                                            Filters.RowFilter.newBuilder()
                                                    .setRowKeyRegexFilter(Filters.RegexFilter.newBuilder()
                                                            .setRegex(rowKey.toStringUtf8())))
                                            .addFilters(Filters.RowFilter.newBuilder()
                                                    .setRowSampleFilter(0.5f))
                                            .build())
                            .build());
        }
        return Optional.<RowFilter> of(rowFilterBuilder.build());
    } else if (filter instanceof ColumnRangeFilter) {
        ColumnRangeFilter rangeFilter = (ColumnRangeFilter) filter;
        ByteString family = FilterAdapterHelper.convertByteArrayToByteString(rangeFilter.getFamily());
        ByteString startQualifier = FilterAdapterHelper.convertByteArrayToByteString(rangeFilter.getMinColumn());
        ByteString endQualifier = FilterAdapterHelper.convertByteArrayToByteString(rangeFilter.getMaxColumn());
        return Optional.<RowFilter> of(new ColumnRangeFilterAdapter(family, startQualifier, endQualifier).adapt(context));
    } else if (filter instanceof TimestampsFilter) {
        TimestampsFilter timestampsFilter = (TimestampsFilter) filter;
        List<Long> timestamps = Longs.asList(timestampsFilter.getTimestamps());
        if (timestamps.isEmpty()) {
            throw new IllegalArgumentException();       
        }
        return Optional.<RowFilter> of(new TimestampRangeFilter(Optional.empty(), Optional.of(timestampsFilter.getTimestamps()[timestamps.size()-1])));
    } else if (filter instanceof ColumnCountGetFilter) {
        ColumnCountGetFilter ccgf = (ColumnCountGetFilter) filter;
        return Optional.<RowFilter> of(new CellsPerColumnLimitFilter(ccgf.getLimit()));
    } else if (filter instanceof ColumnPaginationFilter) {
        ColumnPaginationFilter cpf = (ColumnPaginationFilter) filter;
        throw new UnsupportedOperationException("ColumnPaginationFilter is not currently supported in Bigtable. Please use ColumnCountGetFilter.");
    } else if (filter instanceof RandomRowFilter) {
        RandomRowFilter rrf = (RandomRowFilter) filter;
        return Optional.<RowFilter> of(new RowSampleFilter(rrf.getChance()));
    }
    return Optional.<RowFilter> empty();
}

