        return Optional.of(RowFilter.value().range().startClosed(family.concat(qualifier).concat(value)));
    } else if (filter instanceof FirstKeyOnlyFilter) {
        return Optional.of(RowFilter.cellsPerRow(1));
    } else {
        // Handle other types of filters here
    }
    return Optional.empty();
}

