import com.amazonaws.services.glacier.transfer.ArchiveTransferManager;

public static String calculateTreeHash(File file) throws AmazonClientException {
    try {
        FileInputStream input = new FileInputStream(file);
        byte[][] chunkSHA256Hashes = computeChunkSHA256Hashes(input);
        return computeTreeHash(chunkSHA256Hashes);
    } catch (IOException ioe) {
        throw new AmazonClientException("Unable to compute hash for data in file " + file.getAbsolutePath(), ioe);
    }
}

private static byte[][] computeChunkSHA256Hashes(InputStream input) throws IOException {
    MessageDigest md = null;
    try {
        md = MessageDigest.getInstance("SHA-256");
    } catch (NoSuchAlgorithmException e) {
        throw new UnsupportedOperationException(e);
    }

    byte[][] chunkSHA256Hashes = new byte[(int) (input.available() / ONE_MB) + 1][];
    int bytesRead = 0;
    int chunkIndex = 0;
    while (bytesRead != -1) {
        byte[] buffer = new byte[ONE_MB];
        bytesRead = input.read(buffer);
        if (bytesRead == -1) {
            byte[] mdBytes = md.digest();
            chunkSHA256Hashes[chunkIndex] = mdBytes;
        } else if (bytesRead < ONE_MB) {
            byte[] bufferToHash = new byte[bytesRead];
            System.arraycopy(buffer, 0, bufferToHash, 0, bytesRead);
            md.update(bufferToHash);
            byte[] mdBytes = md.digest();
            chunkSHA256Hashes[chunkIndex] = mdBytes;
        } else {
            md.update(buffer);
            chunkSHA256Hashes[chunkIndex] = md.digest();
            md.reset();
        }
        chunkIndex++;
    }
    return chunkSHA256Hashes;
}

private static String computeTreeHash(byte[][] chunkSHA256Hashes) {
    MessageDigest md = null;
    try {
        md = MessageDigest.getInstance("SHA-256");
    } catch (NoSuchAlgorithmException e) {
        throw new UnsupportedOperationException(e);
    }

    while (chunkSHA256Hashes.length > 1) {
        int numberOfChunks = chunkSHA256Hashes.length;
        int numberOfPairs = numberOfChunks / 2;
        if (numberOfChunks % 2 != 0) {
            chunkSHA256Hashes[numberOfPairs] = chunkSHA256Hashes[numberOfChunks - 1];
            numberOfPairs++;
        }

        byte[][] newHashes = new byte[numberOfPairs][];
        for (int i = 0, j = 0; i < numberOfChunks - 1; i += 2, j++) {
            md.reset();
            md.update(chunkSHA256Hashes[i]);
            md.update(chunkSHA256Hashes[i + 1]);
            newHashes[j] = md.digest();
        }
        chunkSHA256Hashes = newHashes;
    }

    return Base16.encodeAsString(chunkSHA256Hashes[0]);
}

