public static void rgbToXyz(Planar<GrayU8> rgb, Planar<GrayF32> xyz) {
   final double r[] = new double[3];
   final float d[] = new float[3];
   for (int y = 0; y < rgb.height(); y++) {
      int indexRgb = rgb.startIndex + y * rgb.stride[1];
      int indexXyz = xyz.startIndex + y * xyz.stride[1];
      int endRgb = indexRgb + rgb.width()*3;
      for (; indexRgb < endRgb; indexRgb += 3, indexXyz += 3) {
         // load the values from the RGB value packed together in a single integer
         r[0] = (rgb.data[indexRgb    ]&0xFF)/255.0;
         r[1] = (rgb.data[indexRgb + 1]&0xFF)/255.0;
         r[2] = (rgb.data[indexRgb + 2]&0xFF)/255.0;

         // convert from RGB -> XYZ
         d[0] = (float) (0.412453*r[0] + 0.357580*r[1] + 0.180423*r[2]);
         d[1] = (float) (0.212671*r[0] + 0.715160*r[1] + 0.072169*r[2]);
         d[2] = (float) (0.019334*r[0] + 0.119193*r[1] + 0.950227*r[2]);

         // save the calculated values into the output image
         xyz.data[indexXyz    ] = d[0];
         xyz.data[indexXyz + 1] = d[1];
         xyz.data[indexXyz + 2] = d[2];
      }
   }
}

