public String parseAbsoluteJCRName(String name) throws RepositoryException {
    Pattern pattern = Pattern.compile("^([^:]*):([^\\[]*)(\\[(\\d+)\\])?$");
    Matcher matcher = pattern.matcher(name);
    if (!matcher.matches()) {
        throw new RepositoryException("Invalid JCR name format: " + name);
    }
    String namespace = matcher.group(1);
    String localName = matcher.group(2);
    String indexString = matcher.group(4);
    int index = -1;
    if (indexString != null) {
        index = Integer.parseInt(indexString);
    }
    return new Name(namespace, localName, index).toString();
}

