public Schema convertSchema(PangoolSchema pangoolSchema) {
    List<Field> fields = new ArrayList<>();
    pangoolSchema.getFields().forEach(pangoolField -> {
        Schema avroFieldSchema = pangoolTypeToAvro(pangoolField.getSchema());
        String fieldName = pangoolField.getName();
        Object defaultValue = pangoolField.getDefaultValue();
        if (defaultValue != null) {
            fields.add(new Field(fieldName, avroFieldSchema, null, defaultValue));
        } else {
            fields.add(new Field(fieldName, avroFieldSchema, null, null));
        }
    });
    return Schema.createRecord(pangoolSchema.getName(), null, pangoolSchema.getNamespace(), false, fields);
}

private Schema pangoolTypeToAvro(PangoolSchema pangoolType) {
    switch (pangoolType.getType()) {
        case BOOLEAN:
            return Schema.create(Schema.Type.BOOLEAN);
        case INT:
            return Schema.create(Schema.Type.INT);
        case LONG:
            return Schema.create(Schema.Type.LONG);
        case FLOAT:
            return Schema.create(Schema.Type.FLOAT);
        case DOUBLE:
            return Schema.create(Schema.Type.DOUBLE);
        case STRING:
            return Schema.create(Schema.Type.STRING);
        case BYTES:
            return Schema.create(Schema.Type.BYTES);
        case NULL:
            return Schema.create(Schema.Type.NULL);
        case ENUM:
            List<String> symbols = Arrays.asList(pangoolType.getEnumSymbols());
            return Schema.createEnum(pangoolType.getName(), null, pangoolType.getNamespace(), symbols);
        case ARRAY:
            Schema arrSchema = pangoolTypeToAvro(pangoolType.getElementSchema());
            return Schema.createArray(arrSchema);
        case MAP:
            Schema valSchema = pangoolTypeToAvro(pangoolType.getValueSchema());
            return Schema.createMap(valSchema);
        case RECORD:
            return convertSchema(pangoolType);
        default:
            throw new IllegalArgumentException("Unknown type: " + pangoolType.getType());
    }
}

