public void multiplyByInverse(Quaternion q1) {
   double norm = q1.norm();
   norm = (norm == 0.0 ? norm : 1.0 / norm);
   double x = -q1.getX() * norm;
   double y = -q1.getY() * norm;
   double z = -q1.getZ() * norm;
   double w =  q1.getW() * norm;
   double newX = w * getX() + x * getW() + y * getZ() - z * getY();
   double newY = w * getY() + y * getW() + z * getX() - x * getZ();
   double newZ = w * getZ() + z * getW() + x * getY() - y * getX();
   double newW = w * getW() - x * getX() - y * getY() - z * getZ();
   setX(newX);
   setY(newY);
   setZ(newZ);
   setW(newW);
}

