    // Process each block of data
    for (int i = 0; i < dataBlocks; i++) {
        // Extract the data for the current block
        String blockData = adjustedString.substring(i * dataCodewordsPerBlock, (i + 1) * dataCodewordsPerBlock);

        // Convert the block data to an array of bytes
