                    in.get(s1);

                    IoBuffer out = handshake.decodeServerResponse1(IoBuffer.wrap(s1));
                    if (out != null) {

                        rtmp.setState(RTMP.STATE_HANDSHAKE);
                        conn.writeRaw(out);

