import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

public int delete(Session session, Table table, RowSetNavigator oldRows) {
    int deletedRows = 0;
    List<String> whereClauses = new ArrayList<>();

    try {
        Connection conn = session.getConnection();

        // Build the WHERE clause based on the primary keys of the table
        for (int i = 0; i < table.getPrimaryKeys().length; i++) {
            whereClauses.add(table.getPrimaryKeys()[i] + " = ?");
        }

        String deleteQuery = "DELETE FROM " + table.getName() + " WHERE " + String.join(" AND ", whereClauses);

        PreparedStatement deleteStatement = conn.prepareStatement(deleteQuery);

        while (oldRows.next()) {
            for (int i = 0; i < table.getPrimaryKeys().length; i++) {
                deleteStatement.setObject(i + 1, oldRows.get(table.getPrimaryKeys()[i]));
            }

            deletedRows += deleteStatement.executeUpdate();
        }

        deleteStatement.close();
    } catch (SQLException e) {
        e.printStackTrace();
    }

    return deletedRows;
}

