public static boolean canLogFileBeContinued(String fileName, List<String> policies) {
    File file = new File(fileName);
    if (!file.exists()) {
        return false;
    }
    try {
        BufferedReader reader = new BufferedReader(new FileReader(file));
        String line = reader.readLine();
        while (line != null) {
            if (isPolicyLine(line)) {
                String policy = extractPolicyFromLine(line);
                if (!policies.contains(policy)) {
                    reader.close();
                    return false;
                }
            }
            line = reader.readLine();
        }
        reader.close();
    } catch (IOException e) {
        return false;
    }
    return true;
}

private static boolean isPolicyLine(String line) {
    return line.startsWith("[") && line.endsWith("]");
}

private static String extractPolicyFromLine(String line) {
    return line.substring(1, line.length() - 1);
}

