        if (c == '$') {
            if (i + 1 < str.length() && str.charAt(i + 1) == '{') {
                int end = str.indexOf('}', i + 2);
                if (end == -1) {
                    throw new CommandFormatException("Missing closing brace '}'");
                }
                String key = str.substring(i + 2, end);
