import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public static <T, R> Stream<R> groupedBySizeAndTime(Stream<T> stream, int size, long time, TimeUnit t, Supplier<R> factory) {
    return Stream.generate(factory)
        .flatMap(group -> {
            List<T> items = stream.limit(size).collect(Collectors.toList());
            if (!items.isEmpty()) {
                group.addAll(items);
            }
            try {
                Thread.sleep(t.toMillis(time));
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
            return Stream.of(group);
        })
        .takeWhile(group -> !group.isEmpty());
}

