    @SafeVarargs
    public static <T> Predicate<T> and(Predicate<T>... predicates) {
        return t -> {
            for (Predicate<T> predicate : predicates) {
                if (!predicate.test(t)) {
                    return false;
                }
            }
            return true;
        };
    }
}

