public static Resource createResourceFromJar(String jarResource, String rootPath) {
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    URL url = classLoader.getResource(jarResource);
    URI uri;
    try {
        uri = url.toURI();
    } catch (URISyntaxException e) {
        throw new IllegalArgumentException("Invalid URI syntax for jar resource");
    }
    if (!uri.toString().contains("!")) {
        throw new IllegalArgumentException("Jar resource should be of the form 'jar:file:/path/to/jar.jar!/resource/path'");
    }
    String[] jarPath = uri.toString().split("!");
    if (jarPath.length < 2) {
        throw new IllegalArgumentException("Invalid jar resource path");
    }
    FileSystem fs;
    try {
        fs = FileSystems.newFileSystem(URI.create(jarPath[0]), new HashMap<>());
    } catch (IOException e) {
        throw new IllegalArgumentException("Failed to create file system from jar resource");
    }
    Path path = fs.getPath(jarPath[1] + rootPath);
    return new PathResource(path);
}

