public static ModeSReply genericDecoder (ModeSReply modes) throws BadFormatException, UnspecifiedFormatError {
	// Check if the message is null
    if (modes == null) {
        throw new BadFormatException("ModeSReply is null");
    }

    // Check if the message type is unspecified
    if (modes.getType() == ModeSReply.Type.UNSPECIFIED) {
        throw new UnspecifiedFormatError("ModeSReply type is unspecified");
    }

    // Decode based on the type
    switch (modes.getType()) {
        case IDENTIFICATION:
            return new IdentificationReply(modes);
        case SURVEILLANCE:
            return new SurveillanceReply(modes);
        case ALL_CALL_REPLY:
            return new AllCallReply(modes);
        case LONG_ACAS:
            return new LongACASReply(modes);
        case SHORT_ACAS:
            return new ShortACASReply(modes);
        case TCAS:
            return new TCASReply(modes);
        case ADS_B:
            return new ADSBReply(modes);
        default:
            throw new BadFormatException("Unknown ModeSReply type");
    }
}

