public synchronized void externalPushFullVersion(Task task) {
    if (task == null) {
        throw new NullPointerException("Task cannot be null");
    }

    if (!canAddTask()) {
        throw new RejectedExecutionException("ThreadPoolExecutor cannot accept new tasks at this time.");
    }

    if (!isShutdown()) {
        int index = calculateQueueIndex();

        if (queueIsEmptyOrContended(index)) {
            createSharedQueue(index);
        }

        addNewTask(task, index);

        if (firstSubmissionByExternalThread()) {
            performSecondaryInitialization();
        }
    } else {
        rejectNewTask();
    }
}

private boolean canAddTask() {
    return poolSize > getActiveCount() || queue.size() < queueCapacity;
}

private int calculateQueueIndex() {
    int index = threadCount.get() & (queueCount - 1);
    threadCount.incrementAndGet();
    return index;
}

private boolean queueIsEmptyOrContended(int index) {
    return queues[index] == null || queues[index].isContended();
}

private void createSharedQueue(int index) {
    queues[index] = new SharedQueue<>(queueCapacity);
    queueHolder.set(queues);
}

private void addNewTask(Task task, int index) {
    queues[index].offer(task);

    if (threadsInUse.get() < poolSize && !hasActiveThreads()) {
        addNewThread();
    }
}

private boolean firstSubmissionByExternalThread() {
    return !hasActiveThreads() && submittedTaskCount.get() == 1;
}

private void performSecondaryInitialization() {
    startAllCoreThreads();
    defaultMaxSizeCore = false;
}

private void rejectNewTask() {
    throw new RejectedExecutionException("ThreadPoolExecutor has already shutdown");
}

