public void rotateWidget(float angle, float x, float y, float z) {
    // Transform the angle from degrees to radians
    float radians = (float) Math.toRadians(angle);

    // Calculate the sin and cos of the angle
    float sin = (float) Math.sin(radians / 2f);
    float cos = (float) Math.cos(radians / 2f);

    // Create a quaternion to represent the rotation
    // x, y, and z are the components of the axis of rotation
    Quaternion rotation = new Quaternion(x * sin, y * sin, z * sin, cos);

    // Apply the rotation to the widget's current rotation
    widgetRotation.mul(rotation);
}

