public void rotateByAxis(float angle, float x, float y, float z) {
    // Convert the angle to radians
    double rad = Math.toRadians(angle);

    // Create a new rotation matrix
    Matrix4f rotationMatrix = new Matrix4f();
    rotationMatrix.rotate((float) rad, new Vector3f(x, y, z));

    // Apply the rotation to the widget's current transformation matrix
    // Assuming the widget has a 'transform' field of type Matrix4f
    widget.transform.mul(rotationMatrix);
}

