import java.io.File;
import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

public class UIMASentenceIterator {

    public static List<String> createWithPath(String path) throws Exception {
        File file = new File(path);
        List<String> sentences = new ArrayList<>();

        if (file.isDirectory()) {
            File[] directoryListing = file.listFiles();
            if (directoryListing != null) {
                for (File child : directoryListing) {
                    sentences.addAll(readFile(child));
                }
            }
        } else {
            sentences.addAll(readFile(file));
        }

        return sentences;
    }

    private static List<String> readFile(File file) throws Exception {
        List<String> sentences = new ArrayList<>();
        Scanner scanner = new Scanner(file);

        while (scanner.hasNextLine()) {
            sentences.add(scanner.nextLine());
        }

        scanner.close();
        return sentences;
    }
}

