import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;

public static SeLionDataProvider getDataProvider(DataResource resource) throws IOException {
    // Get the file extension
    String fileExtension = getFileExtension(resource.getFileName());

    // Load the data provider based on the file extension
    if (fileExtension.equals("csv")) {
        return new CSVDataProvider(Files.readAllLines(Paths.get(resource.getFilePath())));
    } else if (fileExtension.equals("json")) {
        return new JSONDataProvider(new String(Files.readAllBytes(Paths.get(resource.getFilePath()))));
    } else {
        throw new IOException("Unsupported file type: " + fileExtension);
    }
