public static double stddev(Set<Double> expr) {
    double sum = 0, sumSq = 0;
    int n = 0;
    for (double x : expr) {
        sum += x;
        sumSq += x * x;
        n++;
    }
    return Math.sqrt((sumSq - sum * sum / n) / (n - 1));
}

