public <T> Object groupByField(List<T> results, String fieldName, boolean isNumber) {
    Map<Object, List<T>> resultGroups = new HashMap<>();

    for(T result : results) {
        Object fieldValue = getFieldValue(result, fieldName, isNumber);

        if(resultGroups.containsKey(fieldValue)) {
            resultGroups.get(fieldValue).add(result);
        } else {
            List<T> group = new ArrayList<>();
            group.add(result);
            resultGroups.put(fieldValue, group);
        }
    }

    return resultGroups;
}

private <T> Object getFieldValue(T object, String fieldName, boolean isNumber) {
    try {
        Field field = object.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);

        if(isNumber) {
            return Double.parseDouble(field.get(object).toString());
        } else {
            return field.get(object);
        }
    } catch(NoSuchFieldException | IllegalAccessException | NumberFormatException ex) {
        ex.printStackTrace();
    }

    return null;
}

