public Server choose(ILoadBalancer lb, Object key) {
	if (lb == null) {
        log.warn("no loadbalancer");
        return null;
    }
    Server server = null;
    int count = 0;
    while (server == null && count++ < 10) {
        List<Server> upList = lb.getReachableServers();
        List<Server> allList = lb.getAllServers();
        int upCount = upList != null ? upList.size() : 0;
        int serverCount = allList != null ? allList.size() : 0;
        if ((upCount == 0 && serverCount == 0)) {
            log.warn("No up servers available from load balancer: " + lb);
            return null;
        }
        server = key == null ? randomChoose(upList) : stickySessionChoose(key, upList);
        if (server == null) {
            log.warn("No available server for key: " + key);
        }
    }
    if (server == null) {
        log.error("No available server after 10 tries.");
    }
    return server;
}

private Server randomChoose(List<Server> upList) {
    if (upList == null || upList.isEmpty()) {
        return null;
    }
    int index = ThreadLocalRandom.current().nextInt(upList.size());
    return upList.get(index);
}

private Server stickySessionChoose(Object key, List<Server> upList) {
    if (upList == null || upList.isEmpty()) {
        return null;
    }
    for (Server server : upList) {
        if (server.getAttribute("sessionKey").equals(key)) {
            return server;
        }
    }
    return null;
}

