public static <T, R> List<R> zipIterators(List<Iterator<T>> iterators, T valuesForNone, BiFunction<T, List<T>, R> zipFunction) {
    List<R> result = new ArrayList<>();
    List<T> values = new ArrayList<>(iterators.size());

    while (iterators.stream().anyMatch(Iterator::hasNext)) {
        for (int i = 0; i < iterators.size(); i++) {
            Iterator<T> it = iterators.get(i);
            T value = it.hasNext() ? it.next() : valuesForNone;
            values.set(i, value);
        }
        result.add(zipFunction.apply(valuesForNone, values));
    }
    return result;
}

