    List<Variable> variables = ds.getVariables();

    // Iterate over all variables
    for (Variable var : variables) {
        // Get the dimensions of the current variable
        List<Dimension> varDims = var.getDimensions();

        // Check if the variable has the specified dimension
        if (varDims.contains(dim)) {
            aliasedVariables.add(var);
