            if (workerCount >= minimumWorkers) {
                notifyAll();
            }
        }

        @Override
        public synchronized void onFailure(Throwable thrown) {
            notifyAll();
        }

        public synchronized void await() throws InterruptedException {
            while (workerCount < minimumWorkers) {
                wait();
            }
        }
    };
