public class Cluster {
    private int minimumWorkers;
    private int currentWorkers;

    public Cluster(int minimumWorkers) {
        this.minimumWorkers = minimumWorkers;
        this.currentWorkers = 0;
    }

    public synchronized ListenableFuture<Void> waitForMinimumWorkers() {
        SettableFuture<Void> future = SettableFuture.create();

        if (currentWorkers >= minimumWorkers) {
            future.set(null);
        } else {
            new Thread(() -> {
                while (currentWorkers < minimumWorkers) {
                    // Wait for workers to be added
                    try {
                        Thread.sleep(1000);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
                future.set(null);
            }).start();
        }

        return future;
    }

    public synchronized void addWorker() {
        currentWorkers++;
    }
}

