public static String desc2name(String desc) {
	// Implement the method to convert Java type descriptor to type name
    if (desc == null || desc.isEmpty()) {
        return "";
    }

    StringBuilder name = new StringBuilder();
    int arrayDimensions = 0;

    // Count the number of '[' characters to determine the number of array dimensions
    while (desc.charAt(0) == '[') {
        arrayDimensions++;
        desc = desc.substring(1);
    }

    // Determine the base type
    switch (desc) {
        case "B":
            name.append("byte");
            break;
        case "C":
            name.append("char");
            break;
        case "D":
            name.append("double");
            break;
        case "F":
            name.append("float");
            break;
        case "I":
            name.append("int");
            break;
        case "J":
            name.append("long");
            break;
        case "S":
            name.append("short");
            break;
        case "Z":
            name.append("boolean");
            break;
        default:
            // If it's not a primitive type, it must be an object type
            // Remove the 'L' and ';' from the descriptor
            if (desc.startsWith("L") && desc.endsWith(";")) {
                name.append(desc.substring(1, desc.length() - 1).replace('/', '.'));
            } else {
                return "Unknown";
            }
            break;
    }

    // Append the array dimensions
    for (int i = 0; i < arrayDimensions; i++) {
        name.append("[]");
    }

    return name.toString();
}

