import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class TaskQueue {
    private final BlockingQueue<GlobalPoolTask> queue;
    private final Semaphore maxConcurrencyConstraint;

    public TaskQueue(int maxConcurrency) {
        this.queue = new LinkedBlockingQueue<>();
        this.maxConcurrencyConstraint = new Semaphore(maxConcurrency);
    }

    public void enqueueGlobal(GlobalPoolTask globalTask) {
        if (maxConcurrencyConstraint.tryAcquire()) {
            try {
                queue.put(globalTask);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        } else {
            maxConcurrencyConstraint.release();
        }
    }

    public GlobalPoolTask dequeue() {
        try {
            return queue.take();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return null;
        }
    }

    public void executeTask(GlobalPoolTask task) {
        try {
            task.run();
        } finally {
            maxConcurrencyConstraint.release();
        }
    }
}

