        // Check if the hour is between the start and end dates
        if (hour.after(startDate) && hour.before(endDate)) {
            // Calculate the length of time for this hour
            long hourTime = hour.getTime() - startDate.getTime();

            // Add the length of time for this hour to the total time
            totalTime += hourTime;
        }
    }

    // Return the total time in milliseconds
    return totalTime;
}

