static public Angle difference(Angle angle1, Angle angle2) {
	// Calculate the difference between the two angles
    double diff = angle1.getValue() - angle2.getValue();

    // Normalize the difference to be within the range of -180 to 180 degrees
    while (diff > 180) {
        diff -= 360;
    }
    while (diff < -180) {
        diff -= 360;
    }

    // Return the normalized difference as a new Angle object
    return new Angle(diff);
}

