public void bindDataSourceToProxy(javax.sql.DataSource dataSource, Object proxy) throws SQLException {
    try (java.sql.Connection connection = dataSource.getConnection()) {
        java.sql.DatabaseMetaData metaData = connection.getMetaData();
        String productName = metaData.getDatabaseProductName().toLowerCase();

        if (productName.contains("mysql")) {
            String className = proxy.getClass().getName();
            Class<?> proxyClass = Class.forName(className);

            Object proxiedConnection = Proxy.newProxyInstance(proxyClass.getClassLoader(),
                                  new Class<?>[] { java.sql.Connection.class },
                                  (proxyObject, method, args) -> method.invoke(connection, args));

            Field[] fields = proxyClass.getDeclaredFields();
            for (Field field : fields) {
                if (field.getType().equals(Connection.class)) {
                    field.setAccessible(true);
                    field.set(proxy, proxiedConnection);
                    break;
                }
            }
        } else {
            throw new UnsupportedOperationException("Unsupported database product: " + productName);
        }
    } catch (ClassNotFoundException | IllegalAccessException | InvocationTargetException | NoSuchFieldException e) {
        throw new SQLException(e);
    }
}

