public static String replaceWords(String input, String[] words, String[] replaces) {
    StringBuilder sb = new StringBuilder(input);

    for (int i = 0; i < words.length; i++) {
        int start = 0;
        while (true) {
            start = sb.indexOf(words[i], start);
            if (start != -1) {
                sb.replace(start, start + words[i].length(), replaces[i]);
                start += replaces[i].length();
            } else {
                break;
            }
        }
    }

    return sb.toString();
}

