public static int decodeUnsignedInt(byte[] data, int n) {
    int result = 0;
    int shift = 0;
    int offset = 0;
    int numBytes = (n + 7) / 8;
    for (int i = 0; i < numBytes; i++) {
        result |= (data[i + offset] & 0xFF) << shift;
        shift += 8;
    }
    int mask = (1 << n) - 1;
    return result & mask;
}

