        System.out.println(decodeNBitUnsignedInteger(3, "101")); // should print 5
    }

    public static int decodeNBitUnsignedInteger(int n, String binaryString) throws IOException {
        if (binaryString.length() != n) {
            throw new IOException("Binary string length does not match n");
        }

        int result = 0;
        for (int i = 0; i < n; i++) {
            if (binaryString.charAt(i) == '1') {
                result += Math.pow(2, n - i - 1);
            }
        }

        return result;
    }
