            if (!address.isLoopbackAddress()) {
                try (Socket socket = new Socket(address, port)) {
                    if (socket.isConnected()) {
                        return address;
                    }
                } catch (Exception e) {
                    // Ignore and continue to next address
                }
            }
        }

