public enum ParserType {
    INTEGER,
    DOUBLE,
    STRING,
    BOOLEAN,
    NONE
}

public static ParserType processVariableString(String variableString) {
    if(variableString.matches(".*\\d.*")) {
        if(variableString.matches(".*\\.\\d.*")) {
            return ParserType.DOUBLE;
        } else {
            return ParserType.INTEGER;
        }
    } else if(variableString.equalsIgnoreCase("true") || variableString.equalsIgnoreCase("false")) {
        return ParserType.BOOLEAN;
    } else if(variableString.startsWith("\"") && variableString.endsWith("\"")) {
        return ParserType.STRING;
    } else {
        return ParserType.NONE;
    }
}

