import java.nio.ByteBuffer;

public static int computeLazyFieldMessageSetExtensionSize(final int fieldNumber, final LazyField value) {
    // Assuming LazyField is a class that has a method to get the byte array representation of the value
    byte[] valueBytes = value.toByteArray();

    // Create a ByteBuffer with enough space to hold the field number, the length of the value, and the value itself
    ByteBuffer buffer = ByteBuffer.allocate(4 + 4 + valueBytes.length);

    // Write the field number and the length of the value
    buffer.putInt(fieldNumber);
    buffer.putInt(valueBytes.length);

    // Write the value
    buffer.put(valueBytes);

    // Flip the buffer to prepare for reading
    buffer.flip();

    // The size of the encoded message set extension field is the limit of the buffer
    return buffer.limit();
}

