public static int[] findGap(int[] numbers) {
    int start = -1, end = -1;
    boolean gapStarted = false;
    for (int i = 0; i < numbers.length - 1; i++) {
        if (numbers[i] + 1 != numbers[i + 1]) {
            if (!gapStarted) {
                gapStarted = true;
                start = numbers[i] + 1;
            }
            end = numbers[i + 1] - 1;
        }
    }
    if (gapStarted) {
        return new int[]{start, end};
    } else {
        return null;
    }
}

