import java.util.TreeSet;

public class SequenceGapFinder {
    private TreeSet<Long> sequenceNumbers = new TreeSet<>();

    public void addSequenceNumber(long number) {
        sequenceNumbers.add(number);
    }

    public Pair<Long, Long> getFirstGap() {
        if (sequenceNumbers.size() < 2) {
            return null;
        }

        long previous = sequenceNumbers.first();
        for (long number : sequenceNumbers) {
            if (number - previous > 1) {
                return new Pair<>(previous, number);
            }
            previous = number;
        }

        return null;
    }

    public static class Pair<T, U> {
        public final T first;
        public final U second;

        public Pair(T first, U second) {
            this.first = first;
            this.second = second;
        }
    }
}

