public class IteratorSizeCalculator {
    private boolean isCached;
    private int size;

    public int calculateSize(List<Iterator> iterators) {
        if(isCached) {
            return size;
        }
        int totalSize = 0;
        for(Iterator iterator : iterators) {
            totalSize += calculateSingleIteratorSize(iterator);
        }
        size = totalSize;
        isCached = true;
        return size;
    }

    private int calculateSingleIteratorSize(Iterator iterator) {
        int iteratorSize = 0;
        while(iterator.hasNext()) {
            iterator.next();
            iteratorSize++;
        }
        return iteratorSize;
    }
}

