public static int checkValidHTMLTag(StringBuilder out, String in, int start) {
    // Initialize variables
    int end = in.length();
    int p1 = in.indexOf("<", start);

    // If no opening tag is found return -1
    if (p1 == -1) return -1;

    // Append characters before opening tag to StringBuilder
    out.append(in, start, p1);

    // Check for auto link
    if (in.regionMatches(p1, "<http://", 0, 8) ||
            in.regionMatches(p1, "<https://", 0, 9) ||
            in.regionMatches(p1, "<ftp://", 0, 6)) {
        int p2 = in.indexOf(">", p1 + 1);

        // If no closing angle bracket is found return -1
        if (p2 == -1) return -1;

        // Append auto link to StringBuilder and return new position
        out.append("<a href=\"").append(in.substring(p1 + 1, p2)).append("\">").
                append(in.substring(p1 + 1, p2)).append("</a>");
        return p2 + 1;
    }
    // Check for mailto auto link
    else if (in.regionMatches(p1, "<mailto:", 0, 8)) {
        int p2 = in.indexOf(">", p1 + 1);

        // If no closing angle bracket is found return -1
        if (p2 == -1) return -1;

        // Append mailto auto link to StringBuilder and return new position
        out.append("<a href=\"").append(in.substring(p1 + 1, p2)).append("\">").
                append(in.substring(p1 + 1, p2)).append("</a>");
        return p2 + 1;
    }
    // Parse opening tag
    else {
        int p2 = in.indexOf(">", p1 + 1);

        // If no closing angle bracket is found return -1
        if (p2 == -1) return -1;

        // Append opening tag to StringBuilder
        out.append(in, p1, p2 + 1);

        // If tag is self-closing return new position
        if (in.charAt(p2 - 1) == '/') return p2 + 1;

        // Parse closing tag and content
        String tagName = in.substring(p1 + 1, p2).toLowerCase();
        int p3 = in.lastIndexOf("</" + tagName, p2);

        // If no closing tag is found return -1
        if (p3 == -1) return -1;

        // Append content to StringBuilder
        int p4 = checkValidHTMLTag(out, in, p2 + 1);
        if (p4 == -1) return -1;

        // Append closing tag to StringBuilder and return new position
        out.append(in, p3, p4);
        return p4;
    }
