import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class HtmlChecker {

    private static final Pattern HTML_TAG_PATTERN = Pattern.compile("<(\"[^\"]*\"|'[^']*'|[^'\">])*>");

    private int checkHtml(final StringBuilder out, final String in, final int start) {
        Matcher matcher = HTML_TAG_PATTERN.matcher(in.substring(start));
        if (matcher.find()) {
            out.append(matcher.group());
            return start + matcher.end();
        }
        return -1;
    }

    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        HtmlChecker checker = new HtmlChecker();
        int newPosition = checker.checkHtml(out, "<html><head><title>Test</title></head><body></body></html>", 0);
        System.out.println("New position: " + newPosition);
        System.out.println("Output: " + out);
    }
}

