private int checkHtml(final StringBuilder out, final String in, final int start) {
	// Check for HTML tags
    if (in.startsWith("<", start)) {
        int end = in.indexOf(">", start);
        if (end != -1) {
            String tag = in.substring(start, end + 1);
            if (isValidHtmlTag(tag)) {
                out.append(tag);
                return end + 1;
            }
        }
    }
    // Check for auto links
    int autoLinkEnd = checkAutoLink(out, in, start);
    if (autoLinkEnd != -1) {
        return autoLinkEnd;
    }
    // Check for mailto auto links
    int mailtoLinkEnd = checkMailtoLink(out, in, start);
    if (mailtoLinkEnd != -1) {
        return mailtoLinkEnd;
    }
    return -1;
}

private boolean isValidHtmlTag(String tag) {
    // Simple validation for HTML tags
    return tag.matches("<[a-zA-Z0-9]+(\\s+[^>]+)?>");
}

private int checkAutoLink(StringBuilder out, String in, int start) {
    // Check for auto links (http/https)
    int end = in.indexOf(" ", start);
    if (end == -1) {
        end = in.length();
    }
    String potentialLink = in.substring(start, end);
    if (potentialLink.matches("https?://[\\w.-]+(?:/[\\w.-]*)*")) {
        out.append("<a href=\"").append(potentialLink).append("\">").append(potentialLink).append("</a>");
        return end;
    }
    return -1;
}

