    Boolean isInterfaceTree = false;

    // Check if any of the classes in the list are of type Class or Interface
    for (Class<?> clazz : list) {
        if (clazz.isInterface()) {
            isInterfaceTree = true;
        } else if (clazz.isClass()) {
            isClassTree = true;
        }
    }

    // Add heading depending upon type of tree
    if (isClassTree) {
        Element classHeader = new Element("h3").text("Class Tree: " + heading);
        div.appendChild(classHeader);
