    String[] permissions = getPermissionsFromAnnotation();
    // Resolve the permissions based on the path and method
    String[] resolvedPermissions = new String[permissions.length];
    for (int i = 0; i < permissions.length; i++) {
        String permission = permissions[i];
        // Split the permission into method and path pattern
        String[] parts = permission.split("\\|");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Invalid permission format: " + permission);
        }
        String permissionMethod = parts[0];
        String permissionPathPattern = parts[1];
        // Check if the method matches
        if (!permissionMethod.equalsIgnoreCase(method)) {
            resolvedPermissions[i] = null;
            continue;
        }
        // Resolve the path pattern
        String resolvedPath = resolvePathPattern(path, permissionPathPattern);
        if (resolvedPath == null) {
