public List<List<String>> findConversionPath(String fromUnit, String toUnit, Map<String, List<Pair<String, Double>>> conversionMap) {
    List<List<String>> result = new ArrayList<>();
    Set<String> visited = new HashSet<>();
    LinkedList<List<String>> queue = new LinkedList<>();

    visited.add(fromUnit);
    queue.offer(new ArrayList<>(Collections.singletonList(fromUnit)));

    while (!queue.isEmpty()) {
        List<String> currentPath = queue.poll();
        String currentUnit = currentPath.get(currentPath.size() - 1);

        if (currentUnit.equals(toUnit)) {
            result.add(currentPath);
            continue;
        }

        if (!conversionMap.containsKey(currentUnit)) {
            continue;
        }

        for (Pair<String, Double> neighbor : conversionMap.get(currentUnit)) {
            if (visited.contains(neighbor.getKey())) {
                continue;
            }

            List<String> newPath = new ArrayList<>(currentPath);
            newPath.add(neighbor.getKey());
            queue.offer(newPath);
        }
    }

    return result;
}

