    public List<List<UnitFactor>> getPaths(Unit from, Unit to, Set<Unit> seen) {
        List<List<UnitFactor>> paths = new ArrayList<>();

        if (from.equals(to)) {
            paths.add(new ArrayList<>());
        } else {
            seen.add(from);
            for (UnitFactor factor : conversionMap.get(from)) {
                if (!seen.contains(factor.getTo())) {
                    for (List<UnitFactor> subPath : getPaths(factor.getTo(), to, seen)) {
                        List<UnitFactor> path = new ArrayList<>();
                        path.add(factor);
                        path.addAll(subPath);
                        paths.add(path);
                    }
                }
            }
            seen.remove(from);
        }

        return paths;
    }
}

