public static <T extends ContentMeta> ResourceSelector<T> exactMetadataResourceSelector(final Map<String, String> required, final boolean requireAll) {
    Predicate<T> predicate;

    if (requireAll) {
        // If requireAll is true, create a predicate that checks if all required metadata values are equal
        predicate = resource -> required.entrySet().stream()
                .allMatch(entry -> entry.getValue().equals(resource.getMetadata().get(entry.getKey())));
    } else {
        // If requireAll is false, create a predicate that checks if at least one required metadata value is equal
        predicate = resource -> required.entrySet().stream()
                .anyMatch(entry -> entry.getValue().equals(resource.getMetadata().get(entry.getKey())));
    }

    // Return a ResourceSelector that uses the created predicate
    return resources -> resources.stream().filter(predicate).collect(Collectors.toList());
}

