public Multimap<Type, Class<?>> filterProducibleClasses(Map<Key<?>, Class<?>> bindings) {
    Multimap<Type, Class<?>> producibleClasses = ArrayListMultimap.create();

    for (Map.Entry<Key<?>, Class<?>> entry : bindings.entrySet()) {
        Class<?> clazz = entry.getValue();
        if (isProducible(clazz)) {
