import java.util.HashMap;
import java.util.Map;

public class BlockStore {
    private Map<String, Integer> versionTally = new HashMap<>();

    public void initialize(BlockStore blockStore, StoredBlock chainHead) throws BlockStoreException {
        // Iterate over the blocks in the block store
        for (Block block : blockStore.getBlocks()) {
            // Get the version of the block
            String version = block.getVersion();

            // If the version is already in the tally, increment its count
            if (versionTally.containsKey(version)) {
                versionTally.put(version, versionTally.get(version) + 1);
            } 
            // Otherwise, add the version to the tally with a count of 1
            else {
                versionTally.put(version, 1);
            }
        }
    }
}

