public void initialize(final BlockStore blockStore, final StoredBlock chainHead) throws BlockStoreException {
	// Initialize the version tally from the block store
    // Note this does not search backwards past the start of the block store, so if starting from
    // a checkpoint this may not fill the window.
    int versionTally[] = new int[VERSION_GROUP_COUNT];
    StoredBlock cursor = chainHead;
    int blocksToProcess = VERSION_GROUP_COUNT;

    while (blocksToProcess > 0 && cursor != null) {
        versionTally[cursor.getHeader().getVersion() & VERSION_GROUP_MASK] += 1;
        cursor = cursor.getPrev(blockStore);
        blocksToProcess--;
    }

    // Set the version tally to the tally we just computed
    this.versionTally = versionTally;
}

